insert into content(key,data,updated_at) values('sec:a-r1-p6',$mkd${"id": "a-r1-p6", "area": "RC", "part": 6, "group": "A급 과제", "series": 3, "round": 1, "level": "중급", "title": "A급 과제 1회 · PART 6", "notes": [], "items": [], "sets": [{"range": "131-134", "passage": "TARPON SPRINGS, FL (June 24)- For the first time ever, the Tarpon Springs Museum of Art ---131--- the works of famed local artist Nikos Parios. The retrospective show is planned for the entire month of July.\nMr. Parios will attend the opening of the show on the evening of July 1. However, not all the works in the show will be ---132---. Works by four younger artists who have studied with Mr. Parios will also be featured. ---133---.\nThe show will be the first to take place since the museum's recent remodeling. ---134--- visitors will notice that the murals on the walls have been restored and a large skylight has been installed.", "tr": "TARPON SPRINGS, FL (6월 24일) — 사상 처음으로 Tarpon Springs 미술관이 유명 지역 화가 Nikos Parios의 작품을 전시할 예정이다(131). 이 회고전은 7월 한 달 내내 열릴 계획이다. Parios 씨는 7월 1일 저녁 전시 개막식에 참석할 것이다. 그러나 전시의 모든 작품이 그의 것(132)은 아니다. Parios 씨에게 배운 네 명의 젊은 화가들의 작품도 함께 선보인다. 그 화가들은 7월 1일에 Parios 씨와 함께할 것이다(133). 이번 전시는 미술관의 최근 개조 이후 처음 열리는 전시가 된다. 정기(134) 방문객들은 벽의 벽화가 복원되고 큰 천창이 설치된 것을 알아차리게 될 것이다.", "vocab": "exhibit 동 전시하다 / famed 형 유명한 / retrospective 형 회고의 / entire 형 전체의 / feature 동 특집으로 다루다 / remodeling 명 개조 / mural 명 벽화 / restore 동 복원하다 / skylight 명 천창", "g": {"tarpon": ["고유명사", "타폰(지명)"], "a": ["관사", "하나의"], "on": ["전치사", "~에, ~위에"], "springs": ["고유명사", "스프링스(지명)"], "in": ["전치사", "~에, ~안에"], "fl": ["고유명사", "플로리다 주"], "june": ["명사", "6월"], "24": ["숫자", "24"], "for": ["전치사", "~을 위해, ~동안"], "the": ["관사", "그"], "first": ["형용사", "첫 번째의"], "time": ["명사", "시간"], "ever": ["부사", "지금까지"], "museum": ["명사", "미술관"], "of": ["전치사", "~의"], "art": ["명사", "미술"], "1": ["숫자", "1"], "works": ["명사", "작품", "work"], "famed": ["형용사", "유명한"], "local": ["형용사", "지역의"], "artist": ["명사", "화가"], "is": ["동사", "~이다", "be"], "nikos": ["고유명사", "니코스(인명)"], "parios": ["고유명사", "파리오스(인명)"], "retrospective": ["형용사", "회고의"], "show": ["명사", "전시회"], "planned": ["과거분사", "계획된", "plan"], "entire": ["형용사", "전체의"], "month": ["명사", "달"], "july": ["명사", "7월"], "mr": ["명사", "~씨(남성)"], "will": ["조동사", "~할 것이다"], "attend": ["동사", "참석하다"], "opening": ["명사", "개막식"], "evening": ["명사", "저녁"], "however": ["부사", "그러나"], "not": ["부사", "~않다"], "all": ["한정사", "모든"], "be": ["동사", "~이다, 되다"], "by": ["전치사", "~에 의해, ~까지"], "four": ["숫자", "넷"], "younger": ["형용사", "더 젊은", "young"], "artists": ["명사", "화가들", "artist"], "who": ["대명사", "누구"], "have": ["동사", "가지다, (완료)"], "studied": ["과거분사", "공부한", "study"], "with": ["전치사", "~와 함께, ~으로"], "also": ["부사", "또한"], "featured": ["과거분사", "특별히 포함된", "feature"], "to": ["to부정사", "~하는 것"], "take": ["동사", "(take place) 열리다"], "place": ["명사", "(take place) 개최"], "since": ["전치사", "~이후로"], "museum's": ["명사", "미술관의", "museum"], "recent": ["형용사", "최근의"], "remodeling": ["명사", "개조"], "visitors": ["명사", "방문객", "visitor"], "notice": ["동사", "알아차리다"], "that": ["접속사", "~라는 것"], "murals": ["명사", "벽화", "mural"], "walls": ["명사", "벽", "wall"], "been": ["과거분사", "~였던", "be"], "restored": ["과거분사", "복원된", "restore"], "and": ["접속사", "그리고"], "large": ["형용사", "큰"], "skylight": ["명사", "천창"], "has": ["동사", "가지다, (완료)", "have"], "installed": ["과거분사", "설치된", "install"]}, "questions": [{"no": 131, "q": "", "options": ["has exhibited", "exhibit", "will exhibit", "exhibited"], "answer": 2, "explain": "정답 (C) will exhibit\n해석: 사상 처음으로 Tarpon Springs 미술관이 Nikos Parios의 작품을 전시할 예정이다.\n정답 근거: 문장에 동사가 없으므로 동사 자리. 타동사 exhibit 뒤 목적어 the works가 있어 능동. 뒤 문장에서 전시가 7월에 열릴 계획(is planned)이고 Parios가 개막식에 참석할 것(will attend)이라 하므로 아직 열리지 않은 미래 → will exhibit.\n오답 분석: (A) has exhibited: 현재완료 — 이미 전시했다는 뜻이라 7월 예정 전시와 불일치. / (B) exhibit: 현재형 — 주어 Museum(단수)과 수 불일치(3인칭 단수 -s 필요). / (D) exhibited: 과거 — 앞으로 열릴 전시와 시제 불일치.\n지문 개요: Tarpon Springs 미술관이 7월 한 달간 지역 화가 Nikos Parios의 회고전을 처음으로 개최하며, 제자 4명의 작품도 함께 전시하고 개조된 미술관을 선보인다는 기사."}, {"no": 132, "q": "", "options": ["its", "his", "hers", "theirs"], "answer": 1, "explain": "정답 (B) his\n해석: 그러나 전시의 모든 작품이 그의 것은 아니다.\n정답 근거: be동사 뒤 보어 자리의 소유대명사. 앞에서 Parios 씨의 작품 전시를 말하고 뒤 문장에서 제자 4명의 작품도 전시한다고 하므로 \"모든 작품이 그(Parios)의 것은 아니다\" → his.\n오답 분석: (A) its: 미술관의 것이라는 뜻이 되어 제자 작품과 대비되는 흐름과 맞지 않음. / (C) hers: 여성 인물이 등장하지 않음. / (D) theirs: 복수 소유자가 앞에 제시되지 않음."}, {"no": 133, "q": "", "options": ["Mr. Parios began painting at a young age.", "The artists will join Mr. Parios on July 1.", "Mr. Parios was born in Tarpon Springs.", "One mural was painted by Mr. Parios."], "answer": 1, "explain": "정답 (B) The artists will join Mr. Parios on July 1.\n해석: 그 화가들은 7월 1일에 Parios 씨와 함께할 것이다.\n정답 근거: 바로 앞 문장에서 네 명의 젊은 화가 작품도 전시된다고 했으므로, 그 화가들(The artists)이 개막일 7월 1일에 Parios와 함께한다는 문장이 자연스럽게 이어짐.\n오답 분석: (A) Parios가 어릴 때 그림을 시작했다는 내용은 전시 구성 설명 흐름과 무관. / (C) 출생지 언급은 앞뒤 문맥(제자 작품 전시)과 연결되지 않음. / (D) 벽화 이야기는 뒤의 미술관 개조 문맥이며, 이 위치에서는 논리 연결이 없음."}, {"no": 134, "q": "", "options": ["Preceding", "Early", "Official", "Regular"], "answer": 3, "explain": "정답 (D) Regular\n해석: 정기 방문객들은 벽화가 복원되고 큰 천창이 설치된 것을 알아차리게 될 것이다.\n정답 근거: 개조 이후 첫 전시라는 앞 문장 + 복원된 벽화와 새 천창을 \"알아차린다\"는 내용 → 이전 모습을 아는 단골(정기) 방문객이어야 변화를 알아챌 수 있음 → Regular.\n오답 분석: (A) Preceding: '이전의' — 이전 방문객은 개조 후 변화를 볼 수 없음. / (B) Early: '이른' — 일찍 온 방문객이라서 변화를 알아챈다는 논리가 성립하지 않음. / (C) Official: '공식적인' — 문맥과 무관."}]}, {"range": "135-138", "passage": "To: All employees\nFrom: Martha Bauer\nSubject: Meetings\nDate: April 4\nIn an attempt to improve productivity, we have analyzed the most effective ways to communicate information ---135--- our company. ---136---, we have decided to make an effort to reduce the number of meetings held each month. To that end, we now ---137--- that employees adhere to general guidelines when scheduling a meeting. These include always writing a detailed agenda for any meeting and expressly stating a specific end time for meetings. In addition, employees should only be invited to meetings if their presence is essential. ---138---. By following these guidelines, we hope that we all will have more time to commit to our work.", "tr": "수신: 전 직원 / 발신: Martha Bauer / 제목: 회의 / 날짜: 4월 4일\n생산성을 높이기 위한 시도로 우리는 회사 내에서(135) 정보를 전달하는 가장 효과적인 방법을 분석했습니다. 그 결과(136), 매달 열리는 회의 수를 줄이기 위해 노력하기로 결정했습니다. 그 목적을 위해 이제 직원들이 회의를 잡을 때 일반 지침을 준수할 것을 요청합니다(137). 여기에는 모든 회의에 대해 항상 상세한 안건을 작성하는 것과 회의 종료 시간을 명확히 명시하는 것이 포함됩니다. 또한 직원은 참석이 필수적인 경우에만 회의에 초대되어야 합니다. 참석할 필요가 없다면 초대를 거절하십시오(138). 이 지침을 따름으로써 우리 모두 업무에 쏟을 시간이 더 많아지기를 바랍니다.", "vocab": "in an attempt to 구 ~하려는 시도로 / productivity 명 생산성 / analyze 동 분석하다 / within 전 ~내에서 / to that end 구 그 목적을 위해 / adhere to 구 ~을 준수하다 / agenda 명 안건 / expressly 부 명확히 / presence 명 참석 / decline 동 거절하다", "g": {"to": ["to부정사", "~하기 위해"], "a": ["관사", "하나의"], "all": ["한정사", "모든"], "employees": ["명사", "직원들", "employee"], "from": ["전치사", "~로부터"], "martha": ["고유명사", "마사(인명)"], "bauer": ["고유명사", "바우어(인명)"], "subject": ["명사", "제목"], "meeting": ["명사", "회의"], "meetings": ["명사", "회의", "meeting"], "in": ["전치사", "~에, ~안에"], "date": ["명사", "날짜"], "april": ["명사", "4월"], "4": ["숫자", "4"], "an": ["관사", "하나의"], "attempt": ["명사", "시도"], "improve": ["동사", "향상시키다"], "productivity": ["명사", "생산성"], "we": ["대명사", "우리"], "have": ["동사", "가지다, (완료)"], "analyzed": ["과거분사", "분석한", "analyze"], "the": ["관사", "그"], "most": ["부사", "가장"], "effective": ["형용사", "효과적인"], "ways": ["명사", "방법", "way"], "communicate": ["동사", "전달하다"], "information": ["명사", "정보"], "for": ["전치사", "~을 위해, ~동안"], "our": ["한정사", "우리의"], "company": ["명사", "회사"], "any": ["한정사", "어떤"], "decided": ["과거분사", "결정한", "decide"], "make": ["동사", "(노력을) 하다"], "effort": ["명사", "노력"], "reduce": ["동사", "줄이다"], "number": ["명사", "수"], "be": ["동사", "~이다, 되다"], "of": ["전치사", "~의"], "held": ["과거분사", "열리는", "hold"], "each": ["한정사", "각각의"], "month": ["명사", "달"], "that": ["한정사", "그"], "end": ["명사", "목적; 끝"], "now": ["부사", "지금"], "adhere": ["동사", "(to) 준수하다"], "general": ["형용사", "일반적인"], "guidelines": ["명사", "지침", "guideline"], "when": ["접속사", "~할 때"], "scheduling": ["동명사", "일정을 잡기", "schedule"], "these": ["한정사", "이것들의"], "include": ["동사", "포함하다"], "always": ["부사", "항상"], "writing": ["동명사", "작성하기", "write"], "detailed": ["형용사", "상세한"], "agenda": ["명사", "안건"], "and": ["접속사", "그리고"], "expressly": ["부사", "명확히"], "stating": ["동명사", "명시하기", "state"], "specific": ["형용사", "구체적인"], "if": ["접속사", "만약 ~라면"], "time": ["명사", "시간"], "addition": ["명사", "(in addition) 추가로"], "should": ["조동사", "~해야 한다"], "only": ["부사", "오직"], "invited": ["과거분사", "초대받은", "invite"], "their": ["한정사", "그들의"], "presence": ["명사", "참석"], "is": ["동사", "~이다", "be"], "essential": ["형용사", "필수적인"], "by": ["전치사", "~에 의해, ~까지"], "following": ["동명사", "따르기", "follow"], "hope": ["동사", "바라다"], "will": ["조동사", "~할 것이다"], "more": ["부사", "더"], "commit": ["동사", "(시간을) 쏟다"], "work": ["명사", "업무"]}, "questions": [{"no": 135, "q": "", "options": ["near", "against", "following", "within"], "answer": 3, "explain": "정답 (D) within\n해석: 우리는 회사 내에서 정보를 전달하는 가장 효과적인 방법을 분석했습니다.\n정답 근거: 명사 our company 앞 전치사 자리. 회사 \"안에서\" 정보를 소통하는 방법이라는 의미 → within.\n오답 분석: (A) near: '~근처에' — 회사 근처에서 소통한다는 뜻이 되어 부적절. / (B) against: '~에 반대하여' — 의미 불가. / (C) following: '~후에' — 의미 불가.\n지문 개요: Martha Bauer가 전 직원에게 생산성 향상을 위해 월별 회의 수를 줄이기로 했음을 알리며, 상세 안건 작성·종료 시간 명시·필수 인원만 초대 등 회의 일정 지침을 안내하는 회람."}, {"no": 136, "q": "", "options": ["As a result", "Even so", "Meanwhile", "Instead"], "answer": 0, "explain": "정답 (A) As a result\n해석: 그 결과, 매달 열리는 회의 수를 줄이기 위해 노력하기로 결정했습니다.\n정답 근거: 앞 문장(효과적인 소통 방법을 분석함)이 원인, 뒤 문장(회의 수를 줄이기로 결정)이 결과 → As a result.\n오답 분석: (B) Even so: '그렇다 하더라도' — 역접 관계가 아님. / (C) Meanwhile: '그동안에' — 시간 병행 관계가 아님. / (D) Instead: '대신에' — 대체 관계가 아님."}, {"no": 137, "q": "", "options": ["asking", "asked", "asks", "ask"], "answer": 3, "explain": "정답 (D) ask\n해석: 이제 직원들이 회의를 잡을 때 일반 지침을 준수할 것을 요청합니다.\n정답 근거: 문장의 동사 자리(동사 없음). 주어 we(복수)와 수일치하고 부사 now(현재)와 맞는 현재 동사 ask. ask 뒤 명사절 접속사 that + 주어 employees + 동사원형 adhere(요구동사 뒤 that절 원형).\n오답 분석: (A) asking: 분사 — 동사 자리에 -ing 단독 불가. / (B) asked: 과거 — 부사 now(지금)와 시제 불일치. / (C) asks: 3인칭 단수 — 주어 we와 수 불일치."}, {"no": 138, "q": "", "options": ["Tomorrow's meeting will be held in the auditorium.", "An updated agenda will be sent separately.", "If you do not need to attend, decline the invitation.", "If you are available to help, send me an e-mail."], "answer": 2, "explain": "정답 (C) If you do not need to attend, decline the invitation.\n해석: 참석할 필요가 없다면 초대를 거절하십시오.\n정답 근거: 바로 앞 문장에서 \"참석이 필수인 경우에만 초대되어야 한다\"고 했으므로, 필요 없으면 초대를 거절하라는 지침이 이어지는 것이 자연스러움.\n오답 분석: (A) 내일 회의 장소 안내는 일반 지침을 설명하는 흐름과 무관. / (B) 특정 회의의 업데이트 안건 발송은 문맥과 맞지 않음. / (D) 도움 가능 시 이메일 요청은 회의 지침과 무관."}]}, {"range": "139-142", "passage": "---139--- for an enchanting setting for your family celebration? Why not consider the beautiful Hibiscus Tropical Garden in Tortola, British Virgin Islands? For 50 years, the site was a working tropical flower nursery. Then fifteen years ago, the grounds and structures were completely ---140---. The result of this million-dollar investment is a unique ---141--- of rustic charm with modern amenities. Our converted warehouse accommodates up to 250 guests for dinner and entertainment. When dinner is over, our state-of-the-art sound system guarantees that your guests will be on their feet and dancing all evening long.\nOur event calendar fills up quickly each season. ---142---. Contact Evan Wilder at 284-555-0012 or ewilder@hibiscustropicalgardne.co.vg.", "tr": "가족 축하 행사를 위한 매혹적인 장소를 찾고 계신가요(139)? 영국령 버진아일랜드 Tortola의 아름다운 Hibiscus Tropical Garden을 고려해 보시는 건 어떨까요? 50년 동안 이곳은 운영 중인 열대 화훼 묘목장이었습니다. 그러다 15년 전 부지와 건물이 완전히 개조되었습니다(140). 이 백만 달러 투자의 결과는 소박한 매력과 현대적 편의시설의 독특한 조합(141)입니다. 개조된 창고는 저녁 식사와 여흥을 위해 최대 250명의 손님을 수용합니다. 식사가 끝나면 최첨단 음향 시스템이 손님들이 저녁 내내 일어나 춤추도록 보장합니다. 저희 행사 일정은 시즌마다 빠르게 찹니다. 그러니 오늘 특별한 행사를 계획하기 시작하세요(142). Evan Wilder에게 284-555-0012 또는 ewilder@hibiscustropicalgardne.co.vg로 연락하십시오.", "vocab": "enchanting 형 매혹적인 / setting 명 장소, 배경 / nursery 명 묘목장 / renovate 동 개조하다 / investment 명 투자 / combination 명 조합 / rustic 형 소박한 / amenity 명 편의시설 / a