insert into content(key,data,updated_at) values('sec:a-r12-p6',$mkd${"id": "a-r12-p6", "part": 6, "title": "A급 과제 12회 · PART 6", "area": "RC", "group": "A급 과제", "series": 3, "round": 12, "level": "중급", "notes": [], "items": [], "sets": [{"range": "131-134", "passage": "Dear Collington Fitness Club Members:\nThe fitness club will hold its annual 5-kilometre run at 12 noon on Saturday, 15 November. Members who are interested are encouraged to join. ---131--- will receive a free water bottle on the day of the race. The cost of registration is £10, which should ---132--- to the front desk by 10 November along with a participation form. This year's race will benefit the local primary school. ---133---. Be sure to wear ---134--- clothes and arrive 30 minutes early. We hope to see many of our members come to support our community's young pupils.", "tr": "Collington 피트니스 클럽 회원 여러분께: 클럽은 11월 15일 토요일 정오에 연례 5킬로미터 달리기를 개최합니다. 관심 있는 회원의 참가를 권장합니다. 참가자(131)는 경기 당일 무료 물병을 받습니다. 등록비는 10파운드이며 참가 신청서와 함께 11월 10일까지 프런트로 가져오셔야 (132) 합니다. 올해 경기 수익금은 지역 초등학교에 돌아갑니다. 경기는 마을 공원 문에서 시작해 마을을 굽이돌아 진행됩니다(133). 따뜻한 (134) 옷을 입고 30분 일찍 도착해 주십시오. 많은 회원이 오셔서 우리 지역 어린 학생들을 응원해 주시길 바랍니다.", "vocab": "hold 동 개최하다 / annual 형 연례의 / be encouraged to 구 ~하도록 권장되다 / participant 명 참가자 / registration 명 등록 / front desk 명 안내 데스크 / along with 구 ~와 함께 / participation form 명 참가 신청서 / benefit 동 ~에 도움이 되다 / primary school 명 초등학교 / wind through 구 ~을 굽이굽이 지나다 / pupil 명 학생", "questions": [{"no": 131, "q": "", "options": ["Participants", "Guides", "Bicyclists", "Drivers"], "answer": 0, "explain": "지문 개요: Collington 피트니스 클럽이 11월 15일 토요일 정오 연례 5km 달리기를 열며, 참가자에게 물병을 주고 참가비 10파운드와 참가 신청서를 11월 10일까지 프런트에 내야 하며, 수익금은 지역 초등학교에 돌아가고 마을 공원 문에서 출발한다는 공지.\n정답 (A) Participants\n해석: 참가자는 경기 당일 무료 물병을 받습니다.\n정답 근거: 앞 문장에서 회원의 참가를 권장했으므로 물병을 받는 사람은 참가자 → Participants.\n오답 분석: (B) Guides: '안내인' — 언급 없음. / (C) Bicyclists: '자전거 이용자' — 달리기와 불일치. / (D) Drivers: '운전자' — 불가.", "translation": "참가자는 경기 당일 무료 물병을 받습니다."}, {"no": 132, "q": "", "options": ["be bringing", "be brought", "have brought", "have been brought"], "answer": 1, "explain": "정답 (B) be brought\n해석: 등록비 10파운드는 11월 10일까지 프런트로 가져오셔야 합니다.\n정답 근거: 조동사 should 뒤 동사원형 자리. bring은 타동사인데 빈칸 뒤 목적어 없이 전치사구 to the front desk가 오므로 수동 be brought(주어 등록비가 가져와지는 대상).\n오답 분석: (A) be bringing: 능동 — 목적어가 없어 불가. / (C) have brought: 능동 — 목적어 없음. / (D) have been brought: 완료 수동 — 마감 전 미래 행동과 시제 불일치.", "translation": "등록비 10파운드는 11월 10일까지 프런트로 가져오셔야 합니다."}, {"no": 133, "q": "", "options": ["The £10 fee will be waived for fitness club members.", "The proceeds from it will go to a local animal shelter.", "Please complete registration on the day of the race.", "It will begin at the village park gate and wind through the village."], "answer": 3, "explain": "정답 (D) It will begin at the village park gate and wind through the village.\n해석: 경기는 마을 공원 문에서 시작해 마을을 굽이돌아 진행됩니다.\n정답 근거: 경기 일정·비용 안내 흐름에서 코스 정보를 제공하는 문장이 자연스럽고, 뒤 \"따뜻한 옷을 입고 일찍 오라\"로 이어 짐.\n오답 분석: (A) 회원 면제는 앞서 10파운드를 내라고 한 것과 모순. / (B) 수익금은 앞 문장에서 초등학교로 간다고 함(동물 보호소 아님). / (C) 당일 등록은 11월 10일 마감과 모순.", "translation": "경기는 마을 공원 문에서 시작해 마을을 굽이돌아 진행됩니다."}, {"no": 134, "q": "", "options": ["warmth", "warmly", "warm", "warmest"], "answer": 2, "explain": "정답 (C) warm\n해석: 따뜻한 옷을 입고 30분 일찍 도착해 주십시오.\n정답 근거: 「wear + 빈칸 + 명사 clothes」 → 명사 앞 형용사 → warm.\n오답 분석: (A) warmth: 명사 — 복합명사로 성립하지 않음. / (B) warmly: 부사 — 명사 수식 불가. / (D) warmest: 최상급 — 비교 대상이 없어 부적절.", "translation": "따뜻한 옷을 입고 30분 일찍 도착해 주십시오."}], "g": {"to": ["전치사", "~에게, ~으로"], "our": ["대명사", "우리의"], "are": ["동사", "~이다", "be"], "be": ["동사", "~이다"], "dear": ["형용사", "친애하는"], "at": ["전치사", "~에서"], "on": ["전치사", "~에"], "its": ["대명사", "그것의"], "10": ["숫자", "10"], "and": ["접속사", "그리고"], "with": ["전치사", "~와 함께"], "30": ["숫자", "30"], "should": ["조동사", "~해야 한다"], "we": ["대명사", "우리"], "this": ["한정사", "이"], "a": ["관사", "하나의"], "the": ["관사", "그"], "15": ["숫자", "15"], "of": ["전치사", "~의"], "by": ["전치사", "~까지, ~에 의해"], "many": ["한정사", "많은"], "which": ["관계사", "어느 것"], "will": ["조동사", "~할 것이다"], "is": ["동사", "~이다", "be"], "12": ["숫자", "12"], "who": ["대명사", "누구"], "water": ["명사", "물"], "wear": ["동사", "입다"], "saturday": ["고유명사", "토요일"], "support": ["동사", "응원하다"], "arrive": ["동사", "도착하다"], "clothes": ["명사", "옷"], "cost": ["명사", "비용"], "receive": ["동사", "받다"], "hope": ["동사", "바라다"], "front": ["형용사", "앞쪽의"], "young": ["형용사", "어린"], "benefit": ["동사", "~에 도움이 되다"], "november": ["고유명사", "11월"], "race": ["명사", "경주"], "run": ["명사", "달리기"], "hold": ["동사", "개최하다"], "free": ["형용사", "무료의"], "local": ["형용사", "지역의"], "collington": ["고유명사", "콜링턴(클럽명)"], "join": ["동사", "참가하다"], "school": ["명사", "학교"], "year's": ["명사", "올해의", "year"], "day": ["명사", "날"], "minutes": ["명사", "분", "minute"], "come": ["동사", "오다"], "registration": ["명사", "등록"], "bottle": ["명사", "병"], "along": ["부사", "(along with) ~와 함께"], "annual": ["형용사", "연례의"], "desk": ["명사", "데스크"], "community's": ["명사", "지역 사회의", "community"], "club": ["명사", "클럽"], "pupils": ["명사", "학생들", "pupil"], "members": ["명사", "회원들", "member"], "encouraged": ["과거분사", "권장되는", "encourage"], "noon": ["명사", "정오"], "form": ["명사", "양식"], "early": ["부사", "일찍"], "see": ["동사", "보다"], "fitness": ["명사", "피트니스"], "sure": ["형용사", "(be sure to) 꼭 ~하다"], "interested": ["형용사", "관심 있는"], "primary": ["형용사", "초등의"], "5-kilometre": ["형용사", "5킬로미터의"], "participation": ["명사", "참가"]}}, {"range": "135-138", "passage": "To: All Severus Bank Employees\nFrom: Sang-Hoon Park\nDate: August 3\nSubject: Good news\nI ---135--- received an e-mail from Vivian Paris of Cash and Currency magazine. I am very pleased to inform you that the magazine has rated us number one in customer service. We have also made ---136--- top ten list of best banks in the nation! Well done, everyone. ---137---. We will be updating the bank's advertising in newspapers and social media to reflect this wonderful news. ---138---, I encourage you to continue the good work you have all been doing.", "tr": "수신: Severus Bank 전 직원 / 발신: Sang-Hoon Park / 날짜: 8월 3일 / 제목: 좋은 소식\n방금(135) Cash and Currency 잡지의 Vivian Paris로부터 이메일을 받았습니다. 이 잡지가 우리를 고객 서비스 1위로 평가했음을 알려 드리 게 되어 매우 기쁩니다. 또한 그(136) 잡지의 전국 우수 은행 10위 목록에도 올랐습니다! 모두 잘하셨습니다. 해당 호를 읽고 싶으시면 월요일에 온라인에서 볼 수 있습니다(137). 이 멋진 소식을 반영하도록 신문과 소셜 미디어의 은행 광고를 갱신할 예정입니다. 그동안(138) 여러분 모두가 해 온 좋은 성과를 계속 이어 가시길 권합니다.", "vocab": "just 부 방금 / currency 명 통화 / be pleased to 구 ~하게 되어 기쁘다 / inform 동 알리다 / rate 동 평가하다 / make a list 구 목록에 들다 / issue 명 (잡지의) 호 / available 형 이용 가능한 / update 동 갱신하다 / reflect 동 반영하다 / in the meantime 구 그동안에 / encourage 동 격려하다", "questions": [{"no": 135, "q": "", "options": ["just", "later", "soon", "next"], "answer": 0, "explain": "지문 개요: Severus Bank의 Sang-Hoon Park이 Cash and Currency 잡지가 은행을 고객 서비스 1위로 평가했고 전국 우수 은행 10위 안에 들었다는 소식을 전하며, 잡지는 월요일 온라인에서 볼 수 있고 광고에 이를 반영하겠다며 계속 좋은 성과를 내 달라는 회람.\n정답 (A) just\n해석: 방금 이메일을 받았습니다.\n정답 근거: 현재완료 have received와 함께 \"방금 막\" → just.\n오답 분석: (B) later: '나중에' — 완료 시제와 불일치. / (C) soon: '곧' — 미래 표현. / (D) next: '다음에' — 불가.", "translation": "방금 이메일을 받았습니다."}, {"no": 136, "q": "", "options": ["its", "my", "his", "our"], "answer": 0, "explain": "정답 (A) its\n해석: 또한 그 잡지의 전국 우수 은행 10위 목록에 올랐습니다.\n정답 근거: 명사 top ten list 앞 소유격. 목록을 만든 주체는 앞 문장의 잡지(단수 사물) → its.\n오답 분석: (B) my: 발신자 개인의 목록이 아님. / (C) his: 지시 대상이 될 남성 소유주가 아님. / (D) our: 은행이 만든 목록이 아니라 잡지의 목록.", "translation": "또한 그 잡지의 전국 우수 은행 10위 목록에 올랐습니다."}, {"no": 137, "q": "", "options": ["Make sure you have the correct contact information.", "If you would like to read the issue, it will be available online on Monday.", "It is very important to find the right bank for your needs.", "Our customer service department is now hiring."], "answer": 1, "explain": "정답 (B) If you would like to read the issue, it will be available online on Monday.\n해석: 해당 호를 읽고 싶으시면 월요일에 온라인에서 볼 수 있습니다.\n정답 근거: 잡지 평가 소식을 전한 뒤 그 잡지를 볼 수 있는 방법을 안내하는 문장이 자연스러움.\n오답 분석: (A) 연락처 확인은 문맥과 무관. / (C) 은행 선택 조언은 직원 대상 회람에 부적절. / (D) 채용 공고는 무관.", "translation": "해당 호를 읽고 싶으시면 월요일에 온라인에서 볼 수 있습니다."}, {"no": 138, "q": "", "options": ["However", "In contrast", "Nevertheless", "In the meantime"], "answer": 3, "explain": "정답 (D) In the meantime\n해석: 그동안 좋은 성과를 계속 이어 가시길 권합니다.\n정답 근거: 광고 갱신을 준비하는 사이 직원들에게 계속 잘해 달라는 흐름 → In the meantime(그동안).\n오답 분석: (A) However: 역접 — 대조 내용 없음. / (B) In contrast: 대조 — 불가. / (C) Nevertheless: 역접 — 불가.", "translation": "그동안 좋은 성과를 계속 이어 가시길 권합니다."}], "g": {"that": ["접속사", "~라는 것"], "to": ["전치사", "~에게, ~으로"], "have": ["동사", "가지다"], "us": ["대명사", "우리를"], "in": ["전치사", "~에"], "has": ["동사", "가지다", "have"], "be": ["동사", "~이다"], "an": ["관사", "하나의"], "am": ["동사", "~이다", "be"], "been": ["과거분사", "~였던", "be"], "and": ["접속사", "그리고"], "we": ["대명사", "우리"], "this": ["한정사", "이"], "you": ["대명사", "당신"], "3": ["숫자", "3"], "of": ["전치사", "~의"], "the": ["관사", "그"], "i": ["대명사", "나"], "from": ["전치사", "~에서"], "also": ["부사", "또한"], "very": ["부사", "매우"], "will": ["조동사", "~할 것이다"], "best": ["부사", "가장 잘"], "all": ["한정사", "모든"], "good": ["형용사", "좋은"], "customer": ["명사", "고객"], "vivian": ["고유명사", "비비안(이름)"], "park": ["고유명사", "박(성)"], "severus": ["고유명사", "세베루스(은행명)"], "advertising": ["명사", "광고"], "media": ["명사", "매체"], "newspapers": ["명사", "신문", "newspaper"], "encourage": ["동사", "권장하다"], "bank's": ["명사", "은행의", "bank"], "social": ["형용사", "사회적인"], "rated": ["과거분사", "평가했다", "rate"], "received": ["과거분사", "받았다", "receive"], "employees": ["명사", "직원들", "employee"], "list": ["명사", "목록"], "doing": ["현재분사", "해 오는", "do"], "updating": ["현재분사", "업데이트하는", "update"], "e-mail": ["명사", "이메일"], "service": ["명사", "서비스"], "banks": ["명사", "은행들", "bank"], "one": ["숫자", "1"], "reflect": ["동사", "반영하다"], "everyone": ["대명사", "모두"], "august": ["고유명사", "8월"], "pleased": ["형용사", "기쁜"], "wonderful": ["형용사", "멋진"], "number": ["명사", "(number one) 1위"], "sang-hoon": ["고유명사", "상훈(이름)"], "magazine": ["명사", "잡지"], "nation": ["명사", "국가"], "done": ["과거분사", "(well done) 잘했다", "do"], "cash": ["고유명사", "캐시(잡지명)"], "well": ["부사", "잘"], "paris": ["고유명사", "패리스(성)"], "top": ["형용사", "상위의"], "bank": ["명사", "은행"], "work": ["명사", "일"], "continue": ["동사", "계속하다"], "news": ["명사", "소식"], "currency": ["고유명사", "커런시(잡지명)"], "date": ["명사", "날짜"], "subject": ["명사", "제목"], "ten": ["숫자", "10"], "made": ["과거분사", "(목록에) 올랐다", "make"], "inform": ["동사", "알리다"]}}, {"range": "139-142", "passage": "FOR IMMEDIATE RELEASE\nCONTACT: Najib Habib, (318) 555-0187\n(June 1)―The Shreveport Downtown Development Authority is proud to announce the opening of a new health center located at 1700 Joshua Avenue. Shreveport residents are invited ---139--- an open house from 1:30 P.M. to 3:30 P.M. on June 9. The event will include tours of the recently ---140--- building. The center has 28 medical examination rooms, nearly twice as many as its former site. ---141---, it houses two laboratories, a pharmacy, and a physical therapy room. The center will provide a wide range of services. ---142---. We hope to see you at our open house.", "tr": "즉시 배포 / 연락처: Najib Habib, (318) 555-0187\n(6월 1일) — Shreveport 도심개발청은 1700 Joshua Avenue에 새 보건센터를 개소함을 알리게 되어 자랑스럽습니다. Shreveport 주민 여\n러분을 6월 9일 오후 1시 30분부터 3시 30분까지 열리는 개방 행사에 참석하시도록(139) 초대합니다. 행사에는 최근 신축된(140) 건물 견학이 포함됩니다. 센터에는 28개의 진료실이 있으며 이는 이전 부지의 거의 두 배입니다. 또한(141) 실험실 두 곳, 약국, 물리치료실도 갖추고 있습니 다. 센터는 다양한 서비스를 제공할 것입니다. 여기에는 소아, 성인, 1차 및 응급 진료가 포함됩니다(142). 개방 행사에서 뵙기를 바랍니다.", "vocab": "for immediate release 구 즉시 배포용 / authority 명 (공공) 당국 / be proud to 구 ~하게 되어 자랑스럽다 / resident 명 주민 / be invited to 구 ~하도록 초대받다 / open house 명 공개 행사 / constructed 형 건설된 / examination room 명 진료실 / former 형 이전의 / in addition 구 게다가 / house 동 수용하다 / laboratory 명 실험실 / pharmacy 명 약국 / physical therapy 명 물리치료 / a wide range of 구 다양한", "questions": [{"no": 139, "q": "", "options": ["they attended", "attending", "to attend", "the attendance of"], "answer": 2, "explain": "지문 개요: Shreveport 도심개발청이 1700 Joshua Avenue에 새 보건센터를 열어 6월 9일 오후 1시 30분~3시 30분 개방 행사를 하며, 신축 건물에는 이전보다 두 배 가까운 28개 진료실과 실험실 2곳·약국·물리치료실이 있고 소아·성인·1차·응급 진료를 제공한다는 보도자료.\n정답 (C) to attend\n해석: 주민 여러분을 개방 행사에 참석하시도록 초대합니다.\n정답 근거: 5형식 invite + 목적어 + to V의 수동태 are invited to V → to attend. 타동사 attend 뒤 목적어 an open house 있음.\n오답 분석: (A) they attended: 접속사 없이 절을 붙일 수 없음. / (B) attending: are invited 뒤에는 to부정사가 옴. / (D) the attendance of: 명사구 — 초대 구조에 맞지 않음.", "translation": "주민 여러분을 개방 행사에 참석하시도록 초대합니다."}, {"no": 140, "q": "", "options": ["construct", "constructed", "construction", "constructing"], "answer": 1, "explain": "정답 (B) constructed\n해석: 최근 신축된 건물 견학이 포함됩니다.\n정답 근거: 「the recently + 빈칸 + 명사 building」 → 부사 뒤 명사 앞 분사형용사. construct는 타동사이고 건물은 \"지어 지는\" 대상 → -ed constructed.\n오답 분석: (A) construct: 동사 — 명사 앞 불가. / (C) construction: 명사 — 부사 recently의 수식을 받을 수 없음. / (D) constructing: -ing — 건물이 짓는 주체가 아님.", "translation": "최근 신축된 건물 견학이 포함됩니다."}, {"no": 141, "q": "", "options": ["Previously", "In addition", "Until then", "Unfortunately"], "answer": 1, "explain": "정답 (B) In addition\n해석: 또한 실험실 두 곳, 약국, 물리치료실도 갖추고 있습니다.\n정답 근거: 진료실 개수 설명에 이어 추가 시설을 나열 → In addition.\n오답 분석: (A) Previously: '이전에' — 새 시설 소개와 불일치. / (C) Until then: '그때까지' — 불가. / (D) Unfortunately: '유감스럽게도' — 긍정적 소개와 모순.", "translation": "또한 실험실 두 곳, 약국, 물리치료실도 갖추고 있습니다."}, {"no": 142, "q": "", "options": ["These include pediatric, adult, primary, and urgent care.", "They have many years of medical experience.", "Some former staff members are now working elsewhere.", "The waiting room furniture has been donated."], "answer": 0, "explain": "정답 (A) These include pediatric, adult, primary, and urgent care.\n해석: 여기에는 소아, 성인, 1차 및 응급 진료가 포함됩니다.\n정답 근거: 앞 문장 \"다양한 서비스를 제공할 것\"을 These로 받아 구체화하는 문장이 자연스러움.\n오답 분석: (B) They가 가리킬 사람이 앞에 없음. / (C) 전 직원의 이직은 개소 홍보와 무관. / (D) 대기실 가구 기증은 서비스 설명과 무관.", "translation": "여기에는 소아, 성인, 1차 및 응급 진료가 포함됩니다."}], "g": {"as": ["접속사", "~하듯이"], "to": ["전치사", "~에게, ~으로"], "our": ["대명사", "우리의"], "on": ["전치사", "~에"], "its": ["대명사", "그것의"], "3:30": ["숫자", "3시 30분"], "a": ["관사", "하나의"], "many": ["한정사", "많은"], "1700": ["숫자", "1700"], "it": ["대명사", "그것"], "9": ["숫자", "9"], "for": ["전치사", "~을 위해"], "we": ["대명사", "우리"], "from": ["전치사", "~에서"], "has": ["동사", "가지다", "have"], "at": ["전치사", "~에서"], "p.m": ["명사", "오후"], "and": ["접속사", "그리고"], "is": ["동사", "~이다", "be"], "are": ["동사", "~이다", "be"], "28": ["숫자", "28"], "an": ["관사", "하나의"], "318": ["숫자", "318"], "1:30": ["숫자", "1시 30분"], "you": ["대명사", "당신"], "the": ["관사", "그"], "of": ["전치사", "~의"], "will": ["조동사", "~할 것이다"], "services": ["명사", "서비스", "service"], "authority": ["명사", "당국"], "physical": ["형용사", "물리적인"], "wide": ["형용사", "넓은"], "range": ["명사", "범위"], "recently": ["부사", "최근에"], "contact": ["명사", "연락처"], "building": ["명사", "건물"], "habib": ["고유명사", "하비브(성)"], "include": ["동사", "포함하다"], "avenue": ["명사", "거리"], "immediate": ["형용사", "즉각적인"], "house": ["명사", "(open house) 공개 행사"], "shreveport": ["고유명사", "슈리브포트(지명)"], "development": ["명사", "개발"], "twice": ["부사", "두 배"], "therapy": ["명사", "치료"], "june": ["고유명사", "6월"], "residents": ["명사", "주민들", "resident"], "proud": ["형용사", "자랑스러운"], "joshua": ["고유명사", "조슈아(거리명)"], "center": ["명사", "센터"], "event": ["명사", "행사"], "room": ["명사", "실"], "invited": ["과거분사", "초대된", "invite"], "pharmacy": ["명사", "약국"], "opening": ["명사", "개관"], "former": ["형용사", "이전의"], "site": ["명사", "부지, 장소"], "houses": ["동사", "갖추고 있다", "house"], "nearly": ["부사", "거의"], "new": ["형용사", "새로운"], "555-0187": ["숫자", "전화번호"], "laboratories": ["명사", "검사실", "laboratory"], "see": ["동사", "만나다"], "examination": ["명사", "진찰"], "medical": ["형용사", "의료의"], "hope": ["동사", "바라다"], "two": ["숫자", "2"], "najib": ["고유명사", "나지브(이름)"], "provide": ["동사", "제공하다"], "downtown": ["명사", "도심"], "announce": ["동사", "발표하다"], "open": ["형용사", "공개된"], "release": ["명사", "보도"], "tours": ["명사", "견학", "tour"], "rooms": ["명사", "실", "room"], "1)―the": ["숫자", "1일)―그"], "health": ["명사", "보건, 건강"], "located": ["과거분사", "위치한", "locate"]}}, {"range": "143-146", "passage": "To: All Administrative Staff\nFrom: Hye-Jin Nam, Human Resources Manager\nDate: May 15\nSubject: New protocol for time sheet submissions\nAs of June 15, all administrative staff will be required to ---143--- two new time sheet submission procedures. First, all leave requests must now be made through our new online portal, Alpha Time. ---144---. The new online system should be much more efficient. Second, overtime hours must now be listed under the code OH. The code OT is no longer ---145--- in the system. Finally, please note that ---146--- regarding time sheets should now be directed to Karl Figaro.", "tr": "수신: 전 행정직원 / 발신: Hye-Jin Nam, 인사 매니저 / 날짜: 5월 15일 / 제목: 근무 시간표 제출 새 절차\n6월 15일부로 모든 행정직원은 두 가지 새로운 근무 시간표 제출 절차를 준수해야(143) 합니다. 첫째, 모든 휴가 신청은 이제 새 온라인 포털 Alpha Time을 통해 해야 합니다. 현재 소프트웨어는 폐기할 예정입니다(144). 새 온라인 시스템이 훨씬 효율적일 것입니다. 둘째, 초과근무 시간은 이제 코드 OH로 기재해야 합니다. 코드 OT는 시스템에서 더 이상 유효하지(145) 않습니다. 마지막으로 시간표에 관한 질문(146)은 이제 Karl Figaro에게 문의해 주십시오.", "vocab": "protocol 명 규약, 절차 / time sheet 명 근무 시간 기록표 / submission 명 제출 / as of 구 ~부로 / be required to 구 ~해야 한다 / comply with 구 ~을 준수하다 / procedure 명 절차 / leave request 명 휴가 신청 / retire 동 (시스템을) 퇴역시키다 / efficient 형 효율적인 / overtime 명 초과 근무 / valid 형 유효한 / regarding 전 ~에 관한 / be directed to 구 ~에게 전달되다", "questions": [{"no": 143, "q": "", "options": ["design", "provided for", "comply with", "measure"], "answer": 2, "explain": "지문 개요: 인사 매니저 Hye-Jin Nam이 6월 15일부터 휴가 신청은 새 온라인 포털 Alpha Time으로 하고 기존 소프트웨어는 폐기하며, 초과근 무는 코드 OH로 표기(OT는 무효)하고 시간표 관련 문의는 Karl Figaro에게 하라고 알리는 회람.\n정답 (C) comply with\n해석: 두 가지 새로운 제출 절차를 준수해야 합니다.\n정답 근거: be required to 뒤 동사원형이며 뒤 목적어 two new procedures → comply with(~을 준수하다).\n오답 분석: (A) design: '설계하다' — 직원이 절차를 설계하는 것이 아님. / (B) provided for: 수동형이라 required to 뒤 원형 자리에 맞지 않음. / (D) measure: '측정하다' — 의미 불가.", "translation": "두 가지 새로운 제출 절차를 준수해야 합니다."}, {"no": 144, "q": "", "options": ["These policies can be complicated to understand.", "Monday is a vacation day for all staff.", "For instance, it can perform complicated functions.", "We will be retiring our current software."], "answer": 3, "explain": "정답 (D) We will be retiring our current software.\n해석: 현재 소프트웨어는 폐기할 예정입니다.\n정답 근거: 새 온라인 포털 도입 안내 뒤, 기존 시스템 폐기를 알리고 \"새 시스템이 더 효율적\"으로 이어지는 흐름.\n오답 분석: (A) 정책이 복잡하다는 말은 효율성 강조와 모순. / (B) 휴가일 안내는 절차 변경과 무관. / (C) For instance로 예시할 대상이 없음.", "translation": "현재 소프트웨어는 폐기할 예정입니다."}, {"no": 145, "q": "", "options": ["actual", "restricted", "valid", "confident"], "answer": 2, "explain": "정답 (C) valid\n해석: 코드 OT는 시스템에서 더 이상 유효하지 않습니다.\n정답 근거: 새 코드 OH로 바뀌었으므로 기존 코드는 \"유효하지\" 않음 → valid.\n오답 분석: (A) actual: '실제의' — 의미 불가. / (B) restricted: '제한된' — 불가. / (D) confident: '자신 있는' — 사람에게 쓰는 말.", "translation": "코드 OT는 시스템에서 더 이상 유효하지 않습니다."}, {"no": 146, "q": "", "options": ["question", "questions", "questioned", "to question"], "answer": 1, "explain": "정답 (B) questions\n해석: 시간표에 관한 질문은 Karl Figaro에게 문의해 주십시오.\n정답 근거: 동사 should be directed 앞 주어 자리 → 명사. 관사가 없으므로 복수 questions.\n오답 분석: (A) question: 단수 — 관사 없이 쓸 수 없음. / (C) questioned: 과거분사 — 주어 자리 불가. / (D) to question: to부정사 — 주어로 부적절.", "translation": "시간표에 관한 질문은 Karl Figaro에게 문의해 주십시오."}], "g": {"as": ["접속사", "~하듯이"], "to": ["전치사", "~에게, ~으로"], "our": ["대명사", "우리의"], "that": ["접속사", "~라는 것"], "must": ["조동사", "~해야 한다"], "in": ["전치사", "~에"], "through": ["전치사", "~을 통해"], "be": ["동사", "~이다"], "may": ["조동사", "~일지도 모른다"], "for": ["전치사", "~을 위해"], "more": ["형용사", "더 많은"], "under": ["전치사", "~아래에"], "now": ["부사", "지금"], "should": ["조동사", "~해야 한다"], "15": ["숫자", "15"], "of": ["전치사", "~의"], "the": ["관사", "그"], "no": ["한정사", "아무 ~ 없는"], "please": ["부사", "부디"], "from": ["전치사", "~에서"], "is": ["동사", "~이다", "be"], "will": ["조동사", "~할 것이다"], "all": ["한정사", "모든"], "manager": ["명사", "부장, 관리자"], "portal": ["명사", "포털"], "note": ["동사", "유의하다"], "two": ["숫자", "2"], "longer": ["부사", "(no longer) 더 이상", "long"], "ot": ["고유명사", "OT(코드)"], "online": ["형용사", "온라인의"], "karl": ["고유명사", "칼(이름)"], "submission": ["명사", "제출"], "regarding": ["전치사", "~에 관한"], "oh": ["고유명사", "OH(코드)"], "figaro": ["고유명사", "피가로(성)"], "sheets": ["명사", "시트", "sheet"], "submissions": ["명사", "제출", "submission"], "overtime": ["명사", "초과 근무"], "nam": ["고유명사", "남(성)"], "alpha": ["고유명사", "알파(시스템명)"], "efficient": ["형용사", "효율적인"], "time": ["명사", "근무 시간"], "requests": ["명사", "요청", "request"], "second": ["부사", "둘째"], "listed": ["과거분사", "기재된", "list"], "staff": ["명사", "직원"], "resources": ["명사", "자원", "resource"], "hye-jin": ["고유명사", "혜진(이름)"], "human": ["형용사", "(human resources) 인사"], "system": ["명사", "시스템"], "finally": ["부사", "마지막으로"], "sheet": ["명사", "시트"], "leave": ["명사", "휴가"], "protocol": ["명사", "규정"], "hours": ["명사", "시간", "hour"], "new": ["형용사", "새로운"], "directed": ["과거분사", "전달되는", "direct"], "much": ["부사", "훨씬"], "required": ["과거분사", "요구되는", "require"], "june": ["고유명사", "6월"], "first": ["부사", "첫째"], "code": ["명사", "코드"], "date": ["명사", "날짜"], "subject": ["명사", "제목"], "procedures": ["명사", "절차", "procedure"], "administrative": ["형용사", "행정의"], "made": ["과거분사", "이루어지는", "make"]}}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a-r12-p7',$mkd${"id": "a-r12-p7", "part": 7, "title": "A급 과제 12회 · PART 7 (기출독해 4문항 23·24회)", "area": "RC", "group": "A급 과제", "series": 3, "round": 12, "level": "중급", "notes": [], "items": [], "sets": [{"range": "164-167", "passage": "Cornish Pasties At Grover's Mill\nATLANTA (March 23)―When Emily Pascoe arrived in Atlanta from Cornwall in Britain five years ago, she dearly missed a staple from her birthplace―the Cornish pasty. Traditional pasties, which have been on the menu in Cornwall since the area's mining days, consist of a savory crust filled with steak, potatoes, onions, and turnips.\n― [1] ―. After receiving an enthusiastic response when she made her grandmother's version for friends, Ms. Pascoe bought a small food truck and started selling pasties at local festivals. Over time, her business grew to such an extent that she needed more than just a food truck. And so, this Friday, Ms. Pascoe will be opening her store, Cornwall Delights, in the Grover's Mill Shopping Plaza.\n\"I'm so happy to be able to bring this slice of Cornwall to Atlanta,\" Ms. Pascoe said. \"Even though our pasties are authentic and traditionally prepared, many of the ingredients, including the vegetables and the beef, are locally sourced. ― [2] ―. We can also accommodate customers who prefer meatless options.\"\nMs. Pascoe was able to open the shop after receiving a grant from the Atlanta Food Vendors Alliance (AFVA). ― [3] ―. \"I'm very grateful to the organization for providing me with the financial means,\" she said.\nThe grand opening celebration will take place on Friday and Saturday from 12 noon to 6:00 P.M. People residing outside of Atlanta will soon be able to enjoy \"a slice of Cornwall\" as well. ― [4] ―. Cornwall Delights will begin accepting orders online from customers across the country. Visit www.cornwalldelights.com for details.", "tr": "Grover's Mill의 코니시 패스티\n애틀랜타(3월 23일) — 5년 전 영국 콘월에서 애틀랜타로 온 Emily Pascoe는 고향의 대표 음식인 코니시 패스티를 몹시 그리워했다. 콘월 광산 시절부터 그곳 메뉴에 있던 전통 패스티는 스테이크, 감자, 양파, 순무를 채운 짭짤한 파이 껍질로 이루어진다. — [1] —. 친구들에게 할머니의 방식으로 만들어 준 뒤 열렬한 반응을 얻자 Pascoe 씨는 작은 푸드트럭을 사서 지역 축제에서 패스티를 팔기 시작했다. 시간이 지나며 사업이 커져 푸드트럭 이상이 필요해졌다. 그래서 이번 주 금요일 Pascoe 씨는 Grover's Mill 쇼핑 플라자에 Cornwall Delights 매장을 연다. \"콘월의 이한 조각을 애틀랜타에 가져올 수 있어 정말 기쁩니다.\" Pascoe 씨가 말했다. \"저희 패스티는 정통 방식으로 전통적으로 만들지만 채소와 소고기를 포함한 많은 재료를 지역에서 조달합니다. — [2] — [또한 돼지고기나 닭고기가 들어간 종류도 제공합니다.] 고기를 원하지 않는 손님도 맞출 수 있습니다.\" Pascoe 씨는 애틀랜타 식품 판매자 연합(AFVA)의 보조금을 받은 뒤 매장을 열 수 있었다. — [3] —. \"재정적 수단을 마련해 준 이단체에 매우 감사합니다.\" 그녀는 말했다. 개점 기념 행사는 금요일과 토요일 정오부터 오후 6시까지 열린다. 애틀랜타 밖에 사는 사람들도 곧 \"콘월의 한 조각\"을 즐길 수 있게 된다. — [4] —. Cornwall Delights는 전국 고객의 온라인 주문을 받기 시작한다. 자세한 내용은\nwww.cornwalldelights.com에서 확인하면 된다.", "vocab": "dearly 부 몹시 / staple 명 주식, 기본 식품 / birthplace 명 출생지 / consist of 구 ~로 구성되다 / savory 형 짭짤한, 풍미 있는 / crust 명 빵 껍질 / enthusiastic 형 열광적인 / to such an extent that 구 ~할 정도로 / authentic 형 정통의 / locally sourced 형 지역에서 조달된 / accommodate 동 수용하다 / grant 명 보조금 / financial means 명 재정적 수단 / reside 동 거주하다", "questions": [{"no": 164, "q": "What is indicated about Ms. Pascoe?", "options": ["She is not an Atlanta native.", "She is a descendant of a miner.", "She bought her food truck from a friend.", "She owns a local shopping center."], "answer": 0, "explain": "지문 개요: 5년 전 콘월에서 애틀랜타로 온 Emily Pascoe가 할머니 레시피의 코니시 패스티로 인기를 얻어 푸드트럭에서 시작해 AFVA 보조금으로 Grover's Mill 쇼핑 플라자에 매장을 열며, 지역 식재료 사용과 육류·채식 옵션, 전국 온라인 주문 계획을 소개한 기사.\n정답 (A) She is not an Atlanta native.\n해석: Pascoe 씨에 대해 언급된 것은?\n정답 근거: \"5년 전 영국 콘월에서 애틀랜타로 왔다\", \"고향(birthplace)\" → 애틀랜타 태생이 아님.\n오답 분석: (B) 광부의 후손이라는 언급 없음 — 광산 시절은 음식 유래. / (C) 푸드트럭을 친구에게서 샀다는 언급 없음. / (D) 쇼핑 플라자 소유가 아니라 입점.\nParaphrase: arrived in Atlanta from Cornwall in Britain five years ago → not an Atlanta native", "translation": "Pascoe 씨에 대해 언급된 것은?", "g": {"is": ["동사", "~이다", "be"], "ms": ["명사", "~씨(여성)"], "about": ["전치사", "~에 대해"], "what": ["대명사", "무엇"], "indicated": ["과거분사", "나타난", "indicate"], "pascoe": ["고유명사", "파스코(성)"]}, "sub": "4문항 23회"}, {"no": 165, "q": "What does Ms. Pascoe say about the pasties?", "options": ["They are imported from Cornwall.", "Her grandmother helps her make them.", "They take a long time to prepare.", "They are made with ingredients from nearby farms."], "answer": 3, "explain": "정답 (D) They are made with ingredients from nearby farms.\n해석: Pascoe 씨는 패스티에 대해 무엇이라고 말하는가?\n정답 근거: \"채소와 소고기를 포함한 많은 재료를 지역에서 조달한다\" → 인근 농장 재료 사용.\n오답 분석: (A) 콘월에서 수입한다는 언급 없음. / (B) 할머니 레시피일 뿐 할머니가 돕는 것은 아님. / (C) 조리 시간 언급 없음.\nParaphrase: many of the ingredients ... are locally sourced → ingredients from nearby farms", "translation": "Pascoe 씨는 패스티에 대해 무엇이라고 말하는가?", "g": {"does": ["조동사", "(의문문 조동사)", "do"], "ms": ["명사", "~씨(여성)"], "about": ["전치사", "~에 대해"], "what": ["대명사", "무엇"], "the": ["관사", "그"], "say": ["동사", "말하다"], "pascoe": ["고유명사", "파스코(성)"], "pasties": ["명사", "패스티", "pasty"]}, "sub": "4문항 23회"}, {"no": 166, "q": "What is indicated about the AFVA?", "options": ["It donated ingredients for the pasties.", "It provided funding for Ms. Pascoe's business.", "It repaired Ms. Pascoe's food truck.", "It placed a large order of pasties."], "answer": 1, "explain": "정답 (B) It provided funding for Ms. Pascoe's business.\n해석: AFVA에 대해 언급된 것은?\n정답 근거: \"AFVA의 보조금을 받은 뒤 매장을 열 수 있었다\", \"재정적 수단을 마련해 준 단체에 감사\" → 사업 자금 지원.\n오답 분석: (A) 재료 기부 아님. / (C) 푸드트럭 수리 아님. / (D) 대량 주문 아님.\nParaphrase: receiving a grant from the AFVA → provided funding for Ms. Pascoe's business", "translation": "AFVA에 대해 언급된 것은?", "g": {"is": ["동사", "~이다", "be"], "about": ["전치사", "~에 대해"], "what": ["대명사", "무엇"], "indicated": ["과거분사", "나타난", "indicate"], "the": ["관사", "그"], "afva": ["고유명사", "AFVA(단체 약칭)"]}, "sub": "4문항 23회"}, {"no": 167, "q": "In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"Additionally, we offer varieties containing either pork or chicken.\"", "options": ["[1]", "[2]", "[3]", "[4]"], "answer": 1, "explain": "정답 (B) [2]\n해석: [1], [2], [3], [4] 중 \"Additionally, we offer varieties containing either pork or chicken.\"이 들어가기에 가장 적절한 곳은?\n정답 근거: 재료 설명(소고기·채소) 뒤에 다른 육류 종류를 덧붙이고, 이어 \"고기를 원하지 않는 손님도 맞출 수 있다\"로 자연 스럽게 연결됨 → [2].\n오답 분석: (A) [1]은 전통 패스티 설명 뒤로 we가 가리킬 매장 이야기 전. / (C) [3]은 보조금 이야기 중이라 메뉴 설명과 무관. / (D) [4]는 온라인 주문 안내 부분.\nParaphrase: the vegetables and the beef ... / meatless options → varieties containing either pork or chicken ([2])", "translation": "[1], [2], [3], [4] 중 \"Additionally, we offer varieties containing either pork or chicken.\"이 들어가기에 가장 적절한 곳은?", "g": {"or": ["접속사", "또는"], "marked": ["과거분사", "표시된", "mark"], "1": ["숫자", "1"], "3": ["숫자", "3"], "belong": ["동사", "속하다"], "of": ["전치사", "~의"], "in": ["전치사", "~에"], "4": ["숫자", "4"], "positions": ["명사", "위치", "position"], "which": ["관계사", "어느 것"], "sentence": ["명사", "문장"], "and": ["접속사", "그리고"], "we": ["대명사", "우리"], "the": ["관사", "그"], "2": ["숫자", "2"], "following": ["형용사", "다음의"], "best": ["부사", "가장 잘"], "does": ["조동사", "(의문문 조동사)", "do"], "either": ["한정사", "(either A or B) A나 B"], "offer": ["동사", "제공하다"], "pork": ["명사", "돼지고기"], "varieties": ["명사", "종류", "variety"], "additionally": ["부사", "게다가"], "chicken": ["명사", "닭고기"], "containing": ["현재분사", "들어 있는", "contain"]}, "sub": "4문항 23회"}], "g": {"6:00": ["숫자", "6시"], "very": ["부사", "매우"], "just": ["부사", "막, 단지"], "from": ["전치사", "~에서"], "was": ["동사", "~였다", "be"], "12": ["숫자", "12"], "ms": ["명사", "~씨(여성)"], "which": ["관계사", "어느 것"], "more": ["형용사", "더 많은"], "to": ["전치사", "~에게, ~으로"], "as": ["접속사", "~하듯이"], "over": ["전치사", "~이상"], "can": ["조동사", "~할 수 있다"], "when": ["접속사", "~할 때"], "that": ["접속사", "~라는 것"], "for": ["전치사", "~을 위해"], "than": ["접속사", "~보다"], "this": ["한정사", "이"], "in": ["전치사", "~에"], "the": ["관사", "그"], "be": ["동사", "~이다"], "with": ["전치사", "~와 함께"], "a": ["관사", "하나의"], "an": ["관사", "하나의"], "are": ["동사", "~이다", "be"], "3": ["숫자", "3"], "of": ["전치사", "~의"], "after": ["전치사", "~후에"], "who": ["대명사", "누구"], "me": ["대명사", "나를"], "and": ["접속사", "그리고"], "been": ["과거분사", "~였던", 