insert into content(key,data,updated_at) values('sec:a-r13-p6',$mkd${"id": "a-r13-p6", "part": 6, "title": "A급 과제 13회 · PART 6", "area": "RC", "group": "A급 과제", "series": 3, "round": 13, "level": "중급", "notes": [], "items": [], "sets": [{"range": "131-134", "passage": "To: Beatrice Musomba\nFrom: Kyle Payne\nDate: 19 September\nSubject: Thank you\nThank you for considering a ---131--- to the Climbers for Health. Your generous support is greatly appreciated. ---132---.\nBefore you commit, we suggest that you review your employer's policy on the matter. Many employers ---133--- matching-gift programmes to encourage their employees to support charitable organisations. Typically, such programmes match the amount, but some will even double your gift! Please check ---134--- the human resources department at your company to see whether there is a matching programme that would increase your gift to Climbers for Health.\nSincerely,\nKyle Payne, Director\nClimbers for Health", "tr": "수신: Beatrice Musomba / 발신: Kyle Payne / 날짜: 9월 19일 / 제목: 감사합니다\nClimbers for Health에 기부(131)를 고려해 주셔서 감사합니다. 후한 지원에 깊이 감사드립니다. 그것은 저희가 재정 목표에 도달하는 데 도움이 될 것입니다(132).\n확정하시기 전에 이 사안에 관한 고용주의 정책을 확인해 보시기를 권합니다. 많은 고용주가 직원들이 자선 단체를 후원하도록 장려하기 위해 매칭 기부 프로그램을 제공합니다(133). 일반적으로 그런 프로그램은 같은 금액을 맞춰 주지만, 일부는 기부금을 두 배로 만들어 주기도 합니다! Climbers for Health에 대한 기부금을 늘려 줄 매칭 프로그램이 있는지 회사 인사부에(134) 확인해 보십시오.\nKyle Payne, 이사, Climbers for Health 드림", "vocab": "donation 명 기부 / generous 형 후한 / appreciate 동 감사하다 / commit 동 약속하다 / policy 명 정책 / matching-gift 명 매칭 기부 / charitable 형 자선의 / typically 부 일반적으로 / double 동 두 배로 하다 / check with 구 ~에 확인하다", "questions": [{"no": 131, "q": "", "options": ["proposal", "donation", "change", "quality"], "answer": 1, "explain": "지문 개요: Climbers for Health의 Kyle Payne이 기부를 고려해 준 데 감사하며, 기부를 확정하기 전에 회사의 매칭 기부 프로그램이 있는지 인사부에 확인하면 기부금이 두 배가 될 수도 있다고 안내하는 이메일.\n정답 (B) donation\n해석: Climbers for Health에 기부를 고려해 주셔서 감사합니다.\n정답 근거: 자선 단체가 보낸 감사 편지이고 뒤에서 \"후한 지원\", \"매칭 기부 프로그램\"을 말하므로 → donation(기부).\n오답 분석: (A) proposal: '제안' — 감사와 매칭 기부 문맥에 맞지 않음. / (C) change: '변화' — 불가. / (D) quality: '품질' — 불가.", "translation": "Climbers for Health에 기부를 고려해 주셔서 감사합니다."}, {"no": 132, "q": "", "options": ["You may contact us directly by e-mail.", "It will help us reach our financial goals.", "The following steps will be taken.", "Climbing is an increasingly popular sport."], "answer": 1, "explain": "정답 (B) It will help us reach our financial goals.\n해석: 그것은 저희가 재정 목표에 도달하는 데 도움이 될 것입니다.\n정답 근거: 기부에 대한 감사 직후 그 기부(It)가 단체에 어떤 도움이 되는지 설명하는 문장이 자연스러움.\n오답 분석: (A) 이메일 연락 안내는 감사 흐름과 이어지지 않음. / (C) '다음 단계'가 가리킬 절차가 제시되지 않음. / (D) 등반이 인기 스포츠라는 정보는 기부 안내와 무관.", "translation": "그것은 저희가 재정 목표에 도달하는 데 도움이 될 것입니다."}, {"no": 133, "q": "", "options": ["offer", "to offer", "offered", "offering"], "answer": 0, "explain": "정답 (A) offer\n해석: 많은 고용주가 매칭 기부 프로그램을 제공합니다.\n정답 근거: 문장에 동사가 없으므로 동사 자리. 주어 Many employers(복수)와 수일치하고, 타동사 offer 뒤 목적어 programmes가 있어 능동 현재 → offer.\n오답 분석: (B) to offer: to부정사 — 문장의 동사가 없어짐. / (C) offered: 과거 — 일반적 사실을 말하는 현재 문맥과 불일치. / (D) offering: 분사 — 동사 자리에 단독으로 올 수 없음.", "translation": "많은 고용주가 매칭 기부 프로그램을 제공합니다."}, {"no": 134, "q": "", "options": ["of", "on", "with", "off"], "answer": 2, "explain": "정답 (C) with\n해석: 회사 인사부에 확인해 보십시오.\n정답 근거: check with + 사람/부서(~에게 문의해 확인하다) 형태 → with.\n오답 분석: (A) of: check of는 쓰지 않음. / (B) on: 'check on'은 '~을 살펴보다'로 대상이 사물일 때 쓰며 문의 대상 표현과 다름. / (D) off: 'check off'는 '목록에서 지우다' — 의미 불가.", "translation": "회사 인사부에 확인해 보십시오."}], "g": {"the": ["관사", "그"], "would": ["조동사", "~할 것이다"], "to": ["전치사", "~에게, ~으로"], "on": ["전치사", "~에"], "will": ["조동사", "~할 것이다"], "but": ["접속사", "그러나"], "you": ["대명사", "당신"], "sincerely": ["부사", "진심으로"], "some": ["한정사", "일부의"], "is": ["동사", "~이다", "be"], "please": ["부사", "부디"], "there": ["부사", "거기에"], "we": ["대명사", "우리"], "thank": ["동사", "감사하다"], "their": ["대명사", "그들의"], "whether": ["접속사", "~인지"], "that": ["접속사", "~라는 것"], "a": ["관사", "하나의"], "for": ["전치사", "~을 위해"], "at": ["전치사", "~에서"], "many": ["한정사", "많은"], "from": ["전치사", "~에서"], "your": ["대명사", "당신의"], "19": ["숫자", "19"], "before": ["접속사", "~전에"], "employers": ["명사", "고용주들", "employer"], "encourage": ["동사", "장려하다"], "programme": ["명사", "프로그램"], "beatrice": ["고유명사", "비어트리스(이름)"], "health": ["고유명사", "헬스(단체명)"], "date": ["명사", "날짜"], "human": ["형용사", "(human resources) 인사"], "gift": ["명사", "기부금"], "increase": ["동사", "늘리다"], "company": ["명사", "회사"], "double": ["동사", "두 배로 하다"], "director": ["명사", "대표"], "commit": ["동사", "약속하다"], "matter": ["명사", "문제"], "review": ["동사", "검토하다"], "programmes": ["명사", "프로그램", "programme"], "generous": ["형용사", "너그러운"], "department": ["명사", "부서"], "subject": ["명사", "제목"], "matching-gift": ["형용사", "매칭 기부의"], "september": ["고유명사", "9월"], "charitable": ["형용사", "자선의"], "check": ["동사", "확인하다"], "see": ["동사", "알아보다"], "match": ["동사", "같은 금액을 내다"], "employees": ["명사", "직원들", "employee"], "kyle": ["고유명사", "카일(이름)"], "typically": ["부사", "일반적으로"], "amount": ["명사", "금액"], "matching": ["형용사", "매칭의"], "support": ["명사", "후원"], "payne": ["고유명사", "페인(성)"], "employer's": ["명사", "고용주의", "employer"], "policy": ["명사", "방침"], "appreciated": ["과거분사", "감사히 여겨지는", "appreciate"], "organisations": ["명사", "단체", "organisation"], "even": ["부사", "심지어"], "suggest": ["동사", "제안하다"], "climbers": ["고유명사", "클라이머스(단체명)"], "musomba": ["고유명사", "무솜바(성)"], "considering": ["동명사", "고려하는 것", "consider"], "resources": ["명사", "자원", "resource"], "greatly": ["부사", "크게"], "such": ["한정사", "그러한"]}}, {"range": "135-138", "passage": "From: Chief Information Security Officer\nTo: All Employees\nSubject: Application updates\nDate: Monday, December 2\nE-mail application updates will be released automatically to all networked computers beginning at 5 P.M. on Friday. In order for your computer to receive the updates, ---135--- must be restarted. If you are running any programs ---136--- your computer to stay on without interruption, the process may not be completed. ---137---. To avoid this, we recommend postponing any lengthy processing tasks until next week. The updates will improve the security of our e-mail system. They will ---138--- ensure our compliance with industry standards.", "tr": "발신: 정보보안 최고책임자 / 수신: 전 직원 / 제목: 프로그램 업데이트 / 날짜: 12월 2일 월요일\n이메일 프로그램 업데이트가 금요일 오후 5시부터 네트워크에 연결된 모든 컴퓨터에 자동으로 배포됩니다. 컴퓨터가 업데이트를 받으려면 그것 (135)을 재시작해야 합니다. 컴퓨터가 중단 없이 켜져 있기를 요구하는(136) 프로그램을 실행 중이라면 그 과정이 완료되지 않을 수 있습니다. 그런 경우에는 업데이트를 수동으로 설치해야 합니다(137). 이를 피하려면 긴 처리 작업은 다음 주로 미루시길 권합니다. 이번 업데이트는 이메 일 시스템의 보안을 향상시킬 것입니다. 또한(138) 업계 표준 준수를 보장할 것입니다.", "vocab": "release 동 배포하다 / automatically 부 자동으로 / restart 동 재시작하다 / require 동 필요로 하다 / interruption 명 중단 / complete 동 완료하다 / postpone 동 미루다 / lengthy 형 긴 / manually 부 수동으로 / compliance 명 준수", "questions": [{"no": 135, "q": "", "options": ["it", "ones", "both", "some"], "answer": 0, "explain": "지문 개요: 정보보안 책임자가 금요일 오후 5시부터 자동 배포되는 이메일 프로그램 업데이트를 받으려면 컴퓨터를 재시작해야 하며, 중단 없이 실행해야 하는 프로그램이 있으면 업데이트가 완료되지 않아 수동 설치가 필요하니 긴 작업은 다음 주로 미루라고 안내하는 회람.\n정답 (A) it\n해석: 컴퓨터가 업데이트를 받으려면 그것을 재시작해야 합니다.\n정답 근거: 앞의 your computer(단수)를 다시 가리키는 대명사 자리이며 동사가 must be restarted(단수) → it.\n오답 분석: (B) ones: 복수 — 앞의 단수 your computer와 불일치. / (C) both: 두 대상이 제시되지 않음. / (D) some: 복수 취급 — 가리킬 대상이 없음.", "translation": "컴퓨터가 업데이트를 받으려면 그것을 재시작해야 합니다."}, {"no": 136, "q": "", "options": ["to be requiring", "a requirement", "were required", "that require"], "answer": 3, "explain": "정답 (D) that require\n해석: 컴퓨터가 중단 없이 켜져 있기를 요구하는 프로그램\n정답 근거: 이미 절의 동사 are running이 있고 접속사가 없으므로 동사를 또 쓸 수 없음 → 선행사 programs를 꾸미는 주격 관계대명사 that + 동사 require(선행사 복수와 수일치). 5형식 require + 목적어 your computer + to V.\n오답 분석: (A) to be requiring: to부정사 진행형 — 뒤 구조와 연결되지 않음. / (B) a requirement: 명사 — 뒤의 your computer to stay on을 연결할 수 없음. / (C) were required: 접속사 없이 동사가 하나 더 오게 되고, 뒤에 목적어가 있어 수동도 불가.", "translation": "컴퓨터가 중단 없이 켜져 있기를 요구하는 프로그램"}, {"no": 137, "q": "", "options": ["For example, all computers have a unique identification code.", "Therefore, please complete the form as soon as possible.", "In such cases, the updates must be manually installed.", "However, a list of recently updated programs is attached."], "answer": 2, "explain": "정답 (C) In such cases, the updates must be manually installed.\n해석: 그런 경우에는 업데이트를 수동으로 설치해야 합니다.\n정답 근거: 앞 문장 \"업데이트 과정이 완료되지 않을 수 있다\"를 In such cases로 받아 대응 방법을 제시하는 흐름이 자연스 러움.\n오답 분석: (A) 식별 코드 설명은 업데이트 완료 여부와 무관. / (B) 양식 작성 요청은 앞 내용과 연결되지 않음. / (D) 업데이트된 프로그램 목록 첨부는 언급된 바 없음.", "translation": "그런 경우에는 업데이트를 수동으로 설치해야 합니다."}, {"no": 138, "q": "", "options": ["also", "instead", "otherwise", "since"], "answer": 0, "explain": "정답 (A) also\n해석: 또한 업계 표준 준수를 보장할 것입니다.\n정답 근거: 앞 문장의 \"보안을 향상시킨다\"에 이어 또 다른 효과를 추가 → also. 조동사 will과 동사원형 ensure 사이 부사 자리.\n오답 분석: (B) instead: '대신에' — 대체 관계가 아님. / (C) otherwise: '그렇지 않으면' — 조건 관계가 아님. / (D) since: 접속사 — 부사 자리에 올 수 없음.", "translation": "또한 업계 표준 준수를 보장할 것입니다."}], "g": {"the": ["관사", "그"], "this": ["한정사", "이"], "may": ["조동사", "~일지도 모른다"], "be": ["동사", "~이다"], "to": ["전치사", "~에게, ~으로"], "on": ["전치사", "~에"], "until": ["전치사", "~까지"], "will": ["조동사", "~할 것이다"], "any": ["한정사", "어떤"], "are": ["동사", "~이다", "be"], "you": ["대명사", "당신"], "of": ["전치사", "~의"], "without": ["전치사", "~없이"], "all": ["한정사", "모든"], "we": ["대명사", "우리"], "our": ["대명사", "우리의"], "must": ["조동사", "~해야 한다"], "if": ["접속사", "만약 ~라면"], "2": ["숫자", "2"], "5": ["숫자", "5"], "with": ["전치사", "~와 함께"], "for": ["전치사", "~을 위해"], "they": ["대명사", "그들"], "not": ["부사", "~않다"], "p.m": ["명사", "오후"], "at": ["전치사", "~에서"], "in": ["전치사", "~에"], "next": ["부사", "다음에"], "from": ["전치사", "~에서"], "your": ["대명사", "당신의"], "monday": ["고유명사", "월요일"], "week": ["명사", "주"], "system": ["명사", "시스템"], "receive": ["동사", "받다"], "application": ["명사", "애플리케이션"], "december": ["고유명사", "12월"], "date": ["명사", "날짜"], "postponing": ["동명사", "미루는 것", "postpone"], "released": ["과거분사", "배포되는", "release"], "security": ["명사", "보안"], "ensure": ["동사", "보장하다"], "friday": ["고유명사", "금요일"], "processing": ["명사", "처리"], "standards": ["명사", "표준", "standard"], "information": ["명사", "정보"], "automatically": ["부사", "자동으로"], "completed": ["과거분사", "완료된", "complete"], "improve": ["동사", "개선하다"], "restarted": ["과거분사", "재시작되는", "restart"], "compliance": ["명사", "준수"], "programs": ["명사", "프로그램", "program"], "subject": ["명사", "제목"], "officer": ["명사", "책임자"], "running": ["현재분사", "실행하는", "run"], "chief": ["형용사", "최고의"], "employees": ["명사", "직원들", "employee"], "interruption": ["명사", "중단"], "order": ["명사", "(in order for) ~하기 위해"], "beginning": ["현재분사", "시작하는", "begin"], "industry": ["명사", "업계"], "avoid": ["동사", "피하다"], "networked": ["형용사", "네트워크로 연결된"], "updates": ["명사", "업데이트", "update"], "stay": ["동사", "유지하다"], "computer": ["명사", "컴퓨터"], "process": ["명사", "과정"], "e-mail": ["명사", "이메일"], "computers": ["명사", "컴퓨터", "computer"], "recommend": ["동사", "권장하다"], "tasks": ["명사", "작업", "task"], "lengthy": ["형용사", "긴"]}}, {"range": "139-142", "passage": "Elsner Eye Associates - Appointment Cancellation Policies\nAt Elsner Eye Associates, we are ---139--- focused on patient satisfaction. To better serve all our patients, the following policies will take effect immediately.\n---140---. Your timely cancellation will allow another patient to receive care. To cancel, please call the office during business hours. Cancellation via e-mail, text, or voice mail will not be accepted. If a patient fails to cancel at least 24 hours prior to the appointment, it will be considered a missed appointment. After the first missed appointment, a note will be made in the patient's record. A ---141--- missed appointment will result in a $30 fee billed to the patient's account. A patient will be ---142--- a $50 fee per absence for any additional missed appointments. Future appointments will not be scheduled until any outstanding fee has been paid in full.", "tr": "Elsner Eye Associates — 예약 취소 규정\nElsner Eye Associates에서 저희는 분명하게(139) 환자 만족에 중점을 두고 있습니다. 모든 환자에게 더 나은 서비스를 제공하기 위해 다음 규정이 즉시 시행됩니다. 예약 수요가 매우 많습니다(140). 제때 취소해 주시면 다른 환자가 진료를 받을 수 있습니다. 취소하시려면 영업시간 중에 사무실로 전화해 주십시오. 이메일, 문자, 음성 메시지를 통한 취소는 받지 않습니다. 예약 최소 24시간 전에 취소하지 않으면 예약 불이행으로 간주됩니다. 첫 번째 예약 불이행 후에는 환자 기록에 메모가 남습니다. 두 번째(141) 예약 불이행에는 환자 계정으로 30달러의 요금이 청구됩니 다. 추가 예약 불이행부터는 환자에게 결석 건당 50달러가 청구됩니다(142). 미납 요금이 완납될 때까지 향후 예약은 잡히지 않습니다.", "vocab": "cancellation 명 취소 / satisfaction 명 만족 / take effect 구 효력이 발생하다 / timely 형 시기적절한 / via 전 ~을 통해 / prior to 전 ~전에 / result in 구 ~을 초래하다 / bill 동 청구하다 / charge 동 (요금을) 부과하다 / outstanding 형 미지불된", "questions": [{"no": 139, "q": "", "options": ["clear", "clearer", "cleared", "clearly"], "answer": 3, "explain": "지문 개요: Elsner Eye Associates가 예약 취소는 영업시간 중 전화로만 받으며, 24시간 전에 취소하지 않으면 예약 불이행으로 처리해 1회째는 기록, 2회째는 30달러, 이후에는 건당 50달러를 청구하고 미납 시 다음 예약을 잡지 않는다고 안내하는 규정.\n정답 (D) clearly\n해석: 저희는 분명하게 환자 만족에 중점을 두고 있습니다.\n정답 근거: be동사 are와 분사 focused 사이 빈칸 → 분사(형용사)를 꾸미는 부사 clearly. focus는 타동사이지만 뒤에 목적 어 없이 전치사구 on ~이 오므로 수동형 are focused.\n오답 분석: (A) clear: 형용사 — 형용사 focused를 꾸밀 수 없음. / (B) clearer: 형용사 비교급 — 불가. / (C) cleared: 과거분사 — 부사 자리 불가.", "translation": "저희는 분명하게 환자 만족에 중점을 두고 있습니다."}, {"no": 140, "q": "", "options": ["Bills are sent by mail on the first day of each month.", "Appointments are in high demand.", "Saturday appointments are available.", "Please bring your completed medical history."], "answer": 1, "explain": "정답 (B) Appointments are in high demand.\n해석: 예약 수요가 매우 많습니다.\n정답 근거: 바로 뒤 문장 \"제때 취소해 주시면 다른 환자가 진료를 받을 수 있다\"의 이유가 되는 문장 → 예약 수요가 많다는 내 용.\n오답 분석: (A) 청구서 발송일 안내는 취소 규정 도입부와 연결되지 않음. / (C) 토요일 예약 안내는 취소 문맥과 무관. / (D) 병력 서류 지참은 취소 규정과 무관.", "translation": "예약 수요가 매우 많습니다."}, {"no": 141, "q": "", "options": ["required", "prior", "second", "preliminary"], "answer": 2, "explain": "정답 (C) second\n해석: 두 번째 예약 불이행에는 30달러의 요금이 청구됩니다.\n정답 근거: 앞 문장이 \"첫 번째 불이행 후에는 기록만 남긴다\"이고 뒤 문장이 \"추가 불이행부터 50달러\"이므로 그 사이 단계 → second(두 번째).\n오답 분석: (A) required: '요구된' — 예약 불이행을 꾸미기에 의미 불가. / (B) prior: '이전의' — 순서 흐름과 맞지 않음. / (D) preliminary: '예비의' — 불가.", "translation": "두 번째 예약 불이행에는 30달러의 요금이 청구됩니다."}, {"no": 142, "q": "", "options": ["charge", "charged", "charging", "charges"], "answer": 1, "explain": "정답 (B) charged\n해석: 추가 예약 불이행부터는 환자에게 건당 50달러가 청구됩니다.\n정답 근거: will be 뒤 자리. charge는 4형식으로 쓸 수 있는 타동사(charge + 사람 + 금액)이며 주어가 환자(요금을 부과받는 쪽)이고 빈칸 뒤에 금액 a $50 fee만 남아 있으므로 수동 → will be charged.\n오답 분석: (A) charge: 원형 — will be 뒤에 올 수 없음. / (C) charging: 능동 진행 — 환자가 요금을 부과하는 주체가 되어 불가. / (D) charges: 동사 — will be 뒤 불가.", "translation": "추가 예약 불이행부터는 환자에게 건당 50달러가 청구됩니다."}], "g": {"be": ["동사", "~이다"], "all": ["한정사", "모든"], "please": ["부사", "부디"], "we": ["대명사", "우리"], "24": ["숫자", "24"], "for": ["전치사", "~을 위해"], "at": ["전치사", "~에서"], "it": ["대명사", "그것"], "your": ["대명사", "당신의"], "or": ["접속사", "또는"], "any": ["한정사", "어떤"], "via": ["전치사", "~을 통해"], "our": ["대명사", "우리의"], "if": ["접속사", "만약 ~라면"], "not": ["부사", "~않다"], "after": ["전치사", "~후에"], "following": ["형용사", "다음의"], "to": ["전치사", "~에게, ~으로"], "on": ["전치사", "~에"], "until": ["전치사", "~까지"], "will": ["조동사", "~할 것이다"], "are": ["동사", "~이다", "be"], "been": ["과거분사", "~였던", "be"], "a": ["관사", "하나의"], "has": ["동사", "가지다", "have"], "the": ["관사", "그"], "during": ["전치사", "~동안"], "per": ["전치사", "~당"], "in": ["전치사", "~에"], "receive": ["동사", "받다"], "text": ["명사", "문자"], "first": ["형용사", "첫 번째의"], "patients": ["명사", "환자들", "patient"], "care": ["명사", "진료"], "made": ["과거분사", "남겨지는", "make"], "account": ["명사", "계정"], "hours": ["명사", "시간", "hour"], "serve": ["동사", "모시다"], "fails": ["동사", "하지 못하다", "fail"], "missed": ["과거분사", "놓친", "miss"], "better": ["부사", "더 잘", "well"], "voice": ["명사", "음성"], "record": ["명사", "기록"], "call": ["동사", "전화하다"], "mail": ["명사", "(voice mail) 음성 메시지"], "billed": ["과거분사", "청구된", "bill"], "patient's": ["명사", "환자의", "patient"], "satisfaction": ["명사", "만족"], "considered": ["과거분사", "간주되는", "consider"], "scheduled": ["과거분사", "예약되는", "schedule"], "cancel": ["동사", "취소하다"], "note": ["명사", "메모"], "$50": ["숫자", "50달러"], "allow": ["동사", "가능하게 하다"], "business": ["명사", "(business hours) 영업"], "effect": ["명사", "(take effect) 시행되다"], "absence": ["명사", "불참"], "prior": ["형용사", "(prior to) ~전에"], "timely": ["형용사", "시기적절한"], "full": ["명사", "(in full) 전액"], "fee": ["명사", "수수료"], "eye": ["명사", "안과, 눈"], "result": ["동사", "(result in) 초래하다"], "associates": ["고유명사", "어소시에이츠(병원명)"], "focused": ["과거분사", "집중하는", "focus"], "policies": ["명사", "방침", "policy"], "$30": ["숫자", "30달러"], "additional": ["형용사", "추가의"], "least": ["형용사", "(at least) 최소한"], "elsner": ["고유명사", "엘스너(병원명)"], "patient": ["명사", "환자"], "paid": ["과거분사", "지불된", "pay"], "outstanding": ["형용사", "미납된"], "e-mail": ["명사", "이메일"], "accepted": ["과거분사", "받아들여지는", "accept"], "another": ["한정사", "다른"], "appointment": ["명사", "예약"], "cancellation": ["명사", "취소"], "immediately": ["부사", "즉시"], "take": ["동사", "(take effect) 시행되다"], "appointments": ["명사", "예약", "appointment"], "office": ["명사", "진료실"], "future": ["형용사", "향후의"]}}, {"range": "143-146", "passage": "Hire Experts to Get Your Message Heard!\nDoes your small business need to communicate an important message to the public? Writing your own press release is one option. ---143---, how-to guides and similar resources are readily available. However, writing the perfect press release takes practice and expertise. ---144---. Why go through all the trouble when ---145--- can simply hire our professional writers at PR News Pop to do it better - and in less time? Our team of experts will craft the perfect press release and distribute it to your intended audience. We have long-standing relationships with journalists who cover a range of industries. These ---146--- are priceless when it is time to get your message out to the public.\nGo to prnewspop.com today. We will have your press release written and distributed within 24 hours!", "tr": "메시지를 알리려면 전문가를 고용하세요!\n소규모 사업체가 대중에게 중요한 메시지를 전해야 하나요? 직접 보도자료를 쓰는 것도 한 가지 방법입니다. 어쨌든(143) 사용법 안내서와 비슷 한 자료는 손쉽게 구할 수 있습니다. 하지만 완벽한 보도자료를 쓰는 데는 연습과 전문 지식이 필요합니다. 누구나 그것을 잘할 수 있는 것은 아닙니다(144). 여러분(145)이 PR News Pop의 전문 작가를 고용해 더 잘, 더 짧은 시간에 처리할 수 있는데 왜 그 모든 수고를 겪으시나요? 저희 전문가 팀이 완벽한 보도자료를 정교하게 작성해 의도하신 독자층에 배포해 드립니다. 저희는 다양한 업계를 취재하는 기자들과 오랜 관계를 맺고 있습니다. 대중에게 메시지를 알려야 할 때 이러한 인맥(146)은 값을 매길 수 없을 만큼 소중합니다.\n오늘 prnewspop.com을 방문하세요. 24시간 내에 보도자료를 작성해 배포해 드립니다!", "vocab": "press release 명 보도 자료 / readily 부 손쉽게 / expertise 명 전문 지식 / after all 구 어쨌든, 결국 / go through 구 겪다 / craft 동 정교하게 만들다 / distribute 동 배포하다 / intended 형 의도된 / long-standing 형 오래된 / contact 명 인맥, 연락처", "questions": [{"no": 143, "q": "", "options": ["On the other hand", "In the meantime", "Nevertheless", "After all"], "answer": 3, "explain": "지문 개요: PR News Pop이 직접 보도자료를 쓰는 것도 가능하지만 완벽한 보도자료 작성에는 연습과 전문성이 필요하다며, 전문 작가가 24시 간 내에 보도자료를 작성·배포하고 다양한 업계 기자들과의 오랜 인맥을 활용한다고 홍보하는 광고.\n정답 (D) After all\n해석: 어쨌든 사용법 안내서와 비슷한 자료는 손쉽게 구할 수 있습니다.\n정답 근거: 앞 문장 \"직접 쓰는 것도 한 방법\"에 대한 근거를 덧붙이는 흐름 → After all(어쨌든, 따지고 보면).\n오답 분석: (A) On the other hand: '반면에' — 대조가 아니라 근거 보충. / (B) In the meantime: '그동안에' — 시간 관계가 아님. / (C) Nevertheless: '그럼에도 불구하고' — 역접은 뒤 문장의 However가 담당.", "translation": "어쨌든 사용법 안내서와 비슷한 자료는 손쉽게 구할 수 있습니다."}, {"no": 144, "q": "", "options": ["That is not our goal.", "Not everyone can do it well.", "We can upload them quickly.", "They are published twice a day."], "answer": 1, "explain": "정답 (B) Not everyone can do it well.\n해석: 누구나 그것을 잘할 수 있는 것은 아닙니다.\n정답 근거: 앞 문장 \"완벽한 보도자료 작성에는 연습과 전문성이 필요하다\"를 받아 아무나 잘하지 못한다고 이어가고, 뒤의 \"전문가를 고용하라\"로 연결됨.\n오답 분석: (A) 목표가 아니라는 서술은 지시 대상이 없음. / (C) 업로드 속도 이야기는 문맥과 무관. / (D) 하루 두 번 발행된다는 정보는 무관.", "translation": "누구나 그것을 잘할 수 있는 것은 아닙니다."}, {"no": 145, "q": "", "options": ["you", "we", "us", "either"], "answer": 0, "explain": "정답 (A) you\n해석: 여러분이 저희 전문 작가를 고용할 수 있는데 왜 그 수고를 하시나요?\n정답 근거: when절의 주어 자리. 광고가 독자에게 \"저희를 고용하라\"고 권하는 문맥이므로 고용하는 주체는 독자 → you.\n오답 분석: (B) we: 광고주가 스스로를 고용한다는 뜻이 되어 불가. / (C) us: 목적격 — 주어 자리 불가. / (D) either: 두 대상이 제시되지 않아 의미 불가.", "translation": "여러분이 저희 전문 작가를 고용할 수 있는데 왜 그 수고를 하시나요?"}, {"no": 146, "q": "", "options": ["devices", "contacts", "procedures", "events"], "answer": 1, "explain": "정답 (B) contacts\n해석: 이러한 인맥은 값을 매길 수 없을 만큼 소중합니다.\n정답 근거: 앞 문장의 \"다양한 업계를 취재하는 기자들과의 오랜 관계\"를 가리키는 말 → contacts(인맥).\n오답 분석: (A) devices: '기기' — 지시 대상과 불일치. / (C) procedures: '절차' — 불가. / (D) events: '행사' — 불가.", "translation": "이러한 인맥은 값을 매길 수 없을 만큼 소중합니다."}], "g": {"do": ["동사", "하다"], "these": ["한정사", "이"], "all": ["한정사", "모든"], "we": ["대명사", "우리"], "24": ["숫자", "24"], "at": ["전치사", "~에서"], "it": ["대명사", "그것"], "your": ["대명사", "당신의"], "within": ["전치사", "~이내에"], "of": ["전치사", "~의"], "our": ["대명사", "우리의"], "with": ["전치사", "~와 함께"], "to": ["전치사", "~에게, ~으로"], "will": ["조동사", "~할 것이다"], "when": ["접속사", "~할 때"], "are": ["동사", "~이다", "be"], "have": ["동사", "가지다"], "is": ["동사", "~이다", "be"], "why": ["부사", "왜"], "and": ["접속사", "그리고"], "does": ["조동사", "(의문문 조동사)", "do"], "a": ["관사", "하나의"], "can": ["조동사", "~할 수 있다"], "the": ["관사", "그"], "who": ["대명사", "누구"], "an": ["관사", "하나의"], "in": ["전치사", "~에"], "through": ["전치사", "~을 통해"], "pr": ["고유명사", "PR(회사명)"], "out": ["부사", "(get out) 널리"], "craft": ["동사", "공들여 만들다"], "how-to": ["형용사", "방법을 알려 주는"], "hire": ["동사", "고용하다"], "less": ["형용사", "더 적은"], "hours": ["명사", "시간", "hour"], "own": ["형용사", "자신의"], "practice": ["명사", "연습"], "today": ["부사", "오늘"], "better": ["부사", "더 잘", "well"], "range": ["명사", "다양함"], "resources": ["명사", "자료", "resource"], "release": ["명사", "(press release) 보도 자료"], "expertise": ["명사", "전문 지식"], "get": ["동사", "(get out) 알리다"], "communicate": ["동사", "전달하다"], "news": ["고유명사", "뉴스(회사명)"], "readily": ["부사", "손쉽게"], "experts": ["명사", "전문가", "expert"], "takes": ["동사", "필요로 하다", "take"], "message": ["명사", "메시지"], "journalists": ["명사", "기자들", "journalist"], "writers": ["명사", "작가들", "writer"], "public": ["명사", "대중"], "business": ["명사", "사업체"], "guides": ["명사", "안내서", "guide"], "heard": ["과거분사", "들리는", "hear"], "writing": ["동명사", "작성하는 것", "write"], "intended": ["형용사", "의도한"], "similar": ["형용사", "비슷한"], "available": ["형용사", "구할 수 있는"], "trouble": ["명사", "수고"], "long-standing": ["형용사", "오래된"], "small": ["형용사", "작은"], "however": ["부사", "그러나"], "audience": ["명사", "대상 독자"], "important": ["형용사", "중요한"], "need": ["동사", "필요하다"], "perfect": ["형용사", "완벽한"], "relationships": ["명사", "관계", "relationship"], "option": ["명사", "선택지"], "professional": ["형용사", "전문적인"], "distributed": ["과거분사", "배포된", "distribute"], "distribute": ["동사", "배포하다"], "industries": ["명사", "업계", "industry"], "go": ["동사", "(go through) 겪다"], "press": ["명사", "(press release) 보도"], "cover": ["동사", "다루다"], "pop": ["고유명사", "팝(회사명)"], "simply": ["부사", "간단히"], "one": ["숫자", "하나의"], "time": ["명사", "시간, 때"], "priceless": ["형용사", "매우 귀중한"], "written": ["과거분사", "작성된", "write"], "prnewspop.com": ["고유명사", "웹사이트 주소"], "team": ["명사", "팀"]}}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a-r13-p7',$mkd${"id": "a-r13-p7", "part": 7, "title": "A급 과제 13회 · PART 7 (기출독해 4문항 25·26회)", "area": "RC", "group": "A급 과제", "series": 3, "round": 13, "level": "중급", "notes": [], "items": [], "sets": [{"range": "164-167", "passage": "Marcus Schmidt · 4 Gaffney Street · South Melbourne VIC 3205 8 February\nKylie Garimara\nAnywhere Deliveries Ltd.\n60 Parkes Road\nMelbourne VIC 3000\nDear Ms. Garimara,\nI am writing to apply for the position of truck driver at Anywhere Deliveries Ltd. My colleague Byung-Hun Hahn recommended that I send you my CV, which is enclosed. Mr. Hahn and I have known each other since we attended truck-driving school together, and he mentioned how much he enjoys transporting goods for Anywhere Deliveries.\nAs a dedicated and hardworking individual, I offer twelve years of experience transporting and delivering goods from warehouses to retail stores and businesses. I started off delivering fresh produce for Anerap Company and now deliver construction machinery for Simpson Trucking. I take great pride in always doing my work in a safe and timely manner.\nAs a driver for Simpson Trucking, I travel across the country, often driving hundreds or thousands of kilometres in a single round trip. I was commended by my manager for my 91 percent efficiency rating and for my ability to effectively communicate with mechanics, engineers, customers, and other drivers. Additionally, I was honoured to be selected as the Employee of the Year at Simpson Trucking two years ago.\nI look forward to an opportunity to hear back from you about my application.\nSincerely,\nMarcus Schmidt\nEnclosure", "tr": "Marcus Schmidt · 4 Gaffney Street · South Melbourne VIC 3205 / 2월 8일\nKylie Garimara / Anywhere Deliveries Ltd. / 60 Parkes Road / Melbourne VIC 3000\nGarimara 씨께, Anywhere Deliveries Ltd.의 트럭 기사직에 지원하고자 편지를 씁니다. 제 동료 Byung-Hun Hahn이 이력서를 보내 보라고 추천했고, 이력서를 동봉합니다. Hahn 씨와 저는 트럭 운전 학교를 함께 다닌 이후로 서로 알고 지냈으며, 그는 Anywhere Deliveries를 위해 화물을 운송하는 일을 얼마나 즐기는지 이야기해 주었습니다.\n헌신적이고 성실한 사람으로서 저는 창고에서 소매점과 사업체로 화물을 운송·배송한 12년의 경력을 갖추고 있습니다. Anerap Company에 서 신선 농산물을 배송하는 일로 시작해 지금은 Simpson Trucking에서 건설 기계를 운송합니다. 저는 언제나 안전하고 시기적절한 방식으로 일하는 것을 자랑스럽게 여깁니다.\nSimpson Trucking의 기사로서 저는 전국을 다니며 한 번의 왕복에 수백에서 수천 킬로미터를 운전하는 일이 잦습니다. 저는 91%의 효율성 평가와 정비사, 엔지니어, 고객, 다른 기사들과 효과적으로 소통하는 능력으로 관리자에게 칭찬을 받았습니다. 또한 2년 전에는 Simpson Trucking에서 올해의 직원으로 선정되는 영광을 누렸습니다.\n제 지원에 관한 회신을 들을 기회를 고대합니다. Marcus Schmidt 드림 / 동봉물 있음", "vocab": "apply for 구 ~에 지원하다 / colleague 명 동료 / enclosed 형 동봉된 / dedicated 형 헌신적인 / produce 명 농산물 / machinery 명 기계류 / take pride in 구 ~을 자랑스러워하다 / timely 형 시기적절한 / commend 동 칭찬하다 / efficiency 명 효율성", "questions": [{"no": 164, "q": "Who most likely is Mr. Hahn?", "options": ["A hiring manager", "A driving instructor", "A store owner", "A truck driver"], "answer": 3, "explain": "지문 개요: Marcus Schmidt가 Anywhere Deliveries의 트럭 기사직에 지원하며, 트럭 운전 학교 동기이자 현재 그 회사에서 일하는 Byung- Hun Hahn의 추천으로 이력서를 보낸다고 밝히고, 12년 경력(농산물 배송에서 현재 건설 기계 운송), 91% 효율 평가와 올해의 직원 수상 이력을 소개하는 지원 편지.\n정답 (D) A truck driver\n해석: Hahn 씨는 누구일 것 같은가?\n정답 근거: 트럭 운전 학교를 함께 다녔고 \"Anywhere Deliveries를 위해 화물을 운송하는 일을 즐긴다\"고 함 → 트럭 기사.\n오답 분석: (A) 채용 담당자는 수신인 Garimara 씨. / (B) 운전 강사가 아니라 학교 동기. / (C) 상점 주인 언급 없음.\nParaphrase: he enjoys transporting goods for Anywhere Deliveries → a truck driver", "translation": "Hahn 씨는 누구일 것 같은가?", "g": {"is": ["동사", "~이다", "be"], "who": ["대명사", "누구"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "mr": ["명사", "~씨(남성)"], "hahn": ["고유명사", "한(성)"]}, "sub": "4문항 25회"}, {"no": 165, "q": "What does Mr. Schmidt indicate about his current position?", "options": ["It started twelve years ago.", "It required him to relocate to Melbourne.", "It involves transporting machinery.", "It is at the Anerap Company."], "answer": 2, "explain": "정답 (C) It involves transporting machinery.\n해석: Schmidt 씨는 현재 직무에 대해 무엇을 언급하는가?\n정답 근거: \"지금은 Simpson Trucking에서 건설 기계를 운송한다\" → 기계류 운송이 포함됨.\n오답 분석: (A) 12년은 전체 경력이지 현재 직장 근속이 아님. / (B) 멜버른 이주 언급 없음. / (D) Anerap Company는 과거 근무처.\nParaphrase: now deliver construction machinery → involves transporting machinery", "translation": "Schmidt 씨는 현재 직무에 대해 무엇을 언급하는가?", "g": {"his": ["대명사", "그의"], "about": ["전치사", "~에 대해"], "mr": ["명사", "~씨(남성)"], "what": ["대명사", "무엇"], "does": ["조동사", "(의문문 조동사)", "do"], "indicate": ["동사", "나타내다"], "current": ["형용사", "현재의"], "position": ["명사", "직책"], "schmidt": ["고유명사", "슈미트(성)"]}, "sub": "4문항 25회"}, {"no": 166, "q": "The word \"manner\" in paragraph 2, line 5, is closest in meaning to", "options": ["way", "appearance", "class", "appointment"], "answer": 0, "explain": "정답 (A) way\n해석: 두 번째 단락 다섯 번째 줄의 \"manner\"와 의미가 가장 가까운 것은?\n정답 근거: \"in a safe and timely manner(안전하고 시기적절한 방식으로)\" → 방식 → way.\n오답 분석: (B) appearance: '외모' — 불일치. / (C) class: '등급' — 불일치. / (D) appointment: '약속' — 불일치.", "translation": "두 번째 단락 다섯 번째 줄의 \"manner\"와 의미가 가장 가까운 것은?", "g": {"in": ["전치사", "~에"], "paragraph": ["명사", "단락"], "is": ["동사", "~이다", "be"], "line": ["명사", "줄"], "to": ["전치사", "~에게, ~으로"], "5": ["숫자", "5"], "the": ["관사", "그"], "closest": ["형용사", "가장 가까운", "close"], "meaning": ["명사", "의미"], "2": ["숫자", "2"], "word": ["명사", "단어"], "manner": ["명사", "방식"]}, "sub": "4문항 25회"}, {"no": 167, "q": "What is indicated about Mr. Schmidt?", "options": ["He prefers longer trips to shorter ones.", "He received an award from his employer.", "He was given high ratings by his peers.", "He has taken classes in communication."], "answer": 1, "explain": "정답 (B) He received an award from his employer.\n해석: Schmidt 씨에 대해 언급된 것은?\n정답 근거: \"2년 전 Simpson Trucking에서 올해의 직원으로 선정되었다\" → 고용주로부터 상을 받음.\n오답 분석: (A) 장거리 운행을 선호한다는 언급은 없음. / (C) 높은 평가는 관리자에게서 받은 것이지 동료가 준 것이 아님. / (D) 의사소통 수업 수강 언급 없음.\nParaphrase: selected as the Employee of the Year → received an award from his employer", "translation": "Schmidt 씨에 대해 언급된 것은?", "g": {"is": ["동사", "~이다", "be"], "indicated": ["과거분사", "나타난", "indicate"], "about": ["전치사", "~에 대해"], "mr": ["명사", "~씨(남성)"], "what": ["대명사", "무엇"], "schmidt": ["고유명사", "슈미트(성)"]}, "sub": "4문항 25회"}], "g": {"3000": ["숫자", "3000"], "with": ["전치사", "~와 함께"], "dear": ["형용사", "친애하는"], "sincerely": ["부사", "진심으로"], "be": ["동사", "~이다"], "the": ["관사", "그"], "as": ["접속사", "~하듯이"], "which": ["관계사", "어느 것"], "and": ["접속사", "그리고"], "you": ["대명사", "당신"], "is": ["동사", "~이다", "be"], "am": ["동사", "~이다", "be"], "about": ["전치사", "~에 대해"], "i": ["대명사", "나"], "have": ["동사", "가지다"], "in": ["전치사", "~에"], "8": ["숫자", "8"], "a": ["관사", "하나의"], "4": ["숫자", "4"], "mentioned": ["과거분사", "언급된", "mention"], "other": ["형용사", "다른"], "to": ["전치사", "~에게, ~으로"], "ms": ["명사", "~씨(여성)"], "now": ["부사", "지금"], "by": ["전치사", "~까지, ~에 의해"], "my": ["대명사", "나의"], "how": ["부사", "어떻게"], "he": ["대명사", "그"], "mr": ["명사", "~씨(남성)"], "we": ["대명사", "우리"], "3205": ["숫자", "3205"], "60": ["숫자", "60"], "for": ["전치사", "~을 위해"], "of": ["전치사", "~의"], "91": ["숫자", "91"], "or": ["접속사", "또는"], "that": ["접속사", "~라는 것"], "each": ["한정사", "각각의"], "at": ["전치사", "~에서"], "was": ["동사", "~였다", "be"], "from": ["전치사", "~에서"], "an": ["관사", "하나의"], "produce": ["명사", "농산물"], "opportunity": ["명사", "기회"], "offer": ["동사", "제공하다"], "apply": ["동사", "지원하다"], "hundreds": ["명사", "수백", "hundred"], "honoured": ["과거분사", "영광스러운", "honour"], "experience": ["명사", "경력"], "engineers": ["명사", "기술자들", "engineer"], "year": ["명사", "해"], "thousands": ["명사", "수천", "thousand"], "pride": ["명사", "자부심"], "forward": ["부사", "(look forward to) 고대하다"], "stores": ["명사", "매장", "store"], "enclosure": ["명사", "동봉물"], "hear": ["동사", "듣다"], "years": ["명사", "년", "year"], "selected": ["과거분사", "선정된", "select"], "great": ["형용사", "큰"], "schmidt": ["고유명사", "슈미트(성)"], "individual": ["명사", "사람"], "additionally": ["부사", "게다가"], "hahn": ["고유명사", "한(성)"], "customers": ["명사", "고객", "customer"], "writing": ["현재분사", "쓰는", "write"], "simpson": ["고유명사", "심슨(회사명)"], "off": ["부사", "(start off) 시작하다"], "together": ["부사", "함께"], "marcus": ["고유명사", "마커스(이름)"], "rating": ["명사", "평가"], "trip": ["명사", "여정"], "often": ["부사", "자주"], "twelve": ["숫자", "12"], "much": ["부사", "얼마나 많이"], "timely": ["형용사", "시기적절한"], "cv": ["명사", "이력서"], "driving": ["현재분사", "운전하는", "drive"], "dedicated": ["형용사", "헌신적인"], "driver": ["명사", "운전기사"], "application": ["명사", "지원"], "drivers": ["명사", "운전기사들", "driver"], "attended": ["동사", "다녔다", "attend"], "south": ["고유명사", "사우스(지명)"], "percent": ["명사", "퍼센트"], "always": ["부사", "항상"], "since": ["접속사", "~이래로"], "started": ["동사", "시작했다", "start"], "single": ["형용사", "한 번의"], "company": ["고유명사", "컴퍼니(회사명)"], "machinery": ["명사", "기계류"], "doing": ["동명사", "하는 것", "do"], "school": ["명사", "학교"], "deliver": ["동사", "배송하다"], "effectively": ["부사", "효과적으로"], "back": ["부사", "(hear back) 답변을 듣다"], "ltd": ["명사", "주식회사"], "recommended": ["동사", "추천했다", "recommend"], "delivering": ["동명사", "배송하는 것", "deliver"], "known": ["과거분사", "알아 왔다", "know"], "parkes": ["고유명사", "파크스(도로명)"], "manner": ["명사", "방식"], "position": ["명사", "직책"], "truck": ["명사", "트럭"], "country": ["명사", "나라"], "transporting": ["동명사", "운송하는 것", "transport"], "round": ["형용사", "(round trip) 왕복"], "anerap": ["고유명사", "아네랍(회사명)"], "byung-hun": ["고유명사", "병훈(이름)"], "melbourne": ["고유명사", "멜버른(지명)"], "efficiency": ["명사", "효율성"], "february": ["고유명사", "2월"], "anywhere": ["고유명사", "애니웨어(회사명)"], "enclosed": ["과거분사", "동봉된", "enclose"], "manager": ["명사", "관리자"], "businesses": ["명사", "업체", "business"], "fresh": ["형용사", "신선한"], "work": ["명사", "일"], "garimara": ["고유명사", "가리마라(성)"], "travel": ["동사", "이동하다"], "goods": ["명사", "물품"], "commended": ["과거분사", "칭찬받았다", "commend"], "hardworking": ["형용사", "근면한"], "vic": ["고유명사", "빅토리아주"], "ability": ["명사", "능력"], "take": ["동사", "(take pride) 자부심을 갖다"], "look": ["동사", "(look forward to) 고대하다"], "send": ["동사", "보내다"], "communicate": ["동사", "소통하다"], "gaffney": ["고유명사", "개프니(거리명)"], "warehouses": ["명사", "창고", "warehouse"], "two": ["숫자", "2"], "deliveries": ["고유명사", "딜리버리스(회사명)"], "mechanics": ["명사", "정비사", "mechanic"], "road": ["명사", "도로"], "enjoys": ["동사", "즐기다", "enjoy"], "employee": ["명사", "직원"], "retail": ["형용사", "소매의"], "kilometres": ["명사", "킬로미터", "kilometre"], "street": ["명사", "거리"], "colleague": ["명사", "동료"], "safe": ["형용사", "안전한"], "trucking": ["고유명사", "트러킹(회사명)"], "truck-driving": ["형용사", "트럭 운전의"], "construction": ["명사", "건설"], "ago": ["부사", "~전에"], "kylie": ["고유명사", "카일리(이름)"], "across": ["전치사", "~전역을"]}}, {"range": "168-171", "passage": "Easing Commutes\nA recent survey by Keats Research revealed that the average daily round-trip commute in Holden now tops an hour and a half. Many workers arrive at their job exhausted from their journey and irritated about the cost of commuting. These long commutes lead to lower employee productivity, decreased job satisfaction, and a high turnover rate. ― [1] ―. Consequently, many companies are looking for ways to ease employees' rough commutes.\nTelecommuting is one possible solution. An increasing number of businesses have been allowing employees to work from home a few days a week. ― [2] ―. This is worthwhile for everyone. Eliminating long, stressful commutes leads to employees starting the workday relaxed. This results in increased productivity and a reduction in absenteeism.\nAnother solution is carpools. By reducing the number of vehicles on the road, carpools can reduce overall traffic, resulting in shorter commute times for all. Employees can also decrease their personal commuting costs and arrive at work feeling less stressed. Companies can also choose to organize low-cost carpools for employees who need to work on-site. ― [3] ―.\nOne more way to ease commutes is allowing employees to work on-site during nontraditional hours. This option can significantly cut commuting times by getting workers off the road during rush hour.\nNot all companies are able to implement changes that will help reduce commuting times. ― [4] ―. However, for those that can, the recent survey results may provide additional incentives to make adjustments sooner rather than later.", "tr": "통근 부담 완화하기\nKeats Research의 최근 조사에 따르면 Holden의 하루 평균 왕복 통근 시간이 이제 1시간 30분을 넘는다. 많은 근로자가 이동에 지친 채로, 그 리고 통근 비용에 짜증이 난 상태로 직장에 도착한다. 이런 긴 통근은 직원 생산성 저하, 직무 만족도 감소, 높은 이직률로 이어진다. — [1] —. 그 결과 많은 기업이 직원들의 힘든 통근을 완화할 방법을 찾고 있다.\n재택근무가 한 가지 해결책이다. 점점 더 많은 기업이 직원들에게 주 며칠은 집에서 일하도록 허용해 왔다. — [2] — [이 방식이 성공하려면 직원 들에게 집에 좋은 인터넷 연결이 필요하다.] 이것은 모두에게 가치 있는 일이다. 길고 스트레스가 큰 통근을 없애면 직원들이 편안한 상태로 하루 업무를 시작하게 된다. 이는 생산성 향상과 결근 감소로 이어진다.\n또 다른 해결책은 카풀이다. 도로 위 차량 수를 줄임으로써 카풀은 전체 교통량을 줄여 모두의 통근 시간을 단축할 수 있다. 직원들은 개인 통근 비용도 줄이고 스트레스를 덜 받은 상태로 출근할 수 있다. 기업은 현장 근무가 필요한 직원들을 위해 저비용 카풀을 조직할 수도 있다. — [3] —. 통근을 완화하는 또 다른 방법은 직원들이 비전통적 시간대에 현장 근무를 하도록 허용하는 것이다. 이 선택지는 출퇴근 혼잡 시간대에 근로자를 도로에서 빼내어 통근 시간을 크게 줄일 수 있다.\n모든 기업이 통근 시간을 줄이는 변화를 시행할 수 있는 것은 아니다. — [4] —. 그러나 가능한 기업에는 이번 조사 결과가 나중보다 빨리 조정에 나설 추가 유인이 될 수 있다.", "vocab": "commute 명 통근 / reveal 동 밝히다 / exhausted 형 지친 / irritated 형 짜증이 난 / turnover rate 명 이직률 / ease 동 완화하다 / telecommuting 명 재택근무 / worthwhile 형 가치 있는 / absenteeism 명 결근 / implement 동 시행하다", "questions": [{"no": 168, "q": "What is one purpose of the article?", "options": ["To promote new technology", "To discuss the results of a study", "To highlight changes in traffic patterns", "To report an increase in worker productivity"], "answer": 1, "explain": "지문 개요: Holden의 평균 왕복 통근이 1시간 30분을 넘어 생산성 저하·이직률 상승으로 이어지자, 기업들이 재택근무(가정 내 인터넷 환경 필요), 카풀, 비전통적 근무 시간 허용 등으로 통근 부담을 줄이려 한다는 기사.\n정답 (B) To discuss the results of a study\n해석: 기사의 한 가지 목적은?\n정답 근거: \"Keats Research의 최근 조사에 따르면 ~\"으로 시작해 조사 결과와 그 함의를 다룸 → 연구 결과 논의.\n오답 분석: (A) 신기술 홍보가 아님. / (C) 교통 패턴 변화가 아니라 통근 부담 대책. / (D) 생산성 증가 보고가 아니라 저하 문제 제기.\nParaphrase: A recent survey ... revealed → discuss the results of a study", "translation": "기사의 한 가지 목적은?", "g": {"is": ["동사", "~이다", "be"], "the": ["관사", "그"], "of": ["전치사", "~의"], "what": ["대명사", "무엇"], "purpose": ["명사", "목적"], "one": ["숫자", "하나의"], "article": ["명사", "기사"]}, "sub": "4문항 25회"}, {"no": 169, "q": "What does the article suggest about many workers in Holden?", "options": ["They often report late to work.", "They disagree with the results of a survey.", "They are buying more economical vehicles.", "They arrive at work already feeling tired."], "answer": 3, "explain": "정답 (D) They arrive at work already feeling tired.\n해석: 기사는 Holden의 많은 근로자에 대해 무엇을 시사하는가?\n정답 근거: \"많은 근로자가 이동에 지친 채로 직장에 도착한다\" → 이미 피곤한 상태로 출근.\n오답 분석: (A) 지각 언급 없음. / (B) 조사 결과에 이의를 제기하지 않음. / (C) 경제적인 차량 구매 언급 없음.\nParaphrase: arrive at their job exhausted → arrive at work already feeling tired", "translation": "기사는 Holden의 많은 근로자에 대해 무엇을 시사하는가?", "g": {"in": ["전치사", "~에"], "the": ["관사", "그"], "about": ["전치사", "~에 대해"], "many": ["한정사", "많은"], "what": ["대명사", "무엇"], "does": ["조동사", "(의문문 조동사)", "do"], "article": ["명사", "기사"], "workers": ["명사", "근로자", "worker"], "holden": ["고유명사", "홀든(지명)"], "suggest": ["동사", "시사하다"]}, "sub": "4문항 25회"}, {"no": 170, "q": "What is NOT mentioned in the article as a way to improve commutes?", "options": ["Offering discounted tickets for public transportation", "Allowing employees to work from home", "Scheduling different work hours", "Arranging carpools"], "answer": 0, "explain": "정답 (A) Offering discounted tickets for public transportation\n해석: 기사에서 통근 개선 방법으로 언급되지 않은 것은?\n정답 근거: 대중교통 할인 승차권은 언급되지 않음. 재택근무(B), 다른 근무 시간대(C), 카풀(D)은 모두 제시됨.\n오답 분석: (B) 재택근무가 첫 번째 해결책으로 제시됨. / (C) 비전통적 시간대 현장 근무가 제시됨. / (D) 카풀이 또 다른 해결책으로 제시됨.\nParaphrase: work from home / nontraditional hours / carpools → work from home / different work hours / carpools", "translation": "기사에서 통근 개선 방법으로 언급되지 않은 것은?", "g": {"in": ["전치사", "~에"], "is": ["동사", "~이다", "be"], "a": ["관사", "하나의"], "to": ["전치사", "~에게, ~으로"], "mentioned": ["과거분사", "언급된", "mention"], "the": ["관사", "그"], "as": ["접속사", "~하듯이"], "not": ["부사", "~않다"], "what": ["대명사", "무엇"], "commutes": ["명사", "통근", "commute"], "way": ["명사", "방법"], "improve": ["동사", "개선하다"], "article": ["명사", "기사"]}, "sub": "4문항 25회"}, {"no": 171, "q": "In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"To make this arrangement succeed, employees need a good Internet connection at home.\"", "options": ["[1]", "[2]", "[3]", "[4]"], "answer": 1, "explain": "정답 (B) [2]\n해석: [1], [2], [3], [4] 중 \"To make this arrangement succeed, employees need a good Internet connection at home.\"이 들어가기에 가장 적절한 곳은?\n정답 근거: 재택근무 허용을 설명한 문장 바로 뒤에 \"이 방식(this arrangement)이 성공하려면 집에 좋은 인터넷 연결이 필요하다\"가 와야 지시 대상이 분명함 → [2].\n오답 분석: (A) [1]은 긴 통근의 부작용을 말하는 부분으로 재택근무가 아직 등장하지 않음. / (C) [3]은 카풀 설명 뒤라 인터넷과 무관. / (D) [4]는 변화를 시행하기 어려운 기업 이야기 뒤라 부적절.", "translation": "[1], [2], [3], [4] 중 \"To make this arrangement succeed, employees need a good Internet connection at home.\"이 들어가기에 가장 적절한 곳은?", "g": {"in": ["전치사", "~에"], "a": ["관사", "하나의"], "sentence": ["명사", "문장"], "4": ["숫자", "4"], "best": ["부사", "가장 잘"], "1": ["숫자", "1"], "marked": ["과거분사", "표시된", "mark"], "to": ["전치사", "~에게, ~으로"], "the": ["관사", "그"], "at": ["전치사", "~에서"], "which": ["관계사", "어느 것"], "this": ["한정사", "이"], "and": ["접속사", "그리고"], "following": ["형용사", "다음의"], "of": ["전치사", "~의"], "does": ["조동사", "(의문문 조동사)", "do"], "2": ["숫자", "2"], "positions": ["명사", "위치", "position"], "3": ["숫자", "3"], "belong": ["동사", "속하다"], "need": ["동사", "필요하다"], "succeed": ["동사", "성공하다"], "home": ["명사", "집"], "good": ["형용사", "좋은"], "make": ["동사", "만들다"], "arrangement": ["명사", "방식"], "internet": ["명사", "인터넷"], "employees": ["명사", "직원들", "employee"], "connection": ["명사", "연결"]}, "sub": "4문항 25회"}], "g": {"may": ["조동사", "~일지도 모른다"], "the": ["관사", "그"], "than": ["접속사", "~보다"], "all": ["한정사", "모든"], "and": ["접속사", "그리고"], "is": ["동사", "~이다", "be"], "many": ["한정사", "많은"], "about": ["전치사", "~에 대해"], "have": ["동사", "가지다"], "in": ["전치사", "~에"], "a": ["관사", "하나의"], "4": ["숫자", "4"], "1": ["숫자", "1"], "to": ["전치사", "~에게, ~으로"], "also": ["부사", "또한"], "are": ["동사", "~이다", "be"], "not": ["부사", "~않다"], "now": ["부사", "지금"], "this": ["한정사", "이"], "by": ["전치사", "~까지, ~에 의해"], "those": ["한정사", "그"], "on": ["전치사", "~에"], "during": ["전치사", "~동안"], "their": ["대명사", "그들의"], "can": ["조동사", "~할 수 있다"], "for": ["전치사", "~을 위해"], "of": ["전치사", "~의"], "2": ["숫자", "2"], "that": ["접속사", "~라는 것"], "3": ["숫자", "3"], "who": ["대명사", "누구"], "been": ["과거분사", "~였던", "be"], "more": ["형용사", "더 많은"], "at": ["전치사", "~에서"], "will": ["조동사", "~할 것이다"], "from": ["전치사", "~에서"], "these": ["한정사", "이"], "an": ["관사", "하나의"], "ease": ["동사", "완화하다"], "workday": ["명사", "근무일"], "absenteeism": ["명사", "결근"], "high": ["형용사", "높은"], "productivity": ["명사", "생산성"], "few": ["형용사", "(a few) 몇몇의"], "hour": ["명사", "시간"], "long": ["형용사", "긴"], "number": ["명사", "수"], "allowing": ["동명사", "허용하는 것", "allow"], "sooner": ["부사", "더 빨리", "soon"], "turnover": ["명사", "이직"], "commutes": ["명사", "통근", "commute"], "way": ["명사", "방법"], "overall": ["형용사", "전반적인"], "home": ["명사", "집"], "everyone": ["대명사", "모두"], "reduce": ["동사", "줄이다"], "employees'": ["명사", "직원들의", "employee"], "able": ["형용사", "~할 수 있는"], "another": ["한정사", "또 하나의"], "one": ["숫자", "하나의"], "on-site": ["부사", "현장에서"], "research": ["고유명사", "리서치(회사명)"], "commuting": ["명사", "통근"], "companies": ["명사", "회사들", "company"], "additional": ["형용사", "추가적인"], "organize": ["동사", "마련하다"], "recent": ["형용사", "최근의"], "relaxed": ["형용사", "편안한"], "half": ["명사", "반"], "looking": ["현재분사", "찾는", "look"], "personal": ["형용사", "개인적인"], "help": ["동사", "돕다"], "exhausted": ["형용사", "지친"], "arrive": ["동사", "도착하다"], "lead": ["동사", "이어지다"], "decreased": ["과거분사", "감소된", "decrease"], "off": ["전치사", "~에서 떨어져"], "feeling": ["현재분사", "느끼는", "feel"], "adjustments": ["명사", "조정", "adjustment"], "costs": ["명사", "비용", "cost"], "need": ["동사", "필요하다"], "revealed": ["동사", "밝혔다", "reveal"], "rush": ["명사", "(rush hour) 혼잡"], "changes": ["명사", "변화", "change"], "week": ["명사", "주"], "however": ["부사", "그러나"], "option": ["명사", "선택지"], "provide": ["동사", "제공하다"], "leads": ["동사", "이어지다", "lead"], "daily": ["형용사", "매일의"], "job": ["명사", "직장"], "easing": ["동명사", "완화하기", "ease"], "shorter": ["형용사", "더 짧은", "short"], "eliminating": ["동명사", "없애는 것", "eliminate"], "ways": ["명사", "방법", "way"], "rough": ["형용사", "힘든"], "journey": ["명사", "이동"], "rather": ["부사", "(rather than) ~보다"], "tops": ["동사", "넘다", "top"], "increasing": ["현재분사", "증가하는", "increase"], "rate": ["명사", "비율"], "cost": ["명사", "비용"], "irritated": ["형용사", "짜증 난"], "stressed": ["형용사", "스트레스 받은"], "hours": ["명사", "시간대", "hour"], "worthwhile": ["형용사", "가치 있는"], "later": ["부사", "(rather than later) 나중보다"], "cut": ["동사", "줄이다"], "make": ["동사", "하다"], "low-cost": ["형용사", "저비용의"], "reduction": ["명사", "감소"], "businesses": ["명사", "기업", "business"], "employees": ["명사", "직원들", "employee"], "work": ["동사", "일하다"], "telecommuting": ["명사", "재택근무"], "starting": ["동명사", "시작하는 것", "start"], "increased": ["과거분사", "증가된", "increase"], "getting": ["동명사", "~하게 하는 것", "get"], "solution": ["명사", "해결책"], "results": ["동사", "초래하다", "result"], "possible": ["형용사", "가능한"], "stressful": ["형용사", "스트레스 많은"], "resulting": ["현재분사", "초래하는", "result"], "consequently": ["부사", "그 결과"], "times": ["명사", "시간", "time"], "implement": ["동사", "시행하다"], "average": ["형용사", "평균의"], "traffic": ["명사", "교통량"], "holden": ["고유명사", "홀든(지명)"], "days": ["명사", "날", "day"], "satisfaction": ["명사", "만족"], "lower": ["형용사", "더 낮은", "low"], "incentives": ["명사", "동기", "incentive"], "significantly": ["부사", "상당히"], "keats": ["고유명사", "키츠(회사명)"], "road": ["명사", "도로"], "round-trip": ["형용사", "왕복의"], "workers": ["명사", "근로자", "worker"], "employee": ["명사", "직원"], "vehicles": ["명사", "차량", "vehicle"], "commute": ["명사", "통근"], "choose": ["동사", "선택하다"], "nontraditional": ["형용사", "비전통적인"], "survey": ["명사", "조사"], "less": ["부사", "덜"], "reducing": ["동명사", "줄이는 것", "reduce"], "carpools": ["명사", "카풀", "carpool"], "decrease": ["동사", "줄이다"]}}, {"range": "172-175", "passage": "Dirk Nelson [2:33 P.M.] Hello, Jeffrey and Lisa. I just heard from our linen supplier. They will not be able to deliver tablecloths in the color we requested until Saturday.\nJeffrey Lim [2:34 P.M.] But the grand opening event is this Friday evening. I thought we had confirmed the order. Didn't we receive a confirmation on Monday?\nLisa Cobb [2:35 P.M.] Yes, we did. I have it right here. We were expecting the delivery of two dozen large tablecloths in dark green.\nDirk Nelson [2:36 P.M.] Apparently there was a mix-up in the supplier's warehouse. They are now offering us a discount if we accept a different color.\nJeffrey Lim [2:37 P.M.] What other colors are available?\nLisa Cobb [2:38 P.M.] I'm looking at their Web site right now. There is a soft gold that I would go with.\nJeffrey Lim [2:39 P.M.] That will have to do. We can arrange to have contrasting floral centerpieces on all the tables.\nDirk Nelson [2:40 P.M.] That sounds good. I'll call the linen supplier and tell them that we will take the soft gold ones, and that they should be delivered this Thursday.", "tr": "Dirk Nelson [오후 2:33] 안녕하세요, Jeffrey, Lisa. 방금 리넨 공급업체에서 연락을 받았어요. 우리가 요청한 색의 식탁보를 토요일에야 배송 할 수 있대요.\nJeffrey Lim [오후 2:34] 하지만 개업 행사가 이번 주 금요일 저녁이잖아요. 주문을 확정했다고 생각했는데요. 월요일에 확인서를 받지 않았나 요?\nLisa Cobb [오후 2:35] 네, 받았어요. 지금 바로 여기 있어요. 진녹색 대형 식탁보 24장 배송을 기다리고 있었죠.\nDirk Nelson [오후 2:36] 보아하니 공급업체 창고에서 착오가 있었나 봐요. 다른 색을 받아 주면 할인을 해 주겠다고 합니다.\nJeffrey Lim [오후 2:37] 다른 색은 뭐가 있나요?\nLisa Cobb [오후 2:38] 지금 그쪽 웹사이트를 보고 있어요. 제가 고르고 싶은 연한 금색이 있네요.\nJeffrey Lim [오후 2:39] 그걸로 해야겠네요. 모든 테이블에 대조되는 꽃 중앙 장식을 마련할 수 있어요.\nDirk Nelson [오후 2:40] 좋네요. 제가 리넨 공급업체에 전화해서 연한 금색으로 하겠다고, 이번 주 목요일에 배송해 달라고 말할게요.", "vocab": "linen 명 리넨, 직물류 / supplier 명 공급업체 / tablecloth 명 식탁보 / confirmation 명 확인(서) / apparently 부 보아하니 / mix-up 명 착오, 혼동 / go with 구 ~을 선택하다 / That will have to do. 구 그걸로해야겠다. / contrasting 형 대조되는 / centerpiece 명 중앙 장식", "questions": [{"no": 172, "q": "What type of work do the writers most likely do?", "options": ["Warehouse management", "Linens manufacturing", "Landscape design", "Event planning"], "answer": 3, "explain": "지문 개요: 리넨 공급업체가 요청한 진녹색 식탁보를 토요일에야 배송할 수 있다고 하자, 금요일 저녁 개업 행사를 앞둔 세 사람이 할인된 다른 색 (연금색)을 받기로 하고 대조되는 꽃 장식을 놓기로 하며 목요일 배송을 요청하기로 하는 대화.\n정답 (D) Event planning\n해석: 작성자들은 어떤 종류의 일을 할 것 같은가?\n정답 근거: 개업 행사 준비, 식탁보 주문, 테이블 꽃 장식 논의 → 행사 기획.\n오답 분석: (A) 창고 관리는 공급업체 쪽 이야기. / (B) 리넨 제조가 아니라 구매·사용. / (C) 조경 디자인이 아니라 테이블 장식.\nParaphrase: grand opening event / tablecloths / floral centerpieces → event planning", "translation": "작성자들은 어떤 종류의 일을 할 것 같은가?", "g": {"the": ["관사", "그"], "most": ["부사", "가장"], "of": ["전치사", "~의"], "likely": ["부사", "아마"], "what": ["대명사", "무엇"], "do": ["동사", "하다"], "writers": ["명사", "작성자들", "writer"], "work": ["동사", "일하다"], "type": ["명사", "종류"]}, "sub": "4문항 25회"}, {"no": 173, "q": "When was an order confirmed?", "options": ["On Monday", "On Thursday", "On Friday", "On Saturday"], "answer": 0, "explain": "정답 (A) On Monday\n해석: 주문은 언제 확정되었는가?\n정답 근거: \"월요일에 확인서를 받지 않았나요?\"에 Cobb이 \"네, 받았다\"고 답함 → 월요일.\n오답 분석: (B) 목요일은 변경 요청한 배송일. / (C) 금요일은 개업 행사일. / (D) 토요일은 원래 색상의 배송 가능일.", "translation": "주문은 언제 확정되었는가?", "g": {"when": ["접속사", "~할 때"], "an": ["관사", "하나의"], "was": ["동사", "~였다", "be"], "confirmed": ["과거분사", "확정했다", "confirm"], "order": ["명사", "주문"]}, "sub": "4문항 25회"}, {"no": 174, "q": "At 2:35 P.M., what does Ms. Cobb most likely mean when she writes, \"I have it right here\"?", "options": ["She is looking at a message from a supplier.", "She is viewing a sample of the soft gold color online.", "She found an invoice for floral centerpieces on her desk.", "She has received a shipment of tablecloths."], "answer": 0, "explain": "정답 (A) She is looking at a message from a supplier.\n해석: 오후 2시 35분에 Cobb 씨가 \"I have it right here\"라고 쓴 의도는?\n정답 근거: \"확인서를 받지 않았나요?\"라는 질문에 \"네, 받았어요. 지금 바로 여기 있어요\"라고 답함 → 공급업체가 보낸 확인 메시지를 보고 있음.\n오답 분석: (B) 연금색 확인은 오후 2:38의 웹사이트 열람. / (C) 꽃 장식 청구서 언급 없음. / (D) 식탁보는 아직 배송되지 않음.\nParaphrase: Didn't we receive a confirmation? — Yes, I have it right here → looking at a message from a supplier", "translation": "오후 2시 35분에 Cobb 씨가 \"I have it right here\"라고 쓴 의도는?", "g": {"2:35": ["숫자", "2시 35분"], "here": ["부사", "여기에"], "when": ["접속사", "~할 때"], "she": ["대명사", "그녀"], "writes": ["동사", "쓰다", "write"], "most": ["부사", "가장"], "ms": ["명사", "~씨(여성)"], "likely": ["부사", "아마"], "mean": ["동사", "의미하다"], "at": ["전치사", "~에서"], "i": ["대명사", "나"], "what": ["대명사", "무엇"], "does": ["조동사", "(의문문 조동사)", "do"], "it": ["대명사", "그것"], "p.m": ["명사", "오후"], "have": ["동사", "가지다"], "cobb": ["고유명사", "코브(성)"], "right": ["부사", "바로"]}, "sub": "4문항 25회"}, {"no": 175, "q": "What will Mr. Nelson most likely do next?", "options": ["Contact a restaurant", "Visit a company Web site", "Update a previous order", "Cancel a business relationship"], "answer": 2, "explain": "정답 (C) Update a previous order\n해석: Nelson 씨는 다음에 무엇을 할 것 같은가?\n정답 근거: \"공급업체에 전화해서 연한 금색으로 하겠다고, 목요일에 배송해 달라고 말하겠다\" → 기존 주문 내용을 변경.\n오답 분석: (A) 식당이 아니라 리넨 공급업체에 연락. / (B) 웹사이트는 Cobb 씨가 봄. / (D) 거래 중단이 아니라 주문 변경.\nParaphrase: I'll call the linen supplier and tell them we will take the soft gold ones → update a previous order", "translation": "Nelson 씨는 다음에 무엇을 할 것 같은가?", "g": {"will": ["조동사", "~할 것이다"], "next": ["부사", "다음에"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "mr": ["명사", "~씨(남성)"], "what": ["대명사", "무엇"], "do": ["동사", "하다"], "nelson": ["고유명사", "넬슨(성)"]}, "sub": "4문항 25회"}], "g": {"them": ["대명사", "그들을"], "here": ["부사", "여기에"], "with": ["전치사", "~와 함께"], "hello": ["감탄사", "안녕하세요"], "be": ["동사", "~이다"], "the": ["관사", "그"], "2:39": ["숫자", "2시 39분"], "if": ["접속사", "만약 ~라면"], "they": ["대명사", "그들"], "all": ["한정사", "모든"], "and": ["접속사", "그리고"], "what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "i": ["대명사", "나"], "2:38": ["숫자", "2시 38분"], "have": ["동사", "가지다"], "in": ["전치사", "~에"], "a": ["관사", "하나의"], "other": ["형용사", "다른"], "should": ["조동사", "~해야 한다"], "yes": ["부사", "네"], "to": ["전치사", "~에게, ~으로"], "not": ["부사", "~않다"], "are": ["동사", "~이다", "be"], "p.m": ["명사", "오후"], "but": ["접속사", "그러나"], "now": ["부사", "지금"], "this": ["한정사", "이"], "there": ["부사", "거기에"], "2:34": ["숫자", "2시 34분"], "would": ["조동사", "~할 것이다"], "on": ["전치사", "~에"], "were": ["동사", "~였다", "be"], "it": ["대명사", "그것"], "just": ["부사", "막, 단지"], "their": ["대명사", "그들의"], "do": ["동사", "하다"], "we": ["대명사", "우리"], "can": ["조동사", "~할 수 있다"], "2:35": ["숫자", "2시 