insert into content(key,data,updated_at) values('sec:a-r15-p6',$mkd${"id": "a-r15-p6", "part": 6, "title": "A급 과제 15회 · PART 6", "area": "RC", "group": "A급 과제", "series": 3, "round": 15, "level": "중급", "notes": [], "items": [], "sets": [{"range": "131-134", "passage": "To: Raze Sportswear Employees\nFrom: Marcus Hamilton\nDate: July 25\nSubject: New marketing manager\nDear Staff:\nI am writing to let you know that Patricia Garcia ---131--- our offer of employment as a marketing manager. Her first day will be August 1. Ms. Garcia has sixteen years of marketing experience, the last eight in the athletic-wear ---132---. She will focus initially on developing a marketing strategy for our upcoming Raze Fit women's clothing line. A welcome lunch is planned for her first day. ---133---. Please let me know by July 31 if you are planning to ---134---.", "tr": "수신: Raze Sportswear 직원 / 발신: Marcus Hamilton / 날짜: 7월 25일 / 제목: 신임 마케팅 매니저\n직원 여러분께: Patricia Garcia가 마케팅 매니저 채용 제안을 수락했음(131)을 알려 드립니다. 첫 출근일은 8월 1일입니다. Garcia 씨는 16년의 마케팅 경력을 갖고 있으며 최근 8년은 운동복 업계(132)에서 일했습니다. 그녀는 우선 곧 출시될 Raze Fit 여성 의류 라인의 마케팅 전략 수 립에 집중할 것입니다. 첫날에 환영 오찬이 예정되어 있습니다. 오찬은 124호에서 정오에 열립니다(133). 참석(134)하실 계획이면 7월 31일까 지 알려 주십시오.", "vocab": "accept 동 수락하다 / offer of employment 명 채용 제안 / industry 명 업계 / focus on 구 ~에 집중하다 / initially 부 처음에 / strategy 명 전략 / upcoming 형 다가오는 / clothing line 명 의류 제품군 / attend 동 참석하다 / plan to V 구 ~할 계획이다", "questions": [{"no": 131, "q": "", "options": ["may accept", "has accepted", "having accepted", "was accepting"], "answer": 1, "explain": "지문 개요: Marcus Hamilton이 Raze Sportswear 직원들에게 Patricia Garcia가 마케팅 매니저 제안을 수락해 8월 1일 출근하며, 16년 경력 중 최근 8년은 운동복 업계에서 일했고 Raze Fit 여성 의류 라인 전략을 맡을 것이며 첫날 환영 오찬이 124호에서 열린다고 알리는 이메일.\n정답 (B) has accepted\n해석: Patricia Garcia가 채용 제안을 수락했습니다.\n정답 근거: 문장의 동사 자리. 이미 수락해 8월 1일 출근이 정해졌으므로 현재완료 has accepted. 타동사 accept 뒤 목적어 our offer 있음.\n오답 분석: (A) may accept: 가능성 — 출근일이 확정된 상황과 불일치. / (C) having accepted: 분사 — 동사가 없어짐. / (D) was accepting: 과거진행 — 불일치.", "translation": "Patricia Garcia가 채용 제안을 수락했습니다."}, {"no": 132, "q": "", "options": ["study", "outfit", "industry", "application"], "answer": 2, "explain": "정답 (C) industry\n해석: 최근 8년은 운동복 업계에서 일했습니다.\n정답 근거: 「athletic-wear + 빈칸」 → 분야를 뜻하는 명사 → industry(업계).\n오답 분석: (A) study: '연구' — 경력 분야 표현으로 부적절. / (B) outfit: '옷 한 벌' — 불가. / (D) application: '적용' — 불가.", "translation": "최근 8년은 운동복 업계에서 일했습니다."}, {"no": 133, "q": "", "options": ["We are looking for volunteers to train Ms. Garcia.", "The date has not yet been decided.", "A job interview will be conducted at that time.", "It will be held in room 124 at 12 noon."], "answer": 3, "explain": "정답 (D) It will be held in room 124 at 12 noon.\n해석: 오찬은 124호에서 정오에 열립니다.\n정답 근거: 앞 문장에서 환영 오찬이 예정되어 있다고 했으므로 장소·시간을 알리고, 뒤에서 참석 여부를 알려 달라는 흐름이 자연스러움.\n오답 분석: (A) 교육 자원자 모집은 오찬 안내와 무관. / (B) 날짜 미정은 '첫날에 예정'과 모순. / (C) 면접은 이미 채용이 끝나 불가.", "translation": "오찬은 124호에서 정오에 열립니다."}, {"no": 134, "q": "", "options": ["attend", "reply", "leave", "travel"], "answer": 0, "explain": "정답 (A) attend\n해석: 참석하실 계획이면 7월 31일까지 알려 주십시오.\n정답 근거: 오찬 안내 뒤 참석 여부 확인 → attend(참석하다).\n오답 분석: (B) reply: '답장하다' — 알려 달라는 요청과 중복되어 어색. / (C) leave: '떠나다' — 불가. / (D) travel: '이동하다' — 불가.", "translation": "참석하실 계획이면 7월 31일까지 알려 주십시오."}], "g": {"1": ["숫자", "1"], "25": ["숫자", "25"], "31": ["숫자", "31"], "a": ["관사", "하나의"], "am": ["동사", "~이다", "be"], "are": ["동사", "~이다", "be"], "as": ["전치사", "~로서"], "athletic-wear": ["명사", "운동복"], "august": ["명사", "8월"], "be": ["동사", "~이다, 되다"], "by": ["전치사", "~까지, ~에 의해"], "clothing": ["명사", "의류"], "date": ["명사", "날짜"], "day": ["명사", "날, 하루"], "dear": ["형용사", "친애하는"], "developing": ["동명사", "개발하는 것", "develop"], "eight": ["숫자", "여덟"], "employees": ["명사", "직원들", "employee"], "employment": ["명사", "고용"], "experience": ["명사", "경력"], "first": ["형용사", "첫 번째의"], "fit": ["고유명사", "핏(제품 라인명)"], "focus": ["동사", "집중하다"], "for": ["전치사", "~을 위해, ~ 동안"], "from": ["전치사", "~로부터"], "garcia": ["고유명사", "가르시아(성)"], "hamilton": ["고유명사", "해밀턴(성)"], "has": ["동사", "가지다", "have"], "her": ["대명사", "그녀의"], "i": ["대명사", "나"], "if": ["접속사", "만약 ~라면"], "in": ["전치사", "~에, ~안에"], "initially": ["부사", "처음에"], "is": ["동사", "~이다", "be"], "july": ["명사", "7월"], "know": ["동사", "알다"], "last": ["형용사", "지난"], "let": ["동사", "~하게 하다"], "line": ["명사", "제품 라인"], "lunch": ["명사", "점심"], "manager": ["명사", "관리자"], "marcus": ["고유명사", "마커스(이름)"], "marketing": ["명사", "마케팅"], "me": ["대명사", "나를"], "ms": ["명사", "~씨(여성 호칭)"], "new": ["형용사", "새로운"], "of": ["전치사", "~의"], "offer": ["명사", "제안"], "on": ["전치사", "~에, ~위에"], "our": ["대명사", "우리의"], "patricia": ["고유명사", "퍼트리샤(이름)"], "planned": ["과거분사", "계획된", "plan"], "planning": ["현재분사", "계획 중인", "plan"], "please": ["부사", "부디, ~해 주세요"], "raze": ["고유명사", "레이즈(회사명)"], "she": ["대명사", "그녀"], "sixteen": ["숫자", "열여섯"], "sportswear": ["명사", "스포츠 의류"], "staff": ["명사", "직원"], "strategy": ["명사", "전략"], "subject": ["명사", "제목"], "that": ["접속사", "~라는 것, 그"], "the": ["관사", "그"], "to": ["전치사", "~에게, ~로"], "upcoming": ["형용사", "곧 있을"], "welcome": ["형용사", "환영의"], "will": ["조동사", "~할 것이다"], "women's": ["명사", "여성용의", "woman"], "writing": ["현재분사", "쓰고 있는", "write"], "years": ["명사", "년", "year"], "you": ["대명사", "당신"]}}, {"range": "135-138", "passage": "All Valor Refrigeration appliances are automatically covered under a one-year limited warranty, which ---135--- for an additional fee. If your appliance requires repairs, please retain appropriate payment records and complete the online claim form. Repairs must be performed by a certified Valor Refrigeration service technician to ensure the cost of service is completely covered. ---136---, you may not be reimbursed for the full amount of the repairs. You must include a receipt along with your claim ---137--- verify the repair service provider.\nYour reimbursement will be mailed to you as a debit card. ---138---. To avoid delays, please review your claim before you submit it.", "tr": "모든 Valor Refrigeration 가전제품은 1년 한정 보증이 자동 적용되며, 추가 비용을 내면 연장할 수 있습니다(135). 제품 수리가 필요하면 관련 결제 기록을 보관하고 온라인 청구 양식을 작성해 주십시오. 서비스 비용이 전액 보전되려면 수리는 공인 Valor Refrigeration 서비스 기술자가 수행해야 합니다. 그렇지 않으면(136) 수리비 전액을 환급받지 못할 수 있습니다. 수리 서비스 제공자를 확인하기 위해(137) 청구서와 함께 영수 증을 첨부해야 합니다. 환급액은 직불카드 형태로 우편 발송됩니다. 환급 처리에 2주가 걸리는 점 양해해 주십시오(138). 지연을 피하려면 제출 전에 청구 내용을 검토해 주십시오.", "vocab": "appliance 명 가전제품 / cover 동 보장하다 / warranty 명 보증 / extend 동 연장하다 / retain 동 보관하다 / claim 명 청구 / certified 형 공인된 / reimburse 동 환급하다 / verify 동 확인하다 / otherwise 부 그렇지 않으면", "questions": [{"no": 135, "q": "", "options": ["will be extending", "extending", "can be extended", "extended"], "answer": 2, "explain": "지문 개요: Valor Refrigeration 제품의 1년 한정 보증은 추가 비용으로 연장할 수 있으며, 수리는 공인 기술자가 해야 전액 보전되고, 청구서에 영수증을 첨부해야 하며 환급은 직불카드로 우편 발송되고 처리에 2주가 걸린다는 보증 안내문.\n정답 (C) can be extended\n해석: 추가 비용을 내면 연장할 수 있습니다.\n정답 근거: 동사 2개(are covered, 빈칸)를 잇는 관계대명사 which 뒤 동사 자리. extend는 타동사인데 목적어 없이 for an additional fee가 오므로 수동 → can be extended.\n오답 분석: (A) will be extending: 능동 — 목적어가 없어 불가. / (B) extending: 분사 — 관계절의 동사가 없어짐. / (D) extended: 능동 과거 — 목적어 없음.", "translation": "추가 비용을 내면 연장할 수 있습니다."}, {"no": 136, "q": "", "options": ["Rather", "Besides", "Consequently", "Otherwise"], "answer": 3, "explain": "정답 (D) Otherwise\n해석: 그렇지 않으면 수리비 전액을 환급받지 못할 수 있습니다.\n정답 근거: \"공인 기술자가 수리해야 전액 보전된다\"는 조건을 지키지 않은 경우 → Otherwise(그렇지 않으면).\n오답 분석: (A) Rather: '오히려' — 정정 관계 아님. / (B) Besides: '게다가' — 추가 관계 아님. / (C) Consequently: '결과적으로' — 조건 위반 가정이 빠짐.", "translation": "그렇지 않으면 수리비 전액을 환급받지 못할 수 있습니다."}, {"no": 137, "q": "", "options": ["in relation to", "in order to", "in regard to", "in addition to"], "answer": 1, "explain": "정답 (B) in order to\n해석: 수리 서비스 제공자를 확인하기 위해 영수증을 첨부해야 합니다.\n정답 근거: 「빈칸 + 동사원형 verify」 → 목적을 나타내는 in order to V.\n오답 분석: (A) in relation to: 뒤에 명사가 와야 함. / (C) in regard to: 뒤에 명사 필요. / (D) in addition to: 뒤에 명사/동명사 필요.", "translation": "수리 서비스 제공자를 확인하기 위해 영수증을 첨부해야 합니다."}, {"no": 138, "q": "", "options": ["Please allow two weeks for your refund to be processed.", "To locate the nearest authorized repair service, contact customer relations.", "Valor Refrigeration products often go years without needing repair.", "We at Valor Refrigeration greatly appreciate your business."], "answer": 0, "explain": "정답 (A) Please allow two weeks for your refund to be processed.\n해석: 환급 처리에 2주가 걸리는 점 양해해 주십시오.\n정답 근거: 앞 문장 환급 발송 안내에 이어 처리 기간을 알리고, 뒤 \"지연을 피하려면 검토하라\"로 연결됨.\n오답 분석: (B) 수리점 안내는 이미 앞에서 공인 기술자 요건을 설명해 흐름이 어긋남. / (C) 고장이 드물다는 홍보는 청구 절차 안내와 무관. / (D) 감사 인사는 지연 언급과 연결되지 않음.", "translation": "환급 처리에 2주가 걸리는 점 양해해 주십시오."}], "g": {"a": ["관사", "하나의"], "additional": ["형용사", "추가의"], "all": ["한정사", "모든"], "along": ["부사", "함께"], "amount": ["명사", "금액"], "an": ["관사", "하나의"], "and": ["접속사", "그리고"], "appliance": ["명사", "가전제품"], "appliances": ["명사", "가전제품들", "appliance"], "appropriate": ["형용사", "적절한"], "are": ["동사", "~이다", "be"], "as": ["전치사", "~로서"], "automatically": ["부사", "자동으로"], "be": ["동사", "~이다, 되다"], "before": ["전치사", "~ 전에"], "by": ["전치사", "~까지, ~에 의해"], "card": ["명사", "카드"], "certified": ["과거분사", "공인된", "certify"], "claim": ["명사", "청구"], "complete": ["동사", "작성하다, 완료하다"], "completely": ["부사", "완전히"], "cost": ["명사", "비용"], "covered": ["과거분사", "보장되는", "cover"], "debit": ["명사", "직불"], "delays": ["명사", "지연", "delay"], "ensure": ["동사", "보장하다"], "fee": ["명사", "요금"], "for": ["전치사", "~을 위해, ~ 동안"], "form": ["명사", "양식"], "full": ["형용사", "전체의"], "if": ["접속사", "만약 ~라면"], "include": ["동사", "포함하다"], "is": ["동사", "~이다", "be"], "it": ["대명사", "그것"], "limited": ["과거분사", "제한된", "limit"], "mailed": ["과거분사", "우편 발송되는", "mail"], "may": ["조동사", "~일지도 모른다"], "must": ["조동사", "~해야 한다"], "not": ["부사", "~ 않다"], "of": ["전치사", "~의"], "one-year": ["형용사", "1년의"], "online": ["형용사", "온라인의"], "payment": ["명사", "결제"], "performed": ["과거분사", "수행되는", "perform"], "please": ["부사", "부디, ~해 주세요"], "provider": ["명사", "제공업체"], "receipt": ["명사", "영수증"], "records": ["명사", "기록들", "record"], "refrigeration": ["명사", "냉장"], "reimbursed": ["과거분사", "환급받는", "reimburse"], "reimbursement": ["명사", "환급금"], "repair": ["명사", "수리"], "repairs": ["명사", "수리", "repair"], "requires": ["동사", "필요로 하다", "require"], "retain": ["동사", "보관하다"], "review": ["동사", "검토하다"], "service": ["명사", "서비스"], "submit": ["동사", "제출하다"], "technician": ["명사", "기술자"], "the": ["관사", "그"], "to": ["전치사", "~에게, ~로"], "under": ["전치사", "~하에"], "valor": ["고유명사", "밸러(회사명)"], "verify": ["동사", "확인하다"], "warranty": ["명사", "품질 보증"], "which": ["관계사", "그것은(관계대명사)"], "will": ["조동사", "~할 것이다"], "with": ["전치사", "~와 함께"], "you": ["대명사", "당신"], "your": ["대명사", "당신의"], "avoid": ["동사", "피하다"]}}, {"range": "139-142", "passage": "June promotions and sales at Carson Stores\nWe strongly ---139--- you to take advantage of the deep discounts we are offering this month during our annual sticker sale.\nAll items ---140--- with a green sticker are 10% off, and items with a red sticker are 15% off. There are over 200 items on sale, so you are sure to find something you need.\n---141---, our Carson Club members who spend $200 this month will receive a $40 gift certificate. ---142---. The gift certificate can only be applied to full-priced items, and it must be used by June 30.\nTo see a full list of on-sale items or to learn more about our gift certificate promotion, visit our Web site. Or better yet, come in and see for yourself!", "tr": "Carson Stores 6월 판촉 및 세일\n이번 달 연례 스티커 세일에서 제공하는 큰 폭의 할인을 꼭 이용하시길 강력히 권합니다(139). 초록 스티커가 붙은(140) 모든 품목은 10% 할인, 빨강 스티커 품목은 15% 할인입니다. 200개가 넘는 품목이 세일 중이니 필요한 물건을 반드시 찾으실 수 있습니다. 또한(141) 이번 달에 200달 러를 쓰신 Carson Club 회원은 40달러 상품권을 받습니다. 이 혜택에는 몇 가지 제한이 있습니다(142). 상품권은 정가 품목에만 사용할 수 있으 며 6월 30일까지 사용해야 합니다. 세일 품목 전체 목록을 보거나 상품권 판촉에 대해 더 알아보려면 웹사이트를 방문하세요. 아니면 직접 오셔 서 확인해 보세요!", "vocab": "promotion 명 판촉 행사 / encourage A to V 구 A가 ~하도록 권장하다 / take advantage of 구 ~을 이용하다 / deep discount 명 대폭 할인 / mark 동 표시하다 / in addition 구 게다가 / gift certificate 명 상품권 / restriction 명 제한 / apply to 구 ~에 적용되다 / full-priced 형 정가의", "questions": [{"no": 139, "q": "", "options": ["encourage", "encouraged", "encouraging", "encouragement"], "answer": 0, "explain": "지문 개요: Carson Stores의 연례 스티커 세일 광고. 초록 스티커 10%, 빨강 스티커 15% 할인이며 200개 이상 품목이 대상이고, Carson Club 회원이 이달 200달러를 쓰면 40달러 상품권을 받지만 정가 품목에만 적용되고 6월 30일까지 사용해야 한다는 제한이 있음을 안내함.\n정답 (A) encourage\n해석: 할인을 이용하시길 강력히 권합니다.\n정답 근거: 문장의 동사 자리. 주어 We(복수) + 현재 → encourage. 5형식 encourage + 목적어 you + to V.\n오답 분석: (B) encouraged: 과거 — 진행 중인 이달 세일 광고와 시제 불일치. / (C) encouraging: 분사 — 동사 없음. / (D) encouragement: 명사 — 동사 자리 불가.", "translation": "할인을 이용하시길 강력히 권합니다."}, {"no": 140, "q": "", "options": ["traded", "marked", "signaled", "invited"], "answer": 1, "explain": "정답 (B) marked\n해석: 초록 스티커가 붙은 모든 품목\n정답 근거: 이미 동사 are가 있으므로 명사 items를 뒤에서 꾸미는 분사(관계대명사 축약 items (that are) marked with ~). mark는 타동사인데 목적어 없이 with구가 오므로 -ed marked.\n오답 분석: (A) traded: '거래된' — 스티커와 결합 의미 불가. / (C) signaled: '신호를 보낸' — 부적절. / (D) invited: '초대된' — 불가.", "translation": "초록 스티커가 붙은 모든 품목"}, {"no": 141, "q": "", "options": ["Likewise", "However", "Therefore", "In addition"], "answer": 3, "explain": "정답 (D) In addition\n해석: 또한 200달러를 쓰신 회원은 40달러 상품권을 받습니다.\n정답 근거: 앞의 할인 안내에 더해 추가 혜택을 소개 → In addition.\n오답 분석: (A) Likewise: '마찬가지로' — 유사 비교 관계 아님. / (B) However: 역접 — 불가. / (C) Therefore: 인과 — 불가.", "translation": "또한 200달러를 쓰신 회원은 40달러 상품권을 받습니다."}, {"no": 142, "q": "", "options": ["New items are being added daily to the sale.", "There are some restrictions on this offer.", "Additional promotional offers are coming soon.", "Gift certificates can be purchased in stores and online."], "answer": 1, "explain": "정답 (B) There are some restrictions on this offer.\n해석: 이 혜택에는 몇 가지 제한이 있습니다.\n정답 근거: 뒤 문장에서 \"정가 품목만, 6월 30일까지\"라는 제한을 설명하므로 이를 예고하는 문장이 적절.\n오답 분석: (A) 신규 품목 추가는 뒤의 제한 설명과 연결되지 않음. / (C) 추가 판촉 예고는 무관. / (D) 상품권 구매는 증정 혜택과 다른 내용.", "translation": "이 혜택에는 몇 가지 제한이 있습니다."}], "g": {"$200": ["숫자", "$200"], "$40": ["숫자", "$40"], "10%": ["숫자", "10%"], "15%": ["숫자", "15%"], "200": ["숫자", "200"], "30": ["숫자", "30"], "a": ["관사", "하나의"], "about": ["전치사", "~에 대해"], "advantage": ["명사", "이점(take advantage of 활용)