insert into content(key,data,updated_at) values('sec:a-r2-p6',$mkd${"id": "a-r2-p6", "area": "RC", "part": 6, "group": "A급 과제", "series": 3, "round": 2, "level": "중급", "title": "A급 과제 2회 · PART 6", "notes": [], "items": [], "sets": [{"range": "131-134", "passage": "Williamsen Computer Solutions\nIs your computer running more ---131--- than usual? Do you need help installing applications or upgrading your operating system? ---132---. If you require assistance with any number of common maintenance issues, bring your computer to Williamsen Computer Solutions. Our team of trained experts will perform a complimentary check of its functionality and ---133--- the best course of action. ---134--- us a call today at 555-0165.", "tr": "Williamsen Computer Solutions\n컴퓨터가 평소보다 더 느리게(131) 작동하나요? 응용 프로그램 설치나 운영 체제 업그레이드에 도움이 필요하신가요? 하드 드라이브를 정리하고 싶으신가요(132)? 여러 흔한 유지보수 문제 중 어느 것이든 도움이 필요하시면 컴퓨터를 Williamsen Computer Solutions로 가져오세요. 숙련된 전문가 팀이 기능을 무료로 점검하고 최선의 조치를 추천해 드립니다(133). 오늘 555-0165로 전화 주세요(134).", "vocab": "than usual 구 평소보다 / install 동 설치하다 / operating system 명 운영 체제 / require 동 필요로 하다 / assistance 명 도움 / maintenance 명 유지보수 / complimentary 형 무료의 / functionality 명 기능 / course of action 명 조치 방안 / give A a call 구 A에게 전화하다", "g": {"will": ["조동사", "~할 것이다"], "williamsen": ["고유명사", "윌리엄슨(상호)"], "a": ["관사", "하나의"], "computer": ["명사", "컴퓨터"], "solutions": ["명사", "솔루션", "solution"], "is": ["동사", "~이다", "be"], "you": ["대명사", "당신"], "your": ["한정사", "당신의"], "our": ["한정사", "우리의"], "running": ["현재분사", "작동하는", "run"], "more": ["부사", "더"], "or": ["접속사", "또는"], "than": ["접속사", "~보다"], "usual": ["형용사", "평소의"], "us": ["대명사", "우리를"], "do": ["동사", "하다"], "need": ["동사", "필요로 하다"], "help": ["명사", "도움"], "installing": ["동명사", "설치하기", "install"], "applications": ["명사", "애플리케이션", "application"], "at": ["전치사", "~에, ~에서"], "upgrading": ["동명사", "업그레이드하기", "upgrade"], "operating": ["형용사", "운영하는"], "system": ["명사", "체제"], "if": ["접속사", "만약 ~라면"], "require": ["동사", "필요로 하다"], "assistance": ["명사", "도움"], "with": ["전치사", "~와 함께, ~으로"], "any": ["한정사", "어떤"], "number": ["명사", "(any number of) 다양한"], "of": ["전치사", "~의"], "common": ["형용사", "흔한"], "maintenance": ["명사", "유지보수"], "issues": ["명사", "문제", "issue"], "bring": ["동사", "가져오다"], "to": ["전치사", "~로"], "team": ["명사", "팀"], "trained": ["과거분사", "훈련받은", "train"], "experts": ["명사", "전문가", "expert"], "perform": ["동사", "수행하다"], "complimentary": ["형용사", "무료의"], "check": ["명사", "점검"], "its": ["한정사", "그것의"], "functionality": ["명사", "기능"], "and": ["접속사", "그리고"], "the": ["관사", "그"], "best": ["형용사", "최선의"], "course": ["명사", "방침, 방향"], "action": ["명사", "조치"], "call": ["명사", "전화"], "today": ["부사", "오늘"], "555-0165": ["숫자", "전화번호"]}, "questions": [{"no": 131, "q": "", "options": ["slow", "slowly", "slows", "slowing"], "answer": 1, "explain": "정답 (B) slowly\n해석: 컴퓨터가 평소보다 더 느리게 작동하나요?\n정답 근거: run(작동하다)은 자동사(1형식)이므로 뒤에 목적어가 아닌 부사가 옴. more _______ than 비교 구조에서 동사 running을 꾸미는 부사 slowly.\n오답 분석: (A) slow: 형용사 — 자동사 running을 꾸밀 수 없음. / (C) slows: 동사 — is running과 동사 중복. / (D) slowing: 분사 — 동사를 수식할 수 없음.\n지문 개요: 컴퓨터가 느려지거나 프로그램 설치·OS 업그레이드 등 도움이 필요하면 Williamsen Computer Solutions에 가져오라는 광고. 전문가 팀이 무료 점검 후 최선의 조치를 추천하니 전화하라고 권유함."}, {"no": 132, "q": "", "options": ["Are you planning a vacation?", "Do you want a bigger movie selection?", "Would you like to clean your hard drive?", "Have you received a discount coupon?"], "answer": 2, "explain": "정답 (C) Would you like to clean your hard drive?\n해석: 하드 드라이브를 정리하고 싶으신가요?\n정답 근거: 앞뒤가 모두 컴퓨터 문제(느린 속도, 프로그램 설치, OS 업그레이드)를 묻는 의문문 나열이고 다음 문장이 \"흔한 유지보수 문제\"로 묶으므로, 하드 드라이브 정리라는 컴퓨터 유지보수 질문이 적절.\n오답 분석: (A) 휴가 계획은 컴퓨터 서비스와 무관. / (B) 영화 선택의 폭은 무관. / (D) 할인 쿠폰 수령 여부는 유지보수 문제 나열에 맞지 않음."}, {"no": 133, "q": "", "options": ["demand", "request", "retain", "recommend"], "answer": 3, "explain": "정답 (D) recommend\n해석: 전문가 팀이 기능을 무료로 점검하고 최선의 조치를 추천해 드립니다.\n정답 근거: 등위접속사 and로 will perform과 병렬되는 동사. 점검 후 \"최선의 조치(the best course of action)\"를 제시한다는 의미 → recommend.\n오답 분석: (A) demand: '요구하다' — 고객에게 조치를 요구한다는 뜻이 되어 부적절. / (B) request: '요청하다' — 의미 불가. / (C) retain: '유지하다' — 의미 불가."}, {"no": 134, "q": "", "options": ["Give", "You gave", "To give", "You should have given"], "answer": 0, "explain": "정답 (A) Give\n해석: 오늘 555-0165로 전화 주세요.\n정답 근거: 문장에 주어가 없고 동사 자리로 시작하며, 광고 마무리의 요청문 → 동사원형으로 시작하는 명령문 Give (us a call).\n오답 분석: (B) You gave: 과거 — 광고의 행동 촉구와 시제·의미 불일치. / (C) To give: to부정사 — 문장의 동사가 없어짐. / (D) You should have given: 과거에 했어야 했다는 뜻 — 의미 불가."}]}, {"range": "135-138", "passage": "The Oaktown Classic Cinema (OCC) ---135--- movie tickets at half price on weekends during the summer months. The films shown on these summer weekends will mostly include the standard classic movies that we are known for. We will also, however, offer one ---136--- film per day, usually in the evening. ---137---. The OCC offers three options, including one for unlimited movies.\nThe cinema will publish its list of summer movies ---138--- the end of May.", "tr": "Oaktown Classic Cinema(OCC)는 여름철 주말에 영화표를 반값에 판매할 예정입니다(135). 이 여름 주말에 상영되는 영화는 주로 저희가 잘 알려진 표준 고전 영화들입니다. 하지만 저희는 하루에 한 편, 보통 저녁에 최신(136) 영화도 제공할 것입니다. 개별 상영 티켓 외에 월 이용권도 이용 가능합니다(137). OCC는 무제한 영화 관람권을 포함해 세 가지 옵션을 제공합니다. 극장은 5월 말까지(138) 여름 영화 목록을 발표할 것입니다.", "vocab": "at half price 구 반값으로 / mostly 부 대부분 / be known for 구 ~로 유명하다 / current 형 최신의 / per 전 ~당 / monthly pass 명 월간 이용권 / unlimited 형 무제한의 / publish 동 발표하다 / by 전 ~까지", "g": {"the": ["관사", "그"], "oaktown": ["고유명사", "오크타운(지명)"], "classic": ["형용사", "고전의"], "cinema": ["명사", "영화관"], "in": ["전치사", "~에, ~안에"], "occ": ["고유명사", "OCC(영화관 약칭)"], "movie": ["명사", "영화"], "tickets": ["명사", "표", "ticket"], "at": ["전치사", "~에, ~에서"], "half": ["형용사", "절반의"], "price": ["명사", "가격"], "on": ["전치사", "~에, ~위에"], "we": ["대명사", "우리"], "weekends": ["명사", "주말", "weekend"], "end": ["명사", "말, 끝"], "during": ["전치사", "~동안"], "summer": ["명사", "여름"], "months": ["명사", "달", "month"], "films": ["명사", "영화", "film"], "film": ["명사", "영화"], "shown": ["과거분사", "상영되는", "show"], "these": ["한정사", "이것들의"], "will": ["조동사", "~할 것이다"], "mostly": ["부사", "주로"], "include": ["동사", "포함하다"], "standard": ["형용사", "표준적인"], "movies": ["명사", "영화", "movie"], "that": ["관계사", "~하는"], "are": ["동사", "~이다", "be"], "known": ["과거분사", "알려진", "know"], "for": ["전치사", "~을 위해, ~동안"], "also": ["부사", "또한"], "however": ["부사", "그러나"], "offer": ["동사", "제공하다"], "of": ["전치사", "~의"], "one": ["숫자", "하나"], "per": ["전치사", "~당"], "day": ["명사", "날"], "usually": ["부사", "보통"], "evening": ["명사", "저녁"], "offers": ["동사", "제공하다", "offer"], "three": ["숫자", "셋"], "options": ["명사", "선택 사항", "option"], "including": ["전치사", "~을 포함하여"], "unlimited": ["형용사", "무제한의"], "publish": ["동사", "게시하다"], "its": ["한정사", "그것의"], "list": ["명사", "목록"], "may": ["조동사", "~일지도 모른다"]}, "questions": [{"no": 135, "q": "", "options": ["will sell", "sold", "had sold", "sell"], "answer": 0, "explain": "정답 (A) will sell\n해석: OCC는 여름철 주말에 영화표를 반값에 판매할 예정입니다.\n정답 근거: 문장의 동사 자리. 뒤 문장들이 모두 will(will mostly include, will also offer, will publish)로 앞으로의 여름 계획을 말하므로 미래 will sell. 타동사 sell 뒤 목적어 movie tickets 있음(능동).\n오답 분석: (B) sold: 과거 — 앞으로의 계획과 불일치. / (C) had sold: 과거완료 — 불일치. / (D) sell: 현재 — 주어 The OCC(단수)와 수 불일치(sells 필요).\n지문 개요: Oaktown Classic Cinema가 여름철 주말에 영화표를 반값에 판매하며, 주로 고전 영화에 더해 매일 최신 영화 한 편을 상영하고, 개별 티켓 외 월 이용권(무제한 포함 3종)도 제공하며 5월 말까지 상영 목록을 공개한다는 공지."}, {"no": 136, "q": "", "options": ["absent", "mixed", "current", "preliminary"], "answer": 2, "explain": "정답 (C) current\n해석: 하루에 한 편, 보통 저녁에 최신 영화도 제공할 것입니다.\n정답 근거: 앞 문장의 \"표준 고전 영화\"와 however로 대비되는 영화 → 최신(current) 영화.\n오답 분석: (A) absent: '결석한, 없는' — 의미 불가. / (B) mixed: '혼합된' — 영화 한 편을 꾸미기에 부적절. / (D) preliminary: '예비의' — 의미 불가."}, {"no": 137, "q": "", "options": ["The OCC has been in business for over three decades.", "Besides tickets for individual shows, monthly passes are also available.", "No outside food or drinks are permitted, as the theater has a concessions area.", "Last year, the OCC was closed for two weeks for renovations."], "answer": 1, "explain": "정답 (B) Besides tickets for individual shows, monthly passes are also available.\n해석: 개별 상영 티켓 외에 월 이용권도 이용 가능합니다.\n정답 근거: 뒤 문장 \"OCC는 무제한 영화 관람권을 포함해 세 가지 옵션을 제공한다\"의 옵션이 가리킬 대상(이용권)이 먼저 소개되어야 함 → 월 이용권 안내.\n오답 분석: (A) 30년 영업 이력은 옵션 세 가지와 연결되지 않음. / (C) 외부 음식 반입 금지는 문맥과 무관. / (D) 작년 보수 공사 휴관은 무관."}, {"no": 138, "q": "", "options": ["by", "on", "inside", "beside"], "answer": 0, "explain": "정답 (A) by\n해석: 극장은 5월 말까지 여름 영화 목록을 발표할 것입니다.\n정답 근거: 미래 동사 will publish + 기한 표현 the end of May → \"~까지(기한)\" 전치사 by.\n오답 분석: (B) on: 특정 날짜 앞에 쓰지만 the end of May(시점 범위)와 기한 의미에 부적절. / (C) inside: '~안에' — 의미 불가. / (D) beside: '~옆에' — 의미 불가."}]}, {"range": "139-142", "passage": "Artist Walks to Find Creativity\nArtist and digital content manager Stacy Aham attributes her time-management skills and creative success to a simple habit—a daily walk. Ms. Aham ---139--- it a point to walk every day, at least for one mile, around her neighborhood.\n\"It helps me prepare for the day ahead,\" said Ms. Aham. \"About six months ago, I canceled my gym memberships and exercise classes. I basically decided to leave my car on the drive way most of the time, and now I just walk ---140---. I'm the healthiest I've ever been. Wandering around free of purpose also helps me discover artistic ideas,\" she says. \"The natural surroundings inspire me. ---141---.\"\nMs. Aham ---142--- feels more confidence in her ideas and is better able to focus on her goals.", "tr": "창의력을 찾아 걷는 예술가\n예술가이자 디지털 콘텐츠 관리자인 Stacy Aham은 자신의 시간 관리 능력과 창의적 성공을 간단한 습관, 즉 매일 걷기 덕분이라고 말한다. Aham 씨는 매일 동네를 적어도 1마일은 걷는 것을 원칙으로 삼는다(139). \"그것은 제가 하루를 준비하도록 도와줍니다.\" Aham 씨가 말했다. \"약 6개월 전 저는 체육관 회원권과 운동 수업을 취소했습니다. 대부분의 시간 차를 진입로에 두기로 했고, 지금은 그냥 어디든(140) 걸어 다닙니다. 지금이 제 인생에서 가장 건강합니다. 목적 없이 돌아다니는 것도 예술적 아이디어를 발견하는 데 도움이 됩니다.\" 그녀는 말한다. \"자연환경이 저에게 영감을 줍니다. 봄철에는 특히 그렇습니다(141).\" Aham 씨는 결과적으로(142) 자신의 아이디어에 더 자신감을 느끼고 목표에 더 잘 집중할 수 있다.", "vocab": "attribute A to B 구 A를 B의 덕분으로 여기다 / creative 형 창의적인 / make it a point to 구 반드시 ~하다 / neighborhood 명 동네 / membership 명 회원권 / driveway 명 진입로 / wander 동 거닐다 / surroundings 명 주변 환경 / inspire 동 영감을 주다 / consequently 부 결과적으로", "g": {"artist": ["명사", "예술가"], "a": ["관사", "하나의"], "is": ["동사", "~이다", "be"], "i": ["대명사", "나"], "walks": ["동사", "걷다", "walk"], "walk": ["명사", "산책"], "to": ["to부정사", "~하기 위해"], "find": ["동사", "찾다"], "in": ["전치사", "~에, ~안에"], "creativity": ["명사", "창의력"], "at": ["전치사", "~에, ~에서"], "it": ["대명사", "그것"], "and": ["접속사", "그리고"], "digital": ["형용사", "디지털의"], "content": ["명사", "콘텐츠"], "on": ["전치사", "~에, ~위에"], "manager": ["명사", "관리자"], "stacy": ["고유명사", "스테이시(인명)"], "aham": ["고유명사", "아함(인명)"], "attributes": ["동사", "(A to B) A를 B 덕분으로 여기다", "attribute"], "her": ["한정사", "그녀의"], "time-management": ["명사", "시간 관리"], "time": ["명사", "시간"], "me": ["대명사", "나를"], "skills": ["명사", "기술", "skill"], "creative": ["형용사", "창의적인"], "success": ["명사", "성공"], "simple": ["형용사", "간단한"], "habit—a": ["명사", "습관—하나의", "habit"], "daily": ["형용사", "매일의"], "ms": ["명사", "~씨(여성)"], "point": ["명사", "(make it a point to) 꼭 ~하다"], "ever": ["부사", "지금까지"], "every": ["한정사", "모든"], "day": ["명사", "날"], "least": ["부사", "(at least) 적어도"], "for": ["전치사", "~을 위해, ~동안"], "one": ["숫자", "하나"], "mile": ["명사", "마일"], "around": ["전치사", "~주변에, 약"], "neighborhood": ["명사", "동네"], "helps": ["동사", "돕다", "help"], "prepare": ["동사", "준비하다"], "the": ["관사", "그"], "ahead": ["부사", "미리, 앞에"], "said": ["동사", "말했다", "say"], "about": ["전치사", "~에 대해"], "six": ["숫자", "여섯"], "months": ["명사", "달", "month"], "ago": ["부사", "~전에"], "canceled": ["동사", "취소했다", "cancel"], "my": ["한정사", "나의"], "gym": ["명사", "체육관"], "memberships": ["명사", "회원권", "membership"], "exercise": ["명사", "운동"], "classes": ["명사", "수업", "class"], "basically": ["부사", "기본적으로"], "decided": ["동사", "결정했다", "decide"], "leave": ["동사", "두다"], "car": ["명사", "차"], "drive": ["명사", "진입로(drive way)"], "way": ["명사", "(drive way) 진입로"], "most": ["부사", "가장"], "of": ["전치사", "~의"], "now": ["부사", "지금"], "just": ["부사", "막, 단지"], "i'm": ["대명사", "나는 ~이다", "I am"], "healthiest": ["형용사", "가장 건강한", "healthy"], "i've": ["대명사", "나는 ~했다", "I have"], "been": ["과거분사", "~였던", "be"], "wandering": ["동명사", "돌아다니기", "wander"], "free": ["형용사", "무료의"], "purpose": ["명사", "목적"], "also": ["부사", "또한"], "discover": ["동사", "발견하다"], "artistic": ["형용사", "예술적인"], "ideas": ["명사", "아이디어", "idea"], "she": ["대명사", "그녀"], "says": ["동사", "말하다", "say"], "natural": ["형용사", "자연의"], "surroundings": ["명사", "환경"], "inspire": ["동사", "영감을 주다"], "feels": ["동사", "느끼다", "feel"], "more": ["부사", "더"], "confidence": ["명사", "자신감"], "better": ["부사", "더 잘", "well"], "able": ["형용사", "~할 수 있는"], "focus": ["동사", "집중하다"], "goals": ["명사", "목표", "goal"]}, "questions": [{"no": 139, "q": "", "options": ["made", "makes", "will make", "had made"], "answer": 1, "explain": "정답 (B) makes\n해석: Aham 씨는 매일 적어도 1마일은 걷는 것을 원칙으로 삼는다.\n정답 근거: 문장의 동사 자리. 매일 걷는 현재의 습관(every day)을 말하므로 현재시제이며 주어 Ms. Aham(단수) → makes. make it a point to V(~하는 것을 원칙으로 하다).\n오답 분석: (A) made: 과거 — 현재 습관(every day, now I just walk)과 불일치. / (C) will make: 미래 — 이미 하고 있는 습관과 불일치. / (D) had made: 과거완료 — 불일치.\n지문 개요: 예술가이자 디지털 콘텐츠 관리자 Stacy Aham이 매일 1마일 이상 걷는 습관 덕분에 건강해지고 예술적 아이디어를 얻으며, 아이디어에 자신감이 생기고 목표에 집중하게 되었다는 기사."}, {"no": 140, "q": "", "options": ["anything", "something", "everywhere", "elsewhere"], "answer": 2, "explain": "정답 (C) everywhere\n해석: 지금은 그냥 어디든 걸어 다닙니다.\n정답 근거: 자동사 walk 뒤 자리 → 장소 부사. 차를 두고 다닌다고 했으므로 \"어디든 걸어 다닌다\" → everywhere.\n오답 분석: (A) anything: 대명사 — 자동사 walk의 목적어가 될 수 없음. / (B) something: 대명사 — 동일. / (D) elsewhere: '다른 곳에' — 비교 대상 장소가 없어 의미 불가."}, {"no": 141, "q": "", "options": ["I'm always sure to wear a coat.", "It probably won't be this way for long.", "I expect to return to work next month.", "This is especially true in the springtime."], "answer": 3, "explain": "정답 (D) This is especially true in the springtime.\n해석: 봄철에는 특히 그렇습니다.\n정답 근거: 바로 앞 문장 \"자연환경이 영감을 준다\"를 받아 \"이것(This)은 봄에 특히 그렇다\"로 부연하는 흐름이 자연스러움.\n오답 분석: (A) 코트를 입는다는 말은 영감 이야기와 무관. / (B) 오래가지 않을 것이라는 말은 긍정적 흐름과 모순. / (C) 다음 달 복직은 문맥과 무관."}, {"no": 142, "q": "", "options": ["consequently", "summarily", "adversely", "briefly"], "answer": 0, "explain": "정답 (A) consequently\n해석: Aham 씨는 결과적으로 자신의 아이디어에 더 자신감을 느낀다.\n정답 근거: 앞에서 걷기 습관의 효과를 나열한 뒤 그 결과로 자신감과 집중력이 생겼다는 마무리 → consequently(결과적으로). 주어와 동사 사이 부사 자리.\n오답 분석: (B) summarily: '즉결로, 약식으로' — 의미 불가. / (C) adversely: '불리하게' — 긍정적 결과와 모순. / (D) briefly: '잠시' — 의미 불가."}]}, {"range": "143-146", "passage": "SINGAPORE—Goh Tech Global, Singapore's top ---143--- of accounting and finance software, has announced the appointment of Grace Ng as its new chief operating officer. The appointment is part of an ---144--- restructuring plan. Ms. Ng comes to Goh Tech Global with more than fifteen years of executive experience in the industry, including as COO at Singapore-based Ridgeco Industries. \"We are glad to have Ms. Ng assume this role at such an important stage of growth in our company,\" states Alan Chiang, CEO of Goh Tech Global. \"---145---. She ---146--- our position as a technology company.\" Ms. Ng will start at Goh Tech Global on 15 May.", "tr": "싱가포르 — 싱가포르 최고의 회계·재무 소프트웨어 공급업체(143)인 Goh Tech Global이 Grace Ng를 신임 최고운영책임자(COO)로 임명했다고 발표했다. 이번 임명은 진행 중인(144) 구조조정 계획의 일환이다. Ng 씨는 싱가포르 소재 Ridgeco Industries의 COO를 포함해 업계에서 15년 이상의 경영진 경력을 갖고 Goh Tech Global에 합류한다. \"회사 성장의 이토록 중요한 단계에서 Ng 씨가 이 역할을 맡게 되어 기쁩니다.\" Goh Tech Global CEO Alan Chiang은 말한다. \"그녀의 전문성은 우리가 앞으로 나아가는 데 도움이 될 것입니다(145). 그녀는 기술 기업으로서 우리의 입지를 강화할 것입니다(146).\" Ng 씨는 5월 15일 Goh Tech Global에서 근무를 시작한다.", "vocab": "provider 명 공급업체 / accounting 명 회계 / appointment 명 임명 / chief operating officer 명 최고운영책임자 / ongoing 형 진행 중인 / restructuring 명 구조조정 / executive 형 경영진의 / assume 동 (역할을) 맡다 / expertise 명 전문 지식 / strengthen 동 강화하다", "g": {"singapore—goh": ["고유명사", "싱가포르—고(사명)"], "in": ["전치사", "~에, ~안에"], "ng": ["고유명사", "응(인명)"], "a": ["관사", "하나의"], "goh": ["고유명사", "고(사명)"], "tech": ["고유명사", "테크(사명)"], "global": ["고유명사", "글로벌(사명)"], "singapore's": ["고유명사", "싱가포르의"], "to": ["전치사", "~로"], "top": ["형용사", "최고의"], "of": ["전치사", "~의"], "accounting": ["명사", "회계"], "and": ["접속사", "그리고"], "an": ["관사", "하나의"], "finance": ["명사", "재무"], "software": ["명사", "소프트웨어"], "are": ["동사", "~이다", "be"], "has": ["동사", "가지다, (완료)", "have"], "as": ["전치사", "~로서"], "announced": ["과거분사", "발표한", "announce"], "the": ["관사", "그"], "appointment": ["명사", "임명"], "grace": ["고유명사", "그레이스(인명)"], "its": ["한정사", "그것의"], "new": ["형용사", "새로운"], "chief": ["형용사", "최고의"], "operating": ["형용사", "운영의"], "at": ["전치사", "~에, ~에서"], "officer": ["명사", "책임자"], "is": ["동사", "~이다", "be"], "part": ["명사", "일부"], "restructuring": ["명사", "구조 조정"], "plan": ["명사", "계획"], "ms": ["명사", "~씨(여성)"], "comes": ["동사", "오다", "come"], "with": ["전치사", "~와 함께, ~으로"], "more": ["부사", "더"], "than": ["접속사", "~보다"], "fifteen": ["숫자", "15"], "years": ["명사", "해, 연도", "year"], "executive": ["형용사", "경영진의"], "experience": ["명사", "경험"], "industry": ["명사", "업계"], "including": ["전치사", "~을 포함하여"], "coo": ["명사", "최고운영책임자"], "singapore-based": ["형용사", "싱가포르에 본사를 둔"], "ridgeco": ["고유명사", "리지코(사명)"], "industries": ["고유명사", "인더스트리즈(사명)"], "we": ["대명사", "우리"], "glad": ["형용사", "기쁜"], "have": ["동사", "가지다, (완료)"], "assume": ["동사", "(역할을) 맡다"], "this": ["한정사", "이"], "role": ["명사", "역할"], "such": ["한정사", "그런"], "important": ["형용사", "중요한"], "stage": ["명사", "단계"], "growth": ["명사", "성장"], "our": ["한정사", "우리의"], "company": ["명사", "회사"], "states": ["동사", "말하다", "state"], "alan": ["고유명사", "앨런(인명)"], "chiang": ["고유명사", "창(인명)"], "ceo": ["명사", "최고경영자"], "she": ["대명사", "그녀"], "position": ["명사", "위치"], "on": ["전치사", "~에, ~위에"], "technology": ["명사", "기술"], "will": ["조동사", "~할 것이다"], "start": ["동사", "시작하다"], "15": ["숫자", "15"], "may": ["조동사", "~일지도 모른다"]}, "questions": [{"no": 143, "q": "", "options": ["provider", "opponent", "associate", "method"], "answer": 0, "explain": "정답 (A) provider\n해석: 싱가포르 최고의 회계·재무 소프트웨어 공급업체인 Goh Tech Global\n정답 근거: 「Singapore's top + 빈칸 + of accounting software」로 회사를 설명하는 동격 명사 → 소프트웨어 공급업체 provider.\n오답 분석: (B) opponent: '상대, 적수' — 의미 불가. / (C) associate: '동료, 제휴사' — 소프트웨어의 동료라는 뜻이 되어 불가. / (D) method: '방법' — 회사와 동격 불가.\n지문 개요: 싱가포르 회계·재무 소프트웨어 업체 Goh Tech Global이 진행 중인 구조조정 계획의 일환으로 Grace Ng를 신임 최고운영책임자로 임명했으며, 15년 이상의 경영 경력을 가진 그녀가 5월 15일 합류한다는 보도자료."}, {"no": 144, "q": "", "options": ["alarming", "ongoing", "infrequent", "instant"], "answer": 1, "explain": "정답 (B) ongoing\n해석: 이번 임명은 진행 중인 구조조정 계획의 일환이다.\n정답 근거: 관사 an 뒤 형용사 자리(명사 restructuring plan 수식). 현재 진행되고 있는 구조조정 계획 → ongoing.\n오답 분석: (A) alarming: '놀라운' — 긍정적 발표와 불일치. / (C) infrequent: '드문' — 계획을 꾸미기에 의미 불가. / (D) instant: '즉각적인' — 구조조정 계획과 어울리지 않음."}, {"no": 145, "q": "", "options": ["She used to be well-known for that.", "This had happened before, so many employees were unsurprised.", "Her expertise will help us as we move forward.", "Similar opportunities will become available."], "answer": 2, "explain": "정답 (C) Her expertise will help us as we move forward.\n해석: 그녀의 전문성은 우리가 앞으로 나아가는 데 도움이 될 것입니다.\n정답 근거: CEO가 Ng 씨 영입을 반기는 발언 속에서, 뒤 문장 \"그녀는 우리 입지를 강화할 것\"과 같은 맥락으로 그녀의 전문성이 회사에 도움이 된다는 내용이 자연스러움.\n오답 분석: (A) 과거에 그것으로 유명했다는 말은 지시 대상이 없고 흐름에 맞지 않음. / (B) 직원들이 놀라지 않았다는 내용은 인용문의 긍정적 취지와 무관. / (D) 유사한 기회가 생길 것이라는 말은 문맥과 무관."}, {"no": 146, "q": "", "options": ["had strengthened", "was strengthening", "will strengthen", "strengthen"], "answer": 2, "explain": "정답 (C) will strengthen\n해석: 그녀는 기술 기업으로서 우리의 입지를 강화할 것입니다.\n정답 근거: 문장의 동사 자리. Ng 씨가 5월 15일에 근무를 \"시작할\" 예정이므로 앞으로 할 일 → 미래 will strengthen. 타동사 strengthen 뒤 목적어 our position 있음(능동).\n오답 분석: (A) had strengthened: 과거완료 — 아직 합류 전이므로 불일치. / (B) was strengthening: 과거진행 — 불일치. / (D) strengthen: 현재 — 주어 She(단수)와 수 불일치(strengthens 필요)."}]}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a-r2-p7',$mkd${"id": "a-r2-p7", "area": "RC", "part": 7, "group": "A급 과제", "series": 3, "round": 2, "level": "중급", "title": "A급 과제 2회 · PART 7 (기출독해 2문항 3·4회)", "notes": [], "items": [], "sets": [{"range": "147-148", "sub": "기출독해 2문항 3회", "passage": "We hope you are enjoying your new Blizzo Max product. You can get additional items by taking advantage of our special opportunities!\n1. Be a Product Tester. We are continually developing new products. We will send you one at no charge if you agree to provide us with detailed comments about its quality and usage.\n2. Be a Social Media Influencer. If you have a large social media presence, you can get special discounts or rewards on future purchases. Contact us about ways to make your followers aware of the benefits of Blizzo Max products.\nIf you are interested in these opportunities, please e-mail us at info@blizzomax.com.", "tr": "새 Blizzo Max 제품을 즐기고 계시길 바랍니다. 저희의 특별한 기회를 활용해 추가 제품을 받으실 수 있습니다! 1. 제품 테스터가 되세요. 저희는 계속해서 신제품을 개발하고 있습니다. 제품의 품질과 사용에 관한 상세한 의견을 제공하는 데 동의하시면 신제품을 무료로 보내 드립니다. 2. 소셜 미디어 인플루언서가 되세요. 소셜 미디어 영향력이 크시다면 향후 구매 시 특별 할인이나 보상을 받을 수 있습니다. 팔로워들에게 Blizzo Max 제품의 장점을 알릴 방법에 대해 문의하세요. 이 기회에 관심이 있으시면 info@blizzomax.com으로 이메일을 보내 주십시오.", "vocab": "additional 형 추가의 / take advantage of 구 ~을 이용하다 / continually 부 지속적으로 / at no charge 구 무료로 / usage 명 사용 / presence 명 존재감 / reward 명 보상 / aware of 구 ~을 아는", "g": {"we": ["대명사", "우리"], "hope": ["동사", "바라다"], "you": ["대명사", "당신"], "a": ["관사", "하나의"], "are": ["동사", "~이다", "be"], "enjoying": ["현재분사", "즐기는", "enjoy"], "in": ["전치사", "~에, ~안에"], "your": ["한정사", "당신의"], "our": ["한정사", "우리의"], "new": ["형용사", "새로운"], "blizzo": ["고유명사", "블리조(상호)"], "max": ["고유명사", "맥스(상호)"], "product": ["명사", "제품"], "can": ["조동사", "~할 수 있다"], "get": ["동사", "얻다"], "additional": ["형용사", "추가의"], "on": ["전치사", "~에, ~위에"], "items": ["명사", "물품", "item"], "by": ["전치사", "~에 의해, ~까지"], "taking": ["동명사", "(take advantage of) 활용하기", "take"], "advantage": ["명사", "이점, 활용"], "of": ["전치사", "~의"], "special": ["형용사", "특별한"], "opportunities": ["명사", "기회", "opportunity"], "or": ["접속사", "또는"], "1": ["숫자", "1"], "be": ["동사", "~이다, 되다"], "tester": ["명사", "테스터"], "continually": ["부사", "계속해서"], "developing": ["현재분사", "개발하는", "develop"], "products": ["명사", "제품", "product"], "will": ["조동사", "~할 것이다"], "send": ["동사", "보내다"], "one": ["숫자", "하나"], "at": ["전치사", "~에, ~에서"], "no": ["한정사", "어떤 ~도 없는"], "charge": ["명사", "요금"], "if": ["접속사", "만약 ~라면"], "agree": ["동사", "동의하다"], "to": ["to부정사", "~하는 것"], "provide": ["동사", "제공하다"], "us": ["대명사", "우리를"], "with": ["전치사", "~와 함께, ~으로"], "detailed": ["형용사", "상세한"], "comments": ["명사", "의견", "comment"], "about": ["전치사", "~에 대해"], "its": ["한정사", "그것의"], "quality": ["명사", "품질"], "and": ["접속사", "그리고"], "usage": ["명사", "사용"], "2": ["숫자", "2"], "social": ["형용사", "사회적인"], "media": ["명사", "미디어"], "influencer": ["명사", "인플루언서"], "have": ["동사", "가지다, (완료)"], "large": ["형용사", "큰"], "presence": ["명사", "존재감, 영향력"], "discounts": ["명사", "할인", "discount"], "rewards": ["명사", "보상", "reward"], "future": ["형용사", "향후의"], "purchases": ["명사", "구매", "purchase"], "contact": ["동사", "연락하다"], "ways": ["명사", "방법", "way"], "make": ["동사", "~하게 만들다"], "followers": ["명사", "팔로워", "follower"], "aware": ["형용사", "알고 있는"], "the": ["관사", "그"], "benefits": ["명사", "이점", "benefit"], "interested": ["형용사", "관심 있는"], "these": ["한정사", "이것들의"], "please": ["부사", "부디, ~해 주세요"], "e-mail": ["명사", "이메일"], "info@blizzomax.com": ["고유명사", "이메일 주소"]}, "questions": [{"no": 147, "q": "How can someone get a free Blizzo Max item?", "options": ["By registering for a membership", "By buying two Blizzo Max products at full price", "By entering and winning a monthly drawing", "By giving feedback about a product"], "answer": 3, "explain": "정답 (D) By giving feedback about a product\n해석: 무료 Blizzo Max 제품은 어떻게 받을 수 있는가?\n정답 근거: \"품질과 사용에 관한 상세 의견을 제공하는 데 동의하면 신제품을 무료로 보내 준다\" → 제품에 대한 피드백 제공. provide detailed comments → giving feedback.\n오답 분석: (A) 회원 가입 언급 없음. / (B) 정가 구매 조건 없음. / (C) 월별 추첨 언급 없음.\n지문 개요: Blizzo Max 구매 고객에게 제품 테스터(신제품 무료 제공, 상세 의견 제공 조건)와 소셜 미디어 인플루언서(할인·보상) 두 가지 기회를 안내하는 안내문.", "vocab": "Paraphrase: send you one at no charge / provide detailed comments → giving feedback about a product", "g": {"get": ["동사", "얻다"], "item": ["명사", "물품"], "how": ["부사", "어떻게"], "someone": ["대명사", "누군가"], "max": ["고유명사", "맥스(상호)"], "blizzo": ["고유명사", "블리조(상호)"], "a": ["관사", "하나의"], "can": ["조동사", "~할 수 있다"], "free": ["형용사", "무료의"]}}, {"no": 148, "q": "How does Blizzo Max plan to use social media?", "options": ["To learn about competing products", "To promote its products", "To post job openings", "To identify consumer trends"], "answer": 1, "explain": "정답 (B) To promote its products\n해석: Blizzo Max는 소셜 미디어를 어떻게 활용할 계획인가?\n정답 근거: \"팔로워들에게 Blizzo Max 제품의 장점을 알릴 방법\" → 제품 홍보 목적. make your followers aware of the benefits → promote its products.\n오답 분석: (A) 경쟁 제품 조사 언급 없음. / (C) 채용 공고 게시 없음. / (D) 소비자 트렌드 파악 언급 없음.", "vocab": "Paraphrase: make your followers aware of the benefits → promote its products", "g": {"use": ["동사", "이용하다"], "media": ["명사", "미디어"], "how": ["부사", "어떻게"], "to": ["to부정사", "~하는 것"], "does": ["조동사", "(의문문 조동사)", "do"], "max": ["고유명사", "맥스(상호)"], "plan": ["동사", "계획하다"], "blizzo": ["고유명사", "블리조(상호)"], "social": ["형용사", "사회적인"]}}]}, {"range": "149-150", "sub": "기출독해 2문항 3회", "passage": "Thinking about a career in travel writing?\nThe Kuala Lumpur Writing Centre is offering a new travel writing class. The instructor is Sabrina Khan, whose work has been featured in many national and international publications. Select from five evening sessions during the week of April 22-26, or two full-day sessions on the weekend of April 27 and 28. Registration is limited, and our classes fill up fast. Classes take place at our main campus in Kuala Lumpur. The campus is near the city's main transit hub, easily accessible by bus and train. Call the registration desk at 03 2333-0108 for further information.", "tr": "여행 작가라는 직업을 생각 중이신가요? Kuala Lumpur Writing Centre가 새 여행 작문 강좌를 제공합니다. 강사는 Sabrina Khan으로, 그녀의 글은 국내외 여러 간행물에 실렸습니다. 4월 22~26일 주중 저녁 5회 과정 또는 4월 27·28일 주말 종일 2회 과정 중 선택하세요. 등록 인원은 제한되어 있으며 강좌는 빨리 마감됩니다. 수업은 쿠알라룸푸르 본교에서 진행됩니다. 본교는 도시의 주요 교통 허브 근처에 있어 버스와 기차로 쉽게 갈 수 있습니다. 자세한 정보는 등록 데스크 03 2333-0108로 문의하세요.", "vocab": "career 명 직업, 경력 / instructor 명 강사 / feature 동 싣다, 특집으로 다루다 / publication 명 출판물 / registration 명 등록 / fill up 구 꽉 차다 / transit hub 명 교통 중심지 / accessible 형 접근 가능한", "g": {"thinking": ["현재분사", "생각하는", "think"], "in": ["전치사", "~에, ~안에"], "a": ["관사", "하나의"], "about": ["전치사", "~에 대해"], "career": ["명사", "직업, 경력"], "travel": ["명사", "여행"], "writing": ["명사", "작문, 글쓰기"], "the": ["관사", "그"], "kuala": ["고유명사", "쿠알라(지명)"], "lumpur": ["고유명사", "룸푸르(지명)"], "centre": ["명사", "센터"], "is": ["동사", "~이다", "be"], "of": ["전치사", "~의"], "offering": ["현재분사", "제공하는", "offer"], "new": ["형용사", "새로운"], "class": ["명사", "강좌"], "instructor": ["명사", "강사"], "or": ["접속사", "또는"], "sabrina": ["고유명사", "사브리나(인명)"], "khan": ["고유명사", "칸(인명)"], "whose": ["관계사", "그의(소유격)"], "work": ["명사", "작품"], "has": ["동사", "가지다, (완료)", "have"], "been": ["과거분사", "~였던", "be"], "featured": ["과거분사", "실린", "feature"], "at": ["전치사", "~에, ~에서"], "many": ["형용사", "많은"], "national": ["형용사", "국내의"], "on": ["전치사", "~에, ~위에"], "and": ["접속사", "그리고"], "international": ["형용사", "국제의"], "publications": ["명사", "출판물", "publication"], "select": ["동사", "선택하다"], "from": ["전치사", "~로부터"], "five": ["숫자", "다섯"], "evening": ["명사", "저녁"], "sessions": ["명사", "강의 시간", "session"], "during": ["전치사", "~동안"], "week": ["명사", "주"], "april": ["명사", "4월"], "22-26": ["숫자", "22~26일"], "two": ["숫자", "둘"], "full-day": ["형용사", "종일의"], "weekend": ["명사", "주말"], "27": ["숫자", "27"], "28": ["숫자", "28"], "registration": ["명사", "등록"], "limited": ["형용사", "제한된"], "our": ["한정사", "우리의"], "classes": ["명사", "강좌", "class"], "fill": ["동사", "(fill up) 꽉 차다"], "up": ["부사", "(fill up) 가득"], "fast": ["부사", "빨리"], "take": ["동사", "(take place) 열리다"], "place": ["명사", "(take place) 개최"], "main": ["형용사", "주요한"], "campus": ["명사", "캠퍼스"], "near": ["전치사", "~근처에"], "city's": ["명사", "도시의", "city"], "transit": ["명사", "교통"], "hub": ["명사", "중심지"], "easily": ["부사", "쉽게"], "accessible": ["형용사", "접근 가능한"], "by": ["전치사", "~에 의해, ~까지"], "bus": ["명사", "버스"], "train": ["명사", "기차"], "call": ["동사", "전화하다"], "desk": ["명사", "창구"], "03": ["숫자", "지역번호"], "2333-0108": ["숫자", "전화번호"], "for": ["전치사", "~을 위해, ~동안"], "further": ["부사", "더 나아가"], "information": ["명사", "정보"]}, "questions": [{"no": 149, "q": "What is the main purpose of the notice?", "options": ["To post a job opening", "To announce a schedule change", "To recommend a new book", "To promote a training opportunity"], "answer": 3, "explain": "정답 (D) To promote a training opportunity\n해석: 공지의 주된 목적은?\n정답 근거: 새 여행 작문 강좌를 소개하고 일정·등록을 안내 → 교육(훈련) 기회 홍보. a new travel writing class → a training opportunity.\n오답 분석: (A) 채용 공고가 아니라 수강 안내. / (B) 일정 변경 내용 없음. / (C) 책 추천 없음.\n지문 개요: Kuala Lumpur Writing Centre가 유명 작가 Sabrina Khan이 가르치는 새 여행 작문 강좌(4월 22~26일 저녁 5회 또는 27·28일 주말 종일 2회)를 안내하며, 정원 제한과 교통 편리한 본교 위치, 등록 문의 전화를 알리는 공지.", "vocab": "Paraphrase: offering a new travel writing class → promote a training opportunity", "g": {"main": ["형용사", "주요한"], "what": ["대명사", "무엇"], "of": ["전치사", "~의"], "notice": ["명사", "공지"], "the": ["관사", "그"], "is": ["동사", "~이다", "be"], "purpose": ["명사", "목적"]}}, {"no": 150, "q": "What is indicated about the Kuala Lumpur Writing Centre?", "options": ["It was founded by Ms. Khan.", "It has just opened a new campus.", "It is close to public transportation.", "It publishes popular magazines."], "answer": 2, "explain": "정답 (C) It is close to public transportation.\n해석: Kuala Lumpur Writing Centre에 대해 언급된 것은?\n정답 근거: \"본교는 주요 교통 허브 근처에 있어 버스와 기차로 쉽게 갈 수 있다\" → 대중교통과 가까움.\n오답 분석: (A) Khan 씨는 강사일 뿐 설립자라는 언급 없음. / (B) 새 캠퍼스 개설 언급 없음. / (D) 잡지 발행 언급 없음 — Khan의 글이 간행물에 실렸다는 내용.", "vocab": "Paraphrase: near the city's main transit hub, accessible by bus and train → close to public transportation", "g": {"about": ["전치사", "~에 대해"], "what": ["대명사", "무엇"], "centre": ["명사", "센터"], "indicated": ["과거분사", "언급된", "indicate"], "the": ["관사", "그"], "lumpur": ["고유명사", "룸푸르(지명)"], "is": ["동사", "~이다", "be"], "kuala": ["고유명사", "쿠알라(지명)"], "writing": ["명사", "작문, 글쓰기"]}}]}, {"range": "151-152", "sub": "기출독해 2문항 3회", "passage": "Lindon Hotel and Conference Center — Room Service Order\nRoom Number: 802\nGuest: Henry Crary\nOrder Received: May 10 at 5:30 A.M.\nOrder Details: Combination Platter 7 and Combination Platter 12\nOrder Total: $35.50\nDelivery Date and Time Requested: May 10 at 8:00 A.M.\nSpecial Request: Call room before delivering\nNote: Room was called at 7:45 A.M. on May 10 by Asha Lewis\nDelivery Status: Completed at 7:55 A.M. on May 10 by Asha Lewis", "tr": "Lindon Hotel and Conference Center — 룸서비스 주문 객실 번호: 802 / 투숙객: Henry Crary / 주문 접수: 5월 10일 오전 5:30 주문 내역: 콤비네이션 플래터 7번 및 콤비네이션 플래터 12번 / 주문 합계: 35.50달러 요청 배달 일시: 5월 10일 오전 8:00 / 특별 요청: 배달 전 객실에 전화 비고: 5월 10일 오전 7:45에 Asha Lewis가 객실에 전화함 배달 상태: 5월 10일 오전 7:55에 Asha Lewis가 완료", "vocab": "room service 명 룸서비스 / platter 명 모둠 요리 / total 명 총액 / request 동 요청하다 / deliver 동 배달하다 / status 명 상태 / fulfill 동 이행하다 / complete 동 완료하다", "g": {"lindon": ["고유명사", "린던(호텔명)"], "on": ["전치사", "~에, ~위에"], "hotel": ["명사", "호텔"], "and": ["접속사", "그리고"], "conference": ["명사", "회의"], "center": ["명사", "센터"], "room": ["명사", "객실"], "service": ["명사", "서비스"], "order": ["명사", "주문"], "number": ["명사", "번호"], "802": ["숫자", "802"], "guest": ["명사", "투숙객"], "henry": ["고유명사", "헨리(인명)"], "crary": ["고유명사", "크레리(인명)"], "received": ["과거분사", "접수된", "receive"], "may": ["조동사", "~일지도 모른다"], "10": ["숫자", "10"], "at": ["전치사", "~에, ~에서"], "5:30": ["숫자", "5시 30분"], "a.m": ["명사", "오전"], "details": ["명사", "세부 사항", "detail"], "combination": ["명사", "조합, 모둠"], "platter": ["명사", "플래터(큰 접시 요리)"], "7": ["숫자", "7"], "12": ["숫자", "12"], "total": ["명사", "합계"], "$35.50": ["숫자", "35.50달러"], "delivery": ["명사", "배달"], "date": ["명사", "날짜"], "time": ["명사", "시간"], "request": ["명사", "요청"], "requested": ["과거분사", "요청된", "request"], "8:00": ["숫자", "8시"], "special": ["형용사", "특별한"], "call": ["동사", "전화하다"], "before": ["전치사", "~전에"], "delivering": ["동명사", "배달하기", "deliver"], "note": ["명사", "비고"], "was": ["동사", "~였다", "be"], "called": ["과거분사", "전화받은", "call"], "7:45": ["숫자", "7시 45분"], "by": ["전치사", "~에 의해, ~까지"], "asha": ["고유명사", "아샤(인명)"], "lewis": ["고유명사", "루이스(인명)"], "status": ["명사", "상태"], "completed": ["과거분사", "완료된", "complete"], "7:55": ["숫자", "7시 55분"]}, "questions": [{"no": 151, "q": "What is indicated about Mr. Crary?", "options": ["He moved to a different room.", "He requested to check out early.", "He ordered two items from the menu.", "He picked up a package at the front desk."], "answer": 2, "explain": "정답 (C) He ordered two items from the menu.\n해석: Crary 씨에 대해 언급된 것은?\n정답 근거: 주문 내역에 콤비네이션 플래터 7번과 12번, 두 가지 메뉴가 적혀 있음 → 메뉴에서 두 품목 주문.\n오답 분석: (A) 객실 이동 기록 없음. / (B) 조기 체크아웃 요청 없음. / (D) 프런트 데스크 소포 수령 언급 없음.\n지문 개요: Lindon Hotel 802호 투숙객 Henry Crary의 룸서비스 주문서. 오전 5시 30분에 접수, 콤비네이션 플래터 7·12번 주문(35.50달러), 오전 8시 배달 요청, 배달 전 전화 요청에 따라 Asha Lewis가 7시 45분 전화 후 7시 55분 배달 완료.", "vocab": "Paraphrase: Combination Platter 7 and Combination Platter 12 → ordered two items", "g": {"about": ["전치사", "~에 대해"], "what": ["대명사", "무엇"], "indicated": ["과거분사", "언급된", "indicate"], "crary": ["고유명사", "크레리(인명)"], "is": ["동사", "~이다", "be"], "mr": ["명사", "~씨(남성)"]}}, {"no": 152, "q": "When did Ms. Lewis fulfill a special request?", "options": ["At 5:30 A.M.", "At 7:45 A.M.", "At 7:55 A.M.", "At 8:00 A.M."], "answer": 1, "explain": "정답 (B) At 7:45 A.M.\n해석: Lewis 씨는 특별 요청을 언제 이행했는가?\n정답 근거: 특별 요청은 \"배달 전 객실에 전화\"이고, 비고에 \"오전 7:45에 Asha Lewis가 객실에 전화함\" → 7시 45분.\n오답 분석: (A) 5:30은 주문 접수 시각. / (C) 7:55는 배달 완료 시각. / (D) 8:00은 요청한 배달 시각.", "vocab": "Paraphrase: Call room before delivering / Room was called at 7:45 A.M. → at 7:45 A.M.", "g": {"when": ["접속사", "~할 때"], "ms": ["명사", "~씨(여성)"], "special": ["형용사", "특별한"], "did": ["조동사", "(과거 조동사)", "do"], "request": ["명사", "요청"], "lewis": ["고유명사", "루이스(인명)"], "fulfill": ["동사", "이행하다"], "a": ["관사", "하나의"]}}]}, {"range": "153-154", "sub": "기출독해 2문항 3회", "passage": "Amelie Lachance (3:44 P.M.) Hideo, do you remember the name of the speaker we heard at the conference in Manila last week?\nHideo Morizane (3:45 P.M.) Are you asking about the electric vehicle design talk, or the presentation on fuel economy?\nAmelie Lachance (3:47 P.M.) Oh, I mean the woman who led the fuel economy session. I need her name so I can look up the research paper she published.\nHideo Morizane (3:50 P.M.) I wish I could help. I do know that Darrell Raymond was the design expert from the first session I mentioned, but that's all I remember. Is there a conference program online?\nAmelie Lachance (3:51 P.M.) I'll check.", "tr": "Amelie Lachance (오후 3:44) Hideo, 지난주 마닐라 컨퍼런스에서 들었던 발표자 이름 기억나요?\nHideo Morizane (오후 3:45) 전기차 디자인 강연을 말하는 건가요, 아니면 연비 발표요?\nAmelie Lachance (오후 3:47) 아, 연비 세션을 진행한 여성분이요. 그분이 발표한 연구 논문을 찾아보려면 이름이 필요해서요. Hideo Morizane (오후 3:50) 도와드릴 수 있으면 좋겠네요. 제가 말한 첫 세션의 디자인 전문가가 Darrell Raymond였다는 건 알지만, 기억나는 건 그게 전부예요. 온라인에 컨퍼런스 프로그램이 있나요?\nAmelie Lachance (오후 3:51) 확인해 볼게요.", "vocab": "speaker 명 연사 / electric vehicle 명 전기차 / fuel economy 명 연비 / lead 동 진행하다 / look up 구 찾아보다 / research paper 명 연구 논문 / expert 명 전문가 / program 명 프로그램, 일정표", "g": {"a": ["관사", "하나의"], "amelie": ["고유명사", "아멜리(인명)"], "i": ["대명사", "나"], "lachance": ["고유명사", "라샹스(인명)"], "3:44": ["숫자", "3시 44분"], "p.m": ["명사", "오후"], "hideo": ["고유명사", "히데오(인명)"], "do": ["동사", "하다"], "you": ["대명사", "당신"], "remember": ["동사", "기억하다"], "the": ["관사", "그"], "name": ["명사", "이름"], "of": ["전치사", "~의"], "speaker": ["명사", "연사"], "we": ["대명사", "우리"], "heard": ["동사", "들었다", "hear"], "at": ["전치사", "~에, ~에서"], "conference": ["명사", "회의"], "on": ["전치사", "~에, ~위에"], "in": ["전치사", "~에, ~안에"], "manila": ["고유명사", "마닐라"], "last": ["형용사", "지난, 마지막의"], "week": ["명사", "주"], "morizane": ["고유명사", "모리자네(인명)"], "or": ["접속사", "또는"], "3:45": ["숫자", "3시 45분"], "are": ["동사", "~이다", "be"], "asking": ["현재분사", "묻는", "ask"], "about": ["전치사", "~에 대해"], "electric": ["형용사", "전기의"], "vehicle": ["명사", "자동차"], "design": ["명사", "설계"], "talk": ["명사", "강연"], "presentation": ["명사", "발표"], "fuel": ["명사", "연료"], "economy": ["명사", "효율, 절약"], "3:47": ["숫자", "3시 47분"], "oh": ["감탄사", "아"], "mean": ["동사", "의미하다"], "woman": ["명사", "여성"], "who": ["대명사", "누구"], "led": ["동사", "이끌었다", "lead"], "session": ["명사", "세션"], "need": ["동사", "필요하다"], "her": ["한정사", "그녀의"], "so": ["접속사", "그래서"], "can": ["조동사", "~할 수 있다"], "look": ["동사", "(look up) 찾아보다"], "up": ["부사", "(look up) 찾아"], "research": ["명사", "연구"], "paper": ["명사", "논문"], "she": ["대명사", "그녀"], "published": ["동사", "발표했다", "publish"], "is": ["동사", "~이다", "be"], "3:50": ["숫자", "3시 50분"], "wish": ["동사", "바라다"], "could": ["조동사", "~할 수 있을 것이다"], "help": ["동사", "돕다"], "know": ["동사", "알다"], "that": ["접속사", "~라는 것"], "darrell": ["고유명사", "대럴(인명)"], "raymond": ["고유명사", "레이먼드(인명)"], "was": ["동사", "~였다", "be"], "expert": ["명사", "전문가"], "from": ["전치사", "~로부터"], "first": ["형용사", "첫 번째의"], "mentioned": ["동사", "언급했다", "mention"], "but": ["접속사", "그러나"], "that's": ["대명사", "그것은 ~이다", "that is"], "all": ["한정사", "모든"], "there": ["부사", "거기에"], "program": ["명사", "프로그램(일정표)"], "online": ["형용사", "온라인의"], "3:51": ["숫자", "3시 51분"], "i'll": ["대명사", "나는 ~할 것이다", "I will"], "check": ["동사", "확인하다"]}, "questions": [{"no": 153, "q": "What most likely was the subject of the conference in Manila?", "options": ["Architecture", "Manufacturing", "Finance", "Automobiles"], "answer": 3, "explain": "정답 (D) Automobiles\n해석: 마닐라 컨퍼런스의 주제는 무엇이었을 것 같은가?\n정답 근거: 세션 주제가 \"전기차 디자인 강연\"과 \"연비(fuel economy) 발표\" → 자동차 관련 컨퍼런스.\n오답 분석: (A) 건축 관련 내용 없음. / (B) 제조업 일반이 아니라 차량 디자인·연비. / (C) 금융 관련 내용 없음.\n지문 개요: Amelie Lachance가 지난주 마닐라 컨퍼런스에서 연비 세션을 진행한 여성 발표자 이름을 묻지만, Hideo Morizane은 첫 세션의 디자인 전문가 Darrell Raymond만 기억해 온라인 프로그램을 확인해 보자고 제안하는 대화.", "vocab": "Paraphrase: electric vehicle design / fuel economy → automobiles", "g": {"manila": ["고유명사", "마닐라"], "what": ["대명사", "무엇"], "the": ["관사", "그"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "was": ["동사", "~였다", "be"], "subject": ["명사", "제목"], "conference": ["명사", "회의"], "in": ["전치사", "~에, ~안에"], "of": ["전치사", "~의"]}}, {"no": 154, "q": "At 3:50 P.M., what does Mr. Morizane most likely mean when he writes, \"I wish I could help\"?", "options": ["He does not remember a speaker's name.", "He lost his copy of the conference program.", "He does not have time to locate a report.", "He was unable to attend a conference session."], "answer": 0, "explain": "정답 (A) He does not remember a speaker's name.\n해석: 오후 3시 50분에 Morizane 씨가 \"I wish I could help\"라고 쓴 의도는?\n정답 근거: 연비 세션 발표자 이름을 묻자 \"첫 세션 전문가 이름만 알고 그게 기억나는 전부\"라고 답함 → 그 발표자 이름을 기억하지 못함.\n오답 분석: (B) 프로그램 분실 언급 없음 — 온라인 프로그램 확인을 제안함. / (C) 시간 부족이 아니라 기억 못 함. / (D) 세션에 참석하지 못했다는 내용 없음.", "vocab": "Paraphrase: that's all I remember → does not remember a speaker's name", "g": {"at": ["전치사", "~에, ~에서"], "p.m": ["명사", "오후"], "when": ["접속사", "~할 때"], "he": ["대명사", "그"], "i": ["대명사", "나"], "what": ["대명사", "무엇"], "mean": ["동사", "의미하다"], "could": ["조동사", "~할 수 있을 것이다"], "does": ["조동사", "(의문문 조동사)", "do"], "most": ["부사", "가장"], "help": ["동사", "돕다"], "likely": ["부사", "아마"], "mr": ["명사", "~씨(남성)"], "wish": ["동사", "바라다"], "3:50": ["숫자", "3시 50분"], "morizane": ["고유명사", "모리자네(인명)"], "writes": ["동사", "쓰다", "write"]}}]}, {"range": "147-148", "sub": "기출독해 2문항 4회", "passage": "To: Javier Henao <jhenao106@emailright.com>\nFrom: GFE Customer Service <customerservice@grandforkselectric.com>\nDate: January 5\nSubject: Account status\nDear Mr. Henao,\nYour Grand Forks Electric (GFE) customer account 00-8299-095 is set up for automatic monthly payments. Your next bill, in the amount of $136.04, is available to view. The payment will be made by transfer from your bank on January 14.\nTo view your bill, update your personal information, or change your payment settings, please log in to your online GFE account at www.grandforkselectric.com/myaccount.\nThank you for choosing GFE for your energy needs. — GFE Customer Service", "tr": "수신: Javier Henao / 발신: GFE 고객 서비스 / 날짜: 1월 5일 / 제목: 계정 상태\nHenao 씨께, 귀하의 Grand Forks Electric(GFE) 고객 계정 00-8299-095는 월별 자동 결제로 설정되어 있습니다. 136.04달러의 다음 청구서를 확인하실 수 있습니다. 결제는 1월 14일 귀하의 은행에서 이체로 이루어집니다. 청구서 확인, 개인 정보 수정 또는 결제 설정 변경은 www.grandforkselectric.com/myaccount에서 온라인 GFE 계정에 로그인해 주십시오. 에너지 공급사로 GFE를 선택해 주셔서 감사합니다. — GFE 고객 서비스", "vocab": "account 명 계정 / be set up for 구 ~하도록 설정되다 / automatic 형 자동의 / in the amount of 구 ~의 금액으로 / transfer 명 이체 / update 동 갱신하다 / setting 명 설정 / log in 구 로그인하다", "g": {"to": ["전치사", "~에게(수신)"], "javier": ["고유명사", "하비에르(인명)"], "henao": ["고유명사", "에나오(인명)"], "jhenao106@emailright.com": ["고유명사", "이메일 주소"], "from": ["전치사", "~로부터"], "gfe": ["고유명사", "GFE(회사 약칭)"], "customer": ["명사", "고객"], "service": ["명사", "서비스"], "customerservice@grandforkselectric.com": ["고유명사", "이메일 주소"], "grand": ["고유명사", "그랜드(지명)"], "forks": ["고유명사", "포크스(지명)"], "for": ["전치사", "~을 위해, ~동안"], "or": ["접속사", "또는"], "electric": ["고유명사", "전력(회사명)"], "date": ["명사", "날짜"], "at": ["전치사", "~에, ~에서"], "january": ["명사", "1월"], "5": ["숫자", "5"], "subject": ["명사", "제목"], "account": ["명사", "계정"], "status": ["명사", "상태"], "dear": ["형용사", "친애하는"], "mr": ["명사", "~씨(남성)"], "your": ["한정사", "당신의"], "you": ["대명사", "당신"], "00-8299-095": ["숫자", "계정 번호"], "is": ["동사", "~이다", "be"], "set": ["과거분사", "(set up) 설정된", "set"], "up": ["부사", "(set up) 설정"], "automatic": ["형용사", "자동의"], "monthly": ["형용사", "월별의"], "on": ["전치사", "~에, ~위에"], "payments": ["명사", "납부", "payment"], "payment": ["명사", "납부"], "next": ["형용사", "다음의"], "bill": ["명사", "청구서"], "in": ["전치사", "~에, ~안에"], "the": ["관사", "그"], "amount": ["명사", "금액"], "of": ["전치사", "~의"], "$136.04": ["숫자", "136.04달러"], "available": ["형용사", "이용 가능한"], "view": ["동사", "보다"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "made": ["과거분사", "이루어지는", "make"], "by": ["전치사", "~에 의해, ~까지"], "transfer": ["명사", "이체"], "bank": ["명사", "은행"], "14": ["숫자", "14"], "update": ["동사", "갱신하다"], "personal": ["형용사", "개인의"], "information": ["명사", "정보"], "change": ["동사", "변경하다"], "settings": ["명사", "설정", "setting"], "please": ["부사", "부디, ~해 주세요"], "log": ["동사", "(log in) 로그인하다"], "online": ["형용사", "온라인의"], "www.grandforkselectric.com/myaccount": ["고유명사", "웹사이트 주소"], "thank": ["동사", "감사하다"], "choosing": ["동명사", "선택하기", "choose"], "energy": ["명사", "에너지"], "needs": ["명사", "필요", "need"]}, "questions": [{"no": 147, "q": "What is the purpose of the e-mail?", "options": ["To explain a rate increase", "To request that information be updated", "To introduce new payment options", "To give notification of an upcoming payment"], "answer": 3, "explain": "정답 (D) To give notification of an upcoming payment\n해석: 이메일의 목적은?\n정답 근거: 다음 청구액과 \"1월 14일 은행 이체로 결제될 것\"을 알림 → 다가오는 결제 통지.\n오답 분석: (A) 요금 인상 설명 없음. / (B) 정보 수정은 선택 사항으로 안내했을 뿐 요청이 아님. / (C) 새 결제 옵션 소개 없음.\n지문 개요: Grand Forks Electric이 Javier Henao에게 계정이 자동 결제로 설정되어 있고, 다음 청구액 136.04달러가 1월 14일 은행 이체로 결제될 예정이며, 청구서 확인·정보 수정·결제 설정 변경은 온라인 계정에서 하라고 안내하는 이메일.", "vocab": "Paraphrase: The payment will be made on January 14 → notification of an upcoming payment", "g": {"what": ["대명사", "무엇"], "purpose": ["명사", "목적"], "the": ["관사", "그"], "is": ["동사", "~이다", "be"], "e-mail": ["명사", "이메일"], "of": ["전치사", "~의"]}}, {"no": 148, "q": "According to the e-mail, why might Mr. Henao log in to his online account?", "options": ["To see how much he owes", "To make a payment", "To close his customer account", "To contact GFE customer service"], "answer": 0, "explain": "정답 (A) To see how much he owes\n해석: 이메일에 따르면 Henao 씨는 왜 온라인 계정에 로그인할 수 있는가?\n정답 근거: \"청구서를 확인하려면(To view your bill) ~ 로그인하라\" → 납부할 금액 확인. view your bill → see how much he owes.\n오답 분석: (B) 결제는 자동 이체로 이루어지므로 직접 결제 목적이 아님. / (C) 계정 해지 언급 없음. / (D) 고객 서비스 연락 목적 언급 없음.", "vocab": "Paraphrase: To view your bill → see how much he owes", "g": {"his": ["한정사", "그의"], "log": ["동사", "(log in) 로그인하다"], "according": ["부사", "(to와) ~에 따르면"], "to": ["전치사", "~에게(수신)"], "might": ["조동사", "~일지도 모른다"], "online": ["형용사", "온라인의"], "why": ["부사", "왜"], "the": ["관사", "그"], "account": ["명사", "계정"], "mr": ["명사", "~씨(남성)"], "henao": ["고유명사", "에나오(인명)"], "in": ["전치사", "~에, ~안에"], "e-mail": ["명사", "이메일"]}}]}, {"range": "149-150", "sub": "기출독해 2문항 4회", "passage": "Monroy Botanical Gardens (MBG) — Support Us\nBecome a member and enjoy many great benefits.\n· Free admission to MBG · Discounts on all classes and special events · 15 percent discount in the gift shop · 10 percent discount at select local garden centers · A complimentary one-year subscription to Garden Today magazine · Special admission privileges and discounts at hundreds of participating botanical gardens throughout the country", "tr": "Monroy Botanical Gardens(MBG) — 후원하기 회원이 되어 많은 훌륭한 혜택을 누리세요.\n· MBG 무료 입장\n· 모든 강좌 및 특별 행사 할인\n· 기념품점 15% 할인\n· 일부 지역 정원용품점 10% 할인\n· Garden Today 잡지 1년 무료 구독 · 전국 수백 곳의 제휴 식물원 특별 입장 혜택 및 할인", "vocab": "botanical garden 명 식물원 / benefit 명 혜택 / admission 명 입장 / select 형 엄선된 / complimentary 형 무료의 / subscription 명 구독 / privilege 명 특권 / participating 형 참여하는", "g": {"monroy": ["고유명사", "몬로이(지명)"], "on": ["전치사", "~에, ~위에"], "botanical": ["형용사", "식물의"], "a": ["관사", "하나의"], "gardens": ["명사", "정원, 식물원", "garden"], "garden": ["명사", "원예"], "mbg": ["고유명사", "MBG(식물원 약칭)"], "support": ["동사", "후원하다"], "us": ["대명사", "우리를"], "become": ["동사", "되다"], "member": ["명사", "회원"], "and": ["접속사", "그리고"], "enjoy": ["동사", "누리다"], "many": ["형용사", "많은"], "great": ["형용사", "훌륭한"], "at": ["전치사", "~에, ~에서"], "benefits": ["명사", "혜택", "benefit"], "free": ["형용사", "무료의"], "admission": ["명사", "입장"], "to": ["전치사", "~에"], "discount": ["명사", "할인"], "discounts": ["명사", "할인", "discount"], "all": ["한정사", "모든"], "classes": ["명사", "강좌", "class"], "special": ["형용사", "특별한"], "events": ["명사", "행사", "event"], "15": ["숫자", "15"], "percent": ["명사", "퍼센트"], "in": ["전치사", "~에, ~안에"], "the": ["관사", "그"], "gift": ["명사", "선물"], "shop": ["명사", "가게"], "10": ["숫자", "10"], "select": ["형용사", "엄선된"], "local": ["형용사", "지역의"], "centers": ["명사", "센터", "center"], "complimentary": ["형용사", "무료의"], "one-year": ["형용사", "1년의"], "subscription": ["명사", "구독"], "today": ["부사", "오늘"], "magazine": ["명사", "잡지"], "privileges": ["명사", "특권", "privilege"], "hundreds": ["명사", "수백", "hundred"], "of": ["전치사", "~의"], "participating": ["현재분사", "참여하는", "participate"], "throughout": ["전치사", "~전역에"], "country": ["명사", "나라"]}, "questions": [{"no": 149, "q": "Where would the information most likely be found?", "options": ["In a travel brochure", "In a magazine for teachers", "In a local newspaper", "On a message board for employees"], "answer": 0, "explain": "정답 (A) In a travel brochure\n해석: 이 안내문은 어디에서 볼 수 있을 것 같은가?\n정답 근거: 식물원 방문객을 대상으로 회원 가입과 무료 입장·전국 제휴 식물원 입장 혜택을 소개하는 홍보 자료 → 관광·방문 안내 책자(여행 브로슈어)에 실릴 내용.\n오답 분석: (B) 교사 대상 잡지에 실을 내용이 아님. / (C) 지역 신문 기사가 아니라 회원 모집 홍보물. / (D) 직원용 게시판이 아니라 일반 방문객 대상.\n지문 개요: Monroy Botanical Gardens 회원 가입 시 무료 입장, 강좌·행사 할인, 기념품점 15%·제휴 정원용품점 10% 할인, Garden Today 잡지 1년 무료 구독, 전국 제휴 식물원 입장 혜택 등을 안내하는 안내문.", "vocab": "Paraphrase: Support Us / Become a member → in a local newspaper", "g": {"information": ["명사", "정보"], "be": ["동사", "~이다, 되다"], "found": ["과거분사", "발견되는", "find"], "the": ["관사", "그"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "where": ["부사", "어디에"], "would": ["조동사", "~할 것이다"]}}, {"no": 150, "q": "What is stated about Garden Today magazine?", "options": ["It contained an article about MBG.", "It is available at garden centers.", "It is free to MBG members.", "It is published weekly."], "answer": 2, "explain": "정답 (C) It is free to MBG members.\n해석: Garden Today 잡지에 대해 언급된 것은?\n정답 근거: \"Garden Today 잡지 1년 무료 구독(complimentary one-year subscription)\" → 회원에게 무료.\n오답 분석: (A) MBG 관련 기사 언급 없음. / (B) 정원용품점에서 구할 수 있다는 내용 없음 — 할인 혜택만 언급. / (D) 발행 주기 언급 없음.", "vocab": "Paraphrase: complimentary one-year subscription → free to MBG members", "g": {"stated": ["과거분사", "언급된", "state"], "about": ["전치사", "~에 대해"], "today": ["부사", "오늘"], "what": ["대명사", "무엇"], "magazine": ["명사", "잡지"], "garden": ["명사", "원예"], "is": ["동사", "~이다", "be"]}}]}, {"range": "154-155", "sub": "기출독해 2문항 4회", "passage": "To: Delia Kubas <dkubas@kubasgroup.com>\nFrom: Dennis Churm <dchurm@armanarecordsmgmt.com>\nDate: April 7\nSubject: Document shredding services\nDear Ms. Kubas,\nThank you for contacting Armana Records Management regarding our shredding services for your confidential office documents.\nAs we discussed during our phone conversation, our mobile shredding truck is available to come to your business weekly. Alternatively, you can bring your documents to one of our conveniently located shredding centers. Considering the number of documents, I think our mobile shredding truck is the better choice for you.\nPlease let me know the approximate weight of the documents you will need shredded each week and also how many collection bins you expect to use. Once I have that information, I will send you a cost estimate, and if it is acceptable to you, we can discuss the day of the week and the time of day that will work best for you.\nThank you, Dennis Churm, Client Relations Manager, Armana Records Management", "tr": "수신: Delia Kubas / 발신: Dennis Churm / 날짜: 4월 7일 / 제목: 문서 파쇄 서비스\nKubas 씨께, 귀사의 기밀 사무 문서 파쇄 서비스와 관련해 Armana Records Management에 연락 주셔서 감사합니다. 전화 통화에서 논의한 대로, 저희 이동식 파쇄 트럭이 매주 귀사를 방문할 수 있습니다. 또는 편리한 위치의 저희 파쇄 센터 중 한 곳으로 문서를 가져오셔도 됩니다. 문서 양을 고려하면 이동식 파쇄 트럭이 더 나은 선택이라고 생각합니다. 매주 파쇄가 필요한 문서의 대략적인 무게와 사용하실 수거함 개수를 알려 주십시오. 그 정보를 받으면 비용 견적을 보내 드리고, 수락하시면 가장 적합한 요일과 시간대를 논의할 수 있습니다. 감사합니다. Dennis Churm, 고객 관계 관리자, Armana Records Management", "vocab": "shred 동 파쇄하다 / confidential 형 기밀의 / alternatively 부 그 대신에 / conveniently 부 편리하게 / approximate 형 대략의 / collection bin 명 수거함 / estimate 명 견적 / acceptable 형 수락할 만한", "g": {"to": ["전치사", "~에게(수신)"], "delia": ["고유명사", "델리아(인명)"], "i": ["대명사", "나"], "a": ["관사", "하나의"], "kubas": ["고유명사", "쿠바스(인명)"], "as": ["접속사", "~대로"], "dkubas@kubasgroup.com": ["고유명사", "이메일 주소"], "from": ["전치사", "~로부터"], "dennis": ["고유명사", "데니스(인명)"], "is": ["동사", "~이다", "be"], "churm": ["고유명사", "첨(인명)"], "dchurm@armanarecordsmgmt.com": ["고유명사", "이메일 주소"], "armana": ["고유명사", "아르마나(회사명)"], "records": ["명사", "기록", "record"], "date": ["명사", "날짜"], "april": ["명사", "4월"], "7": ["숫자", "7"], "subject": ["명사", "제목"], "document": ["명사", "문서"], "me": ["대명사", "나를"], "shredding": ["명사", "파쇄"], "services": ["명사", "서비스", "service"], "dear": ["형용사", "친애하는"], "ms": ["명사", "~씨(여성)"], "thank": ["동사", "감사하다"], "you": ["대명사", "당신"], "for": ["전치사", "~을 위해, ~동안"], "contacting": ["동명사", "연락하기", "contact"], "management": ["명사", "관리"], "regarding": ["전치사", "~에 관하여"], "our": ["한정사", "우리의"], "your": ["한정사", "당신의"], "confidential": ["형용사", "기밀의"], "of": ["전치사", "~의"], "office": ["명사", "사무실"], "documents": ["명사", "문서", "document"], "we": ["대명사", "우리"], "discussed": ["동사", "논의했다", "discuss"], "discuss": ["동사", "논의하다"], "during": ["전치사", "~동안"], "phone": ["명사", "전화"], "one": ["숫자", "하나"], "conversation": ["명사", "통화"], "mobile": ["형용사", "이동식의"], "truck": ["명사", "트럭"], "available": ["형용사", "이용 가능한"], "come": ["동사", "오다"], "business": ["명사", "사업체"], "weekly": ["부사", "매주"], "week": ["명사", "주"], "alternatively": ["부사", "그 대신에"], "can": ["조동사", "~할 수 있다"], "bring": ["동사", "가져오다"], "conveniently": ["부사", "편리하게"], "located": ["과거분사", "위치한", "locate"], "centers": ["명사", "센터", "center"], "considering": ["전치사", "~을 고려하면"], "the": ["관사", "그"], "number": ["명사", "양, 수"], "think": ["동사", "생각하다"], "better": ["형용사", "더 나은", "good"], "choice": ["명사", "선택"], "please": ["부사", "부디, ~해 주세요"], "let": ["동사", "~하게 하다"], "know": ["동사", "알다"], "approximate": ["형용사", "대략의"], "weight": ["명사", "무게"], "will": ["조동사", "~할 것이다"], "need": ["동사", "필요하다"], "shredded": ["과거분사", "파쇄된", "shred"], "each": ["한정사", "각각의"], "and": ["접속사", "그리고"], "also": ["부사", "또한"], "how": ["부사", "어떻게"], "many": ["형용사", "많은"], "collection": ["명사", "수거"], "bins": ["명사", "통", "bin"], "expect": ["동사", "예상하다"], "use": ["동사", "사용하다"], "once": ["부사", "한 번"], "have": ["동사", "가지다, (완료)"], "that": ["한정사", "그"], "information": ["명사", "정보"], "send": ["동사", "보내다"], "cost": ["명사", "비용"], "estimate": ["명사", "견적"], "if": ["접속사", "만약 ~라면"], "it": ["대명사", "그것"], "acceptable": ["형용사", "받아들일 수 있는"], "day": ["명사", "날"], "time": ["명사", "시간"], "work": ["동사", "(일정이) 맞다"], "best": ["부사", "가장 잘"], "client": ["명사", "고객"], "relations": ["명사", "관계", "relation"], "manager": ["명사", "관리자"]}, "questions": [{"no": 154, "q": "What is one purpose of the e-mail?", "options": ["To announce a company's newest location", "To request feedback on a service", "To inquire about the size of a job", "To offer a special discount"], "answer": 2, "explain": "정답 (C) To inquire about the size of a job\n해석: 이메일의 한 가지 목적은?\n정답 근거: \"매주 파쇄할 문서의 대략적인 무게와 수거함 개수를 알려 달라\" → 작업 규모 문의.\n오답 분석: (A) 새 지점 발표 없음. / (B) 서비스에 대한 피드백 요청 없음. / (D) 특별 할인 제안 없음.\n지문 개요: Armana Records Management의 Dennis Churm이 Delia Kubas에게 주간 방문 파쇄 트럭을 추천하며, 견적을 내기 위해 매주 파쇄할 문서의 대략적인 무게와 수거함 개수를 알려 달라고 요청하는 이메일.", "vocab": "Paraphrase: let me know the approximate weight / how many collection bins → inquire about the size of a job", "g": {"what": ["대명사", "무엇"], "of": ["전치사", "~의"], "the": ["관사", "그"], "is": ["동사", "~이다", "be"], "one": ["숫자", "하나"], "e-mail": ["명사", "이메일"], "purpose": ["명사", "목적"]}}, {"no": 155, "q": "What information has Ms. Kubas probably already provided?", "options": ["How frequently she will need a service", "The best time of day for a service to take place", "The amount of money she is willing to spend", "Whom to contact if she is unavailable"], "answer": 0, "explain": "정답 (A) How frequently she will need a service\n해석: Kubas 씨가 이미 제공했을 것으로 보이는 정보는?\n정답 근거: \"전화 통화에서 논의한 대로 트럭이 매주(weekly) 방문할 수 있다\", \"매주(each week) 파쇄할 문서\" → 주 1회라는 서비스 빈도는 이미 논의됨.\n오답 분석: (B) 요일·시간대는 견적 수락 후 논의할 사항. / (C) 지출 금액은 견적을 아직 보내지 않았으므로 미제공. / (D) 부재 시 연락처 언급 없음.", "vocab": "Paraphrase: As we discussed... weekly → how frequently she will need a service", "g": {"information": ["명사", "정보"], "has": ["동사", "가지다, (완료)", "have"], "ms": ["명사", "~씨(여성)"], "what": ["대명사", "무엇"], "kubas": ["고유명사", "쿠바스(인명)"], "provided": ["과거분사", "제공한", "provide"], "already": ["부사", "이미"], "probably": ["부사", "아마"]}}]}, {"range": "159-160", "sub": "기출독해 2문항 4회", "passage": "Thomas Betz [2:16 P.M.] Hi, Elena. Is something going on with our wireless connection? I can't seem to get online. I've been trying to complete a customer order for the last ten minutes.\nElena Cardona [2:17 P.M.] I'm afraid you're not the only one. We're starting to hear from other staff around the building. We're trying to get it figured out now.\nThomas Betz [2:18 P.M.] Thanks, Elena. Do you have any idea how long we might need to wait?\nElena Cardona [2:19 P.M.] I'm expecting that it should be resolved within the next hour.", "tr": "Thomas Betz [오후 2:16] 안녕하세요, Elena. 무선 연결에 무슨 문제가 있나요? 인터넷에 접속이 안 되는 것 같아요. 지난 10분 동안 고객 주문을 완료하려고 애쓰고 있어요.\nElena Cardona [오후 2:17] 유감스럽게도 당신만 그런 게 아니에요. 건물 곳곳의 다른 직원들에게서도 연락이 오기 시작했어요. 지금 해결하려고 하는 중이에요.\nThomas Betz [오후 2:18] 고마워요, Elena. 얼마나 기다려야 할지 아시나요?\nElena Cardona [오후 2:19] 한 시간 안에 해결될 것으로 예상해요.", "vocab": "wireless connection 명 무선 연결 / get online 구 인터넷에 접속하다 / complete 동 완료하다 / figure out 구 알아내다 / have any idea 구 알다 / resolve 동 해결하다 / within 전 ~이내에", "g": {"thomas": ["고유명사", "토머스(인명)"], "a": ["관사", "하나의"], "betz": ["고유명사", "베츠(인명)"], "be": ["동사", "~이다, 되다"], "2:16": ["숫자", "2시 16분"], "p.m": ["명사", "오후"], "hi": ["감탄사", "안녕"], "i": ["대명사", "나"], "elena": ["고유명사", "엘레나(인명)"], "is": ["동사", "~이다", "be"], "something": ["대명사", "무언가"], "going": ["현재분사", "(go on) 일어나는", "go"], "on": ["전치사", "~에, ~위에"], "with": ["전치사", "~와 함께, ~으로"], "it": ["대명사", "그것"], "our": ["한정사", "우리의"], "wireless": ["형용사", "무선의"], "connection": ["명사", "연결"], "can't": ["조동사", "~할 수 없다", "cannot"], "seem": ["동사", "~인 것 같다"], "to": ["to부정사", "~하는 것"], "get": ["동사", "~되다(get online 접속하다)"], "online": ["형용사", "온라인의"], "i've": ["대명사", "나는 ~했다", "I have"], "been": ["과거분사", "~였던", "be"], "trying": ["현재분사", "노력하는", "try"], "complete": ["동사", "완료하다"], "customer": ["명사", "고객"], "order": ["명사", "주문"], "for": ["전치사", "~을 위해, ~동안"], "the": ["관사", "그"], "last": ["형용사", "지난, 마지막의"], "ten": ["숫자", "10"], "minutes": ["명사", "분", "minute"], "cardona": ["고유명사", "카르도나(인명)"], "do": ["동사", "하다"], "2:17": ["숫자", "2시 17분"], "i'm": ["대명사", "나는 ~이다", "I am"], "afraid": ["형용사", "유감스러운"], "you're": ["대명사", "당신은 ~이다", "you are"], "you": ["대명사", "당신"], "not": ["부사", "~않다"], "only": ["부사", "오직"], "one": ["숫자", "하나"], "we": ["대명사", "우리"], "we're": ["대명사", "우리는 ~이다", "we are"], "starting": ["현재분사", "시작하는", "start"], "hear": ["동사", "듣다(연락받다)"], "from": ["전치사", "~로부터"], "other": ["형용사", "다른"], "staff": ["명사", "직원"], "around": ["전치사", "~주변에, 약"], "building": ["명사", "건물"], "figured": ["과거분사", "(figure out) 해결된", "figure"], "out": ["부사", "(figure out) 해결하여"], "now": ["부사", "지금"], "2:18": ["숫자", "2시 18분"], "thanks": ["명사", "감사"], "have": ["동사", "가지다, (완료)"], "any": ["한정사", "어떤"], "idea": ["명사", "생각, 짐작"], "how": ["부사", "어떻게"], "long": ["부사", "오래"], "might": ["조동사", "~일지도 모른다"], "need": ["동사", "필요하다"], "wait": ["동사", "기다리다"], "2:19": ["숫자", "2시 19분"], "expecting": ["현재분사", "예상하는", "expect"], "that": ["접속사", "~라는 것"], "should": ["조동사", "~해야 한다"], "resolved": ["과거분사", "해결된", "resolve"], "within": ["전치사", "~이내에"], "next": ["형용사", "다음의"], "hour": ["명사", "시간"]}, "questions": [{"no": 159, "q": "In what department does Mr. Betz most likely work?", "options": ["Technical Support", "Building Maintenance", "Customer Service", "Accounting"], "answer": 2, "explain": "정답 (C) Customer Service\n해석: Betz 씨는 어느 부서에서 일할 것 같은가?\n정답 근거: \"고객 주문을 완료하려고 애쓰고 있다(complete a customer order)\" → 고객 서비스 부서.\n오답 분석: (A) 기술 지원은 장애를 해결하는 Cardona 쪽에 가까움. / (B) 건물 유지보수 관련 내용 없음. / (D) 회계 업무 언급 없음.\n지문 개요: Thomas Betz가 고객 주문 처리 중 무선 연결이 끊겨 Elena Cardona에게 문의하고, Cardona는 건물 내 다른 직원들도 같은 문제를 보고하고 있으며 한 시간 내 해결될 것으로 예상한다고 답하는 대화.", "vocab": "Paraphrase: complete a customer order → Customer Service", "g": {"what": ["대명사", "무엇"], "betz": ["고유명사", "베츠(인명)"], "work": ["동사", "일하다"], "does": ["조동사", "(의문문 조동사)", "do"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "mr": ["명사", "~씨(남성)"], "in": ["전치사", "~에, ~안에"], "department": ["명사", "부서"]}}, {"no": 160, "q": "At 2:17 P.M., what does Ms. Cardona mean when she writes, \"I'm afraid you're not the only one\"?", "options": ["Other employees are reporting similar problems.", "She also has some customer orders to fill.", "Other employees will have to attend a meeting.", "She has the same computer model as Mr. Betz."], "answer": 0, "explain": "정답 (A) Other employees are reporting similar problems.\n해석: 오후 2시 17분에 Cardona 씨가 \"I'm afraid you're not the only one\"이라고 쓴 의도는?\n정답 근거: 바로 이어서 \"건물 곳곳의 다른 직원들에게서도 연락이 오기 시작했다\"고 함 → 다른 직원들도 같은 문제를 보고하고 있음.\n오답 분석: (B) 본인도 주문이 있다는 내용 아님. / (C) 회의 참석 언급 없음. / (D) 컴퓨터 모델 언급 없음.", "vocab": "Paraphrase: hear from other staff around the building → other employees are reporting similar problems", "g": {"at": ["전치사", "~에, ~에서"], "p.m": ["명사", "오후"], "ms": ["명사", "~씨(여성)"], "when": ["접속사", "~할 때"], "what": ["대명사", "무엇"], "mean": ["동사", "의미하다"], "does": ["조동사", "(의문문 조동사)", "do"], "the": ["관사", "그"], "she": ["대명사", "그녀"], "cardona": ["고유명사", "카르도나(인명)"], "2:17": ["숫자", "2시 17분"], "afraid": ["형용사", "유감스러운"], "one": ["숫자", "하나"], "not": ["부사", "~않다"], "you're": ["대명사", "당신은 ~이다", "you are"], "only": ["부사", "오직"], "i'm": ["대명사", "나는 ~이다", "I am"], "writes": ["동사", "쓰다", "write"]}}]}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a-r3-p6',$mkd${"id": "a-r3-p6", "area": "RC", "part": 6, "group": "A급 과제", "series": 3, "round": 3, "level": "중급", "title": "A급 과제 3회 · PART 6", "notes": [], "items": [], "sets": [{"range": "131-134", "passage": "The Barrowhill Village Library will be closed for the month of August. After several decades of ---131--- the community, we have decided it is time to refurbish our building. There will be two stages to the ---132---. We will begin by installing new windows in the inner lobby. ---133---.\nPatrons who check out books during the last two weeks of July may keep them ---134--- the work on the building is completed. This means that those books will be due back on September 1.", "tr": "Barrowhill Village 도서관은 8월 한 달간 휴관합니다. 수십 년간 지역사회에 봉사해(131) 온 후, 우리는 건물을 새단장할 때가 되었다고 결정했습니다. 보수 공사(132)는 두 단계로 진행됩니다. 먼저 안쪽 로비에 새 창문을 설치하는 것으로 시작합니다. 그런 다음 도서관 전체를 다시 칠할 것입니다(133). 7월 마지막 2주 동안 책을 대출하신 이용자는 건물 공사가 완료될 때까지(134) 책을 보관하셔도 됩니다. 즉 그 책들의 반납 기한은 9월 1일입니다.", "vocab": "decade 명 10년 / serve 동 봉사하다 / refurbish 동 개보수하다 / stage 명 단계 / renovation 명 개조 / install 동 설치하다 / patron 명 이용객 / check out 구 대출하다 / until 접 ~할 때까지 / due 형 반납 기한인", "g": {"the": ["관사", "그"], "barrowhill": ["고유명사", "배로힐(지명)"], "village": ["명사", "마을"], "library": ["명사", "도서관"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "closed": ["과거분사", "문을 닫은", "close"], "for": ["전치사", "~을 위해, ~동안"], "month": ["명사", "달"], "on": ["전치사", "~에, ~위에"], "of": ["전치사", "~의"], "august": ["명사", "8월"], "after": ["전치사", "~후에"], "several": ["형용사", "여러"], "decades": ["명사", "수십 년", "decade"], "1": ["숫자", "1"], "community": ["명사", "지역 사회"], "it": ["대명사", "그것"], "we": ["대명사", "우리"], "have": ["동사", "가지다, (완료)"], "decided": ["과거분사", "결정한", "decide"], "is": ["동사", "~이다", "be"], "time": ["명사", "시간"], "to": ["to부정사", "~할"], "refurbish": ["동사", "보수하다"], "our": ["한정사", "우리의"], "building": ["명사", "건물"], "in": ["전치사", "~에, ~안에"], "there": ["부사", "거기에"], "two": ["숫자", "둘"], "stages": ["명사", "단계", "stage"], "begin": ["동사", "시작하다"], "by": ["전치사", "~에 의해, ~까지"], "installing": ["동명사", "설치하기", "install"], "new": ["형용사", "새로운"], "windows": ["명사", "창문", "window"], "inner": ["형용사", "내부의"], "lobby": ["명사", "로비"], "patrons": ["명사", "이용객", "patron"], "who": ["대명사", "누구"], "check": ["동사", "(check out) 대출하다"], "out": ["부사", "(check out) 대출하여"], "books": ["명사", "책", "book"], "during": ["전치사", "~동안"], "last": ["형용사", "지난, 마지막의"], "weeks": ["명사", "주", "week"], "july": ["명사", "7월"], "may": ["조동사", "~일지도 모른다"], "keep": ["동사", "보관하다"], "them": ["대명사", "그들을"], "work": ["명사", "공사"], "completed": ["과거분사", "완료된", "complete"], "this": ["한정사", "이"], "means": ["동사", "의미하다", "mean"], "that": ["접속사", "~라는 것"], "those": ["한정사", "그것들의"], "due": ["형용사", "(due back) 반납 기한인"], "back": ["부사", "다시, 뒤로"], "september": ["명사", "9월"]}, "questions": [{"no": 131, "q": "", "options": ["serving", "served", "to serve", "had served"], "answer": 0, "explain": "정답 (A) serving\n해석: 수십 년간 지역사회에 봉사해 온 후\n정답 근거: 「전치사 of + 빈칸 + 명사 the community」 → 전치사 뒤 동명사 자리. 타동사 serve 뒤 목적어 the community가 있으므로 능동 -ing → serving.\n오답 분석: (B) served: 과거분사 — 전치사 뒤에 올 수 없고, 뒤에 목적어가 있어 수동 불가. / (C) to serve: to부정사 — 전치사 뒤 불가. / (D) had served: 동사 — 전치사 뒤 불가.\n지문 개요: Barrowhill Village 도서관이 건물 보수를 위해 8월 한 달간 휴관하며, 공사는 로비 창문 교체 후 전체 재도색의 2단계로 진행되고, 7 월 마지막 2주에 대출한 책은 공사 완료 시까지(9월 1일 반납) 보관할 수 있다는 공지."}, {"no": 132, "q": "", "options": ["discussion", "contest", "renovation", "research"], "answer": 2, "explain": "정답 (C) renovation\n해석: 보수 공사는 두 단계로 진행됩니다.\n정답 근거: 앞 문장 \"건물을 새단장(refurbish)할 때\"를 받아 두 단계(창문 설치, 재도색)로 진행되는 것 → renovation(보수 공사).\n오답 분석: (A) discussion: '논의' — 창문 설치와 도색은 논의 단계가 아님. / (B) contest: '대회' — 의미 불가. / (D) research: '연구' — 의미 불가."}, {"no": 133, "q": "", "options": ["The library also has a multimedia room.", "Rather, we will hire more library staff.", "The library is next to the village museum.", "Then we will repaint the entire library."], "answer": 3, "explain": "정답 (D) Then we will repaint the entire library.\n해석: 그런 다음 도서관 전체를 다시 칠할 것입니다.\n정답 근거: \"두 단계\"라 했고 첫 단계가 창문 설치이므로 두 번째 단계(Then ~ repaint)를 제시하는 문장이 필요함.\n오답 분석: (A) 멀티미디어실 보유는 공사 단계와 무관. / (B) 직원 채용은 건물 보수의 두 번째 단계가 아님. / (C) 도서관 위치 설명은 무관."}, {"no": 134, "q": "", "options": ["until", "around", "where", "which"], "answer": 0, "explain": "정답 (A) until\n해석: 건물 공사가 완료될 때까지 책을 보관하셔도 됩니다.\n정답 근거: 동사 2개(may keep, is completed)이므로 부사절 접속사 필요. \"공사가 완료될 때까지 보관\" → until. 뒤 문장의 반납 기한 9월 1일과 일치.\n오답 분석: (B) around: 전치사 — 뒤에 주어+동사 절을 연결할 수 없음. / (C) where: 관계부사 — 장소 선행사가 없고 의미 불가. / (D) which: 관계대명사 — 뒤 절이 완전하고 의미 불가."}]}, {"range": "135-138", "passage": "The San Pedro Society of Photographic Artists invites you to its ---135--- retreat at Rio Bayas Conference Center from July 21 to July 24. This event is an opportunity for serious photographers to meet and share ---136--- work in a peaceful, scenic location each year. This year, the program will be expanded to include both morning and afternoon sessions. ---137--- are asked to bring several prints or digital files of work to introduce at each of the sessions. The cost of the retreat is $800 and includes room, meals, and gratuities. ---138---.", "tr": "San Pedro 사진 예술가 협회가 7월 21일부터 24일까지 Rio Bayas 컨퍼런스 센터에서 열리는 연례(135) 수련회에 여러분을 초대합니다. 이 행사는 진지한 사진가들이 매년 평화롭고 경치 좋은 장소에서 만나 자신들의(136) 작품을 공유하는 기회입니다. 올해는 프로그램이 오전과 오후 세션을 모두 포함하도록 확대됩니다. 참가자(137)들은 각 세션에서 소개할 작품의 인쇄물이나 디지털 파일을 여러 점 가져오셔야 합니다. 수련회 비용은 800달러이며 숙박, 식사, 팁이 포함됩니다. 비회원은 추가로 25달러의 프로그램 비용을 내셔야 합니다(138).", "vocab": "society 명 협회 / annual 형 연례의 / retreat 명 수련회 / opportunity 명 기회 / scenic 형 경치가 좋은 / expand 동 확대하다 / participant 명 참가자 / print 명 인화 사진 / gratuity 명 팁 / nonmember 명 비회원", "g": {"the": ["관사", "그"], "san": ["고유명사", "산(지명)"], "a": ["관사", "하나의"], "an": ["관사", "하나의"], "pedro": ["고유명사", "페드로(지명)"], "society": ["명사", "협회"], "of": ["전치사", "~의"], "photographic": ["형용사", "사진의"], "to": ["전치사", "~에"], "artists": ["명사", "예술가", "artist"], "is": ["동사", "~이다", "be"], "in": ["전치사", "~에, ~안에"], "invites": ["동사", "초대하다", "invite"], "you": ["대명사", "당신"], "its": ["한정사", "그것의"], "retreat": ["명사", "수련회"], "at": ["전치사", "~에, ~에서"], "rio": ["고유명사", "리오(지명)"], "bayas": ["고유명사", "바야스(지명)"], "conference": ["명사", "회의"], "center": ["명사", "센터"], "from": ["전치사", "~로부터"], "july": ["명사", "7월"], "21": ["숫자", "21"], "24": ["숫자", "24"], "this": ["한정사", "이"], "event": ["명사", "행사"], "opportunity": ["명사", "기회"], "or": ["접속사", "또는"], "for": ["전치사", "~을 위해, ~동안"], "serious": ["형용사", "진지한"], "photographers": ["명사", "사진작가", "photographer"], "meet": ["동사", "만나다"], "and": ["접속사", "그리고"], "share": ["동사", "공유하다"], "are": ["동사", "~이다", "be"], "work": ["명사", "작품"], "peaceful": ["형용사", "평화로운"], "scenic": ["형용사", "경치 좋은"], "location": ["명사", "장소"], "each": ["한정사", "각각의"], "year": ["명사", "해, 연도"], "program": ["명사", "프로그램"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "expanded": ["과거분사", "확대된", "expand"], "include": ["동사", "포함하다"], "both": ["한정사", "둘 다"], "morning": ["명사", "오전"], "afternoon": ["명사", "오후"], "sessions": ["명사", "세션", "session"], "asked": ["과거분사", "요청받은", "ask"], "bring": ["동사", "가져오다"], "several": ["형용사", "여러"], "prints": ["명사", "인화 사진", "print"], "digital": ["형용사", "디지털의"], "files": ["명사", "파일", "file"], "introduce": ["동사", "소개하다"], "cost": ["명사", "비용"], "$800": ["숫자", "800달러"], "includes": ["동사", "포함하다", "include"], "room": ["명사", "숙소"], "meals": ["명사", "식사", "meal"], "gratuities": ["명사", "봉사료", "gratuity"]}, "questions": [{"no": 135, "q": "", "options": ["initial", "monthly", "early", "annual"], "answer": 3, "explain": "정답 (D) annual\n해석: 협회는 연례 수련회에 여러분을 초대합니다.\n정답 근거: 뒤 문장에 \"매년(each year)\" 만나는 기회라고 하므로 해마다 열리는 행사 → annual.\n오답 분석: (A) initial: '최초의' — 매년 열린다는 설명과 모순. / (B) monthly: '월간의' — each year와 불일치. / (C) early: '이른' — 의미 불가.\n지문 개요: San Pedro 사진 예술가 협회가 7월 21~24일 Rio Bayas 컨퍼런스 센터에서 열리는 연례 수련회에 초대하며, 올해는 오전·오후 세션으로 확대되고 참가자는 작품 인쇄물이나 디지털 파일을 지참해야 하며 비용은 800달러(비회원 추가 25달러)라는 초대장."}, {"no": 136, "q": "", "options": ["they", "their", "them", "themselves"], "answer": 1, "explain": "정답 (B) their\n해석: 사진가들이 만나 자신들의 작품을 공유하는 기회\n정답 근거: 타동사 share 뒤 「빈칸 + 명사 work」 → 명사 앞 소유격 their(photographers의 것).\n오답 분석: (A) they: 주격 — 명사 앞 불가. / (C) them: 목적격 — 뒤에 명사 work가 있어 불가. / (D) themselves: 재귀대명사 — 명사 앞 불가."}, {"no": 137, "q": "", "options": ["Participants", "Organizers", "Candidates", "Supervisors"], "answer": 0, "explain": "정답 (A) Participants\n해석: 참가자들은 각 세션에서 소개할 작품을 가져오셔야 합니다.\n정답 근거: 세션에서 소개할 작품을 가져와야 하는 사람 = 수련회에 참여하는 사진가들 → Participants.\n오답 분석: (B) Organizers: '주최자' — 작품을 가져와 소개하는 쪽이 아님. / (C) Candidates: '후보자' — 의미 불가. / (D) Supervisors: '감독관' — 의미 불가."}, {"no": 138, "q": "", "options": ["The conference center hosts many exhibitions.", "Nonmembers are asked to pay an additional $25 program fee.", "The society accepts photo submission requests via e-mail only.", "Most of our members prefer to use lightweight digital cameras."], "answer": 1, "explain": "정답 (B) Nonmembers are asked to pay an additional $25 program fee.\n해석: 비회원은 추가로 25달러의 프로그램 비용을 내셔야 합니다.\n정답 근거: 바로 앞 문장이 수련회 비용(800달러, 포함 항목)을 안내하므로 비용 관련 추가 정보(비회원 추가 요금)가 이어지는 것이 자연스러움.\n오답 분석: (A) 컨퍼런스 센터의 전시회 개최는 비용 설명 뒤에 부적절. / (C) 이메일 제출 방식은 문맥과 무관. / (D) 회원들의 카메라 선호는 무관."}]}, {"range": "139-142", "passage": "CRAIGSBORO (July 21)━Gildermere Park will open its gates to the public on Saturday, July 26, after a five-year project to transform the former golf course into a community recreation area. The new park will offer roughly 25 kilometers of walking and biking trails, as well as two small botanical gardens. ---139---.\nCraigsboro mayor Steven Ramanithy is expected to attend the official opening along with county officials and local residents. ---140---, the event could draw more than 400 people. The mayor, ---141--- has been a vocal proponent of the park's development, notes that the park will enable more people in the area to enjoy fresh air and physical exercise on a regular basis. Moreover, the park is being heralded by community leaders as a ---142--- step forward in environmental conservation efforts locally.", "tr": "CRAIGSBORO (7월 21일) — Gildermere 공원이 옛 골프장을 지역 휴양 공간으로 바꾸는 5년간의 사업을 마치고 7월 26일 토요일 대중에게 문을 연다. 새 공원은 약 25km의 산책로와 자전거 길은 물론 두 곳의 작은 식물원을 제공한다. 정원 중 한 곳은 이 지역 토종 꽃들을 선보일 것이다(139). Craigsboro 시장 Steven Ramanithy가 카운티 공무원 및 지역 주민들과 함께 공식 개장식에 참석할 것으로 예상된다. 총(140), 이 행사는 400명 이상을 끌어모을 수 있다. 공원 개발의 열렬한 지지자였던(141) 시장은 공원 덕분에 지역의 더 많은 사람이 정기적으로 신선한 공기와 운동을 즐길 수 있게 될 것이라고 말한다. 또한 공원은 지역 환경 보전 노력에서 중요한(142) 진전으로 지역사회 지도자들에게 환영받고 있다.", "vocab": "transform A into B 구 A를 B로 바꾸다 / former 형 이전의 / roughly 부 대략 / trail 명 산책로 / native to 구 ~고유의 / in all 구 전부 합쳐 / draw 동 끌어들이다 / proponent 명 지지자 / herald 동 알리다 / conservation 명 보존", "g": {"craigsboro": ["고유명사", "크레이그스보로(지명)"], "a": ["관사", "하나의"], "july": ["명사", "7월"], "21)━gildermere": ["고유명사", "21일) 길더미어(공원명)"], "park": ["명사", "공원"], "will": ["조동사", "~할 것이다"], "open": ["동사", "열다"], "its": ["한정사", "그것의"], "gates": ["명사", "문", "gate"], "to": ["전치사", "~에게"], "the": ["관사", "그"], "public": ["명사", "대중"], "on": ["전치사", "~에, ~위에"], "saturday": ["명사", "토요일"], "26": ["숫자", "26"], "after": ["전치사", "~후에"], "five-year": ["형용사", "5년의"], "project": ["명사", "사업"], "transform": ["동사", "탈바꿈시키다"], "former": ["형용사", "이전의"], "golf": ["명사", "골프"], "course": ["명사", "코스"], "in": ["전치사", "~에, ~안에"], "into": ["전치사", "~안으로"], "community": ["명사", "지역 사회"], "recreation": ["명사", "휴양, 오락"], "area": ["명사", "공간"], "new": ["형용사", "새로운"], "offer": ["동사", "제공하다"], "of": ["전치사", "~의"], "roughly": ["부사", "대략"], "25": ["숫자", "25"], "kilometers": ["명사", "킬로미터", "kilometer"], "walking": ["명사", "걷기"], "and": ["접속사", "그리고"], "biking": ["명사", "자전거 타기"], "trails": ["명사", "산책로", "trail"], "as": ["부사", "(as well as) ~뿐 아니라"], "well": ["부사", "(as well as) ~도"], "two": ["숫자", "둘"], "small": ["형용사", "작은"], "botanical": ["형용사", "식물의"], "gardens": ["명사", "정원", "garden"], "mayor": ["명사", "시장"], "steven": ["고유명사", "스티븐(인명)"], "ramanithy": ["고유명사", "라마니시(인명)"], "is": ["동사", "~이다", "be"], "expected": ["과거분사", "예상되는", "expect"], "attend": ["동사", "참석하다"], "official": ["형용사", "공식적인"], "opening": ["명사", "개장식"], "along": ["전치사", "~을 따라"], "with": ["전치사", "~와 함께, ~으로"], "county": ["명사", "군(행정구역)"], "officials": ["명사", "공무원", "official"], "local": ["형용사", "지역의"], "residents": ["명사", "주민", "resident"], "event": ["명사", "행사"], "could": ["조동사", "~할 수 있을 것이다"], "draw": ["동사", "끌어모으다"], "more": ["부사", "더"], "than": ["접속사", "~보다"], "400": ["숫자", "400"], "people": ["명사", "사람들"], "has": ["동사", "가지다, (완료)", "have"], "been": ["과거분사", "~였던", "be"], "vocal": ["형용사", "목소리를 높이는"], "proponent": ["명사", "지지자"], "park's": ["명사", "공원의", "park"], "development": ["명사", "개발"], "notes": ["동사", "언급하다", "note"], "that": ["접속사", "~라는 것"], "enable": ["동사", "가능하게 하다"], "enjoy": ["동사", "즐기다"], "fresh": ["형용사", "신선한"], "air": ["명사", "공기"], "physical": ["형용사", "신체의"], "exercise": ["명사", "운동"], "regular": ["형용사", "규칙적인"], "basis": ["명사", "기준(on a regular basis 정기적으로)"], "moreover": ["부사", "게다가"], "being": ["현재분사", "~인 것", "be"], "heralded": ["과거분사", "환영받는", "herald"], "by": ["전치사", "~에 의해, ~까지"], "leaders": ["명사", "지도자", "leader"], "step": ["명사", "걸음, 조치"], "forward": ["부사", "앞으로"], "environmental": ["형용사", "환경의"], "conservation": ["명사", "보존"], "efforts": ["명사", "노력", "effort"], "locally": ["부사", "지역적으로"]}, "questions": [{"no": 139, "q": "", "options": ["Some park users have not been locking their bikes.", "One of the gardens will feature flowers native to the region.", "Instead, a ten-kilometer stretch of road will be repaved.", "These will be handed out to visitors on the day of the opening."], "answer": 1, "explain": "정답 (B) One of the gardens will feature flowers native to the region.\n해석: 정원 중 한 곳은 이 지역 토종 꽃들을 선보일 것이다.\n정답 근거: 바로 앞 문장에서 \"두 곳의 작은 식물원(two small botanical gardens)\"을 언급했으므로 그중 하나(One of the gardens)를 부연하는 문장이 자연스러움.\n오답 분석: (A) 아직 개장 전이라 공원 이용자의 자전거 잠금 문제는 불가. / (C) 도로 재포장은 Instead로 연결될 대비 내용이 없음. / (D) These가 가리킬 나눠 줄 물건이 앞에 없음.\n지문 개요: 옛 골프장을 5년에 걸쳐 지역 휴양 공간으로 바꾼 Gildermere 공원이 7월 26일 개장하며, 25km 산책·자전거 길과 두 곳의 식물원을 갖추고, 시장과 공무원·주민 400여 명이 개장식에 참석할 것이며, 환경 보전의 중요한 진전으로 평가된다는 기사."}, {"no": 140, "q": "", "options": ["By comparison", "Previously", "In all", "For example"], "answer": 2, "explain": "정답 (C) In all\n해석: 총 이 행사는 400명 이상을 끌어모을 수 있다.\n정답 근거: 앞 문장에서 시장·카운티 공무원·지역 주민이 참석한다고 한 뒤 이들을 합친 총인원을 말하므로 In all(모두 합쳐).\n오답 분석: (A) By comparison: '비교하면' — 비교 대상 없음. / (B) Previously: '이전에' — 미래 행사와 불일치. / (D) For example: '예를 들어' — 예시 관계 아님."}, {"no": 141, "q": "", "options": ["his", "either", "who", "another"], "answer": 2, "explain": "정답 (C) who\n해석: 공원 개발의 열렬한 지지자였던 시장은 ~라고 말한다.\n정답 근거: 동사 2개(has been, notes)이므로 접속사 필요. 선행사 The mayor(사람) 뒤에서 주어 역할을 하며 절을 이끄는 주격 관계대명사 who.\n오답 분석: (A) his: 소유격 — 접속사 역할이 없어 동사 2개를 연결할 수 없음. / (B) either: 대명사 — 접속사 아님. / (D) another: 대명사 — 접속사 아님."}, {"no": 142, "q": "", "options": ["significantly", "significance", "signify", "significant"], "answer": 3, "explain": "정답 (D) significant\n해석: 지역 환경 보전 노력에서 중요한 진전\n정답 근거: 「관사 a + 빈칸 + 명사 step」 → 명사 앞 형용사 자리 → significant.\n오답 분석: (A) significantly: 부사 — 명사 step을 꾸밀 수 없음. / (B) significance: 명사 — 명사 step 앞에 명사를 둘 수 없음(복합명사 아님). / (C) signify: 동사 — 관사 뒤 불가."}]}, {"range": "143-146", "passage": "5 January\nDear Employees;\nOn behalf of the board of directors of Daville Ltd., I am proud to announce our acquisition of GPD Oil and Gas. ---143---. The merger of the two companies ---144--- to result in over $1 billion in cost savings as administrative are streamlined.\nOne major change brought by the merger will be the ---145--- of the Baker refinery near Melbourne. ---146---, All employees currently assigned to that location will be transferred to other facilities. More details will be provided soon. Please know that we appreciate your hard work, which led to this exciting opportunity.\nSincerely, Jhonson B. Falworth, Secretary, Board of Directors, Daville Ltd.", "tr": "1월 5일\n직원 여러분께, Daville Ltd. 이사회를 대표하여 GPD Oil and Gas 인수를 발표하게 되어 자랑스럽습니다. Daville Ltd.는 이제 이 지역 최대의 석유·천연가스 유통업체입니다(143). 두 회사의 합병은 행정 업무가 간소화됨에 따라 10억 달러 이상의 비용 절감을 가져올 것으로 예상됩니다(144). 합병으로 인한 한 가지 큰 변화는 Melbourne 인근 Baker 정유소의 폐쇄(145)입니다. 결과적으로(146), 현재 그곳에 배정된 모든 직원은 다른 시설로 전근됩니다. 자세한 내용은 곧 제공됩니다. 이 흥미로운 기회로 이어진 여러분의 노고에 감사드립니다. Jhonson B. Falworth, Daville Ltd. 이사회 서기 드림", "vocab": "on behalf of 구 ~을 대표하여 / board of directors 명 이사회 / acquisition 명 인수 / merger 명 합병 / be projected to 구 ~할 것으로 예상되다 / streamline 동 간소화하다 / refinery 명 정유소 / assign 동 배치하다 / transfer 동 전근시키다 / facility 명 시설", "g": {"5": ["숫자", "5"], "january": ["명사", "1월"], "dear": ["형용사", "친애하는"], "employees": ["명사", "직원", "employee"], "on": ["전치사", "~에, ~위에"], "be": ["동사", "~이다, 되다"], "b": ["고유명사", "B(이니셜)"], "behalf": ["명사", "(on behalf of) ~을 대표하여"], "of": ["전치사", "~의"], "the": ["관사", "그"], "board": ["명사", "이사회"], "directors": ["명사", "이사", "director"], "i": ["대명사", "나"], "to": ["to부정사", "~하게 되어"], "daville": ["고유명사", "대빌(회사명)"], "ltd": ["명사", "유한회사"], "am": ["동사", "~이다", "be"], "proud": ["형용사", "자랑스러운"], "announce": ["동사", "발표하다"], "our": ["한정사", "우리의"], "acquisition": ["명사", "인수"], "gpd": ["고유명사", "GPD(회사명)"], "oil": ["명사", "석유"], "and": ["접속사", "그리고"], "gas": ["명사", "가스"], "as": ["접속사", "~함에 따라"], "merger": ["명사", "합병"], "two": ["숫자", "둘"], "companies": ["명사", "회사", "company"], "result": ["동사", "(in) 결과로 낳다"], "in": ["전치사", "~에, ~안에"], "over": ["전치사", "~이상"], "$1": ["숫자", "1(달러)"], "billion": ["숫자", "10억"], "cost": ["명사", "비용"], "savings": ["명사", "절감", "saving"], "administrative": ["형용사", "관리의, 행정의"], "are": ["동사", "~이다", "be"], "streamlined": ["과거분사", "간소화된", "streamline"], "one": ["숫자", "하나"], "major": ["형용사", "주요한"], "change": ["명사", "변화"], "brought": ["과거분사", "초래된", "bring"], "by": ["전치사", "~에 의해, ~까지"], "will": ["조동사", "~할 것이다"], "baker": ["고유명사", "베이커(정유소명)"], "refinery": ["명사", "정유 공장"], "near": ["전치사", "~근처에"], "melbourne": ["고유명사", "멜버른"], "all": ["한정사", "모든"], "currently": ["부사", "현재"], "assigned": ["과거분사", "배치된", "assign"], "that": ["한정사", "그"], "location": ["명사", "장소, 사업장"], "transferred": ["과거분사", "전근된", "transfer"], "other": ["형용사", "다른"], "facilities": ["명사", "시설", "facility"], "more": ["부사", "더"], "details": ["명사", "세부 사항", "detail"], "provided": ["과거분사", "제공되는", "provide"], "soon": ["부사", "곧"], "please": ["부사", "부디, ~해 주세요"], "know": ["동사", "알다"], "we": ["대명사", "우리"], "appreciate": ["동사", "감사하다"], "your": ["한정사", "당신의"], "hard": ["형용사", "열심히 하는"], "work": ["명사", "노고"], "which": ["관계사", "~하는 것"], "led": ["동사", "이끌었다", "lead"], "this": ["한정사", "이"], "exciting": ["형용사", "흥미로운"], "opportunity": ["명사", "기회"], "sincerely": ["부사", "진심으로(맺음말)"], "jhonson": ["고유명사", "존슨(인명)"], "falworth": ["고유명사", "폴워스(인명)"], "secretary": ["명사", "간사, 비서"]}, "questions": [{"no": 143, "q": "", "options": ["GPD Oil and Gas recently celebrated its fortieth anniversary.", "Daville Ltd. is now the region's largest distributor of oil and natural gas.", "We appreciate your interest in investing in our company.", "A new board of directors is elected every three years."], "answer": 1, "explain": "정답 (B) Daville Ltd. is now the region's largest distributor of oil and natural gas.\n해석: Daville Ltd.는 이제 이 지역 최대의 석유·천연가스 유통업체입니다.\n정답 근거: 인수 발표 직후 그 결과(회사의 위상 변화)를 말하는 문장이 자연스럽고, 뒤의 합병 효과 설명으로 이어짐.\n오답 분석: (A) GPD의 40주년은 인수 발표 흐름과 무관. / (C) 투자 관심 감사는 직원 대상 편지와 맞지 않음. / (D) 이사회 선출 주기는 무관.\n지문 개요: Daville Ltd. 이사회가 직원들에게 GPD Oil and Gas 인수를 알리며, 합병으로 10억 달러 이상의 비용 절감이 예상되고 Melbourne 인근 Baker 정유소가 폐쇄되어 해당 직원들은 다른 시설로 전근된다는 편지."}, {"no": 144, "q": "", "options": ["projects", "projecting", "is projected", "has been projecting"], "answer": 2, "explain": "정답 (C) is projected\n해석: 두 회사의 합병은 10억 달러 이상의 비용 절감을 가져올 것으로 예상됩니다.\n정답 근거: 문장의 동사 자리. project(예상하다)는 타동사인데 빈칸 뒤 목적어(명사) 없이 to result가 오므로 수동 is projected (to V). 합병은 \"예상되는\" 대상.\n오답 분석: (A) projects: 능동 — 목적어가 없어 불가. / (B) projecting: 분사 — 동사 없음. / (D) has been projecting: 능동 진행 — 목적어 없음."}, {"no": 145, "q": "", "options": ["closing", "purchase", "dedication", "construction"], "answer": 0, "explain": "정답 (A) closing\n해석: 큰 변화 한 가지는 Baker 정유소의 폐쇄입니다.\n정답 근거: 뒤 문장 \"그곳에 배정된 모든 직원이 다른 시설로 전근된다\"로 보아 정유소가 문을 닫는 것 → closing.\n오답 분석: (B) purchase: '구매' — 직원 전근 이유가 되지 않음. / (C) dedication: '헌정' — 의미 불가. / (D) construction: '건설' — 새로 짓는다면 직원 전근과 모순."}, {"no": 146, "q": "", "options": ["In effect", "In addition", "In case", "In a way"], "answer": 0, "explain": "정답 (A) In effect\n해석: 결과적으로 현재 그곳에 배정된 모든 직원은 다른 시설로 전근됩니다.\n정답 근거: 정유소 폐쇄(원인)에 따라 직원 전근(결과)이 이어지므로 \"사실상, 결과적으로\"를 뜻하는 In effect.\n오답 분석: (B) In addition: '게다가' — 추가가 아니라 폐쇄의 결과임. / (C) In case: '~할 경우에 대비해' — 뒤에 절이 와야 하고 의미 불가. / (D) In a way: '어떤 면에서' — 의미 불가."}]}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a-r3-p7',$mkd${"id": "a-r3-p7", "area": "RC", "part": 7, "group": "A급 과제", "series": 3, "round": 3, "level": "중급", "title": "A급 과제 3회 · PART 7 (기출독해 2문항 5·6회)", "notes": [], "items": [], "sets": [{"range": "147-148", "sub": "기출독해 2문항 5회", "passage": "NORTH RIVER HOTEL — Same-day wash/dry/fold service\n· Drop off at reception before 8:30 A.M. · Ready by 6:00 P.M. · Cost: $10.00 per bag\nITEMS IN BAG\nQUANTITY: Shirts or blouses 4\nTrousers or skirts 3\nDresses —\nSweaters or vests —\nShorts 1\nSocks (pair) 2\nName and room: Lidia Lee, 603\nReceived by: Darnell Reed\nDate: January 19\nTotal cost: $10.00", "tr": "NORTH RIVER HOTEL — 당일 세탁/건조/접기 서비스\n· 오전 8시 30분 전 리셉션에 맡기세요 · 오후 6시까지 준비 · 비용: 가방당 10.00달러\n가방 내 품목 / 수량: 셔츠 또는 블라우스 4 / 바지 또는 치마 3 / 드레스 — / 스웨터 또는 조끼 — / 반바지 1 / 양말(켤레) 2 이름 및 객실: Lidia Lee, 603 / 접수자: Darnell Reed / 날짜: 1월 19일 / 총 비용: 10.00달러", "vocab": "same-day 형 당일의 / fold 동 개다 / drop off 구 맡기다 / reception 명 프런트 / per 전 ~당 / quantity 명 수량 / trousers 명 바지 / receive 동 접수하다", "g": {"north": ["고유명사", "노스(호텔명)"], "or": ["접속사", "또는"], "river": ["고유명사", "리버(호텔명)"], "hotel": ["명사", "호텔"], "same-day": ["형용사", "당일의"], "wash/dry/fold": ["명사", "세탁/건조/개기"], "service": ["명사", "서비스"], "drop": ["동사", "(drop off) 맡기다"], "off": ["부사", "(drop off) 맡겨"], "at": ["전치사", "~에, ~에서"], "reception": ["명사", "프런트"], "before": ["전치사", "~전에"], "8:30": ["숫자", "8시 30분"], "3": ["숫자", "3"], "a.m": ["명사", "오전"], "ready": ["형용사", "준비된"], "by": ["전치사", "~에 의해, ~까지"], "6:00": ["숫자", "6시"], "p.m": ["명사", "오후"], "cost": ["명사", "비용"], "$10.00": ["숫자", "10달러"], "1": ["숫자", "1"], "per": ["전치사", "~당"], "bag": ["명사", "봉투"], "items": ["명사", "품목", "item"], "in": ["전치사", "~에, ~안에"], "quantity": ["명사", "수량"], "shirts": ["명사", "셔츠", "shirt"], "blouses": ["명사", "블라우스", "blouse"], "4": ["숫자", "4"], "trousers": ["명사", "바지"], "skirts": ["명사", "치마", "skirt"], "dresses": ["명사", "원피스", "dress"], "sweaters": ["명사", "스웨터", "sweater"], "vests": ["명사", "조끼", "vest"], "shorts": ["명사", "반바지"], "socks": ["명사", "양말", "sock"], "pair": ["명사", "켤레"], "2": ["숫자", "2"], "name": ["명사", "이름"], "and": ["접속사", "그리고"], "room": ["명사", "객실"], "lidia": ["고유명사", "리디아(인명)"], "lee": ["고유명사", "리(인명)"], "603": ["숫자", "603"], "received": ["과거분사", "접수된", "receive"], "darnell": ["고유명사", "다넬(인명)"], "reed": ["고유명사", "리드(인명)"], "date": ["명사", "날짜"], "january": ["명사", "1월"], "19": ["숫자", "19"], "total": ["형용사", "총"]}, "questions": [{"no": 147, "q": "What is indicated about the laundry service?", "options": ["It was recently introduced at the hotel.", "Its cost depends on the weight of the clothes.", "It is completed in one day.", "Its price increases on weekends."], "answer": 2, "explain": "정답 (C) It is completed in one day.\n해석: 세탁 서비스에 대해 언급된 것은?\n정답 근거: \"당일(Same-day) 세탁 서비스\", 오전 8시 30분 전 접수 → 오후 6시 완료 → 하루 안에 완료됨.\n오답 분석: (A) 최근 도입되었다는 언급 없음. / (B) 비용은 무게가 아니라 가방당 10달러. / (D) 주말 요금 인상 언급 없음.\n지문 개요: North River Hotel의 당일 세탁·건조·접기 서비스 영수증. 오전 8시 30분 전 접수, 오후 6시 완료, 가방당 10달러이며 603호 Lidia Lee가 셔츠 4·바지 3·반바지 1·양말 2켤레를 맡김.", "vocab": "Paraphrase: Same-day service / Drop off before 8:30 A.M., Ready by 6:00 P.M. → completed in one day", "g": {"laundry": ["명사", "세탁"], "indicated": ["과거분사", "언급된", "indicate"], "is": ["동사", "~이다", "be"], "about": ["전치사", "~에 대해"], "service": ["명사", "서비스"], "what": ["대명사", "무엇"], "the": ["관사", "그"]}}, {"no": 148, "q": "Who most likely is Ms. Lee?", "options": ["A laundry employee", "A hotel receptionist", "A tailor", "A hotel guest"], "answer": 3, "explain": "정답 (D) A hotel guest\n해석: Lee 씨는 누구일 것 같은가?\n정답 근거: \"이름 및 객실: Lidia Lee, 603\" → 603호 투숙객.\n오답 분석: (A) 세탁 직원이 아니라 세탁을 맡긴 사람. / (B) 접수자는 Darnell Reed. / (C) 재단사 관련 내용 없음.", "vocab": "Paraphrase: Name and room: Lidia Lee, 603 → a hotel guest", "g": {"most": ["부사", "가장"], "likely": ["부사", "아마"], "is": ["동사", "~이다", "be"], "ms": ["명사", "~씨(여성)"], "lee": ["고유명사", "리(인명)"], "who": ["대명사", "누구"]}}]}, {"range": "149-150", "sub": "기출독해 2문항 5회", "passage": "To: Jenna Caron <jenna.caron@parbatrentals.com>\nFrom: David Kwan <davidkwan@dkwanconstruction.com>\nDate: February 23\nSubject: Follow-up\nHello, Jenna,\nI am writing to follow up on the phone call we had earlier this week, in which I agreed to rent a crane from March 15 until April 10. Unfortunately, my construction team is running a bit behind schedule on our project at the Aipuni Street site. We actually need the crane a week later, from March 22 until April 17. Is the crane available for those dates? Would there be any additional charges related to the date change? Please get back to me when you can.\nThanks, David Kwan", "tr": "수신: Jenna Caron / 발신: David Kwan / 날짜: 2월 23일 / 제목: 후속 연락\n안녕하세요 Jenna, 이번 주 초 전화 통화에서 3월 15일부터 4월 10일까지 크레인을 대여하기로 합의한 건에 대해 후속 연락을 드립니다. 안타\n깝게도 저희 공사팀이 Aipuni Street 현장 프로젝트에서 일정이 조금 지연되고 있습니다. 실제로는 일주일 늦은 3월 22일부터 4월 17일까지 크레인이 필요합니다. 그 날짜에 크레인을 이용할 수 있나요? 날짜 변경과 관련해 추가 요금이 있을까요? 가능하실 때 답장 부탁드립니다. 감사합니다, David Kwan", "vocab": "follow up on 구 ~에 대해 후속 조치하다 / crane 명 크레인 / behind schedule 구 일정보다 늦은 / site 명 현장 / available 형 이용 가능한 / additional charge 명 추가 요금 / get back to 구 ~에게 회신하다 / adjustment 명 조정", "g": {"to": ["to부정사", "~하기 위해"], "jenna": ["고유명사", "제나(인명)"], "a": ["관사", "하나의"], "caron": ["고유명사", "캐런(인명)"], "on": ["전치사", "~에, ~위에"], "jenna.caron@parbatrentals.com": ["고유명사", "이메일 주소"], "at": ["전치사", "~에, ~에서"], "rent": ["동사", "빌리다"], "from": ["전치사", "~로부터"], "david": ["고유명사", "데이비드(인명)"], "i": ["대명사", "나"], "kwan": ["고유명사", "콴(인명)"], "davidkwan@dkwanconstruction.com": ["고유명사", "이메일 주소"], "construction": ["명사", "건설"], "date": ["명사", "날짜"], "february": ["명사", "2월"], "23": ["숫자", "23"], "subject": ["명사", "제목"], "follow": ["동사", "(follow up) 후속 연락하다"], "follow-up": ["명사", "후속 연락"], "up": ["부사", "(follow up) 이어서"], "hello": ["감탄사", "안녕하세요"], "am": ["동사", "~이다", "be"], "writing": ["현재분사", "쓰는", "write"], "in": ["전치사", "~에, ~안에"], "the": ["관사", "그"], "phone": ["명사", "전화"], "call": ["명사", "통화"], "we": ["대명사", "우리"], "had": ["동사", "가졌다, (완료)", "have"], "earlier": ["부사", "앞서"], "this": ["한정사", "이"], "is": ["동사", "~이다", "be"], "week": ["명사", "주"], "which": ["관계사", "~하는 것"], "agreed": ["동사", "합의했다", "agree"], "crane": ["명사", "크레인"], "march": ["명사", "3월"], "15": ["숫자", "15"], "until": ["전치사", "~까지"], "april": ["명사", "4월"], "10": ["숫자", "10"], "unfortunately": ["부사", "유감스럽게도"], "for": ["전치사", "~을 위해, ~동안"], "my": ["한정사", "나의"], "team": ["명사", "팀"], "running": ["현재분사", "진행되는", "run"], "bit": ["명사", "(a bit) 조금"], "be": ["동사", "~이다, 되다"], "behind": ["전치사", "~보다 뒤처진"], "schedule": ["명사", "일정"], "our": ["한정사", "우리의"], "project": ["명사", "프로젝트"], "aipuni": ["고유명사", "아이푸니(거리명)"], "street": ["명사", "거리"], "site": ["명사", "사이트"], "actually": ["부사", "실제로"], "need": ["동사", "필요하다"], "later": ["부사", "뒤에"], "22": ["숫자", "22"], "17": ["숫자", "17"], "available": ["형용사", "이용 가능한"], "those": ["한정사", "그것들의"], "dates": ["명사", "날짜", "date"], "would": ["조동사", "~할 것이다"], "there": ["부사", "거기에"], "any": ["한정사", "어떤"], "additional": ["형용사", "추가의"], "charges": ["명사", "요금", "charge"], "related": ["과거분사", "관련된", "relate"], "change": ["명사", "변경"], "please": ["부사", "부디, ~해 주세요"], "get": ["동사", "(get back to) 답하다"], "back": ["부사", "다시, 뒤로"], "me": ["대명사", "나를"], "when": ["접속사", "~할 때"], "you": ["대명사", "당신"], "can": ["조동사", "~할 수 있다"], "thanks": ["명사", "감사"]}, "questions": [{"no": 149, "q": "Why did Mr. Kwan write the e-mail?", "options": ["To point out a mistake in a service charge", "To request an adjustment to an agreement", "To offer feedback on a service from Parbat Rentals", "To ask Ms. Caron to visit a construction site"], "answer": 1, "explain": "정답 (B) To request an adjustment to an agreement\n해석: Kwan 씨는 왜 이메일을 썼는가?\n정답 근거: 전화로 합의한 대여 기간을 일주일 늦춰 달라고 요청 → 합의 내용의 조정 요청.\n오답 분석: (A) 요금 오류 지적 없음. / (C) 서비스 피드백 아님. / (D) 현장 방문 요청 없음.\n지문 개요: David Kwan이 Parbat Rentals의 Jenna Caron에게 3월 15일~4월 10일로 합의한 크레인 대여를 공사 지연으로 일주일 늦춘 3월 22일~4월 17일로 바꿀 수 있는지, 추가 요금이 있는지 묻는 이메일.", "vocab": "Paraphrase: We actually need the crane a week later → request an adjustment to an agreement", "g": {"did": ["조동사", "(과거 조동사)", "do"], "why": ["부사", "왜"], "mr": ["명사", "~씨(남성)"], "kwan": ["고유명사", "콴(인명)"], "the": ["관사", "그"], "e-mail": ["명사", "이메일"], "write": ["동사", "쓰다"]}}, {"no": 150, "q": "According to the e-mail, when will Mr. Kwan's team be finished with the crane?", "options": ["On March 15", "On March 22", "On April 10", "On April 17"], "answer": 3, "explain": "정답 (D) On April 17\n해석: 이메일에 따르면 Kwan 씨의 팀은 언제 크레인 사용을 끝내는가?\n정답 근거: \"실제로는 3월 22일부터 4월 17일까지 크레인이 필요\" → 변경된 종료일 4월 17일.\n오답 분석: (A) 3월 15일은 원래 시작일. / (B) 3월 22일은 변경된 시작일. / (C) 4월 10일은 원래 종료일.", "vocab": "Paraphrase: from March 22 until April 17 → on April 17", "g": {"when": ["접속사", "~할 때"], "team": ["명사", "팀"], "finished": ["과거분사", "끝낸", "finish"], "be": ["동사", "~이다, 되다"], "kwan's": ["고유명사", "콴의"], "to": ["to부정사", "~하기 위해"], "mr": ["명사", "~씨(남성)"], "with": ["전치사", "~와 함께, ~으로"], "crane": ["명사", "크레인"], "according": ["부사", "(to와) ~에 따르면"], "e-mail": ["명사", "이메일"], "will": ["조동사", "~할 것이다"], "the": ["관사", "그"]}}]}, {"range": "151-152", "sub": "기출독해 2문항 5회", "passage": "Hello, Ms. Mehta! This is a reminder that you still have some items in your online shopping cart. We will keep them there for 24 hours, after which your cart will be emptied. To place your order now, just go to www.warblyelectronics.com, log in, and click the cart icon. Please note that our product prices fluctuate based on daily and weekly sales. Once your cart is emptied, we cannot guarantee that the cost of these items will stay the same. ―The Warbly Electronics Team", "tr": "안녕하세요, Mehta 씨! 온라인 장바구니에 아직 상품이 남아 있음을 알려드립니다. 24시간 동안 보관한 뒤 장바구니는 비워집니다. 지금 주문하시려면 www.warblyelectronics.com에 접속해 로그인하고 장바구니 아이콘을 클릭하세요. 저희 제품 가격은 일간·주간 세일에 따라 변동됩니다. 장바구니가 비워지면 이 상품들의 가격이 동일하게 유지된다고 보장할 수 없습니다. — Warbly Electronics 팀", "vocab": "reminder 명 알림 / shopping cart 명 장바구니 / empty 동 비우다 / place an order 구 주문하다 / fluctuate 동 변동하다 / based on 구 ~에 근거하여 / guarantee 동 보장하다 / stay the same 구 그대로 유지되다", "g": {"hello": ["감탄사", "안녕하세요"], "ms": ["명사", "~씨(여성)"], "mehta": ["고유명사", "메타(인명)"], "a": ["관사", "하나의"], "this": ["한정사", "이"], "is": ["동사", "~이다", "be"], "reminder": ["명사", "알림"], "in": ["전치사", "~에, ~안에"], "that": ["접속사", "~라는 것"], "you": ["대명사", "당신"], "still": ["부사", "여전히"], "have": ["동사", "가지다, (완료)"], "some": ["한정사", "몇몇의"], "items": ["명사", "물품", "item"], "your": ["한정사", "당신의"], "our": ["한정사", "우리의"], "online": ["형용사", "온라인의"], "on": ["전치사", "~에, ~위에"], "shopping": ["명사", "쇼핑"], "cart": ["명사", "장바구니"], "we": ["대명사", "우리"], "will": ["조동사", "~할 것이다"], "keep": ["동사", "보관하다"], "them": ["대명사", "그들을"], "the": ["관사", "그"], "there": ["부사", "거기에"], "for": ["전치사", "~을 위해, ~동안"], "24": ["숫자", "24"], "hours": ["명사", "시간", "hour"], "after": ["전치사", "~후에"], "which": ["관계사", "~하는 것"], "be": ["동사", "~이다, 되다"], "emptied": ["과거분사", "비워진", "empty"], "to": ["to부정사", "~하기 위해"], "place": ["동사", "(주문을) 하다"], "order": ["명사", "주문"], "now": ["부사", "지금"], "just": ["부사", "막, 단지"], "go": ["동사", "가다"], "www.warblyelectronics.com": ["고유명사", "웹사이트 주소"], "warbly": ["고유명사", "워블리(회사명)"], "electronics": ["고유명사", "전자(회사명)"], "log": ["동사", "(log in) 로그인하다"], "and": ["접속사", "그리고"], "click": ["동사", "클릭하다"], "icon": ["명사", "아이콘"], "please": ["부사", "부디, ~해 주세요"], "note": ["동사", "유의하다"], "product": ["명사", "제품"], "prices": ["명사", "가격", "price"], "fluctuate": ["동사", "변동하다"], "based": ["과거분사", "(based on) ~에 따라", "base"], "daily": ["형용사", "일별의"], "weekly": ["형용사", "주별의"], "sales": ["명사", "판매", "sale"], "once": ["부사", "한 번"], "cannot": ["조동사", "~할 수 없다"], "guarantee": ["동사", "보장하다"], "cost": ["명사", "가격"], "of": ["전치사", "~의"], "these": ["한정사", "이것들의"], "stay": ["동사", "유지되다"], "same": ["형용사", "같은"], "team": ["명사", "팀"]}, "questions": [{"no": 151, "q": "Why is Ms. Mehta receiving a notification?", "options": ["A refund has been issued.", "A delivery has been delayed.", "An order has not been placed.", "A product is no longer available."], "answer": 2, "explain": "정답 (C) An order has not been placed.\n해석: Mehta 씨는 왜 알림을 받는가?\n정답 근거: \"장바구니에 아직 상품이 남아 있다\"는 알림이고 \"지금 주문하려면\"이라고 안내 → 주문이 아직 완료되지 않음.\n오답 분석: (A) 환불 언급 없음. / (B) 배송 지연 없음. / (D) 품절 언급 없음.\n지문 개요: Warbly Electronics가 Mehta 씨에게 장바구니에 남은 상품이 24시간 후 비워진다고 알리며, 가격이 일·주 단위 세일에 따라 변동하므로 비워진 뒤에는 같은 가격을 보장할 수 없다고 안내하는 알림.", "vocab": "Paraphrase: still have some items in your cart / To place your order now → an order has not been placed", "g": {"why": ["부사", "왜"], "is": ["동사", "~이다", "be"], "mehta": ["고유명사", "메타(인명)"], "a": ["관사", "하나의"], "ms": ["명사", "~씨(여성)"], "notification": ["명사", "알림"], "receiving": ["현재분사", "받는", "receive"]}}, {"no": 152, "q": "What does the notification mention about Warbly Electronics?", "options": ["It changes its prices frequently.", "It provides free shipping.", "It has extended its hours.", "It has a new Web site."], "answer": 0, "explain": "정답 (A) It changes its prices frequently.\n해석: 알림은 Warbly Electronics에 대해 무엇을 언급하는가?\n정답 근거: \"제품 가격은 일간·주간 세일에 따라 변동된다(fluctuate)\" → 가격을 자주 바꿈.\n오답 분석: (B) 무료 배송 언급 없음. / (C) 영업시간 연장 없음. / (D) 새 웹사이트 언급 없음.", "vocab": "Paraphrase: prices fluctuate based on daily and weekly sales → changes its prices frequently", "g": {"notification": ["명사", "알림"], "warbly": ["고유명사", "워블리(회사명)"], "about": ["전치사", "~에 대해"], "what": ["대명사", "무엇"], "electronics": ["고유명사", "전자(회사명)"], "does": ["조동사", "(의문문 조동사)", "do"], "mention": ["동사", "언급하다"], "the": ["관사", "그"]}}]}, {"range": "153-154", "sub": "기출독해 2문항 5회", "passage": "James Rais 8:07 A.M. Laura, I requested a repair for my air conditioner. Someone came by my office, but the problem has not been fixed.\nLaura Xue 8:08 A.M. I'm sorry to hear that. What is the issue?\nJames Rais 8:11 A.M. My air conditioner is not cooling properly. It is set at a comfortable temperature, but the office is still too warm.\nLaura Xue 8:13 A.M. That sounds very frustrating. I will put in a recall notice and have the technician prioritize your office today.\nJames Rais 8:14 A.M. That's great, but I don't want to pay twice. Is this a free service?\nLaura Xue 8:16 A.M. Absolutely. When a technician does not fix a problem on the first visit, any recall visit is complimentary.", "tr": "James Rais 오전 8:07 Laura, 에어컨 수리를 요청했어요. 누군가 제 사무실에 다녀갔지만 문제가 해결되지 않았어요. Laura Xue 오전 8:08 유감입니다. 무슨 문제인가요?\nJames Rais 오전 8:11 에어컨이 제대로 냉방이 안 돼요. 쾌적한 온도로 설정되어 있는데도 사무실이 여전히 너무 더워요. Laura Xue 오전 8:13 정말 답답하시겠어요. 재방문 요청을 넣고 기술자가 오늘 귀하의 사무실을 우선 처리하도록 하겠습니다. James Rais 오전 8:14 좋네요. 하지만 두 번 내고 싶진 않아요. 무료 서비스인가요? Laura Xue 오전 8:16 물론입니다. 기술자가 첫 방문에서 문제를 해결하지 못하면 재방문은 모두 무료입니다.", "vocab": "repair 명 수리 / come by 구 들르다 / properly 부 제대로 / frustrating 형 답답한 / recall notice 명 재방문 요청 / prioritize 동 우선 처리하다 / technician 명 기술자 / complimentary 형 무료의", "g": {"james": ["고유명사", "제임스(인명)"], "a": ["관사", "하나의"], "rais": ["고유명사", "라이스(인명)"], "is": ["동사", "~이다", "be"], "i": ["대명사", "나"], "8:07": ["숫자", "8시 7분"], "a.m": ["명사", "오전"], "laura": ["고유명사", "로라(인명)"], "requested": ["동사", "요청했다", "request"], "repair": ["명사", "수리"], "air": ["명사", "공기"], "for": ["전치사", "~을 위해, ~동안"], "my": ["한정사", "나의"], "conditioner": ["명사", "(air conditioner) 에어컨"], "on": ["전치사", "~에, ~위에"], "it": ["대명사", "그것"], "someone": ["대명사", "누군가"], "came": ["동사", "(come by) 들르다", "come"], "by": ["전치사", "~에 의해, ~까지"], "office": ["명사", "사무실"], "but": ["접속사", "그러나"], "the": ["관사", "그"], "problem": ["명사", "문제"], "has": ["동사", "가지다, (완료)", "have"], "not": ["부사", "~않다"], "been": ["과거분사", "~였던", "be"], "fix": ["동사", "고치다"], "fixed": ["과거분사", "고쳐진", "fix"], "xue": ["고유명사", "쉐(인명)"], "8:08": ["숫자", "8시 8분"], "i'm": ["대명사", "나는 ~이다", "I am"], "sorry": ["형용사", "유감스러운"], "to": ["to부정사", "~해서"], "hear": ["동사", "듣다"], "that": ["대명사", "그것"], "at": ["전치사", "~에, ~에서"], "what": ["대명사", "무엇"], "issue": ["명사", "문제"], "8:11": ["숫자", "8시 11분"], "cooling": ["현재분사", "냉방하는", "cool"], "in": ["전치사", "~에, ~안에"], "properly": ["부사", "제대로"], "set": ["과거분사", "설정된", "set"], "comfortable": ["형용사", "쾌적한"], "temperature": ["명사", "온도"], "still": ["부사", "여전히"], "too": ["부사", "너무"], "warm": ["형용사", "따뜻한"], "8:13": ["숫자", "8시 13분"], "sounds": ["동사", "~하게 들리다", "sound"], "very": ["부사", "매우"], "frustrating": ["형용사", "답답한"], "will": ["조동사", "~할 것이다"], "put": ["동사", "(put in) 제출하다"], "recall": ["명사", "재방문"], "notice": ["명사", "요청서, 통지"], "and": ["접속사", "그리고"], "have": ["동사", "가지다, (완료)"], "technician": ["명사", "기술자"], "prioritize": ["동사", "우선 처리하다"], "your": ["한정사", "당신의"], "today": ["부사", "오늘"], "8:14": ["숫자", "8시 14분"], "that's": ["대명사", "그것은 ~이다", "that is"], "great": ["형용사", "훌륭한"], "don't": ["조동사", "~하지 않다", "do not"], "want": ["동사", "원하다"], "pay": ["동사", "지불하다"], "twice": ["부사", "두 번"], "this": ["한정사", "이"], "free": ["형용사", "무료의"], "service": ["명사", "서비스"], "8:16": ["숫자", "8시 16분"], "absolutely": ["부사", "물론이다"], "when": ["접속사", "~할 때"], "does": ["조동사", "(의문문 조동사)", "do"], "first": ["형용사", "첫 번째의"], "visit": ["명사", "방문"], "any": ["한정사", "어떤"], "complimentary": ["형용사", "무료의"]}, "questions": [{"no": 153, "q": "Why does Mr. Rais contact Ms. Xue?", "options": ["He would like to rent an office.", "He has a maintenance issue.", "He wants to buy an air conditioner.", "He has a balance left on his account."], "answer": 1, "explain": "정답 (B) He has a maintenance issue.\n해석: Rais 씨는 왜 Xue 씨에게 연락하는가?\n정답 근거: 에어컨 수리를 요청했는데 고쳐지지 않았고 냉방이 안 된다고 함 → 유지보수(설비) 문제.\n오답 분석: (A) 사무실 임대 문의 아님. / (C) 에어컨 구매가 아니라 수리. / (D) 잔액 관련 내용 없음.\n지문 개요: James Rais가 에어컨 수리 후에도 냉방이 안 된다고 하자 Laura Xue가 재방문 요청을 접수해 당일 우선 처리하겠다고 하고, 첫 방문에서 해결되지 않은 경우 재방문은 무료라고 답하는 대화.", "vocab": "Paraphrase: requested a repair / problem has not been fixed → a maintenance issue", "g": {"why": ["부사", "왜"], "mr": ["명사", "~씨(남성)"], "rais": ["고유명사", "라이스(인명)"], "xue": ["고유명사", "쉐(인명)"], "ms": ["명사", "~씨(여성)"], "does": ["조동사", "(의문문 조동사)", "do"], "contact": ["동사", "연락하다"]}}, {"no": 154, "q": "At 8:16 A.M., what does Ms. Xue most likely mean when she writes, \"Absolutely\"?", "options": ["A technician has made a repair.", "She will stop by Mr. Rais's office.", "A service fee will not be charged.", "She has not yet made a payment."], "answer": 2, "explain": "정답 (C) A service fee will not be charged.\n해석: 오전 8시 16분에 Xue 씨가 \"Absolutely\"라고 쓴 의도는?\n정답 근거: \"무료 서비스인가요?\"라는 질문에 대한 답이고 이어서 \"재방문은 모두 무료\"라고 설명 → 서비스 요금이 청구되지 않음.\n오답 분석: (A) 수리 완료 여부가 아니라 요금 질문에 대한 답. / (B) Xue 본인 방문 언급 없음. / (D) 결제 여부와 무관.", "vocab": "Paraphrase: any recall visit is complimentary → a service fee will not be charged", "g": {"a.m": ["명사", "오전"], "when": ["접속사", "~할 때"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "writes": ["동사", "쓰다", "write"], "absolutely": ["부사", "물론이다"], "at": ["전치사", "~에, ~에서"], "what": ["대명사", "무엇"], "she": ["대명사", "그녀"], "8:16": ["숫자", "8시 16분"], "xue": ["고유명사", "쉐(인명)"], "mean": ["동사", "의미하다"], "ms": ["명사", "~씨(여성)"], "does": ["조동사", "(의문문 조동사)", "do"]}}]}, {"range": "147-148", "sub": "기출독해 2문항 6회", "passage": "Holden's Tree Company — Serving Taylorsville for over 20 years\nOur company's crew will be working near your office building in the coming week. If you have a large tree or multiple trees that you need removed, now would be a good time to have the work done and save on the project. We also provide ground clearing, stump removal, and maintenance services, including trimming. Our certified tree specialist is available to consult as needed.\nCall 555-0109 to schedule your appointment. If you mention this advertisement, you will receive an additional 10 percent off any scheduled work. All work must be completed by July 15 to receive the discount.", "tr": "Holden's Tree Company — 20년 넘게 Taylorsville에 봉사\n저희 작업팀이 다음 주에 귀하의 사무실 건물 근처에서 작업할 예정입니다. 제거가 필요한 큰 나무나 여러 그루의 나무가 있다면, 지금이 작업을 맡기고 비용을 절약할 좋은 때입니다. 저희는 부지 정리, 그루터기 제거, 가지치기를 포함한 유지관리 서비스도 제공합니다. 필요 시 공인 수목 전문가의 상담도 가능합니다. 555-0109로 전화해 예약하세요. 이 광고를 언급하시면 예약된 모든 작업에 10% 추가 할인을 받으실 수 있습니다. 할인을 받으려면 모든 작업이 7월 15일까지 완료되어야 합니다.", "vocab": "crew 명 작업팀 / remove 동 제거하다 / stump 명 그루터기 / trimming 명 가지치기 / certified 형 공인된 / consult 동 상담하다 / mention 동 언급하다 / additional 형 추가의", "g": {"holden's": ["고유명사", "홀든의(상호)"], "tree": ["명사", "나무"], "company": ["명사", "회사"], "a": ["관사", "하나의"], "any": ["한정사", "어떤"], "an": ["관사", "하나의"], "serving": ["현재분사", "서비스하는", "serve"], "in": ["전치사", "~에, ~안에"], "taylorsville": ["고유명사", "테일러스빌(지명)"], "or": ["접속사", "또는"], "for": ["전치사", "~을 위해, ~동안"], "over": ["전치사", "~이상"], "20": ["숫자", "20"], "years": ["명사", "해, 연도", "year"], "our": ["한정사", "우리의"], "company's": ["명사", "회사의", "company"], "crew": ["명사", "작업반"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "working": ["현재분사", "작업하는", "work"], "work": ["명사", "작업"], "near": ["전치사", "~근처에"], "your": ["한정사", "당신의"], "you": ["대명사", "당신"], "off": ["부사", "할인되어"], "office": ["명사", "사무실"], "building": ["명사", "건물"], "the": ["관사", "그"], "coming": ["형용사", "다가오는"], "week": ["명사", "주"], "we": ["대명사", "우리"], "if": ["접속사", "만약 ~라면"], "have": ["동사", "가지다, (완료)"], "large": ["형용사", "큰"], "multiple": ["형용사", "여러"], "trees": ["명사", "나무", "tree"], "that": ["관계사", "~하는"], "need": ["동사", "필요로 하다"], "removed": ["과거분사", "제거된", "remove"], "now": ["부사", "지금"], "would": ["조동사", "~할 것이다"], "good": ["형용사", "좋은"], "time": ["명사", "시간"], "to": ["to부정사", "~할"], "done": ["과거분사", "완료된", "do"], "on": ["전치사", "~에, ~위에"], "and": ["접속사", "그리고"], "save": ["동사", "절약하다"], "project": ["명사", "작업"], "also": ["부사", "또한"], "provide": ["동사", "제공하다"], "ground": ["명사", "땅"], "clearing": ["명사", "정리"], "stump": ["명사", "그루터기"], "removal": ["명사", "제거"], "maintenance": ["명사", "관리"], "services": ["명사", "서비스", "service"], "including": ["전치사", "~을 포함하여"], "trimming": ["명사", "가지치기"], "certified": ["형용사", "공인된"], "specialist": ["명사", "전문가"], "is": ["동사", "~이다", "be"], "available": ["형용사", "이용 가능한"], "consult": ["동사", "상담하다"], "as": ["접속사", "(as needed) 필요에 따라"], "needed": ["과거분사", "필요한", "need"], "call": ["동사", "전화하다"], "all": ["한정사", "모든"], "555-0109": ["숫자", "전화번호"], "10": ["숫자", "10"], "schedule": ["동사", "일정을 잡다"], "appointment": ["명사", "예약"], "mention": ["동사", "언급하다"], "this": ["한정사", "이"], "advertisement": ["명사", "광고"], "receive": ["동사", "받다"], "additional": ["형용사", "추가의"], "percent": ["명사", "퍼센트"], "scheduled": ["과거분사", "예약된", "schedule"], "must": ["조동사", "~해야 한다"], "completed": ["과거분사", "완료된", "complete"], "by": ["전치사", "~에 의해, ~까지"], "july": ["명사", "7월"], "15": ["숫자", "15"], "discount": ["명사", "할인"]}, "questions": [{"no": 147, "q": "What is indicated about Holden's Tree Company?", "options": ["Its tree specialist consults on every project.", "Its services include tree maintenance.", "It requires ten days' notice before starting a job.", "It is currently hiring additional crew members."], "answer": 1, "explain": "정답 (B) Its services include tree maintenance.\n해석: Holden's Tree Company에 대해 언급된 것은?\n정답 근거: \"가지치기를 포함한 유지관리 서비스(maintenance services, including trimming)도 제공\" → 나무 유지관리 서비스 포함.\n오답 분석: (A) 전문가 상담은 '필요 시(as needed)'이지 모든 프로젝트가 아님. / (C) 10일 전 통보 요건 없음. / (D) 직원 채용 언급 없음.\n지문 개요: Taylorsville에서 20년 넘게 영업한 Holden's Tree Company가 다음 주 인근 작업을 계기로 나무 제거·부지 정리·그루터기 제거· 가지치기 등 유지관리 서비스를 홍보하며, 광고를 언급하면 10% 추가 할인(7월 15일까지 완료 조건)을 준다는 광고.", "vocab": "Paraphrase: maintenance services, including trimming → services include tree maintenance", "g": {"indicated": ["과거분사", "언급된", "indicate"], "holden's": ["고유명사", "홀든의(상호)"], "is": ["동사", "~이다", "be"], "about": ["전치사", "~에 대해"], "company": ["명사", "회사"], "tree": ["명사", "나무"], "what": ["대명사", "무엇"]}}, {"no": 148, "q": "How can a discount be obtained from Holden's Tree Company?", "options": ["By booking multiple appointments", "By referring to an advertisement", "By scheduling work after July", "By making a call within 24 hours"], "answer": 1, "explain": "정답 (B) By referring to an advertisement\n해석: Holden's Tree Company에서 할인은 어떻게 받을 수 있는가?\n정답 근거: \"이 광고를 언급하면(If you mention this advertisement) 10% 추가 할인\" → 광고 언급.\n오답 분석: (A) 여러 건 예약 조건 없음. / (C) 7월 15일까지 완료해야 하므로 7월 이후 예약은 오히려 할인 불가. / (D) 24시간 내 전화 조건 없음.", "vocab": "Paraphrase: If you mention this advertisement → referring to an advertisement", "g": {"can": ["조동사", "~할 수 있다"], "how": ["부사", "어떻게"], "from": ["전치사", "~로부터"], "holden's": ["고유명사", "홀든의(상호)"], "a": ["관사", "하나의"], "company": ["명사", "회사"], "obtained": ["과거분사", "얻어진", "obtain"], "tree": ["명사", "나무"], "discount": ["명사", "할인"], "be": ["동사", "~이다, 되다"]}}]}, {"range": "149-150", "sub": "기출독해 2문항 6회", "passage": "Linwood Piano Studio — 328 Shepherd Street, Linwood, MA 01525\nA lifelong musical journey begins with piano lessons at Linwood Piano Studio. All types of learners can succeed through our unique multisensory approach to instruction. Included in the course fee is an engaging take-home lesson book for self-directed learning between sessions.\nTeens and adults: · Group lessons (class sizes capped at six), one hour weekly, beginner and intermediate levels · Individual one-hour lessons, advanced level only\nChildren twelve and under: · Small-group lessons (class sizes capped at three), one hour weekly, beginner and intermediate levels · Individual 30-minute lessons, all levels\nVisit www.lpsmusic.com to watch our introductory video and to enroll.", "tr": "Linwood Piano Studio — 328 Shepherd Street, Linwood, MA 01525 평생의 음악 여정은 Linwood Piano Studio의 피아노 수업에서 시작됩니다. 저희의 독특한 다감각 교수법을 통해 모든 유형의 학습자가 성공할 수 있습니다. 수강료에는 수업 사이 자기 주도 학습을 위한 재미있는 가정용 교재가 포함되어 있습니다.\n청소년 및 성인: · 그룹 수업(정원 6명), 주 1회 1시간, 초급 및 중급 · 개인 1시간 수업, 고급만 12세 이하 어린이: · 소그룹 수업(정원 3명), 주 1회 1시간, 초급 및 중급 · 개인 30분 수업, 전 레벨 소개 영상을 보고 등록하시려면 www.lpsmusic.com을 방문하세요.", "vocab": "lifelong 형 평생의 / multisensory 형 다감각의 / approach 명 접근법 / instruction 명 교육 / engaging 형 흥미로운 / self-directed 형 자기 주도의 / cap 동 상한을 두다 / intermediate 형 중급의 / enroll 동 등록하다", "g": {"linwood": ["고유명사", "린우드(지명)"], "in": ["전치사", "~에, ~안에"], "piano": ["명사", "피아노"], "an": ["관사", "하나의"], "a": ["관사", "하나의"], "studio": ["명사", "교습소"], "328": ["숫자", "328"], "shepherd": ["고유명사", "셰퍼드(거리명)"], "street": ["명사", "거리"], "ma": ["고유명사", "매사추세츠 주"], "01525": ["숫자", "우편번호"], "lifelong": ["형용사", "평생의"], "musical": ["형용사", "음악의"], "journey": ["명사", "여정"], "our": ["한정사", "우리의"], "begins": ["동사", "시작되다", "begin"], "with": ["전치사", "~와 함께, ~으로"], "lesson": ["명사", "수업"], "lessons": ["명사", "수업", "lesson"], "at": ["전치사", "~에, ~에서"], "all": ["한정사", "모든"], "types": ["명사", "유형", "type"], "of": ["전치사", "~의"], "learners": ["명사", "학습자", "learner"], "can": ["조동사", "~할 수 있다"], "succeed": ["동사", "성공하다"], "through": ["전치사", "~을 통해"], "unique": ["형용사", "독특한"], "multisensory": ["형용사", "다감각의"], "is": ["동사", "~이다", "be"], "approach": ["명사", "접근법"], "to": ["전치사", "~에 대한"], "instruction": ["명사", "교수, 지도"], "included": ["과거분사", "포함된", "include"], "the": ["관사", "그"], "course": ["명사", "강좌"], "fee": ["명사", "수강료"], "engaging": ["형용사", "흥미로운"], "take-home": ["형용사", "집에 가져가는"], "book": ["명사", "책"], "for": ["전치사", "~을 위해, ~동안"], "self-directed": ["형용사", "자기 주도의"], "learning": ["명사", "학습"], "between": ["전치사", "~사이에"], "sessions": ["명사", "수업 시간", "session"], "teens": ["명사", "십대", "teen"], "and": ["접속사", "그리고"], "adults": ["명사", "성인", "adult"], "group": ["명사", "그룹"], "class": ["명사", "반"], "sizes": ["명사", "규모", "size"], "capped": ["과거분사", "상한이 정해진", "cap"], "six": ["숫자", "6"], "one": ["숫자", "하나"], "hour": ["명사", "시간"], "weekly": ["부사", "매주"], "beginner": ["명사", "초급자"], "intermediate": ["형용사", "중급의"], "levels": ["명사", "수준", "level"], "level": ["명사", "수준"], "individual": ["형용사", "개인의"], "one-hour": ["형용사", "1시간의"], "advanced": ["형용사", "고급의"], "only": ["부사", "오직"], "children": ["명사", "아이들", "child"], "twelve": ["숫자", "12"], "under": ["부사", "이하"], "small-group": ["형용사", "소그룹의"], "three": ["숫자", "셋"], "30-minute": ["형용사", "30분의"], "visit": ["동사", "방문하다"], "www.lpsmusic.com": ["고유명사", "웹사이트 주소"], "watch": ["동사", "보다"], "introductory": ["형용사", "소개의"], "video": ["명사", "영상"], "enroll": ["동사", "등록하다"]}, "questions": [{"no": 149, "q": "What is indicated about Linwood Piano Studio?", "options": ["It provides lessons to students at their homes.", "It offers students a chance to give public performances.", "It sells an instruction book for an additional fee.", "It uses a special method to teach piano skills."], "answer": 3, "explain": "정답 (D) It uses a special method to teach piano skills.\n해석: Linwood Piano Studio에 대해 언급된 것은?\n정답 근거: \"독특한 다감각 교수법(unique multisensory approach)\" → 피아노를 가르치는 특별한 방법 사용.\n오답 분석: (A) 학생 집 방문 수업 언급 없음. / (B) 공개 연주 기회 언급 없음. / (C) 교재는 수강료에 포함되어 있어 추가 비용 아님.\n지문 개요: Linwood Piano Studio가 독특한 다감각 교수법과 수강료에 포함된 자습용 교재를 소개하고, 청소년·성인(그룹 1시간 주 1회 초· 중급 / 개인 1시간 고급만)과 12세 이하 어린이(소그룹 1시간 초·중급 / 개인 30분 전 레벨) 수업을 안내하는 광고.", "vocab": "Paraphrase: unique multisensory approach → uses a special method", "g": {"indicated": ["과거분사", "언급된", "indicate"], "is": ["동사", "~이다", "be"], "about": ["전치사", "~에 대해"], "studio": ["명사", "교습소"], "what": ["대명사", "무엇"], "linwood": ["고유명사", "린우드(지명)"], "piano": ["명사", "피아노"]}}, {"no": 150, "q": "What is offered to adult learners at the intermediate level?", "options": ["An online course", "Thirty-minute lessons", "A sixty-minute group class", "One-on-one private instruction"], "answer": 2, "explain": "정답 (C) A sixty-minute group class\n해석: 중급 수준의 성인 학습자에게 제공되는 것은?\n정답 근거: 청소년·성인 항목: 그룹 수업이 주 1회 1시간이며 초급·중급 대상 → 60분 그룹 수업. 개인 수업은 고급만 가능.\n오답 분석: (A) 온라인 강좌 없음. / (B) 30분 수업은 12세 이하 개인 수업. / (D) 성인 개인 수업은 고급 레벨만.", "vocab": "Paraphrase: Group lessons, one hour weekly, intermediate levels → a sixty-minute group class", "g": {"adult": ["형용사", "성인의"], "offered": ["과거분사", "제공되는", "offer"], "is": ["동사", "~이다", "be"], "to": ["전치사", "~에 대한"], "at": ["전치사", "~에, ~에서"], "learners": ["명사", "학습자", "learner"], "level": ["명사", "수준"], "what": ["대명사", "무엇"], "intermediate": ["형용사", "중급의"], "the": ["관사", "그"]}}]}, {"range": "151-152", "sub": "기출독해 2문항 6회", "passage": "Notice to the Public — Scheduled Road Closure: Wednesday, December 16, 8:00 A.M. to 4:00 P.M.\nOn Wednesday, December 16, Forty-Fifth Street will be closed from Red River Road to White Oak Lane, from 8:00 A.M. to 4:00 P.M. This is to allow for the demolition of a house in the area and for the demolition crew to maneuver their heavy equipment. Residents who regularly park their car in the area are requested to remove their vehicle no later than 7:30 A.M. on Wednesday.\nAlso, please be aware that as a result of the demolition work, nails, screws, and other sharp objects are likely to fall on the streets. While the street will be cleaned following the demolition, residents are nevertheless asked to proceed with caution thorough the area once the road closure has been lifted.\nThank you, Public Works Department, City of Mariandale", "tr": "공공 안내 — 예정된 도로 폐쇄: 12월 16일 수요일 오전 8:00~오후 4:00\n12월 16일 수요일 Forty-Fifth Street의 Red River Road부터 White Oak Lane 구간이 오전 8시부터 오후 4시까지 폐쇄됩니다. 이는 해당 지역 주택 철거와 철거 작업팀의 중장비 이동을 위한 것입니다. 이 지역에 정기적으로 주차하시는 주민께서는 수요일 오전 7시 30분까지 차량을 옮겨 주시기 바랍니다. 또한 철거 작업으로 인해 못, 나사 등 날카로운 물체가 거리에 떨어질 수 있음을 유의하세요. 철거 후 거리를 청소하겠지만, 도로 폐쇄가 해제된 뒤에도 주민들은 해당 지역을 주의해서 지나가 주시기 바랍니다. 감사합니다, Mariandale 시 공공사업부", "vocab": "closure 명 폐쇄 / demolition 명 철거 / maneuver 동 이동시키다 / heavy equipment 명 중장비 / no later than 구 늦어도 ~까지 / be aware that 구 ~을 유의하다 / proceed 동 나아가다 / with caution 구 조심해서 / lift 동 해제하다", "g": {"notice": ["명사", "공지"], "no": ["한정사", "어떤 ~도 없는"], "to": ["전치사", "~에게, ~까지"], "the": ["관사", "그"], "public": ["명사", "대중"], "scheduled": ["과거분사", "예정된", "schedule"], "road": ["명사", "도로"], "a": ["관사", "하나의"], "closure": ["명사", "폐쇄"], "wednesday": ["명사", "수요일"], "december": ["명사", "12월"], "be": ["동사", "~이다, 되다"], "16": ["숫자", "16"], "8:00": ["숫자", "8시"], "a.m": ["명사", "오전"], "4:00": ["숫자", "4시"], "p.m": ["명사", "오후"], "on": ["전치사", "~에, ~위에"], "forty-fifth": ["고유명사", "45번(가)"], "for": ["전치사", "~을 위해, ~동안"], "street": ["명사", "거리"], "will": ["조동사", "~할 것이다"], "closed": ["과거분사", "폐쇄된", "close"], "from": ["전치사", "~로부터"], "red": ["고유명사", "레드(도로명)"], "river": ["고유명사", "리버(도로명)"], "white": ["고유명사", "화이트(도로명)"], "oak": ["고유명사", "오크(도로명)"], "lane": ["명사", "길"], "this": ["한정사", "이"], "is": ["동사", "~이다", "be"], "allow": ["동사", "(allow for) 가능하게 하다"], "demolition": ["명사", "철거"], "of": ["전치사", "~의"], "house": ["명사", "주택"], "in": ["전치사", "~에, ~안에"], "are": ["동사", "~이다", "be"], "area": ["명사", "지역"], "and": ["접속사", "그리고"], "crew": ["명사", "작업반"], "maneuver": ["동사", "조종하다, 움직이다"], "their": ["한정사", "그들의"], "heavy": ["형용사", "무거운"], "equipment": ["명사", "장비"], "residents": ["명사", "주민", "resident"], "who": ["대명사", "누구"], "regularly": ["부사", "정기적으로"], "park": ["동사", "주차하다"], "car": ["명사", "차"], "requested": ["과거분사", "요청받은", "request"], "remove": ["동사", "옮기다, 치우다"], "vehicle": ["명사", "차량"], "later": ["부사", "(no later than) 늦어도"], "than": ["접속사", "~보다"], "7:30": ["숫자", "7시 30분"], "also": ["부사", "또한"], "please": ["부사", "부디, ~해 주세요"], "as": ["전치사", "(as a result of) ~의 결과로"], "aware": ["형용사", "알고 있는"], "that": ["접속사", "~라는 것"], "result": ["명사", "결과"], "work": ["명사", "작업"], "nails": ["명사", "못", "nail"], "screws": ["명사", "나사", "screw"], "other": ["형용사", "다른"], "sharp": ["형용사", "날카로운"], "objects": ["명사", "물체", "object"], "likely": ["부사", "아마"], "fall": ["동사", "떨어지다"], "streets": ["명사", "거리", "street"], "while": ["접속사", "~하는 동안"], "cleaned": ["과거분사", "청소된", "clean"], "following": ["전치사", "~후에"], "nevertheless": ["부사", "그럼에도 불구하고"], "asked": ["과거분사", "요청받은", "ask"], "proceed": ["동사", "나아가다"], "with": ["전치사", "~와 함께, ~으로"], "caution": ["명사", "주의"], "thorough": ["전치사", "(through 오기) ~을 지나"], "once": ["부사", "한 번"], "has": ["동사", "가지다, (완료)", "have"], "been": ["과거분사", "~였던", "be"], "lifted": ["과거분사", "해제된", "lift"], "thank": ["동사", "감사하다"], "you": ["대명사", "당신"], "works": ["명사", "(Public Works) 공공사업", "work"], "department": ["명사", "부서"], "city": ["명사", "시"], "mariandale": ["고유명사", "마리안데일(지명)"]}, "questions": [{"no": 151, "q": "Why are residents asked to remove their car from a section of Forty-Fifth Street?", "options": ["A festive activity will be held.", "A parking area will be repaired.", "A structure will be torn down.", "Tree trimming work will occur."], "answer": 2, "explain": "정답 (C) A structure will be torn down.\n해석: 주민들은 왜 Forty-Fifth Street 일부 구간에서 차를 옮기라고 요청받는가?\n정답 근거: \"해당 지역 주택 철거(demolition of a house)와 중장비 이동을 위해\" 폐쇄 → 건물이 철거됨. demolition of a house → a structure will be torn down.\n오답 분석: (A) 축제 행사 아님. / (B) 주차장 보수 아님. / (D) 나무 가지치기 아님.\n지문 개요: Mariandale 시 공공사업부가 12월 16일 수요일 오전 8시~오후 4시 주택 철거 작업으로 Forty-Fifth Street 일부 구간을 폐쇄하니 7 시 30분까지 차량을 옮기고, 못·나사 등 날카로운 물체가 떨어질 수 있으니 폐쇄 해제 후에도 주의하라는 공지.", "vocab": "Paraphrase: demolition of a house → a structure will be torn down", "g": {"are": ["동사", "~이다", "be"], "asked": ["과거분사", "요청받은", "ask"], "why": ["부사", "왜"], "from": ["전치사", "~로부터"], "to": ["전치사", "~에게, ~까지"], "section": ["명사", "구역"], "street": ["명사", "거리"], "a": ["관사", "하나의"], "their": ["한정사", "그들의"], "remove": ["동사", "옮기다, 치우다"], "forty-fifth": ["고유명사", "45번(가)"], "of": ["전치사", "~의"], "car": ["명사", "차"], "residents": ["명사", "주민", "resident"]}}, {"no": 152, "q": "What are residents warned about?", "options": ["Wet road surface", "Sharp objects on the road", "A delayed traffic signal", "Narrow sidewalks"], "answer": 1, "explain": "정답 (B) Sharp objects on the road\n해석: 주민들은 무엇에 대해 경고받는가?\n정답 근거: \"못, 나사 등 날카로운 물체가 거리에 떨어질 수 있다\" → 도로 위 날카로운 물체.\n오답 분석: (A) 젖은 노면 언급 없음. / (C) 신호등 지연 없음. / (D) 좁은 보도 언급 없음.", "vocab": "Paraphrase: nails, screws, and other sharp objects → sharp objects on the road", "g": {"are": ["동사", "~이다", "be"], "warned": ["과거분사", "경고받은", "warn"], "about": ["전치사", "~에 대해"], "what": ["대명사", "무엇"], "residents": ["명사", "주민", "resident"]}}]}, {"range": "153-154", "sub": "기출독해 2문항 6회", "passage": "Kevin Peek 1:19 P.M. Hi, Anjali. I was supposed to make copies of the agenda for the 2:00 P.M. meeting, but I'm going to arrive about ten minutes late. Could you make them for me?\nAnjali Sarathe 1:20 P.M. Of course. Do you already have a printed copy?\nKevin Peek 1:20 P.M. Yes, it's on my desk. My office door is unlocked. Let me know when you find it.\nAnjali Sarathe 1:23 P.M. Got it.\nKevin Peek 1:24 P.M. Great. Please make fifteen copies and distribute them to the other attendees. Thanks for helping me!\nAnjali Sarathe 1:30 P.M. OK, it's done. See you soon.", "tr": "Kevin Peek 오후 1:19 안녕하세요, Anjali. 제가 오후 2시 회의 안건을 복사하기로 했는데 10분 정도 늦게 도착할 것 같아요. 대신 복사해 주실 수 있나요?\nAnjali Sarathe 오후 1:20 물론이죠. 인쇄본은 이미 있나요?\nKevin Peek 오후 1:20 네, 제 책상 위에 있어요. 사무실 문은 잠겨 있지 않아요. 찾으면 알려 주세요.\nAnjali Sarathe 오후 1:23 찾았어요.\nKevin Peek 오후 1:24 좋아요. 15부 복사해서 다른 참석자들에게 나눠 주세요. 도와줘서 고마워요!\nAnjali Sarathe 오후 1:30 네, 다 했어요. 곧 봬요.", "vocab": "be supposed to 구 ~하기로 되어 있다 / make a copy 구 복사하다 / agenda 명 안건 / unlocked 형 잠기지 않은 / distribute 동 나눠주다 / attendee 명 참석자 / out of order 구 고장 난", "g": {"kevin": ["고유명사", "케빈(인명)"], "i": ["대명사", "나"], "peek": ["고유명사", "피크(인명)"], "1:19": ["숫자", "1시 19분"], "p.m": ["명사", "오후"], "hi": ["감탄사", "안녕"], "a": ["관사", "하나의"], "anjali": ["고유명사", "안잘리(인명)"], "was": ["동사", "~였다", "be"], "supposed": ["과거분사", "(be supposed to) ~하기로 되어 있는", "suppose"], "to": ["to부정사", "~하는 것"], "make": ["동사", "만들다"], "copies": ["명사", "복사본", "copy"], "of": ["전치사", "~의"], "the": ["관사", "그"], "agenda": ["명사", "안건"], "for": ["전치사", "~을 위해, ~동안"], "2:00": ["숫자", "2시"], "meeting": ["명사", "회의"], "me": ["대명사", "나를"], "but": ["접속사", "그러나"], "i'm": ["대명사", "나는 ~이다", "I am"], "going": ["현재분사", "(be going to) ~할 예정", "go"], "arrive": ["동사", "도착하다"], "about": ["전치사", "~에 대해"], "ten": ["숫자", "10"], "minutes": ["명사", "분", "minute"], "late": ["부사", "늦게"], "could": ["조동사", "~할 수 있을 것이다"], "you": ["대명사", "당신"], "them": ["대명사", "그들을"], "sarathe": ["고유명사", "사라테(인명)"], "1:20": ["숫자", "1시 20분"], "course": ["명사", "(of course) 물론"], "do": ["동사", "하다"], "already": ["부사", "이미"], "have": ["동사", "가지다, (완료)"], "printed": ["과거분사", "인쇄된", "print"], "copy": ["명사", "사본"], "yes": ["감탄사", "네"], "it's": ["대명사", "그것은 ~이다", "it is"], "it": ["대명사", "그것"], "on": ["전치사", "~에, ~위에"], "my": ["한정사", "나의"], "desk": ["명사", "책상"], "office": ["명사", "사무실"], "door": ["명사", "문"], "is": ["동사", "~이다", "be"], "unlocked": ["과거분사", "잠기지 않은", "unlock"], "let": ["동사", "~하게 하다"], "know": ["동사", "알다"], "when": ["접속사", "~할 때"], "find": ["동사", "찾다"], "1:23": ["숫자", "1시 23분"], "got": ["동사", "(got it) 찾았다, 알았다", "get"], "1:24": ["숫자", "1시 24분"], "great": ["형용사", "훌륭한"], "please": ["부사", "부디, ~해 주세요"], "fifteen": ["숫자", "15"], "and": ["접속사", "그리고"], "distribute": ["동사", "나눠 주다"], "other": ["형용사", "다른"], "attendees": ["명사", "참석자", "attendee"], "thanks": ["명사", "감사"], "helping": ["동명사", "돕는 것", "help"], "1:30": ["숫자", "1시 30분"], "ok": ["감탄사", "좋아요"], "done": ["과거분사", "다 된", "do"], "see": ["동사", "보다"], "soon": ["부사", "곧"]}, "questions": [{"no": 153, "q": "Why is Mr. Peck unable to make copies of the agenda for the meeting?", "options": ["He does not have enough time.", "He is locked out of his office.", "He does not have the correct version.", "The photocopier is out of order."], "answer": 0, "explain": "정답 (A) He does not have enough time.\n해석: Peek 씨는 왜 회의 안건을 복사할 수 없는가?\n정답 근거: \"10분 정도 늦게 도착할 것 같다\" → 회의 전에 복사할 시간이 부족함.\n오답 분석: (B) 사무실 문은 잠겨 있지 않다고 함. / (C) 잘못된 버전 언급 없음. / (D) 복사기 고장 언급 없음.\n지문 개요: Kevin Peek가 오후 2시 회의에 10분 늦게 도착하게 되어 Anjali Sarathe에게 책상 위 안건 인쇄본을 찾아 15부 복사해 참석자들에게 나눠 달라고 부탁하고, Sarathe가 이를 처리하는 대화.", "vocab": "Paraphrase: arrive about ten minutes late → does not have enough time", "g": {"meeting": ["명사", "회의"], "unable": ["형용사", "~할 수 없는"], "why": ["부사", "왜"], "is": ["동사", "~이다", "be"], "to": ["to부정사", "~하는 것"], "mr": ["명사", "~씨(남성)"], "peck": ["고유명사", "펙(인명, 원문 표기)"], "for": ["전치사", "~을 위해, ~동안"], "make": ["동사", "만들다"], "copies": ["명사", "복사본", "copy"], "of": ["전치사", "~의"], "agenda": ["명사", "안건"], "the": ["관사", "그"]}}, {"no": 154, "q": "At 1:23 P.M., what does Ms. Sarathe most likely mean when she writes, \"Got it\"?", "options": ["She had expected Mr. Peck to arrive late.", "She knows where the meeting will be.", "She has the list of meeting attendees.", "She had found a document."], "answer": 3, "explain": "정답 (D) She had found a document.\n해석: 오후 1시 23분에 Sarathe 씨가 \"Got it\"이라고 쓴 의도는?\n정답 근거: \"책상 위에 있으니 찾으면 알려 달라\"는 말에 대한 답 → 문서(안건 인쇄본)를 찾았다는 뜻.\n오답 분석: (A) 지각 예상 여부와 무관. / (B) 회의 장소 언급 없음. / (C) 참석자 명단이 아니라 안건 인쇄본.", "vocab": "Paraphrase: Let me know when you find it. / Got it. → had found a document", "g": {"when": ["접속사", "~할 때"], "most": ["부사", "가장"], "got": ["동사", "(got it) 찾았다, 알았다", "get"], "likely": ["부사", "아마"], "writes": ["동사", "쓰다", "write"], "it": ["대명사", "그것"], "at": ["전치사", "~에, ~에서"], "what": ["대명사", "무엇"], "p.m": ["명사", "오후"], "ms": ["명사", "~씨(여성)"], "she": ["대명사", "그녀"], "mean": ["동사", "의미하다"], "1:23": ["숫자", "1시 23분"], "does": ["조동사", "(의문문 조동사)", "do"], "sarathe": ["고유명사", "사라테(인명)"]}}]}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a-r4-p6',$mkd${"id": "a-r4-p6", "area": "RC", "part": 6, "group": "A급 과제", "series": 3, "round": 4, "level": "중급", "title": "A급 과제 4회 · PART 6", "notes": [], "items": [], "sets": [{"range": "131-134", "passage": "To: m.tennyson@yackelartmuseum.co.uk\nFrom: l.rivera@pollimail.co.uk\nSubject: Re: Onboarding\nAttachment: Rivera_Bio\nDear Ms. Tennyson:\nI just completed the new-hire procedures online, but there may be an issue. When I hit the submit button, the screen went blank briefly, and I was returned to the main page. I never got a confirmation message of any kind. Can you please verify that my ---131--- was received?\nI am also attaching the staff biography you asked me ---132--- for the Web site. I tried my best to follow the format you provided. ---133---. Now that I am looking at everyone else's, I see that it might be too different from the others. Please let me know if I should ---134--- it.\nKind regards,\nLiam Rivera", "tr": "수신: m.tennyson@yackelartmuseum.co.uk / 발신: l.rivera@pollimail.co.uk / 제목: Re: 온보딩 / 첨부: Rivera_Bio\nTennyson 씨께: 방금 온라인으로 신입 직원 절차를 완료했는데 문제가 있을지도 모릅니다. 제출 버튼을 눌렀을 때 화면이 잠시 빈 화면이 되었다가 메인 페이지로 돌아갔습니다. 어떤 확인 메시지도 받지 못했습니다. 제 정보(131)가 접수되었는지 확인해 주시겠습니까? 또한 웹사이트용으로 작성해(132) 달라고 하신 직원 약력을 첨부합니다. 주신 형식을 최대한 따르려고 했습니다. 하지만 저의 개성도 조금 더하고 싶었습니다(133). 이제 다른 모든 분들의 것을 보니 제 것이 다른 것들과 너무 다를 수도 있을 것 같습니다. 수정해야(134) 할지 알려 주십시오. Liam Rivera 드림", "vocab": "onboarding 명 신입 교육 / new-hire 형 신입 사원의 / procedure 명 절차 / go blank 구 화면이 꺼지다 / confirmation 명 확인 / verify 동 확인하다 / biography 명 약력 / format 명 형식 / revise 동 수정하다", "questions": [{"no": 131, "q": "", "options": ["gift", "approval", "payment", "information"], "answer": 3, "explain": "정답 (D) information\n해석: 제 정보가 접수되었는지 확인해 주시겠습니까?\n정답 근거: 온라인 신입 직원 절차를 제출했지만 확인 메시지를 받지 못했으므로, 제출한 \"정보\"가 접수되었는지 확인 요청 → information.\n오답 분석: (A) gift: '선물' — 문맥 무관. / (B) approval: '승인' — 본인이 제출한 것은 승인이 아님. / (C) payment: '결제' — 입사 절차와 무관.\n지문 개요: 신입 직원 Liam Rivera가 온라인 입사 절차 제출 후 확인 메시지를 못 받아 정보 수신을 확인해 달라고 하고, 요청받은 직원 약력을 첨부하며 형식이 너무 다르면 수정하겠다고 하는 이메일."}, {"no": 132, "q": "", "options": ["to write", "writing it", "that wrote", "was written"], "answer": 0, "explain": "정답 (A) to write\n해석: 웹사이트용으로 작성해 달라고 하신 직원 약력\n정답 근거: 「the staff biography (that) you asked me + 빈칸」 — 목적격 관계대명사가 생략된 관계절. 5형식 ask + 목적어(me) + to V → to write. 타동사 write의 목적어는 선행사 biography.\n오답 분석: (B) writing it: ask + 목적어 뒤에는 to부정사가 와야 하고 it이 중복됨. / (C) that wrote: 관계절 안에 또 관계사가 들어가 구조 불가. / (D) was written: 접속사 없이 동사가 또 올 수 없음."}, {"no": 133, "q": "", "options": ["I greatly appreciate their help.", "Likewise, I will see what I can do.", "However, I also wanted to add some of my personality.", "I believe it can be found somewhere online."], "answer": 2, "explain": "정답 (C) However, I also wanted to add some of my personality.\n해석: 하지만 저의 개성도 조금 더하고 싶었습니다.\n정답 근거: 앞 문장 \"주신 형식을 최대한 따르려 했다\"와 역접(However)으로 \"개성도 더하고 싶었다\"가 이어지고, 뒤 문장 \"다른 사람들 것과 너무 다를 수 있다\"로 연결됨.\n오답 분석: (A) their help의 지시 대상이 없음. / (B) Likewise로 받을 앞 내용이 없음. / (D) 온라인에서 찾을 수 있다는 말은 문맥 무관."}, {"no": 134, "q": "", "options": ["borrow", "revise", "locate", "protect"], "answer": 1, "explain": "정답 (B) revise\n해석: 수정해야 할지 알려 주십시오.\n정답 근거: 약력이 다른 사람들 것과 너무 다를 수 있다고 했으므로 고쳐야 할지 묻는 흐름 → revise.\n오답 분석: (A) borrow: '빌리다' — 의미 불가. / (C) locate: '찾다' — 본인이 첨부한 약력을 찾을 필요 없음. / (D) protect: '보호하다' — 의미 불가."}], "g": {"to": ["전치사", "받는 사람"], "m.tennyson@yackelartmuseum.co.uk": ["고유명사", "이메일 주소"], "from": ["전치사", "보내는 사람"], "l.rivera@pollimail.co.uk": ["고유명사", "이메일 주소"], "subject": ["명사", "제목"], "re": ["전치사", "~에 관하여(회신)"], "onboarding": ["명사", "신입 교육"], "attachment": ["명사", "첨부 파일"], "rivera_bio": ["고유명사", "Rivera 약력 파일"], "dear": ["형용사", "친애하는"], "ms": ["명사", "~씨(여성)"], "tennyson": ["고유명사", "테니슨(성)"], "i": ["대명사", "나"], "just": ["부사", "막, 단지"], "completed": ["동사", "완료했다", "complete"], "the": ["관사", "그"], "new-hire": ["형용사", "신입 사원의"], "procedures": ["명사", "절차", "procedure"], "online": ["부사", "온라인으로"], "but": ["접속사", "그러나"], "there": ["부사", "거기에"], "may": ["조동사", "~일지도 모른다"], "be": ["동사", "~이다, 되다"], "an": ["관사", "하나의"], "issue": ["명사", "문제"], "when": ["접속사", "~할 때"], "hit": ["동사", "눌렀다", "hit"], "submit": ["동사", "제출하다"], "button": ["명사", "버튼"], "screen": ["명사", "화면"], "went": ["동사", "~되었다(go blank)", "go"], "blank": ["형용사", "빈, 아무것도 없는"], "briefly": ["부사", "잠시"], "and": ["접속사", "그리고"], "was": ["동사", "~였다", "be"], "returned": ["과거분사", "되돌려진", "return"], "main": ["형용사", "주된, 메인"], "page": ["명사", "페이지"], "never": ["부사", "결코 ~않다"], "got": ["동사", "받았다", "get"], "a": ["관사", "하나의"], "confirmation": ["명사", "확인"], "message": ["명사", "메시지"], "of": ["전치사", "~의"], "any": ["한정사", "어떤"], "kind": ["명사", "종류"], "can": ["조동사", "~할 수 있다"], "you": ["대명사", "당신"], "please": ["부사", "부디, ~해 주세요"], "verify": ["동사", "확인하다"], "that": ["접속사", "~라는 것"], "my": ["한정사", "나의"], "received": ["과거분사", "받아진", "receive"], "am": ["동사", "~이다", "be"], "also": ["부사", "또한"], "attaching": ["현재분사", "첨부하는", "attach"], "staff": ["명사", "직원"], "biography": ["명사", "약력"], "asked": ["동사", "요청했다", "ask"], "me": ["대명사", "나를"], "for": ["전치사", "~을 위해, ~동안"], "web": ["명사", "웹"], "site": ["명사", "사이트"], "tried": ["동사", "노력했다", "try"], "best": ["명사", "최선"], "follow": ["동사", "따르다"], "format": ["명사", "형식"], "provided": ["동사", "제공했다", "provide"], "now": ["접속사", "(now that) ~이므로"], "looking": ["현재분사", "보는", "look"], "at": ["전치사", "~에, ~에서"], "everyone": ["대명사", "모든 사람"], "else's": ["대명사", "다른 사람의 것"], "see": ["동사", "알다"], "it": ["대명사", "그것"], "might": ["조동사", "~일지도 모른다"], "too": ["부사", "너무"], "different": ["형용사", "다른"], "others": ["대명사", "다른 것들"], "let": ["동사", "~하게 하다"], "know": ["동사", "알다"], "if": ["접속사", "만약 ~라면"], "should": ["조동사", "~해야 한다"], "regards": ["명사", "안부"], "liam": ["고유명사", "리암(이름)"], "rivera": ["고유명사", "리베라(성)"]}}, {"range": "135-138", "passage": "Going Native Xeriscaping\nLow-Water Garden Experts\nXeriscaping is a type of garden design that uses native plants that can thrive in your garden with very little ---135---. Using drought-resistant plants helps ---136--- conserve limited water resources. Less water used means lower utility bills. And with so many beautiful native plants to choose from, anyone can enjoy a garden full of vibrant colors and interesting textures while ---137--- water use.\nGoing Native has been creating xeriscapes for 20 years. ---138---. Call today for a free consultation.", "tr": "Going Native 절수 조경 — 저수분 정원 전문가\n절수 조경은 아주 적은 수분(135)으로도 정원에서 잘 자랄 수 있는 토종 식물을 사용하는 정원 설계 방식입니다. 가뭄에 강한 식물을 사용하면 여러분(136)이 한정된 수자원을 보존하는 데 도움이 됩니다. 물을 덜 쓰면 공과금도 낮아집니다. 그리고 선택할 수 있는 아름다운 토종 식물이 아주 많아서 누구나 물 사용을 줄이면서(137) 생생한 색과 흥미로운 질감이 가득한 정원을 즐길 수 있습니다. Going Native는 20년 동안 절수 조경을 만들어 왔습니다. 저희의 숙련된 디자이너들이 여러분이 꿈꾸는 정원을 만들어 드릴 수 있습니다(138). 오늘 전화하셔서 무료 상담을 받으세요.", "vocab": "native 형 토착의 / thrive 동 잘 자라다 / moisture 명 수분 / drought-resistant 형 가뭄에 강한 / conserve 동 보존하다 / utility bill 명 공과금 / vibrant 형 선명한 / texture 명 질감 / consultation 명 상담", "questions": [{"no": 135, "q": "", "options": ["soil", "sunlight", "fertilizer", "moisture"], "answer": 3, "explain": "정답 (D) moisture\n해석: 아주 적은 수분으로도 정원에서 잘 자랄 수 있는 토종 식물\n정답 근거: \"저수분(Low-Water) 정원\", \"가뭄에 강한 식물\", \"물을 덜 쓴다\"는 문맥 → 적은 수분(moisture)으로 자라는 식물.\n오답 분석: (A) soil: '흙' — 물 절약 문맥과 불일치. / (B) sunlight: '햇빛' — 무관. / (C) fertilizer: '비료' — 무관.\n지문 개요: 적은 수분으로도 잘 자라는 토종 식물을 쓰는 절수 조경(xeriscaping)을 소개하며, 물 절약과 공과금 절감, 다채로운 정원을 강조하고 20년 경력의 Going Native에 무료 상담을 권하는 광고."}, {"no": 136, "q": "", "options": ["him", "you", "them", "itself"], "answer": 1, "explain": "정답 (B) you\n해석: 여러분이 한정된 수자원을 보존하는 데 도움이 됩니다.\n정답 근거: 5형식 help + 목적어 + (to) V 구조의 목적어 자리. 광고의 독자(정원 주인)가 물을 보존하는 주체 → you.\n오답 분석: (A) him: 지시 대상이 되는 남성이 없음. / (C) them: 가리킬 복수 대상이 없음. / (D) itself: 재귀대명사 — 주어 Using ~와 동일 대상이 아님."}, {"no": 137, "q": "", "options": ["reducing", "to reduce", "they reduced", "the reduction of"], "answer": 0, "explain": "정답 (A) reducing\n해석: 누구나 물 사용을 줄이면서 정원을 즐길 수 있습니다.\n정답 근거: 부사절 접속사 while 뒤 분사구문(주어 anyone 생략). after·before·while·when·since 5개 접속사 뒤엔 - ing. 타동사 reduce 뒤 목적어 water use가 있으므로 능동 reducing.\n오답 분석: (B) to reduce: while 뒤 to부정사 불가. / (C) they reduced: 주절이 현재(can enjoy)인데 과거시제이고 주어 anyone과 they 불일치. / (D) the reduction of: while 뒤 명사구 단독 불가."}, {"no": 138, "q": "", "options": ["However, we appreciate your request for native plants.", "Similarly, roses are available in many different colors.", "A backyard swimming pool can be fun for the whole family.", "Our experienced designers can create the garden of your dreams."], "answer": 3, "explain": "정답 (D) Our experienced designers can create the garden of your dreams.\n해석: 저희의 숙련된 디자이너들이 여러분이 꿈꾸는 정원을 만들어 드릴 수 있습니다.\n정답 근거: \"20년 동안 절수 조경을 만들어 왔다\"는 회사 소개 뒤, 디자이너의 역량을 강조하고 \"오늘 전화해 무료 상담\"으로 이어지는 광고 마무리 흐름.\n오답 분석: (A) 요청에 감사한다는 말은 However로 연결될 대비 내용이 없음. / (B) 장미 색상 이야기는 절수 조경 홍보와 무관. / (C) 수영장은 정원 조경 광고와 무관."}], "g": {"going": ["고유명사", "(Going Native) 회사명", "go"], "native": ["형용사", "토착의"], "xeriscaping": ["명사", "절수 조경"], "low-water": ["형용사", "물을 적게 쓰는"], "garden": ["명사", "정원"], "experts": ["명사", "전문가들", "expert"], "is": ["동사", "~이다", "be"], "a": ["관사", "하나의"], "type": ["명사", "종류"], "of": ["전치사", "~의"], "design": ["명사", "설계"], "that": ["관계사", "~하는"], "uses": ["동사", "사용하다", "use"], "plants": ["명사", "식물들", "plant"], "can": ["조동사", "~할 수 있다"], "thrive": ["동사", "잘 자라다"], "in": ["전치사", "~에, ~안에"], "your": ["한정사", "당신의"], "with": ["전치사", "~와 함께, ~으로"], "very": ["부사", "매우"], "little": ["형용사", "거의 없는, 적은"], "using": ["동명사", "사용하는 것", "use"], "drought-resistant": ["형용사", "가뭄에 강한"], "helps": ["동사", "돕다", "help"], "conserve": ["동사", "보존하다"], "limited": ["형용사", "한정된"], "water": ["명사", "물"], "resources": ["명사", "자원", "resource"], "less": ["형용사", "더 적은"], "used": ["과거분사", "사용된", "use"], "means": ["동사", "의미하다", "mean"], "lower": ["형용사", "더 낮은", "low"], "utility": ["명사", "공공요금"], "bills": ["명사", "청구서", "bill"], "and": ["접속사", "그리고"], "so": ["접속사", "그래서"], "many": ["형용사", "많은"], "beautiful": ["형용사", "아름다운"], "to": ["to부정사", "~할"], "choose": ["동사", "고르다"], "from": ["전치사", "~로부터"], "anyone": ["대명사", "누구나"], "enjoy": ["동사", "즐기다"], "full": ["형용사", "가득한"], "vibrant": ["형용사", "선명한"], "colors": ["명사", "색깔", "color"], "interesting": ["형용사", "흥미로운"], "textures": ["명사", "질감", "texture"], "while": ["접속사", "~하는 동안"], "use": ["명사", "사용"], "has": ["동사", "(현재완료) ~했다", "have"], "been": ["과거분사", "~였던", "be"], "creating": ["현재분사", "만드는", "create"], "xeriscapes": ["명사", "절수 정원", "xeriscape"], "for": ["전치사", "~을 위해, ~동안"], "20": ["숫자", "20"], "years": ["명사", "년", "year"], "call": ["동사", "전화하다"], "today": ["부사", "오늘"], "free": ["형용사", "무료의"], "consultation": ["명사", "상담"]}}, {"range": "139-142", "passage": "Rite Shop Stores Introduce New Collaborations\nNational grocery chain Rite Shop has just announced partnerships with several specialty food brands ---139--- for their unique products. These include Gerry's Cheeses, H&R Bagels, and Daily Bread baked goods. The brands will ---140--- be available at select Rite Shop stores. ---141---.\n\"I think customers will be really pleased to see these brands at Rite Shop,\" CEO Natalie Yalbirs said at a press conference on Wednesday. \"And we at Rite Shop are excited about this opportunity to expand our ---142---.\"", "tr": "Rite Shop 매장, 새로운 협업 도입\n전국 식료품 체인 Rite Shop은 독특한 제품으로 알려진(139) 여러 특산 식품 브랜드와의 제휴를 방금 발표했다. 여기에는 Gerry's Cheeses, H&R Bagels, Daily Bread 제과류가 포함된다. 이 브랜드들은 곧(140) 일부 Rite Shop 매장에서 구입할 수 있게 된다. 모든 매장이 향후 몇 달에 걸쳐 이 제품들을 판매하기 시작할 것이다(141). \"고객들이 Rite Shop에서 이 브랜드들을 보고 정말 기뻐할 것이라고 생각합니다.\" CEO Natalie Yalbirs는 수요일 기자회견에서 말했다. \"그리고 저희 Rite Shop은 제품군(142)을 확대할 이번 기회에 들떠 있습니다.\"", "vocab": "collaboration 명 협업 / grocery chain 명 식료품 체인 / partnership 명 제휴 / specialty 형 전문의 / be known for 구 ~로 유명하다 / select 형 엄선된 / press conference 명 기자 회견 / expand 동 확대하다 / offerings 명 제공 상품", "questions": [{"no": 139, "q": "", "options": ["known", "that know", "they know", "were known"], "answer": 0, "explain": "정답 (A) known\n해석: 독특한 제품으로 알려진 여러 특산 식품 브랜드\n정답 근거: 이미 동사 has announced가 있고 접속사가 없으므로 동사 불가 → 명사 brands를 뒤에서 꾸미는 분사. 관계대명사 축약: brands (that are) known for ~. know는 타동사인데 빈칸 뒤 목적어 없이 전치사 for가 오므로 -ed(수동) known.\n오답 분석: (B) that know: 능동이면 뒤에 목적어(명사)가 필요한데 전치사 for뿐이고 의미도 불가. / (C) they know: 접속사 없이 절을 이어 붙일 수 없음. / (D) were known: 동사 2개(has announced, were known)인데 접속사 없음.\n지문 개요: 전국 식료품 체인 Rite Shop이 Gerry's Cheeses, H&R Bagels, Daily Bread 등 독특한 제품으로 알려진 특산 식품 브랜드들과 제휴해 곧 일부 매장에서 판매를 시작하고 수개월 내 전 매장으로 확대하며, CEO가 제품군 확대에 기대를 표한 기사."}, {"no": 140, "q": "", "options": ["still", "soon", "likewise", "ever"], "answer": 1, "explain": "정답 (B) soon\n해석: 이 브랜드들은 곧 일부 Rite Shop 매장에서 구입할 수 있게 된다.\n정답 근거: 제휴를 \"방금 발표\"했고 미래 will be available이므로 \"곧\" → soon. 조동사 will과 be 사이 부사 자리.\n오답 분석: (A) still: '여전히' — 새로 시작되는 판매와 불일치. / (C) likewise: '마찬가지로' — 비교 대상 없음. / (D) ever: '언젠가, 항상' — 의미 불가."}, {"no": 141, "q": "", "options": ["Nevertheless, hot coffee can now be purchased at all stores.", "Rite Shop was founded more than 25 years ago.", "All stores will begin selling the products over the next several months.", "For example, Daily Bread operates locally."], "answer": 2, "explain": "정답 (C) All stores will begin selling the products over the next several months.\n해석: 모든 매장이 향후 몇 달에 걸쳐 이 제품들을 판매하기 시작할 것이다.\n정답 근거: 앞 문장 \"일부(select) 매장에서 판매\"에 이어 \"전 매장으로 확대\"라는 계획이 자연스럽게 연결되고, 뒤 CEO의 기대 발언으로 이어짐.\n오답 분석: (A) Nevertheless로 대비할 내용이 없고 커피 판매는 무관. / (B) 설립 연도는 제휴 소식과 무관. / (D) For example로 예시할 내용이 아니며 지역 운영 여부는 무관."}, {"no": 142, "q": "", "options": ["budget", "offerings", "warehouse", "membership"], "answer": 1, "explain": "정답 (B) offerings\n해석: 제품군을 확대할 이번 기회에 들떠 있습니다.\n정답 근거: 새 브랜드 제품을 판매하게 되므로 회사가 \"제공하는 상품(offerings)\"이 늘어남 → expand our offerings.\n오답 분석: (A) budget: '예산' — 제휴로 예산을 확대한다는 뜻이 아님. / (C) warehouse: '창고' — 무관. / (D) membership: '회원' — 무관."}], "g": {"rite": ["고유명사", "라이트(상호)"], "shop": ["고유명사", "숍(상호)"], "stores": ["명사", "매장", "store"], "introduce": ["동사", "도입하다"], "new": ["형용사", "새로운"], "collaborations": ["명사", "협업", "collaboration"], "national": ["형용사", "전국적인"], "grocery": ["명사", "식료품"], "chain": ["명사", "체인점"], "has": ["동사", "(현재완료) ~했다", "have"], "just": ["부사", "막, 단지"], "announced": ["과거분사", "발표한", "announce"], "partnerships": ["명사", "제휴", "partnership"], "with": ["전치사", "~와 함께, ~으로"], "several": ["형용사", "여러"], "specialty": ["명사", "특산품, 전문"], "food": ["명사", "식품"], "brands": ["명사", "브랜드", "brand"], "for": ["전치사", "~을 위해, ~동안"], "their": ["한정사", "그들의"], "unique": ["형용사", "독특한"], "products": ["명사", "제품", "product"], "these": ["한정사", "이들"], "include": ["동사", "포함하다"], "gerry's": ["고유명사", "제리스(브랜드)"], "cheeses": ["명사", "치즈", "cheese"], "h&r": ["고유명사", "H&R(브랜드)"], "bagels": ["명사", "베이글", "bagel"], "and": ["접속사", "그리고"], "daily": ["고유명사", "데일리(브랜드)"], "bread": ["명사", "빵"], "baked": ["과거분사", "구운", "bake"], "goods": ["명사", "제품", "good"], "the": ["관사", "그"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "available": ["형용사", "구입 가능한"], "at": ["전치사", "~에, ~에서"], "select": ["형용사", "엄선된, 일부의"], "i": ["대명사", "나"], "think": ["동사", "생각하다"], "customers": ["명사", "고객들", "customer"], "really": ["부사", "정말"], "pleased": ["형용사", "기쁜"], "to": ["to부정사", "~해서"], "see": ["동사", "보다"], "ceo": ["명사", "최고경영자"], "natalie": ["고유명사", "나탈리(이름)"], "yalbirs": ["고유명사", "얄비르스(성)"], "said": ["동사", "말했다", "say"], "a": ["관사", "하나의"], "press": ["명사", "언론"], "conference": ["명사", "회견"], "on": ["전치사", "~에, ~위에"], "wednesday": ["명사", "수요일"], "we": ["대명사", "우리"], "are": ["동사", "~이다", "be"], "excited": ["형용사", "들뜬"], "about": ["전치사", "~에 대해"], "this": ["한정사", "이"], "opportunity": ["명사", "기회"], "expand": ["동사", "확대하다"], "our": ["한정사", "우리의"]}}, {"range": "143-146", "passage": "From: Sergio L. McGovern, Vice President of Operations\nTo: All Floor Supervisors\nSubject: Inspections\nDate: 3 June\nAs part of our efforts ---143--- product quality and ensure compliance with national regulations, all manufacturing units will be subject to random inspections effective immediately. These checks ---144--- conducted by engineers from Venturia Systems, Inc. They will monitor the production line and observe warehouse operations. Please be aware that the inspectors will arrive without ---145---. Thus, they may walk in at any time. We ask that you proceed as usual with your work while the inspectors complete theirs. Within one week of each inspection, a detailed report will be sent directly to me. ---146---. Thank you.", "tr": "발신: Sergio L. McGovern, 운영 부사장 / 수신: 전 층별 감독관 / 제목: 검사 / 날짜: 6월 3일\n제품 품질을 개선하고(143) 국가 규정 준수를 보장하려는 노력의 일환으로, 모든 제조 부서는 즉시 무작위 검사를 받게 됩니다. 이 검사는 Venturia Systems, Inc.의 엔지니어들이 실시할 것입니다(144). 그들은 생산 라인을 점검하고 창고 운영을 관찰할 것입니다. 검사관들은 예고(145) 없이 도착한다는 점을 유념하십시오. 따라서 언제든 들어올 수 있습니다. 검사관들이 일을 마치는 동안 여러분은 평소대로 업무를 진행하시기 바랍니다. 각 검사 후 일주일 이내에 상세 보고서가 저에게 직접 전달됩니다. 여러분도 사본을 받게 될 것입니다(146). 감사합니다.", "vocab": "inspection 명 점검 / compliance with 구 ~의 준수 / regulation 명 규정 / be subject to 구 ~의 대상이 되다 / effective immediately 구 즉시 효력이 있는 / conduct 동 실시하다 / observe 동 관찰하다 / warning 명 예고 / proceed 동 진행하다", "questions": [{"no": 143, "q": "", "options": ["improving", "to improve", "that improved", "of improvement"], "answer": 1, "explain": "정답 (B) to improve\n해석: 제품 품질을 개선하려는 노력의 일환으로\n정답 근거: 명사 efforts 뒤에서 그 목적을 설명하는 to부정사(efforts to V, ~하려는 노력). 타동사 improve 뒤 목적어 product quality 있음(능동).\n오답 분석: (A) improving: efforts 뒤에 -ing 분사를 붙이는 형태는 쓰지 않음(to부정사 필요). / (C) that improved: 관계절이면 시제가 맞지 않고 의미 불가. / (D) of improvement: 명사 improvement 뒤에 목적어 product quality를 연결할 수 없음.\n지문 개요: 운영 부사장 Sergio McGovern이 층별 감독관들에게 제품 품질 개선과 국가 규정 준수를 위해 즉시 모든 제조 부서에 Venturia Systems 엔지니어의 무작위 검사를 시행하며, 검사관이 예고 없이 방문하니 평소대로 일하고, 검사 보고서 사본도 받게 된다고 알리는 회람."}, {"no": 144, "q": "", "options": ["were", "will be", "had been", "were being"], "answer": 1, "explain": "정답 (B) will be\n해석: 이 검사는 Venturia Systems의 엔지니어들이 실시할 것입니다.\n정답 근거: 앞 문장의 \"즉시(effective immediately) 시행된다\"는 새 방침이므로 앞으로 실시될 검사 → 미래 will be (conducted). conduct 타동사인데 빈칸 뒤 목적어 없이 by구 → 수동.\n오답 분석: (A) were: 과거 — 새로 시작되는 검사와 불일치. / (C) had been: 과거완료 — 불일치. / (D) were being: 과거진행 — 불일치."}, {"no": 145, "q": "", "options": ["warning", "delay", "permission", "accommodation"], "answer": 0, "explain": "정답 (A) warning\n해석: 검사관들은 예고 없이 도착한다는 점을 유념하십시오.\n정답 근거: 뒤 문장 \"따라서 언제든 들어올 수 있다\"와 \"무작위 검사\"이므로 사전 통보(예고) 없이 옴 → warning.\n오답 분석: (B) delay: '지연' — 언제든 들어온다는 결과와 연결되지 않음. / (C) permission: '허가' — 검사관이 허가 없이 온다는 뜻은 문맥과 다름. / (D) accommodation: '숙박' — 무관."}, {"no": 146, "q": "", "options": ["Please submit your evaluation upon completion.", "Please arrive promptly at the agreed-upon time.", "Inspectors will register at the front desk.", "You will be receiving a copy as well."], "answer": 3, "explain": "정답 (D) You will be receiving a copy as well.\n해석: 여러분도 사본을 받게 될 것입니다.\n정답 근거: 앞 문장 \"상세 보고서가 저(부사장)에게 직접 전달된다\"에 이어 수신자인 감독관들도 사본(as well)을 받는다는 내용이 자연스러움.\n오답 분석: (A) 감독관이 평가를 제출하는 것이 아니라 검사관이 보고서를 작성함. / (B) 검사는 예고 없이 이루어지므로 합의된 시간이 없음. / (C) 프런트 등록은 '언제든 들어온다'는 내용과 모순."}], "g": {"from": ["전치사", "~로부터"], "sergio": ["고유명사", "세르히오(이름)"], "l": ["고유명사", "L.(이름 머리글자)"], "mcgovern": ["고유명사", "맥거번(성)"], "vice": ["형용사", "부(副)"], "president": ["명사", "사장"], "of": ["전치사", "~의"], "operations": ["명사", "운영", "operation"], "to": ["전치사", "받는 사람"], "all": ["한정사", "모든"], "floor": ["명사", "작업장, 층"], "supervisors": ["명사", "감독관", "supervisor"], "subject": ["형용사", "(be subject to) ~의 대상인"], "inspections": ["명사", "점검", "inspection"], "date": ["명사", "날짜"], "3": ["숫자", "3"], "june": ["명사", "6월"], "as": ["접속사", "~처럼, ~때문에"], "part": ["명사", "일부"], "our": ["한정사", "우리의"], "efforts": ["명사", "노력", "effort"], "product": ["명사", "제품"], "quality": ["명사", "품질"], "and": ["접속사", "그리고"], "ensure": ["동사", "보장하다"], "compliance": ["명사", "준수"], "with": ["전치사", "~와 함께, ~으로"], "national": ["형용사", "국가의"], "regulations": ["명사", "규정", "regulation"], "manufacturing": ["명사", "제조"], "units": ["명사", "부서, 단위", "unit"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "random": ["형용사", "무작위의"], "effective": ["형용사", "효력이 있는"], "immediately": ["부사", "즉시"], "these": ["한정사", "이들"], "checks": ["명사", "점검", "check"], "conducted": ["과거분사", "실시된", "conduct"], "by": ["전치사", "~에 의해, ~까지"], "engineers": ["명사", "기술자", "engineer"], "venturia": ["고유명사", "벤투리아(회사명)"], "systems": ["고유명사", "시스템즈(회사명)", "system"], "inc": ["명사", "주식회사"], "they": ["대명사", "그들"], "monitor": ["동사", "감시하다"], "the": ["관사", "그"], "production": ["명사", "생산"], "line": ["명사", "라인"], "observe": ["동사", "관찰하다"], "warehouse": ["명사", "창고"], "please": ["부사", "부디, ~해 주세요"], "aware": ["형용사", "알고 있는"], "that": ["접속사", "~라는 것"], "inspectors": ["명사", "검사관", "inspector"], "arrive": ["동사", "도착하다"], "without": ["전치사", "~없이"], "thus": ["부사", "따라서"], "may": ["조동사", "~일지도 모른다"], "walk": ["동사", "걷다(walk in 들어오다)"], "in": ["전치사", "~에, ~안에"], "at": ["전치사", "~에, ~에서"], "any": ["한정사", "어떤"], "time": ["명사", "시간"], "we": ["대명사", "우리"], "ask": ["동사", "요청하다"], "you": ["대명사", "당신"], "proceed": ["동사", "진행하다"], "usual": ["형용사", "평소의"], "your": ["한정사", "당신의"], "work": ["명사", "업무"], "while": ["접속사", "~하는 동안"], "complete": ["동사", "완료하다"], "theirs": ["대명사", "그들의 것"], "within": ["전치사", "~이내에"], "one": ["숫자", "하나"], "week": ["명사", "주"], "each": ["한정사", "각각의"], "inspection": ["명사", "점검"], "a": ["관사", "하나의"], "detailed": ["형용사", "상세한"], "report": ["명사", "보고서"], "sent": ["과거분사", "보내진", "send"], "directly": ["부사", "직접"], "me": ["대명사", "나를"], "thank": ["동사", "감사하다"]}}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a-r4-p7',$mkd${"id": "a-r4-p7", "area": "RC", "part": 7, "group": "A급 과제", "series": 3, "round": 4, "level": "중급", "title": "A급 과제 4회 · PART 7 (기출독해 2문항 7·8회)", "notes": [], "items": [], "sets": [{"range": "147-148", "sub": "기출독해 2문항 7회", "passage": "Next Step: Success!\nThe Merriweather Convention Hall\n8 June, 9:00 A.M. ― 4:00 P.M.\nMeet with human resources representatives!\nHighlights\n· Free admission\n· Open positions with over 300 companies\n· Resume-writing help by appointment (a small fee applies)\n· Lectures and discussions on finding and keeping a job in today's competitive environment\nMany different professions will be represented: office work, accounting, security, sales and marketing, shipping and receiving, and more.", "tr": "다음 단계: 성공! The Merriweather Convention Hall, 6월 8일 오전 9시~오후 4시\n인사 담당자들을 만나세요! 주요 내용 · 무료 입장 · 300개 이상 기업의 채용 공고 · 예약제 이력서 작성 도움(소액 요금 적용) · 오늘날의 경쟁 환경에서 일자리를 찾고 유지하는 것에 관한 강연과 토론\n사무직, 회계, 보안, 영업·마케팅, 배송·입고 등 다양한 직종이 참여합니다.", "vocab": "representative 명 담당자 / admission 명 입장 / open position 명 공석 / by appointment 구 예약제로 / fee 명 요금 / competitive 형 경쟁이 치열한 / profession 명 직종 / publicize 동 홍보하다", "questions": [{"no": 147, "q": "What type of event is being publicized?", "options": ["A writing workshop", "An employment fair", "A computer networking seminar", "A human resources course"], "answer": 1, "explain": "정답 (B) An employment fair\n해석: 어떤 종류의 행사가 홍보되고 있는가?\n정답 근거: \"인사 담당자들을 만나세요\", \"300개 이상 기업의 채용 공고\", \"일자리를 찾고 유지하는 것에 관한 강연\" → 취업 박람회.\n오답 분석: (A) 이력서 작성 도움은 부대 서비스일 뿐 글쓰기 워크숍이 아님. / (C) 컴퓨터 네트워킹 세미나 아님. / (D) 인사 강좌가 아니라 인사 담당자를 만나는 행사.\n지문 개요: 6월 8일 Merriweather Convention Hall에서 열리는 취업 박람회 광고. 무료 입장, 300개 이상 기업의 채용 공고, 예약제 이력서 작성 도움(소액 유료), 취업 강연, 사무·회계·보안·영업 등 다양한 직종 참여를 안내함.", "vocab": "Paraphrase: Open positions with over 300 companies / human resources representatives → an employment fair", "g": {"what": ["대명사", "무엇"], "type": ["명사", "종류"], "of": ["전치사", "~의"], "event": ["명사", "행사"], "is": ["동사", "~이다", "be"], "being": ["현재분사", "~되는 중인", "be"], "publicized": ["과거분사", "홍보되는", "publicize"]}}, {"no": 148, "q": "What is indicated about the event?", "options": ["It will take place over two days.", "It will be held at an office building.", "All activities and services are free of charge.", "Representatives from many companies will attend."], "answer": 3, "explain": "정답 (D) Representatives from many companies will attend.\n해석: 행사에 대해 언급된 것은?\n정답 근거: \"300개 이상 기업의 채용 공고\", \"인사 담당자들을 만나라\" → 많은 기업의 대표자가 참석함.\n오답 분석: (A) 6월 8일 하루 행사. / (B) 장소는 컨벤션 홀. / (C) 이력서 작성 도움은 소액 요금이 있어 전부 무료가 아님.", "vocab": "Paraphrase: Open positions with over 300 companies → representatives from many companies will attend", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "indicated": ["과거분사", "언급된", "indicate"], "about": ["전치사", "~에 대해"], "the": ["관사", "그"], "event": ["명사", "행사"]}}], "g": {"next": ["형용사", "다음의"], "step": ["명사", "단계"], "success": ["명사", "성공"], "the": ["관사", "그"], "merriweather": ["고유명사", "메리웨더(지명)"], "convention": ["명사", "컨벤션, 대회"], "hall": ["명사", "홀, 회관"], "8": ["숫자", "8"], "june": ["명사", "6월"], "9:00": ["숫자", "9시"], "a.m": ["명사", "오전"], "4:00": ["숫자", "4시"], "p.m": ["명사", "오후"], "meet": ["동사", "만나다"], "with": ["전치사", "~와 함께, ~으로"], "human": ["형용사", "인적인"], "resources": ["명사", "자원(HR 인사)", "resource"], "representatives": ["명사", "담당자", "representative"], "highlights": ["명사", "주요 내용", "highlight"], "free": ["형용사", "무료의"], "admission": ["명사", "입장"], "open": ["형용사", "비어 있는(공석)"], "positions": ["명사", "일자리", "position"], "over": ["전치사", "~동안, ~이상"], "300": ["숫자", "300"], "companies": ["명사", "회사", "company"], "resume-writing": ["명사", "이력서 작성"], "help": ["명사", "도움"], "by": ["전치사", "~에 의해, ~까지"], "appointment": ["명사", "예약"], "a": ["관사", "하나의"], "small": ["형용사", "적은"], "fee": ["명사", "요금"], "applies": ["동사", "적용되다", "apply"], "lectures": ["명사", "강연", "lecture"], "and": ["접속사", "그리고"], "discussions": ["명사", "토론", "discussion"], "on": ["전치사", "~에, ~위에"], "finding": ["동명사", "찾는 것", "find"], "keeping": ["동명사", "유지하는 것", "keep"], "job": ["명사", "일자리"], "in": ["전치사", "~에, ~안에"], "today's": ["명사", "오늘날의"], "competitive": ["형용사", "경쟁이 치열한"], "environment": ["명사", "환경"], "many": ["형용사", "많은"], "different": ["형용사", "다양한"], "professions": ["명사", "직종", "profession"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "represented": ["과거분사", "대표되는, 참여하는", "represent"], "office": ["명사", "사무"], "work": ["명사", "일"], "accounting": ["명사", "회계"], "security": ["명사", "보안"], "sales": ["명사", "영업"], "marketing": ["명사", "마케팅"], "shipping": ["명사", "배송"], "receiving": ["명사", "입고"], "more": ["부사", "더"]}}, {"range": "149-150", "sub": "기출독해 2문항 7회", "passage": "Temporary Closure\nThank you for joining us today at Arthur's Continental Cuisine (ACC) on Durham Road in Southbank. We hope that you will dine with us again, but please note that this location will be closed for a private party on Tuesday, 8 February, from 4:00 P.M. to closing. Our other locations (in East Melbourne, Carlton, and Parkville) will remain open to the public on that date. To make a reservation, call your location of choice or visit our Web site at www.arthurscc.com.au.", "tr": "임시 휴업\n오늘 Southbank Durham Road의 Arthur's Continental Cuisine(ACC)을 찾아 주셔서 감사합니다. 다시 식사하러 오시길 바라지만, 이 지점은 2월 8일 화요일 오후 4시부터 마감까지 개인 파티로 문을 닫는다는 점을 유의해 주십시오. 다른 지점(East Melbourne, Carlton, Parkville)은 그 날짜에 정상 영업합니다. 예약하시려면 원하는 지점에 전화하시거나 저희 웹사이트 www.arthurscc.com.au를 방문하세요.", "vocab": "temporary 형 일시적인 / closure 명 폐쇄 / cuisine 명 요리 / dine 동 식사하다 / private party 명 개인 행사 / remain open 구 계속 영업하다 / location of choice 명 원하는 지점 / reservation 명 예약", "questions": [{"no": 149, "q": "What will happen on February 8?", "options": ["The Carlton location will stay open later than usual.", "A surprise party will be given for ACC employees.", "A private event will be held at ACC's Southbank location.", "Durham Road will be temporarily closed."], "answer": 2, "explain": "정답 (C) A private event will be held at ACC's Southbank location.\n해석: 2월 8일에 무슨 일이 있을 것인가?\n정답 근거: \"이 지점(Southbank Durham Road)은 2월 8일 개인 파티로 문을 닫는다\" → Southbank 지점에서 개인 행사가 열림.\n오답 분석: (A) Carlton 지점은 정상 영업이지 연장 영업 아님. / (B) 직원 깜짝 파티가 아니라 개인(고객) 파티. / (D) 도로가 아니라 식당이 문을 닫음.\n지문 개요: Southbank Durham Road의 Arthur's Continental Cuisine이 2월 8일 화요일 오후 4시부터 마감까지 개인 파티로 문을 닫으며, 다른 지점(East Melbourne, Carlton, Parkville)은 정상 영업하고 예약은 전화나 웹사이트로 하라는 공지.", "vocab": "Paraphrase: closed for a private party / on Durham Road in Southbank → a private event at ACC's Southbank location", "g": {"what": ["대명사", "무엇"], "will": ["조동사", "~할 것이다"], "happen": ["동사", "일어나다"], "on": ["전치사", "~에, ~위에"], "february": ["명사", "2월"], "8": ["숫자", "8"]}}, {"no": 150, "q": "What does the notice say that customers can do on a Web site?", "options": ["View a restaurant menu", "Make a dining reservation", "Respond to an online survey", "Vote for a favorite location"], "answer": 1, "explain": "정답 (B) Make a dining reservation\n해석: 공지에 따르면 고객은 웹사이트에서 무엇을 할 수 있는가?\n정답 근거: \"예약하려면 전화하거나 웹사이트를 방문하라\" → 식사 예약.\n오답 분석: (A) 메뉴 열람 언급 없음. / (C) 설문 응답 없음. / (D) 투표 없음.", "vocab": "Paraphrase: To make a reservation, visit our Web site → make a dining reservation", "g": {"what": ["대명사", "무엇"], "does": ["조동사", "(의문문 조동사)", "do"], "the": ["관사", "그"], "notice": ["명사", "공지"], "say": ["동사", "말하다"], "that": ["한정사", "그"], "customers": ["명사", "고객들", "customer"], "can": ["조동사", "~할 수 있다"], "do": ["동사", "하다"], "on": ["전치사", "~에, ~위에"], "a": ["관사", "하나의"], "web": ["명사", "웹"], "site": ["명사", "사이트"]}}], "g": {"temporary": ["형용사", "일시적인"], "closure": ["명사", "휴업"], "thank": ["동사", "감사하다"], "you": ["대명사", "당신"], "for": ["전치사", "~을 위해, ~동안"], "joining": ["동명사", "함께하는 것", "join"], "us": ["대명사", "우리를"], "today": ["부사", "오늘"], "at": ["전치사", "~에, ~에서"], "arthur's": ["고유명사", "아서스(상호)"], "continental": ["형용사", "유럽 대륙의"], "cuisine": ["명사", "요리"], "acc": ["고유명사", "ACC(상호 약칭)"], "on": ["전치사", "~에, ~위에"], "durham": ["고유명사", "더럼(지명)"], "road": ["명사", "도로"], "in": ["전치사", "~에, ~안에"], "southbank": ["고유명사", "사우스뱅크(지명)"], "we": ["대명사", "우리"], "hope": ["동사", "바라다"], "that": ["한정사", "그"], "will": ["조동사", "~할 것이다"], "dine": ["동사", "식사하다"], "with": ["전치사", "~와 함께, ~으로"], "again": ["부사", "다시"], "but": ["접속사", "그러나"], "please": ["부사", "부디, ~해 주세요"], "note": ["동사", "유의하다"], "this": ["한정사", "이"], "location": ["명사", "지점"], "be": ["동사", "~이다, 되다"], "closed": ["과거분사", "문을 닫은", "close"], "a": ["관사", "하나의"], "private": ["형용사", "개인의, 비공개의"], "party": ["명사", "파티"], "tuesday": ["명사", "화요일"], "8": ["숫자", "8"], "february": ["명사", "2월"], "from": ["전치사", "~로부터"], "4:00": ["숫자", "4시"], "p.m": ["명사", "오후"], "to": ["to부정사", "~하기 위해"], "closing": ["명사", "폐점(시간)"], "our": ["한정사", "우리의"], "other": ["형용사", "다른"], "locations": ["명사", "지점들", "location"], "east": ["고유명사", "이스트(지명)"], "melbourne": ["고유명사", "멜버른"], "carlton": ["고유명사", "칼턴(지명)"], "and": ["접속사", "그리고"], "parkville": ["고유명사", "파크빌(지명)"], "remain": ["동사", "~인 채로 있다"], "open": ["형용사", "영업 중인"], "the": ["관사", "그"], "public": ["명사", "대중"], "date": ["명사", "날짜"], "make": ["동사", "하다"], "reservation": ["명사", "예약"], "call": ["동사", "전화하다"], "your": ["한정사", "당신의"], "of": ["전치사", "~의"], "choice": ["명사", "선택"], "or": ["접속사", "또는"], "visit": ["동사", "방문하다"], "web": ["명사", "웹"], "site": ["명사", "사이트"], "www.arthurscc.com.au": ["고유명사", "웹사이트 주소"]}}, {"range": "151-152", "sub": "기출독해 2문항 7회", "passage": "To: Nancy Earlham <nearlham@mail4u.net>\nFrom: Anton Savino <savinoa@savinorealestate.com>\nDate: July 2\nSubject: Special offer\nDear Ms. Earlham,\nCongratulations on completing Savino Real Estate's seminar, \"Target Marketing for Selling Condominiums.\" We hope you received some valuable information that will help you in your career.\nOur next seminar will be held on Saturday, August 8. It will focus on recent changes to commercial real estate law. If you sign up by July 20, you will receive 30 percent off all course materials. Register online at www.savinorealestate.com. We hope you will join us!\nSincerely,\nAnton Savino", "tr": "수신: Nancy Earlham / 발신: Anton Savino / 날짜: 7월 2일 / 제목: 특별 제안\nEarlham 씨께, Savino Real Estate의 세미나 \"콘도 판매를 위한 타깃 마케팅\"을 수료하신 것을 축하드립니다. 경력에 도움이 될 귀중한 정보를 얻으셨길 바랍니다. 다음 세미나는 8월 8일 토요일에 열립니다. 상업용 부동산법의 최근 변경 사항에 초점을 맞출 예정입니다. 7월 20일까지 등록하시면 모든 교재를 30% 할인해 드립니다. www.savinorealestate.com에서 온라인으로 등록하세요. 함께하시길 바랍니다! Anton Savino 드림", "vocab": "real estate 명 부동산 / condominium 명 아파트 / valuable 형 유용한 / commercial 형 상업의 / sign up 구 등록하다 / course materials 명 강의 자료 / waive 동 면제하다 / administrative 형 행정의", "questions": [{"no": 151, "q": "Who most likely is Ms. Earlham?", "options": ["A lawyer", "A real estate agent", "A seminar leader", "An administrative assistant"], "answer": 1, "explain": "정답 (B) A real estate agent\n해석: Earlham 씨는 누구일 것 같은가?\n정답 근거: \"콘도 판매를 위한 타깃 마케팅\" 세미나를 수료했고 \"경력에 도움이 될 정보\"라 함 → 부동산 중개인.\n오답 분석: (A) 부동산법 세미나를 듣는 것이지 변호사라는 근거 없음. / (C) 세미나 수강생이지 강사가 아님. / (D) 행정 보조 근거 없음.\n지문 개요: Anton Savino가 콘도 판매 마케팅 세미나를 수료한 Nancy Earlham에게 8월 8일 상업용 부동산법 변경 세미나를 안내하며, 7월 20일까지 등록하면 교재 30% 할인을 준다는 이메일.", "vocab": "Paraphrase: Savino Real Estate's seminar / Selling Condominiums / your career → a real estate agent", "g": {"who": ["대명사", "누구"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "is": ["동사", "~이다", "be"], "ms": ["명사", "~씨(여성)"], "earlham": ["고유명사", "얼럼(성)"]}}, {"no": 152, "q": "What is offered to Ms. Earlham?", "options": ["A book signed by Mr. Savino", "A free online course", "A waived registration fee", "A discount on course books"], "answer": 3, "explain": "정답 (D) A discount on course books\n해석: Earlham 씨에게 제공되는 것은?\n정답 근거: \"7월 20일까지 등록하면 모든 교재(course materials) 30% 할인\" → 교재 할인.\n오답 분석: (A) 서명된 책 언급 없음. / (B) 무료 온라인 강좌 아님. / (C) 등록비 면제가 아니라 교재 할인.", "vocab": "Paraphrase: 30 percent off all course materials → a discount on course books", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "offered": ["과거분사", "제공되는", "offer"], "to": ["전치사", "받는 사람"], "ms": ["명사", "~씨(여성)"], "earlham": ["고유명사", "얼럼(성)"]}}], "g": {"to": ["전치사", "받는 사람"], "nancy": ["고유명사", "낸시(이름)"], "earlham": ["고유명사", "얼럼(성)"], "nearlham@mail4u.net": ["고유명사", "이메일 주소"], "from": ["전치사", "~로부터"], "anton": ["고유명사", "안톤(이름)"], "savino": ["고유명사", "사비노(성)"], "savinoa@savinorealestate.com": ["고유명사", "이메일 주소"], "date": ["명사", "날짜"], "july": ["명사", "7월"], "2": ["숫자", "2"], "subject": ["명사", "제목"], "special": ["형용사", "특별한"], "offer": ["명사", "제안"], "dear": ["형용사", "친애하는"], "ms": ["명사", "~씨(여성)"], "congratulations": ["명사", "축하", "congratulation"], "on": ["전치사", "~에, ~위에"], "completing": ["동명사", "수료한 것", "complete"], "real": ["형용사", "(real estate) 부동산"], "estate's": ["명사", "부동산(회사)의", "estate"], "seminar": ["명사", "세미나"], "target": ["명사", "표적, 타깃"], "marketing": ["명사", "마케팅"], "for": ["전치사", "~을 위해, ~동안"], "selling": ["동명사", "판매하는 것", "sell"], "condominiums": ["명사", "아파트", "condominium"], "we": ["대명사", "우리"], "hope": ["동사", "바라다"], "you": ["대명사", "당신"], "received": ["동사", "받았다", "receive"], "some": ["한정사", "약간의"], "valuable": ["형용사", "유용한"], "information": ["명사", "정보"], "that": ["관계사", "~하는"], "will": ["조동사", "~할 것이다"], "help": ["동사", "돕다"], "in": ["전치사", "~에, ~안에"], "your": ["한정사", "당신의"], "career": ["명사", "경력"], "our": ["한정사", "우리의"], "next": ["형용사", "다음의"], "be": ["동사", "~이다, 되다"], "held": ["과거분사", "개최되는", "hold"], "saturday": ["명사", "토요일"], "august": ["명사", "8월"], "8": ["숫자", "8"], "it": ["대명사", "그것"], "focus": ["동사", "초점을 맞추다"], "recent": ["형용사", "최근의"], "changes": ["명사", "변경 사항", "change"], "commercial": ["형용사", "상업의"], "estate": ["명사", "부동산"], "law": ["명사", "법"], "if": ["접속사", "만약 ~라면"], "sign": ["동사", "(sign up) 등록하다"], "up": ["부사", "위로, 완전히"], "by": ["전치사", "~에 의해, ~까지"], "20": ["숫자", "20"], "receive": ["동사", "받다"], "30": ["숫자", "30"], "percent": ["명사", "퍼센트"], "off": ["부사", "할인되어"], "all": ["한정사", "모든"], "course": ["명사", "강좌"], "materials": ["명사", "자료", "material"], "register": ["동사", "등록하다"], "online": ["부사", "온라인으로"], "at": ["전치사", "~에, ~에서"], "www.savinorealestate.com": ["고유명사", "웹사이트 주소"], "join": ["동사", "함께하다"], "us": ["대명사", "우리를"], "sincerely": ["부사", "진심으로"]}}, {"range": "153-154", "sub": "기출독해 2문항 7회", "passage": "Roger Varland (12:21 P.M.)\nHello. This is Kolpin Art Supply's 24-hour customer-support chat. My name is Roger. How can I help you?\nShaina Orbes (12:22 P.M.)\nI have been waiting for four items I ordered online, and now I see that the order was canceled. I often order from Kolpin, and I've never had a problem before. Can you check my account?\nRoger Varland (12:24 P.M.)\nI'm bringing it up now. It states here that the credit card you have on file with us has expired, so we could not process the payment. If you log in to your customer account, you can update your payment information. Then you can click on your order number and the system will let you place the order again.\nShaina Orbes (12:26 P.M.)\nI'll do that now. Thanks for your help!", "tr": "Roger Varland (오후 12:21) 안녕하세요. Kolpin Art Supply 24시간 고객 지원 채팅입니다. 저는 Roger입니다. 무엇을 도와드릴까요?\nShaina Orbes (오후 12:22) 온라인으로 주문한 물품 4개를 기다리고 있었는데, 지금 보니 주문이 취소되었네요. Kolpin에서 자주 주문하는데 전에는 문제가 없었어요. 제 계정을 확인해 주시겠어요?\nRoger Varland (오후 12:24) 지금 불러오고 있습니다. 등록된 신용카드가 만료되어 결제를 처리할 수 없었다고 나와 있습니다. 고객 계정에 로그인하시면 결제 정보를 업데이트할 수 있습니다. 그런 다음 주문 번호를 클릭하면 시스템이 다시 주문할 수 있게 해 줍니다.\nShaina Orbes (오후 12:26) 지금 하겠습니다. 도와주셔서 감사해요!", "vocab": "customer support 명 고객 지원 / cancel 동 취소하다 / bring up 구 (화면에) 띄우다 / on file 구 기록되어 있는 / expire 동 만료되다 / process 동 처리하다 / place an order 구 주문하다 / out of stock 구 재고가 없는", "questions": [{"no": 153, "q": "Why did Ms. Orbes contact customer support?", "options": ["An order did not arrive.", "A product was damaged.", "A package was sent by mistake.", "An item is out of stock."], "answer": 0, "explain": "정답 (A) An order did not arrive.\n해석: Orbes 씨는 왜 고객 지원에 연락했는가?\n정답 근거: \"주문한 물품 4개를 기다리고 있었는데 주문이 취소되었다\" → 주문이 도착하지 않음.\n오답 분석: (B) 제품 파손 언급 없음. / (C) 잘못 발송된 소포 아님. / (D) 품절이 아니라 결제 실패로 취소.\n지문 개요: Shaina Orbes가 온라인 주문 4개를 기다리다 주문이 취소된 것을 발견해 문의하자, 상담원 Roger Varland가 등록 카드 만료로 결제가 안 됐으니 계정에서 결제 정보를 갱신하고 주문 번호를 눌러 재주문하라고 안내하는 대화.", "vocab": "Paraphrase: I have been waiting for four items I ordered online → an order did not arrive", "g": {"why": ["부사", "왜"], "did": ["조동사", "(과거 의문문 조동사)", "do"], "ms": ["명사", "~씨(여성)"], "orbes": ["고유명사", "오브스(성)"], "contact": ["동사", "연락하다"], "customer": ["명사", "고객"], "support": ["명사", "지원"]}}, {"no": 154, "q": "At 12:24 P.M., what does Mr. Varland most likely mean when he writes, \"I'm bringing it up now\"?", "options": ["He is mentioning the problem to his supervisor.", "He is helping Ms. Orbes create a new password.", "He is applying a discount to some items.", "He is looking at the details of Ms. Orbes' account."], "answer": 3, "explain": "정답 (D) He is looking at the details of Ms. Orbes' account.\n해석: 오후 12시 24분에 Varland 씨가 \"I'm bringing it up now\"라고 쓴 의도는?\n정답 근거: \"제 계정을 확인해 주시겠어요?\"라는 요청에 대한 답이고, 바로 이어 계정에 기록된 카드 만료 내용을 말함 → 계정 정보를 불러와 보고 있음.\n오답 분석: (A) 상사에게 언급한다는 내용 없음. / (B) 비밀번호 생성 도움 아님. / (C) 할인 적용 아님.", "vocab": "Paraphrase: Can you check my account? → I'm bringing it up now → looking at the details of her account", "g": {"at": ["전치사", "~에, ~에서"], "12:24": ["숫자", "12시 24분"], "p.m": ["명사", "오후"], "what": ["대명사", "무엇"], "does": ["조동사", "(의문문 조동사)", "do"], "mr": ["명사", "~씨(남성)"], "varland": ["고유명사", "발랜드(성)"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "mean": ["동사", "의미하다"], "when": ["접속사", "~할 때"], "he": ["대명사", "그"], "writes": ["동사", "쓰다", "write"], "i'm": ["대명사", "나는 ~이다(I am)"], "bringing": ["현재분사", "(bring up) 화면에 띄우는", "bring"], "it": ["대명사", "그것"], "up": ["부사", "(bring up) 불러내어"], "now": ["부사", "지금"]}}], "g": {"roger": ["고유명사", "로저(이름)"], "varland": ["고유명사", "발랜드(성)"], "12:21": ["숫자", "12시 21분"], "p.m": ["명사", "오후"], "hello": ["감탄사", "안녕하세요"], "this": ["한정사", "이"], "is": ["동사", "~이다", "be"], "kolpin": ["고유명사", "콜핀(상호)"], "art": ["명사", "미술"], "supply's": ["명사", "용품점의", "supply"], "24-hour": ["형용사", "24시간의"], "customer-support": ["명사", "고객 지원"], "chat": ["명사", "채팅"], "my": ["한정사", "나의"], "name": ["명사", "이름"], "how": ["부사", "어떻게"], "can": ["조동사", "~할 수 있다"], "i": ["대명사", "나"], "help": ["동사", "돕다"], "you": ["대명사", "당신"], "shaina": ["고유명사", "샤이나(이름)"], "orbes": ["고유명사", "오브스(성)"], "12:22": ["숫자", "12시 22분"], "have": ["동사", "가지다"], "been": ["과거분사", "~였던", "be"], "waiting": ["현재분사", "기다리는", "wait"], "for": ["전치사", "~을 위해, ~동안"], "four": ["숫자", "넷"], "items": ["명사", "물품", "item"], "ordered": ["동사", "주문했다", "order"], "online": ["부사", "온라인으로"], "and": ["접속사", "그리고"], "now": ["부사", "지금"], "see": ["동사", "알다"], "that": ["접속사", "~라는 것"], "the": ["관사", "그"], "order": ["명사", "주문"], "was": ["동사", "~였다", "be"], "canceled": ["과거분사", "취소된", "cancel"], "often": ["부사", "자주"], "from": ["전치사", "~로부터"], "i've": ["대명사", "나는 ~해 왔다(I have)"], "never": ["부사", "결코 ~않다"], "had": ["동사", "(과거완료) ~했었다", "have"], "a": ["관사", "하나의"], "problem": ["명사", "문제"], "before": ["부사", "전에"], "check": ["동사", "확인하다"], "account": ["명사", "계정"], "12:24": ["숫자", "12시 24분"], "i'm": ["대명사", "나는 ~이다(I am)"], "bringing": ["현재분사", "(bring up) 화면에 띄우는", "bring"], "it": ["대명사", "그것"], "up": ["부사", "(bring up) 불러내어"], "states": ["동사", "명시하다", "state"], "here": ["부사", "여기에"], "credit": ["명사", "신용"], "card": ["명사", "카드"], "on": ["전치사", "~에, ~위에"], "file": ["명사", "(on file) 기록"], "with": ["전치사", "~와 함께, ~으로"], "us": ["대명사", "우리를"], "has": ["동사", "(현재완료) ~했다", "have"], "expired": ["과거분사", "만료된", "expire"], "so": ["접속사", "그래서"], "we": ["대명사", "우리"], "could": ["조동사", "~할 수 있었다"], "not": ["부사", "~아니다"], "process": ["동사", "처리하다"], "payment": ["명사", "결제"], "if": ["접속사", "만약 ~라면"], "log": ["동사", "(log in) 로그인하다"], "in": ["전치사", "~에, ~안에"], "to": ["전치사", "~에게, ~로"], "your": ["한정사", "당신의"], "customer": ["명사", "고객"], "update": ["동사", "업데이트하다"], "information": ["명사", "정보"], "then": ["부사", "그런 다음"], "click": ["동사", "클릭하다"], "number": ["명사", "번호"], "system": ["명사", "시스템"], "will": ["조동사", "~할 것이다"], "let": ["동사", "~하게 하다"], "place": ["동사", "(주문을) 하다"], "again": ["부사", "다시"], "12:26": ["숫자", "12시 26분"], "i'll": ["대명사", "나는 ~할 것이다(I will)"], "do": ["동사", "하다"], "thanks": ["명사", "감사"]}}, {"range": "147-148", "sub": "기출독해 2문항 8회", "passage": "HELP WANTED!\nVolunteers are needed for the annual Greenville Library Book Sale. Help us make room for new books! We need workers for the following tasks:\n· Setup (pricing and arranging books for display); June 2-3\n· Sales (greeting customers and answering questions); June 4-6\n· End-of-day cleanup (reorganizing books); June 4-6\n· Teardown (removing and storing display materials); June 6-7\nVisit greenvillelibrary.com to register. Questions about the event can be e-mailed to booksale@greenvillelibrary.com.", "tr": "도움 구함! Greenville 도서관 연례 도서 판매에 자원봉사자가 필요합니다. 새 책을 위한 공간을 만드는 일을 도와주세요! 다음 업무에 일손이 필요합니다: · 준비(가격 책정 및 진열용 책 배치); 6월 2~3일 · 판매(고객 맞이 및 질문 응대); 6월 4~6일 · 마감 정리(책 재정리); 6월 4~6일 · 철거(진열 자재 제거 및 보관); 6월 6~7일\n등록하려면 greenvillelibrary.com을 방문하세요. 행사 관련 질문은 booksale@greenvillelibrary.com으로 이메일 보내 주세요.", "vocab": "volunteer 명 자원봉사자 / make room for 구 ~을 위한 공간을 만들다 / task 명 업무 / setup 명 준비, 설치 / arrange 동 배치하다 / teardown 명 철거 / register 동 등록하다 / donor 명 기부자", "questions": [{"no": 147, "q": "What are volunteers NOT asked to do?", "options": ["Collect books from donors", "Set up displays", "Answer customer questions", "Sign up online"], "answer": 0, "explain": "정답 (A) Collect books from donors\n해석: 자원봉사자에게 요청되지 않은 일은?\n정답 근거: 업무 목록(준비·판매·정리·철거)에 기부자에게서 책을 수거하는 일은 없음. 진열 준비(B), 질문 응대(C), 온라인 등록(D)은 모두 언급됨.\n오답 분석: (B) 준비 업무에 진열용 책 배치가 포함됨. / (C) 판매 업무에 질문 응대가 포함됨. / (D) 웹사이트에서 등록하라고 안내함.\n지문 개요: Greenville 도서관 연례 도서 판매 행사의 자원봉사자를 모집하며, 준비(6월 2~3일), 판매(6월 4~6일), 마감 정리(6월 4~6일), 철거 (6월 6~7일) 업무를 안내하고 웹사이트 등록과 이메일 문의를 안내하는 광고.", "vocab": "Paraphrase: Visit greenvillelibrary.com to register → sign up online", "g": {"what": ["대명사", "무엇"], "are": ["동사", "~이다", "be"], "volunteers": ["명사", "자원봉사자", "volunteer"], "not": ["부사", "~아니다"], "asked": ["과거분사", "요청받은", "ask"], "to": ["to부정사", "~하기 위해"], "do": ["동사", "하다"]}}, {"no": 148, "q": "What most likely is the final date of the sale?", "options": ["June 3", "June 4", "June 6", "June 7"], "answer": 2, "explain": "정답 (C) June 6\n해석: 판매 마지막 날은 언제일 것 같은가?\n정답 근거: 판매(Sales) 업무가 6월 4~6일이고 철거가 6월 6~7일에 시작되므로 판매 마지막 날은 6월 6일.\n오답 분석: (A) 6월 3일은 준비 기간. / (B) 6월 4일은 판매 첫날. / (D) 6월 7일은 철거 마지막 날.", "vocab": "Paraphrase: Sales ... June 4-6 → June 6", "g": {"what": ["대명사", "무엇"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "final": ["형용사", "마지막의"], "date": ["명사", "날짜"], "of": ["전치사", "~의"], "sale": ["명사", "판매"]}}], "g": {"help": ["명사", "도움"], "wanted": ["과거분사", "구함", "want"], "volunteers": ["명사", "자원봉사자", "volunteer"], "are": ["동사", "~이다", "be"], "needed": ["과거분사", "필요한", "need"], "for": ["전치사", "~을 위해, ~동안"], "the": ["관사", "그"], "annual": ["형용사", "연례의"], "greenville": ["고유명사", "그린빌(지명)"], "library": ["명사", "도서관"], "book": ["명사", "책"], "sale": ["명사", "판매"], "us": ["대명사", "우리를"], "make": ["동사", "만들다"], "room": ["명사", "공간"], "new": ["형용사", "새로운"], "books": ["명사", "책", "book"], "we": ["대명사", "우리"], "need": ["동사", "필요로 하다"], "workers": ["명사", "일손", "worker"], "following": ["형용사", "다음의"], "tasks": ["명사", "업무", "task"], "setup": ["명사", "준비, 설치"], "pricing": ["동명사", "가격 매기기", "price"], "and": ["접속사", "그리고"], "arranging": ["동명사", "배치하기", "arrange"], "display": ["명사", "진열"], "june": ["명사", "6월"], "2-3": ["숫자", "2~3일"], "sales": ["명사", "판매"], "greeting": ["동명사", "맞이하기", "greet"], "customers": ["명사", "고객", "customer"], "answering": ["동명사", "답하기", "answer"], "questions": ["명사", "질문", "question"], "4-6": ["숫자", "4~6일"], "end-of-day": ["형용사", "하루 마감의"], "cleanup": ["명사", "정리"], "reorganizing": ["동명사", "재정리하기", "reorganize"], "teardown": ["명사", "철거"], "removing": ["동명사", "제거하기", "remove"], "storing": ["동명사", "보관하기", "store"], "materials": ["명사", "자재", "material"], "6-7": ["숫자", "6~7일"], "visit": ["동사", "방문하다"], "greenvillelibrary.com": ["고유명사", "웹사이트 주소"], "to": ["to부정사", "~하기 위해"], "register": ["동사", "등록하다"], "about": ["전치사", "~에 대해"], "event": ["명사", "행사"], "can": ["조동사", "~할 수 있다"], "be": ["동사", "~이다, 되다"], "e-mailed": ["과거분사", "이메일로 보내진", "e-mail"], "booksale@greenvillelibrary.com": ["고유명사", "이메일 주소"]}}, {"range": "149-150", "sub": "기출독해 2문항 8회", "passage": "Esmeralda Quinones (8:37 A.M.)\nHi Ying. There is a problem with the trains, so I'm going to walk to the office. I probably won't get there until 9:15.\nYing Han (8:38 A.M.)\nOk, do you want us to postpone the personnel meeting until you get here?\nEsmeralda Quinones (8:39 A.M.)\nNo, go ahead and start on time. Could you run the meeting until I get there?\nYing Han (8:39 A.M.)\nSure. I'll start with announcements, even though they're last on the agenda. Is that OK?\nEsmeralda Quinones (8:40 A.M.)\nThat's fine. I can take over when I get there to lead the policy discussion.", "tr": "Esmeralda Quinones (오전 8:37) 안녕하세요 Ying. 기차에 문제가 있어서 사무실까지 걸어갈 거예요. 아마 9시 15분은 되어야 도착할 것 같아요.\nYing Han (오전 8:38) 알겠어요, 도착할 때까지 인사 회의를 미룰까요?\nEsmeralda Quinones (오전 8:39) 아니요, 정시에 시작하세요. 제가 갈 때까지 회의를 진행해 주시겠어요?\nYing Han (오전 8:39) 물론이죠. 안건에서 마지막 순서이긴 하지만 공지 사항부터 시작할게요. 괜찮을까요?\nEsmeralda Quinones (오전 8:40) 괜찮아요. 제가 도착하면 이어받아서 정책 논의를 진행할게요.", "vocab": "postpone 동 연기하다 / personnel 명 인사 / on time 구 제시간에 / run a meeting 구 회의를 진행하다 / announcement 명 공지 / agenda 명 안건 / take over 구 인계받다 / policy 명 정책", "questions": [{"no": 149, "q": "What was Ms. Quinones originally planning to do?", "options": ["Take a train to work", "Work at home", "Postpone a trip", "Visit the personnel office"], "answer": 0, "explain": "정답 (A) Take a train to work\n해석: Quinones 씨는 원래 무엇을 하려고 계획했는가?\n정답 근거: \"기차에 문제가 있어서 걸어갈 것\" → 원래는 기차로 출근할 계획이었음.\n오답 분석: (B) 재택근무 언급 없음. / (C) 출장 연기 아님. / (D) 인사 사무실 방문이 아니라 인사 회의 참석.\n지문 개요: Esmeralda Quinones가 기차 문제로 걸어서 9시 15분에 도착할 예정이라 Ying Han에게 인사 회의를 정시에 시작해 진행해 달라고 부탁하고, Han이 안건 순서를 바꿔 공지 사항부터 시작하겠다고 하자 동의하는 대화.", "vocab": "Paraphrase: There is a problem with the trains, so I'm going to walk → take a train to work", "g": {"what": ["대명사", "무엇"], "was": ["동사", "~였다", "be"], "ms": ["명사", "~씨(여성)"], "quinones": ["고유명사", "키뇨네스(성)"], "originally": ["부사", "원래"], "planning": ["현재분사", "계획하는", "plan"], "to": ["to부정사", "~하는 것"], "do": ["동사", "하다"]}}, {"no": 150, "q": "At 8:40 A.M., what does Ms. Quinones most likely mean when she writes, \"That's fine\"?", "options": ["The agenda order can be changed.", "The new policy is acceptable.", "The meeting can be moved to the next day.", "The announcements can be skipped."], "answer": 0, "explain": "정답 (A) The agenda order can be changed.\n해석: 오전 8시 40분에 Quinones 씨가 \"That's fine\"이라고 쓴 의도는?\n정답 근거: \"안건 마지막 순서인 공지 사항부터 시작해도 괜찮을까요?\"라는 질문에 대한 답 → 안건 순서를 바꿔도 됨.\n오답 분석: (B) 새 정책 수용 여부가 아니라 순서 변경에 대한 동의. / (C) 회의를 다음 날로 옮기는 것이 아니라 정시 시작. / (D) 공지 사항을 건너뛰는 것이 아니라 먼저 다룸.", "vocab": "Paraphrase: start with announcements, even though they're last on the agenda → the agenda order can be changed", "g": {"at": ["전치사", "~에, ~에서"], "8:40": ["숫자", "8시 40분"], "a.m": ["명사", "오전"], "what": ["대명사", "무엇"], "does": ["조동사", "(의문문 조동사)", "do"], "ms": ["명사", "~씨(여성)"], "quinones": ["고유명사", "키뇨네스(성)"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "mean": ["동사", "의미하다"], "when": ["접속사", "~할 때"], "she": ["대명사", "그녀"], "writes": ["동사", "쓰다", "write"], "that's": ["대명사", "그것은 ~이다(that is)"], "fine": ["형용사", "괜찮은"]}}], "g": {"esmeralda": ["고유명사", "에스메랄다(이름)"], "quinones": ["고유명사", "키뇨네스(성)"], "8:37": ["숫자", "8시 37분"], "a.m": ["명사", "오전"], "hi": ["감탄사", "안녕"], "ying": ["고유명사", "잉(이름)"], "there": ["부사", "거기에"], "is": ["동사", "~이다", "be"], "a": ["관사", "하나의"], "problem": ["명사", "문제"], "with": ["전치사", "~와 함께, ~으로"], "the": ["관사", "그"], "trains": ["명사", "기차", "train"], "so": ["접속사", "그래서"], "i'm": ["대명사", "나는 ~이다(I am)"], "going": ["현재분사", "(be going to) ~할 것이다", "go"], "to": ["to부정사", "~하는 것"], "walk": ["동사", "걷다"], "office": ["명사", "사무실"], "i": ["대명사", "나"], "probably": ["부사", "아마"], "won't": ["조동사", "~하지 않을 것이다(will not)"], "get": ["동사", "도착하다"], "until": ["전치사", "~까지"], "9:15": ["숫자", "9시 15분"], "han": ["고유명사", "한(성)"], "8:38": ["숫자", "8시 38분"], "ok": ["감탄사", "좋아요"], "do": ["동사", "하다"], "you": ["대명사", "당신"], "want": ["동사", "원하다"], "us": ["대명사", "우리를"], "postpone": ["동사", "연기하다"], "personnel": ["명사", "인사"], "meeting": ["명사", "회의"], "here": ["부사", "여기에"], "8:39": ["숫자", "8시 39분"], "no": ["한정사", "어떤 ~도 없는"], "go": ["동사", "(go ahead) 진행하다"], "ahead": ["부사", "앞으로, 어서"], "and": ["접속사", "그리고"], "start": ["동사", "시작하다"], "on": ["전치사", "~에, ~위에"], "time": ["명사", "(on time) 제시간"], "could": ["조동사", "~할 수 있었다"], "run": ["동사", "진행하다"], "sure": ["감탄사", "물론이죠"], "i'll": ["대명사", "나는 ~할 것이다(I will)"], "announcements": ["명사", "공지 사항", "announcement"], "even": ["부사", "~조차"], "though": ["접속사", "(even though) 비록 ~지만"], "they're": ["대명사", "그것들은 ~이다(they are)"], "last": ["형용사", "마지막의"], "agenda": ["명사", "안건"], "that": ["대명사", "그것"], "8:40": ["숫자", "8시 40분"], "that's": ["대명사", "그것은 ~이다(that is)"], "fine": ["형용사", "괜찮은"], "can": ["조동사", "~할 수 있다"], "take": ["동사", "(take over) 인계받다"], "over": ["부사", "(take over) 넘겨받아"], "when": ["접속사", "~할 때"], "lead": ["동사", "이끌다"], "policy": ["명사", "정책"], "discussion": ["명사", "논의"]}}, {"range": "151-152", "sub": "기출독해 2문항 8회", "passage": "To: Grace Tembo <gtembo@kubalelebistro.co.za>\nFrom: Victor Aluko <victor.aluko@paliproperties.co.za>\nSubject: Commercial properties\nDate: 7 April\nDear Ms. Tembo,\nI am writing you regarding your inquiry about commercial space in our Bronkhorst St. property in Pretoria. Currently, there are two units available.\nThe first one is on the second floor of the building. It has 275 square meters of space but no food preparation area, as the previous business there was a clothing retailer.\nThe second unit is 153 square meters in size and on the ground floor of the building. It previously housed a coffee shop. There are already hookups for plumbing and gas. However, in light of the full-scale commercial kitchen you would like your restaurant to have, further equipment upgrades would be necessary.\nLet me know your preference, if any, and we can arrange a viewing of the property at your convenience.\nThank you,\nVictor Aluko, Sales Specialist\nPali Properties, LLC\nPretoria", "tr": "수신: Grace Tembo / 발신: Victor Aluko / 제목: 상업용 부동산 / 날짜: 4월 7일\nTembo 씨께, Pretoria의 Bronkhorst St. 건물 상업 공간에 관한 문의와 관련해 연락드립니다. 현재 두 개의 공간이 있습니다. 첫 번째는 건물 2층입니다. 275제곱미터이지만 이전 업체가 의류 소매점이어서 음식 조리 공간이 없습니다. 두 번째 공간은 153제곱미터로 건물 1층에 있습니다. 이전에는 커피숍이 있었습니다. 배관과 가스 연결이 이미 되어 있습니다. 다만 귀하의 식당에 갖추고자 하시는 본격적인 상업용 주방을 고려하면 추가 설비 업그레이드가 필요할 것입니다. 선호하시는 곳이 있으면 알려 주시면 편하신 때에 건물 견학을 잡아 드리겠습니다. 감사합니다, Victor Aluko, 영업 전문가, Pali Properties, LLC Pretoria", "vocab": "inquiry 명 문의 / commercial space 명 상업 공간 / unit 명 (건물의) 호 / previous 형 이전의 / retailer 명 소매업체 / house 동 수용하다 / hookup 명 연결 장치 / in light of 구 ~을 고려하여 / viewing 명 둘러보기", "questions": [{"no": 151, "q": "What is the purpose of the e-mail?", "options": ["To advertise a new business", "To confirm the purchase of equipment", "To explain a service available to building tenants", "To respond to an inquiry about rental space"], "answer": 3, "explain": "정답 (D) To respond to an inquiry about rental space\n해석: 이메일의 목적은?\n정답 근거: \"상업 공간에 관한 문의와 관련해 연락\" + 두 공간의 조건 안내 → 임대 공간 문의에 대한 답변.\n오답 분석: (A) 새 사업 광고 아님. / (B) 설비 구매 확인 아님. / (C) 세입자 대상 서비스 설명 아님.\n지문 개요: Pali Properties의 Victor Aluko가 Grace Tembo의 Bronkhorst St. 상업 공간 문의에 답해, 2층 275㎡(조리 공간 없음, 이전 의류점)와 1층 153㎡(이전 커피숍, 배관·가스 연결 있음)의 두 공간을 소개하며 식당용 주방에는 추가 설비가 필요하다고 안내하는 이메일.", "vocab": "Paraphrase: regarding your inquiry about commercial space → respond to an inquiry about rental space", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "purpose": ["명사", "목적"], "of": ["전치사", "~의"], "e-mail": ["명사", "이메일"]}}, {"no": 152, "q": "What kind of business does Ms. Tembo most likely own?", "options": ["A restaurant", "A real estate agency", "A coffee shop", "A clothing store"], "answer": 0, "explain": "정답 (A) A restaurant\n해석: Tembo 씨는 어떤 사업체를 소유하고 있을 것 같은가?\n정답 근거: \"귀하의 식당(your restaurant)에 갖추고자 하는 본격적인 상업용 주방\" → 식당. 이메일 주소도 bistro.\n오답 분석: (B) 부동산 중개는 Aluko 쪽. / (C) 커피숍은 이전 입주 업체. / (D) 의류점은 2층 이전 업체.", "vocab": "Paraphrase: the full-scale commercial kitchen you would like your restaurant to have → a restaurant", "g": {"what": ["대명사", "무엇"], "kind": ["명사", "종류"], "of": ["전치사", "~의"], "business": ["명사", "업체"], "does": ["조동사", "(의문문 조동사)", "do"], "ms": ["명사", "~씨(여성)"], "tembo": ["고유명사", "템보(성)"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "own": ["형용사", "자신의"]}}], "g": {"to": ["전치사", "받는 사람"], "grace": ["고유명사", "그레이스(이름)"], "tembo": ["고유명사", "템보(성)"], "gtembo@kubalelebistro.co.za": ["고유명사", "이메일 주소"], "from": ["전치사", "~로부터"], "victor": ["고유명사", "빅터(이름)"], "aluko": ["고유명사", "알루코(성)"], "victor.aluko@paliproperties.co.za": ["고유명사", "이메일 주소"], "subject": ["명사", "제목"], "commercial": ["형용사", "상업용의"], "properties": ["명사", "부동산", "property"], "date": ["명사", "날짜"], "7": ["숫자", "7"], "april": ["명사", "4월"], "dear": ["형용사", "친애하는"], "ms": ["명사", "~씨(여성)"], "i": ["대명사", "나"], "am": ["동사", "~이다", "be"], "writing": ["현재분사", "쓰는", "write"], "you": ["대명사", "당신"], "regarding": ["전치사", "~에 관하여"], "your": ["한정사", "당신의"], "inquiry": ["명사", "문의"], "about": ["전치사", "~에 대해"], "space": ["명사", "공간"], "in": ["전치사", "~에, ~안에"], "our": ["한정사", "우리의"], "bronkhorst": ["고유명사", "브롱크호르스트(지명)"], "st": ["명사", "거리(Street)"], "property": ["명사", "건물, 부동산"], "pretoria": ["고유명사", "프리토리아(도시)"], "currently": ["부사", "현재"], "there": ["부사", "거기에"], "are": ["동사", "~이다", "be"], "two": ["숫자", "둘"], "units": ["명사", "(건물의) 호, 공간", "unit"], "available": ["형용사", "이용 가능한"], "the": ["관사", "그"], "first": ["형용사", "첫 번째의"], "one": ["숫자", "하나"], "is": ["동사", "~이다", "be"], "on": ["전치사", "~에, ~위에"], "second": ["형용사", "두 번째의"], "floor": ["명사", "층"], "of": ["전치사", "~의"], "building": ["명사", "건물"], "it": ["대명사", "그것"], "has": ["동사", "(현재완료) ~했다", "have"], "275": ["숫자", "275"], "square": ["형용사", "제곱의"], "meters": ["명사", "미터", "meter"], "but": ["접속사", "그러나"], "no": ["한정사", "어떤 ~도 없는"], "food": ["명사", "음식"], "preparation": ["명사", "준비, 조리"], "area": ["명사", "구역"], "as": ["접속사", "~처럼, ~때문에"], "previous": ["형용사", "이전의"], "business": ["명사", "업체"], "was": ["동사", "~였다", "be"], "a": ["관사", "하나의"], "clothing": ["명사", "의류"], "retailer": ["명사", "소매업체"], "unit": ["명사", "(건물의) 호, 공간"], "153": ["숫자", "153"], "size": ["명사", "크기"], "and": ["접속사", "그리고"], "ground": ["명사", "(ground floor) 1층"], "previously": ["부사", "이전에"], "housed": ["동사", "수용했다, 들어 있었다", "house"], "coffee": ["명사", "커피"], "shop": ["명사", "가게"], "already": ["부사", "이미"], "hookups": ["명사", "연결 장치", "hookup"], "for": ["전치사", "~을 위해, ~동안"], "plumbing": ["명사", "배관"], "gas": ["명사", "가스"], "however": ["부사", "그러나"], "light": ["명사", "(in light of) ~을 고려하여"], "full-scale": ["형용사", "본격적인"], "kitchen": ["명사", "주방"], "would": ["조동사", "~할 것이다"], "like": ["동사", "원하다"], "restaurant": ["명사", "식당"], "have": ["동사", "가지다"], "further": ["형용사", "추가의"], "equipment": ["명사", "설비"], "upgrades": ["명사", "개선", "upgrade"], "be": ["동사", "~이다, 되다"], "necessary": ["형용사", "필요한"], "let": ["동사", "~하게 하다"], "me": ["대명사", "나를"], "know": ["동사", "알다"], "preference": ["명사", "선호"], "if": ["접속사", "만약 ~라면"], "any": ["한정사", "어떤"], "we": ["대명사", "우리"], "can": ["조동사", "~할 수 있다"], "arrange": ["동사", "마련하다"], "viewing": ["명사", "둘러보기"], "at": ["전치사", "~에, ~에서"], "convenience": ["명사", "편의"], "thank": ["동사", "감사하다"], "sales": ["명사", "영업"], "specialist": ["명사", "전문가"], "pali": ["고유명사", "팔리(회사명)"], "llc": ["명사", "유한책임회사"]}}, {"range": "156-157", "sub": "기출독해 2문항 8회", "passage": "Welcome to the fifth annual International Conference of Professional Food Scientists! The Luxor Food Technology Corporation is proud to sponsor this important event.\nOn day one of the conference, you are invited to attend the Advancements in Food Technology consortium at 10 A.M. - Noon and 2 P.M. - 5 P.M. in the main auditorium. On day two, you are invited to attend two of the four seminars below. Please sign up for them in the main lobby on the day of your arrival.\n8 A.M.―Noon\nRoom 107\nFood Processing\nMalcom Revere, Hasward University, Toronto, Canada\n8 A.M.―Noon\nRoom 119\nTasty Food and Drink\nAhmad Malkawi, University of the Food Sciences, Amman, Jordan\n2 P.M.―5 P.M.\nRoom 210\nMicrobiology of Food\nSiqi Peng, Wiangyi Agricultural University, Xiangyi, China\n2 P.M.―5 P.M.\nRoom 213\nColours and Stabilisers\nElina Ojala, University of Espoo, Espoo, Finland\nThank you. We hope you enjoy the conference.", "tr": "제5회 연례 국제 전문 식품 과학자 컨퍼런스에 오신 것을 환영합니다! Luxor Food Technology Corporation은 이 중요한 행사를 후원하게 되어 자랑스럽습니다. 컨퍼런스 첫날에는 본 강당에서 오전 10시~정오, 오후 2~5시에 열리는 식품 기술 발전 컨소시엄에 참석하시기 바랍니다. 둘째 날에는 아래 네 개 세미나 중 두 개에 참석하실 수 있습니다. 도착 당일 본관 로비에서 신청해 주십시오.\n오전 8시~정오 / 107호 / 식품 가공 / Malcom Revere, Hasward University, 토론토, 캐나다\n오전 8시~정오 / 119호 / 맛있는 식음료 / Ahmad Malkawi, University of the Food Sciences, 암만, 요르단\n오후 2~5시 / 210호 / 식품 미생물학 / Siqi Peng, Wiangyi Agricultural University, Xiangyi, 중국\n오후 2~5시 / 213호 / 색소와 안정제 / Elina Ojala, University of Espoo, 에스포, 핀란드\n감사합니다. 즐거운 컨퍼런스 되시기 바랍니다.", "vocab": "annual 형 연례의 / sponsor 동 후원하다 / advancement 명 발전 / consortium 명 협의회 / auditorium 명 강당 / sign up for 구 ~에 등록하다 / arrival 명 도착 / microbiology 명 미생물학", "questions": [{"no": 156, "q": "What is NOT mentioned about the conference?", "options": ["It is a yearly event.", "It is being held in Canada.", "It lasts more than one day.", "It is sponsored by a company."], "answer": 1, "explain": "정답 (B) It is being held in Canada.\n해석: 컨퍼런스에 대해 언급되지 않은 것은?\n정답 근거: 캐나다는 발표자 Revere의 소속 대학 소재지일 뿐 컨퍼런스 개최지는 언급되지 않음. 연례(fifth annual), 이틀 이상(day one, day two), 기업 후원(Luxor)은 모두 언급됨.\n오답 분석: (A) 제5회 연례 행사라고 명시됨. / (C) 첫날·둘째 날이 있어 하루 이상. / (D) Luxor Food Technology Corporation이 후원.\n지문 개요: Luxor Food Technology가 후원하는 제5회 국제 전문 식품 과학자 컨퍼런스 안내. 첫날 식품 기술 발전 컨소시엄, 둘째 날 4개 세미나(오전: 식품 가공·맛있는 식음료 / 오후: 식품 미생물학·색소와 안정제) 중 2개를 선택해 로비에서 신청하라는 내용.", "vocab": "Paraphrase: fifth annual / day one, day two / proud to sponsor → yearly, more than one day, sponsored by a company", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "not": ["부사", "~아니다"], "mentioned": ["과거분사", "언급된", "mention"], "about": ["전치사", "~에 대해"], "the": ["관사", "그"], "conference": ["명사", "회의, 컨퍼런스"]}}, {"no": 157, "q": "What is true about Ms. Peng?", "options": ["She will talk about tasty food and drink.", "She attended Hasward University.", "She will speak at an afternoon session.", "She will give a lecture in room 213."], "answer": 2, "explain": "정답 (C) She will speak at an afternoon session.\n해석: Peng 씨에 대해 사실인 것은?\n정답 근거: Siqi Peng의 세미나는 오후 2~5시, 210호 \"식품 미생물학\" → 오후 세션에서 발표.\n오답 분석: (A) 맛있는 식음료는 Malkawi의 세미나. / (B) Hasward University는 Revere의 소속. / (D) 213호는 Ojala의 세미나.", "vocab": "Paraphrase: 2 P.M.―5 P.M. Room 210 Siqi Peng → speak at an afternoon session", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "true": ["형용사", "사실인"], "about": ["전치사", "~에 대해"], "ms": ["명사", "~씨(여성)"], "peng": ["고유명사", "펑(성)"]}}], "g": {"welcome": ["감탄사", "환영합니다"], "to": ["to부정사", "~하게 되어"], "the": ["관사", "그"], "fifth": ["형용사", "다섯 번째의"], "annual": ["형용사", "연례의"], "international": ["형용사", "국제의"], "conference": ["명사", "회의, 컨퍼런스"], "of": ["전치사", "~의"], "professional": ["형용사", "전문적인"], "food": ["명사", "식품"], "scientists": ["명사", "과학자", "scientist"], "luxor": ["고유명사", "룩소르(회사명)"], "technology": ["명사", "기술"], "corporation": ["명사", "기업"], "is": ["동사", "~이다", "be"], "proud": ["형용사", "자랑스러운"], "sponsor": ["동사", "후원하다"], "this": ["한정사", "이"], "important": ["형용사", "중요한"], "event": ["명사", "행사"], "on": ["전치사", "~에, ~위에"], "day": ["명사", "날"], "one": ["숫자", "하나"], "you": ["대명사", "당신"], "are": ["동사", "~이다", "be"], "invited": ["과거분사", "초대받은", "invite"], "attend": ["동사", "참석하다"], "advancements": ["명사", "발전", "advancement"], "in": ["전치사", "~에, ~안에"], "consortium": ["명사", "협의회"], "at": ["전치사", "~에, ~에서"], "10": ["숫자", "10"], "a.m": ["명사", "오전"], "noon": ["명사", "정오"], "and": ["접속사", "그리고"], "2": ["숫자", "2"], "p.m": ["명사", "오후"], "5": ["숫자", "5"], "main": ["형용사", "주된"], "auditorium": ["명사", "강당"], "two": ["숫자", "둘"], "four": ["숫자", "넷"], "seminars": ["명사", "세미나", "seminar"], "below": ["부사", "아래에"], "please": ["부사", "부디, ~해 주세요"], "sign": ["동사", "(sign up) 신청하다"], "up": ["부사", "위로, 완전히"], "for": ["전치사", "~을 위해, ~동안"], "them": ["대명사", "그들을"], "lobby": ["명사", "로비"], "your": ["한정사", "당신의"], "arrival": ["명사", "도착"], "8": ["숫자", "8"], "a.m.―noon": ["명사", "오전~정오"], "room": ["명사", "~호실"], "107": ["숫자", "107"], "processing": ["명사", "가공"], "malcom": ["고유명사", "맬컴(이름)"], "revere": ["고유명사", "리비어(성)"], "hasward": ["고유명사", "해스워드(대학명)"], "university": ["명사", "대학교"], "toronto": ["고유명사", "토론토"], "canada": ["고유명사", "캐나다"], "119": ["숫자", "119"], "tasty": ["형용사", "맛있는"], "drink": ["명사", "음료"], "ahmad": ["고유명사", "아마드(이름)"], "malkawi": ["고유명사", "말카위(성)"], "sciences": ["명사", "과학", "science"], "amman": ["고유명사", "암만(요르단 수도)"], "jordan": ["고유명사", "요르단"], "p.m.―5": ["명사", "오후~5시"], "210": ["숫자", "210"], "microbiology": ["명사", "미생물학"], "siqi": ["고유명사", "쓰치(이름)"], "peng": ["고유명사", "펑(성)"], "wiangyi": ["고유명사", "위앙이(지명)"], "agricultural": ["형용사", "농업의"], "xiangyi": ["고유명사", "샹이(지명)"], "china": ["고유명사", "중국"], "213": ["숫자", "213"], "colours": ["명사", "색소", "colour"], "stabilisers": ["명사", "안정제", "stabiliser"], "elina": ["고유명사", "엘리나(이름)"], "ojala": ["고유명사", "오얄라(성)"], "espoo": ["고유명사", "에스포(핀란드 도시)"], "finland": ["고유명사", "핀란드"], "thank": ["동사", "감사하다"], "we": ["대명사", "우리"], "hope": ["동사", "바라다"], "enjoy": ["동사", "즐기다"]}}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a-r5-p6',$mkd${"id": "a-r5-p6", "area": "RC", "part": 6, "group": "A급 과제", "series": 3, "round": 5, "level": "중급", "title": "A급 과제 5회 · PART 6", "notes": [], "items": [], "sets": [{"range": "131-134", "passage": "HELSINKI (June 1)—Hoventia Corporation announced today the ---131--- anticipated release of its Littala Max signal booster for mobile phone users.\nWhen callers live or work in an area that is far from cell towers, they may experience gaps in coverage. The Littala Max works by ---132--- the radio signals that are sent between users' phones and cell towers. ---133---. The Littala Max also improves the mobile phone signal inside buildings constructed with reinforced concrete, sheet metal, or wire mesh. It is a well-established fact that these ---134--- can affect phone reception.\nFor further information about Hoventia Corporation and worldwide sales of the Littala Max, contact Mr. Matti Koskinen at mkoskinen@hoventia.fi.", "tr": "헬싱키(6월 1일) — Hoventia Corporation은 오늘 휴대전화 사용자를 위한 Littala Max 신호 증폭기의 크게(131) 기대되던 출시를 발표했다. 통화자가 기지국에서 먼 지역에 살거나 일하면 통화권 공백을 겪을 수 있다. Littala Max는 사용자 전화기와 기지국 사이에 오가는 무선 신호를 증폭함(132)으로써 작동한다. 이 기능은 예기치 않게 끊기는 통화가 줄어들도록 보장한다(133). Littala Max는 철근 콘크리트, 금속판, 철망으로 지어진 건물 내부의 휴대전화 신호도 개선한다. 이러한 자재(134)가 전화 수신에 영향을 줄 수 있다는 것은 잘 알려진 사실이다. Hoventia Corporation과 Littala Max의 전 세계 판매에 관한 추가 정보는 Matti Koskinen(mkoskinen@hoventia.fi)에게 문의하십시오.", "vocab": "press release 명 보도 자료 / anticipated 형 기대되는 / release 명 출시 / coverage 명 통신 범위 / amplify 동 증폭하다 / reinforced concrete 명 철근 콘크리트 / well-established 형 확립된 / material 명 재료 / reception 명 수신", "questions": [{"no": 131, "q": "", "options": ["great", "greatness", "greatly", "greater"], "answer": 2, "explain": "정답 (C) greatly\n해석: 크게 기대되던 Littala Max 신호 증폭기의 출시\n정답 근거: 「the + 빈칸 + anticipated + 명사 release」 — 명사를 꾸미는 분사형용사 anticipated를 수식하는 자리 → 부사 greatly.\n오답 분석: (A) great: 형용사 — 형용사 anticipated를 꾸밀 수 없음. / (B) greatness: 명사 — 불가. / (D) greater: 형용사 비교급 — 불가.\n지문 개요: Hoventia Corporation이 기지국에서 먼 지역의 통화 끊김을 줄이고 철근 콘크리트·금속판 건물 내부 수신도 개선하는 Littala Max 휴대전화 신호 증폭기 출시를 발표한 보도자료."}, {"no": 132, "q": "", "options": ["amplified", "amplifying", "to amplify", "have amplified"], "answer": 1, "explain": "정답 (B) amplifying\n해석: 무선 신호를 증폭함으로써 작동한다.\n정답 근거: 「전치사 by + 빈칸 + 명사 the radio signals」 → 전치사 뒤 동명사 자리. 타동사 amplify 뒤 목적어가 있으므로 능동 -ing → amplifying.\n오답 분석: (A) amplified: 과거분사 — 전치사 뒤 불가. / (C) to amplify: to부정사 — 전치사 뒤 불가. / (D) have amplified: 동사 — 전치사 뒤 불가."}, {"no": 133, "q": "", "options": ["This feature ensures that fewer calls are unexpectedly cut off.", "This problem has increased calls for greater investments.", "This measure lowers the costs of mobile phones.", "Mobile phone users prefer texting over talking."], "answer": 0, "explain": "정답 (A) This feature ensures that fewer calls are unexpectedly cut off.\n해석: 이 기능은 예기치 않게 끊기는 통화가 줄어들도록 보장한다.\n정답 근거: 앞에서 통화권 공백 문제와 신호 증폭 원리를 설명했으므로 그 기능(This feature)의 효과, 즉 통화 끊김 감소가 이어지는 것이 자연스러움.\n오답 분석: (B) 문제가 투자 요구를 늘렸다는 내용은 제품 효과 설명과 무관. / (C) 전화기 가격 인하는 무관. / (D) 문자 선호는 무관."}, {"no": 134, "q": "", "options": ["systems", "patterns", "windows", "materials"], "answer": 3, "explain": "정답 (D) materials\n해석: 이러한 자재가 전화 수신에 영향을 줄 수 있다.\n정답 근거: 앞 문장의 철근 콘크리트, 금속판, 철망을 가리키는 말 → materials(자재).\n오답 분석: (A) systems: '시스템' — 건축 자재를 가리키지 않음. / (B) patterns: '패턴' — 불가. / (C) windows: '창문' — 불가."}], "g": {"helsinki": ["고유명사", "헬싱키"], "june": ["명사", "6월"], "1)—hoventia": ["고유명사", "1일)—호벤티아(회사명)"], "corporation": ["명사", "기업"], "announced": ["동사", "발표했다", "announce"], "today": ["부사", "오늘"], "the": ["관사", "그"], "anticipated": ["과거분사", "기대되는", "anticipate"], "release": ["명사", "출시"], "of": ["전치사", "~의"], "its": ["한정사", "그것의"], "littala": ["고유명사", "리탈라(제품명)"], "max": ["고유명사", "맥스(제품명)"], "signal": ["명사", "신호"], "booster": ["명사", "증폭기"], "for": ["전치사", "~을 위해, ~동안"], "mobile": ["형용사", "휴대용의"], "phone": ["명사", "전화"], "users": ["명사", "사용자", "user"], "when": ["접속사", "~할 때"], "callers": ["명사", "통화자", "caller"], "live": ["동사", "살다"], "or": ["접속사", "또는"], "work": ["동사", "일하다"], "in": ["전치사", "~에, ~안에"], "an": ["관사", "하나의"], "area": ["명사", "지역"], "that": ["관계사", "~하는"], "is": ["동사", "~이다", "be"], "far": ["형용사", "먼"], "from": ["전치사", "~로부터"], "cell": ["명사", "휴대전화(cell)"], "towers": ["명사", "기지국, 탑", "tower"], "they": ["대명사", "그들"], "may": ["조동사", "~일지도 모른다"], "experience": ["동사", "겪다"], "gaps": ["명사", "공백", "gap"], "coverage": ["명사", "통화권, 수신 범위"], "works": ["동사", "작동하다", "work"], "by": ["전치사", "~에 의해, ~까지"], "radio": ["명사", "무선"], "signals": ["명사", "신호", "signal"], "are": ["동사", "~이다", "be"], "sent": ["과거분사", "보내진", "send"], "between": ["전치사", "~사이에"], "users'": ["명사", "사용자들의", "user"], "phones": ["명사", "전화기", "phone"], "and": ["접속사", "그리고"], "also": ["부사", "또한"], "improves": ["동사", "개선하다", "improve"], "inside": ["전치사", "~안에서"], "buildings": ["명사", "건물", "building"], "constructed": ["과거분사", "지어진", "construct"], "with": ["전치사", "~와 함께, ~으로"], "reinforced": ["과거분사", "강화된(철근)", "reinforce"], "concrete": ["명사", "콘크리트"], "sheet": ["명사", "판"], "metal": ["명사", "금속"], "wire": ["명사", "철사"], "mesh": ["명사", "망"], "it": ["대명사", "그것"], "a": ["관사", "하나의"], "well-established": ["형용사", "잘 확립된"], "fact": ["명사", "사실"], "these": ["한정사", "이들"], "can": ["조동사", "~할 수 있다"], "affect": ["동사", "영향을 미치다"], "reception": ["명사", "수신"], "further": ["형용사", "추가의"], "information": ["명사", "정보"], "about": ["전치사", "~에 대해"], "hoventia": ["고유명사", "호벤티아(회사명)"], "worldwide": ["형용사", "전 세계의"], "sales": ["명사", "판매"], "contact": ["동사", "연락하다"], "mr": ["명사", "~씨(남성)"], "matti": ["고유명사", "마티(이름)"], "koskinen": ["고유명사", "코스키넨(성)"], "at": ["전치사", "~에, ~에서"], "mkoskinen@hoventia.fi": ["고유명사", "이메일 주소"]}}, {"range": "135-138", "passage": "CHESTERFIELD (September 23)—About 100 years ago, a small sycamore tree was planted on Proper Street. Today, ---135--- can find what now is a 30-meter tree along the driveway that leads to the entrance of the Lowell Library. ---136---. How many years, ---137---, has the tree been around? That would be hard to tell, unless it were cut down and the rings in its exposed trunk counted.\n---138---, that is unlikely to happen as long as the tree is healthy. And since healthy sycamore trees usually have a life expectancy of about 200 years or more, there will be ample opportunity for those coming after us to revel in its beauty.", "tr": "CHESTERFIELD(9월 23일) — 약 100년 전 작은 플라타너스 한 그루가 Proper Street에 심어졌다. 오늘날 방문객(135)들은 Lowell 도서관 입구로 이어지는 진입로를 따라 지금은 30미터가 된 나무를 볼 수 있다. 아마도 이 나무는 마을에서 가장 오래된 플라타너스일 것이다(136). 그렇다면 정확히(137) 몇 년이나 이 나무가 있었을까? 나무를 베어 드러난 줄기의 나이테를 세지 않는 한 알기 어려울 것이다. 다행히(138), 나무가 건강한 한 그런 일은 일어날 것 같지 않다. 그리고 건강한 플라타너스는 보통 약 200년 이상의 수명을 가지므로, 우리 뒤에 올 사람들도 그 아름다움을 즐길 충분한 기회가 있을 것이다.", "vocab": "sycamore 명 플라타너스 / plant 동 심다 / driveway 명 진입로 / presumably 부 아마도 / exactly 부 정확히 / trunk 명 나무 줄기 / life expectancy 명 기대 수명 / ample 형 충분한 / revel in 구 ~을 만끽하다", "questions": [{"no": 135, "q": "", "options": ["visitors", "visit", "visiting", "visits"], "answer": 0, "explain": "정답 (A) visitors\n해석: 오늘날 방문객들은 30미터가 된 나무를 볼 수 있다.\n정답 근거: 문장의 주어 자리(조동사 can 앞)이며 나무를 \"보는\" 주체는 사람 → 명사 visitors.\n오답 분석: (B) visit: 동사 — 주어 자리 불가. / (C) visiting: 분사 — 불가. / (D) visits: '방문'(명사) — 사물이라 볼 수 없음.\n지문 개요: 약 100년 전 Proper Street에 심어진 플라타너스가 지금은 Lowell 도서관 진입로의 30m 나무가 되었으며, 정확한 나이는 베어 나이테를 세지 않으면 알기 어렵지만 건강한 한 그럴 일은 없고 200년 이상 살 수 있어 후손들도 즐길 수 있다는 기사."}, {"no": 136, "q": "", "options": ["Sycamore trees are found across the country.", "Presumably it is the oldest sycamore tree in town.", "Lowell Library was built more than 50 years ago.", "There are various other tree species along the driveway."], "answer": 1, "explain": "정답 (B) Presumably it is the oldest sycamore tree in town.\n해석: 아마도 이 나무는 마을에서 가장 오래된 플라타너스일 것이다.\n정답 근거: 뒤 문장 \"그렇다면 정확히 몇 년이나 있었을까?\"가 나무의 나이에 대한 추측을 받아 이어지므로 가장 오래된 나무라는 추정 문장이 적절.\n오답 분석: (A) 전국 분포는 이 나무의 나이 질문과 연결되지 않음. / (C) 도서관 건립 시기는 무관. / (D) 다른 수종 언급은 무관."}, {"no": 137, "q": "", "options": ["exacted", "exact", "exactly", "exactness"], "answer": 2, "explain": "정답 (C) exactly\n해석: 정확히 몇 년이나 이 나무가 있었을까?\n정답 근거: 의문문 How many years ~ 사이에 쉼표로 삽입된 자리 → 부사 exactly.\n오답 분석: (A) exacted: 과거분사 — 삽입 부사 자리 불가. / (B) exact: 형용사 — 불가. / (D) exactness: 명사 — 불가."}, {"no": 138, "q": "", "options": ["Similarly", "Accordingly", "Therefore", "Fortunately"], "answer": 3, "explain": "정답 (D) Fortunately\n해석: 다행히 나무가 건강한 한 그런 일은 일어날 것 같지 않다.\n정답 근거: 나무를 베어야 나이를 안다는 앞 문장에 이어, 그런 일(베는 것)이 일어나지 않을 것이라는 긍정적 내용 → Fortunately.\n오답 분석: (A) Similarly: '마찬가지로' — 유사 관계 아님. / (B) Accordingly: '따라서' — 인과 관계 아님. / (C) Therefore: '그러므로' — 인과 관계 아님."}], "g": {"chesterfield": ["고유명사", "체스터필드(지명)"], "september": ["명사", "9월"], "23)—about": ["숫자", "23일)—약"], "100": ["숫자", "100"], "years": ["명사", "년", "year"], "ago": ["부사", "~전에"], "a": ["관사", "하나의"], "small": ["형용사", "작은"], "sycamore": ["명사", "플라타너스"], "tree": ["명사", "나무"], "was": ["동사", "~였다", "be"], "planted": ["과거분사", "심어진", "plant"], "on": ["전치사", "~에, ~위에"], "proper": ["고유명사", "프로퍼(거리 이름)"], "street": ["명사", "거리"], "today": ["부사", "오늘"], "can": ["조동사", "~할 수 있다"], "find": ["동사", "발견하다"], "what": ["관계사", "~인 것"], "now": ["부사", "지금"], "is": ["동사", "~이다", "be"], "30-meter": ["형용사", "30미터의"], "along": ["전치사", "~을 따라"], "the": ["관사", "그"], "driveway": ["명사", "진입로"], "that": ["관계사", "~하는"], "leads": ["동사", "이어지다", "lead"], "to": ["전치사", "~에게, ~로"], "entrance": ["명사", "입구"], "of": ["전치사", "~의"], "lowell": ["고유명사", "로웰(도서관명)"], "library": ["명사", "도서관"], "how": ["부사", "어떻게"], "many": ["형용사", "많은"], "has": ["동사", "(현재완료) ~했다", "have"], "been": ["과거분사", "~였던", "be"], "around": ["부사", "존재하여(be around)"], "would": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "hard": ["형용사", "어려운"], "tell": ["동사", "알다, 판단하다"], "unless": ["접속사", "~하지 않으면"], "it": ["대명사", "그것"], "were": ["동사", "(가정법) ~라면", "be"], "cut": ["과거분사", "잘린(cut down)", "cut"], "down": ["부사", "아래로(베어 넘어뜨려)"], "and": ["접속사", "그리고"], "rings": ["명사", "나이테", "ring"], "in": ["전치사", "~에, ~안에"], "its": ["한정사", "그것의"], "exposed": ["과거분사", "드러난", "expose"], "trunk": ["명사", "줄기"], "counted": ["과거분사", "세어진", "count"], "unlikely": ["형용사", "~할 것 같지 않은"], "happen": ["동사", "일어나다"], "as": ["접속사", "~처럼, ~때문에"], "long": ["부사", "(as long as) ~하는 한"], "healthy": ["형용사", "건강한"], "since": ["접속사", "~이므로"], "trees": ["명사", "나무", "tree"], "usually": ["부사", "보통"], "have": ["동사", "가지다"], "life": ["명사", "수명"], "expectancy": ["명사", "기대(수명)"], "about": ["전치사", "~에 대해"], "200": ["숫자", "200"], "or": ["접속사", "또는"], "more": ["부사", "더"], "there": ["부사", "거기에"], "will": ["조동사", "~할 것이다"], "ample": ["형용사", "충분한"], "opportunity": ["명사", "기회"], "for": ["전치사", "~을 위해, ~동안"], "those": ["한정사", "그들, 저것들"], "coming": ["현재분사", "오는", "come"], "after": ["전치사", "~후에"], "us": ["대명사", "우리를"], "revel": ["동사", "한껏 즐기다"], "beauty": ["명사", "아름다움"]}}, {"range": "139-142", "passage": "From: msampson@bes.com.bz\nTo: allstaff@bes.com.bz\nDate: 20 April\nSubject: Wellness workshops\nDear Colleagues,\nBeginning on Thursday, 7 May, and every Thursday thereafter ---139--- 11 June, Belize Energy Services, in partnership with Corporate Health Interactive, will be offering a series of wellness workshops. These sessions will be held in Room 130 from 1:00 P.M. to 2:00 P.M. Seating is limited to 40 participants per workshop. ---140---.\nThe speaker for the first workshop will be Dr. Tracy Fonseca, a highly ---141--- nutritionist. Participants will learn how to improve the ---142--- of their food choices. Specifically, they will receive guidelines on how to create balanced and healthy meals with fresh ingredients.\nDetails on other workshops in the series are available at bes.com.bz/chiworkshops.\nSincerely,\nMark Sampson, Human Resources Director", "tr": "발신: msampson@bes.com.bz / 수신: allstaff@bes.com.bz / 날짜: 4월 20일 / 제목: 웰니스 워크숍\n동료 여러분께, 5월 7일 목요일부터 시작해 6월 11일까지(139) 이후 매주 목요일에 Belize Energy Services는 Corporate Health Interactive와 제휴하여 웰니스 워크숍 시리즈를 제공합니다. 이 세션은 130호에서 오후 1시부터 2시까지 열립니다. 좌석은 워크숍당 40명으로 제한됩니다. 따라서 사전 등록이 필요합니다(140). 첫 워크숍의 강연자는 매우 존경받는(141) 영양사 Tracy Fonseca 박사입니다. 참가자들은 음식 선택의 질(142)을 개선하는 방법을 배울 것입니다. 구체적으로 신선한 재료로 균형 잡힌 건강한 식사를 만드는 지침을 받게 됩니다. 시리즈의 다른 워크숍 세부 사항은 bes.com.bz/chiworkshops에서 확인할 수 있습니다. Mark Sampson, 인사 이사 드림", "vocab": "wellness 명 건강 / thereafter 부 그 이후 / in partnership with 구 ~와 제휴하여 / a series of 구 일련의 / be limited to 구 ~로 제한되다 / advance registration 명 사전 등록 / highly regarded 형 높이 평가받는 / nutritionist 명 영양사 / ingredient 명 재료", "questions": [{"no": 139, "q": "", "options": ["onto", "around", "through", "toward"], "answer": 2, "explain": "정답 (C) through\n해석: 5월 7일부터 6월 11일까지 매주 목요일\n정답 근거: 시작일(Beginning on 7 May)부터 종료일 11 June까지 계속된다는 기간 표현 → through(~까지 내내).\n오답 분석: (A) onto: '~위로' — 의미 불가. / (B) around: '~쯤' — 기간 종료 의미 불가. / (D) toward: '~을 향해' — 불가.\n지문 개요: 인사 이사 Mark Sampson이 전 직원에게 5월 7일부터 6월 11일까지 매주 목요일 130호에서 열리는 웰니스 워크숍 시리즈를 안내하며, 좌석이 40명으로 제한되어 사전 등록이 필요하고 첫 강연자는 저명한 영양사 Tracy Fonseca 박사라는 이메일."}, {"no": 140, "q": "", "options": ["Participants must attend both days.", "Therefore, advance registration is required.", "Moreover, all other workshops have been canceled.", "The seating arrangement was very successful."], "answer": 1, "explain": "정답 (B) Therefore, advance registration is required.\n해석: 따라서 사전 등록이 필요합니다.\n정답 근거: 앞 문장 \"좌석이 40명으로 제한된다\"가 원인이 되어 사전 등록이 필요하다는 결과(Therefore)가 자연스러움.\n오답 분석: (A) 이틀 모두 참석 요구는 매주 목요일 1회 세션과 맞지 않음. / (C) 다른 워크숍 취소는 뒤에서 다른 워크숍을 안내하므로 모순. / (D) 좌석 배치 성공은 아직 열리지 않은 행사와 불일치."}, {"no": 141, "q": "", "options": ["regard", "regards", "regarded", "regarding"], "answer": 2, "explain": "정답 (C) regarded\n해석: 매우 존경받는 영양사 Tracy Fonseca 박사\n정답 근거: 「a highly + 빈칸 + 명사 nutritionist」 → 부사 highly의 수식을 받는 분사형용사. regard는 타동사이고 영양사는 \"높이 평가받는\" 대상 → -ed regarded.\n오답 분석: (A) regard: 동사/명사 — 부사 뒤 명사 앞 불가. / (B) regards: 동사/명사 — 불가. / (D) regarding: 전치사 — 불가."}, {"no": 142, "q": "", "options": ["quality", "likelihood", "frequency", "convenience"], "answer": 0, "explain": "정답 (A) quality\n해석: 참가자들은 음식 선택의 질을 개선하는 방법을 배울 것입니다.\n정답 근거: 뒤 문장 \"균형 잡힌 건강한 식사를 만드는 지침\"이 곧 음식 선택의 질을 높이는 것 → quality.\n오답 분석: (B) likelihood: '가능성' — 의미 불가. / (C) frequency: '빈도' — 건강한 식사 지침과 불일치. / (D) convenience: '편의' — 불일치."}], "g": {"from": ["전치사", "~로부터"], "msampson@bes.com.bz": ["고유명사", "이메일 주소"], "to": ["전치사", "~에게, ~로"], "allstaff@bes.com.bz": ["고유명사", "이메일 주소"], "date": ["명사", "날짜"], "20": ["숫자", "20"], "april": ["명사", "4월"], "subject": ["명사", "제목"], "wellness": ["명사", "건강"], "workshops": ["명사", "워크숍", "workshop"], "dear": ["형용사", "친애하는"], "colleagues": ["명사", "동료", "colleague"], "beginning": ["현재분사", "~부터 시작하여", "begin"], "on": ["전치사", "~에, ~위에"], "thursday": ["명사", "목요일"], "7": ["숫자", "7"], "may": ["명사", "5월"], "and": ["접속사", "그리고"], "every": ["한정사", "모든"], "thereafter": ["부사", "그 이후로"], "11": ["숫자", "11"], "june": ["명사", "6월"], "belize": ["고유명사", "벨리즈(국가명)"], "energy": ["명사", "에너지"], "services": ["명사", "서비스", "service"], "in": ["전치사", "~에, ~안에"], "partnership": ["명사", "제휴"], "with": ["전치사", "~와 함께, ~으로"], "corporate": ["고유명사", "코퍼릿(회사명)"], "health": ["명사", "건강"], "interactive": ["고유명사", "인터랙티브(회사명)"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "offering": ["현재분사", "제공하는", "offer"], "a": ["관사", "하나의"], "series": ["명사", "시리즈"], "of": ["전치사", "~의"], "these": ["한정사", "이들"], "sessions": ["명사", "시간, 세션", "session"], "held": ["과거분사", "열리는", "hold"], "room": ["명사", "~호실"], "130": ["숫자", "130"], "1:00": ["숫자", "1시"], "p.m": ["명사", "오후"], "2:00": ["숫자", "2시"], "seating": ["명사", "좌석"], "is": ["동사", "~이다", "be"], "limited": ["과거분사", "제한된", "limit"], "40": ["숫자", "40"], "participants": ["명사", "참가자", "participant"], "per": ["전치사", "~당"], "workshop": ["명사", "워크숍"], "the": ["관사", "그"], "speaker": ["명사", "강연자"], "for": ["전치사", "~을 위해, ~동안"], "first": ["형용사", "첫 번째의"], "dr": ["명사", "박사"], "tracy": ["고유명사", "트레이시(이름)"], "fonseca": ["고유명사", "폰세카(성)"], "highly": ["부사", "매우, 높이"], "nutritionist": ["명사", "영양사"], "learn": ["동사", "배우다"], "how": ["부사", "어떻게"], "improve": ["동사", "개선하다"], "their": ["한정사", "그들의"], "food": ["명사", "음식"], "choices": ["명사", "선택", "choice"], "specifically": ["부사", "구체적으로"], "they": ["대명사", "그들"], "receive": ["동사", "받다"], "guidelines": ["명사", "지침", "guideline"], "create": ["동사", "만들다"], "balanced": ["형용사", "균형 잡힌"], "healthy": ["형용사", "건강한"], "meals": ["명사", "식사", "meal"], "fresh": ["형용사", "신선한"], "ingredients": ["명사", "재료", "ingredient"], "details": ["명사", "세부 사항", "detail"], "other": ["형용사", "다른"], "are": ["동사", "~이다", "be"], "available": ["형용사", "이용 가능한"], "at": ["전치사", "~에, ~에서"], "bes.com.bz/chiworkshops": ["고유명사", "웹사이트 주소"], "sincerely": ["부사", "진심으로"], "mark": ["고유명사", "마크(이름)"], "sampson": ["고유명사", "샘슨(성)"], "human": ["형용사", "인적인"], "resources": ["명사", "자원(HR 인사)", "resource"], "director": ["명사", "부장, 책임자"]}}, {"range": "143-146", "passage": "PARAMARIBO (5 May)—Allied Agricultural Technologies (AAT), the Suriname-based company that specializes in agricultural resources for the Caribbean and Latin America, recently patented a new grow-light system called Agrotorch. It is designed to make indoor farming easier and more efficient ---143--- automatically creating the optimal lighting conditions for growing crops.\nAccording to Ms. Anuradha Mohammed, AAT's spokesperson, \"Trying to raise plants inside a greenhouse or private home can be quite ---144---. This is particularly true when you have to adjust your lighting system constantly for different species. Agrotorch takes the job of constantly having to adjust the light out of the farmer's hands because it automatically emits the correct amount of light. ---145---. Moreover, the light ---146--- to ward off diseases.\"\nAAT hopes to have Agrotorch ready for production early next year.", "tr": "PARAMARIBO(5월 5일) — 카리브해와 라틴아메리카를 위한 농업 자원을 전문으로 하는 수리남 기반 기업 Allied Agricultural Technologies(AAT)는 최근 Agrotorch라는 새 재배 조명 시스템의 특허를 취득했다. 이 시스템은 작물 재배에 최적의 조명 조건을 자동으로 만들어줌으로써(143) 실내 농업을 더 쉽고 효율적으로 하도록 설계되었다. AAT 대변인 Anuradha Mohammed 씨에 따르면 \"온실이나 가정 안에서 식물을 기르는 것은 꽤 어려울(144) 수 있습니다. 특히 여러 종에 맞춰 조명 시스템을 끊임없이 조정해야 할 때 그렇습니다. Agrotorch는 정확한 양의 빛을 자동으로 내보내기 때문에 농부가 조명을 계속 조정해야 하는 일을 덜어 줍니다. 식물의 성장 주기에 맞춰 빛의 세기를 바꿉니다(145). 게다가 이 빛은 병해를 막는 데 도움이 됩니다(146).\" AAT는 내년 초 Agrotorch를 생산 준비 상태로 만들기를 희망한다.", "vocab": "specialize in 구 ~을 전문으로 하다 / patent 동 특허를 받다 / optimal 형 최적의 / crop 명 농작물 / spokesperson 명 대변인 / challenging 형 힘든 / adjust 동 조절하다 / emit 동 방출하다 / ward off 구 막다, 물리치다", "questions": [{"no": 143, "q": "", "options": ["to", "by", "thus", "which"], "answer": 1, "explain": "정답 (B) by\n해석: 최적의 조명 조건을 자동으로 만들어 줌으로써\n정답 근거: 「빈칸 + 부사 automatically + 동명사 creating」 → 동명사 앞 전치사 자리. 실내 농업을 쉽게 하는 \"수단\" → by -ing(~함으로써).\n오답 분석: (A) to: to 뒤 동명사는 불가(to부정사면 원형 필요). / (C) thus: 부사 — 수단 의미가 아니며 앞 내용의 결과로 보기 어려움. / (D) which: 관계대명사 — 뒤에 동사가 없어 구조 불가.\n지문 개요: 수리남 기업 AAT가 작물 재배에 최적인 조명을 자동으로 만들어 실내 농업을 쉽게 하는 Agrotorch 시스템의 특허를 취득했으며, 식물 성장 주기에 맞춰 밝기를 바꾸고 병해 예방에도 도움이 되어 내년 초 생산을 목표로 한다는 기사."}, {"no": 144, "q": "", "options": ["rewarding", "interesting", "surprising", "challenging"], "answer": 3, "explain": "정답 (D) challenging\n해석: 온실이나 가정 안에서 식물을 기르는 것은 꽤 어려울 수 있습니다.\n정답 근거: 뒤 문장 \"특히 조명을 끊임없이 조정해야 할 때 그렇다\"와 제품이 그 일을 덜어 준다는 설명 → 어려움 (challenging)을 말하는 문맥.\n오답 분석: (A) rewarding: '보람 있는' — 뒤의 어려움 설명과 불일치. / (B) interesting: '흥미로운' — 불일치. / (C) surprising: '놀라운' — 불일치."}, {"no": 145, "q": "", "options": ["It is surprisingly affordable.", "It turns on when motion is detected.", "It is very light, making it easy to handle.", "It changes intensity to match the growth cycle of the plants."], "answer": 3, "explain": "정답 (D) It changes intensity to match the growth cycle of the plants.\n해석: 식물의 성장 주기에 맞춰 빛의 세기를 바꿉니다.\n정답 근거: 앞 문장 \"정확한 양의 빛을 자동으로 내보낸다\"에 이어 자동 조절 기능을 구체화하고, 뒤 \"게다가 병해 예방\"으로 장점이 추가되는 흐름.\n오답 분석: (A) 가격은 기능 설명 흐름과 무관. / (B) 동작 감지 작동은 조명 조절과 무관. / (C) 가벼움은 조명 기능과 무관."}, {"no": 146, "q": "", "options": ["helps", "helped", "has helped", "was helping"], "answer": 0, "explain": "정답 (A) helps\n해석: 게다가 이 빛은 병해를 막는 데 도움이 됩니다.\n정답 근거: 제품의 일반적 기능을 설명하는 현재시제이며 주어 the light(단수) → helps. help to V.\n오답 분석: (B) helped: 과거 — 기능 설명과 불일치. / (C) has helped: 현재완료 — 아직 생산 전 제품이라 불일치. / (D) was helping: 과거진행 — 불일치."}], "g": {"paramaribo": ["고유명사", "파라마리보(수리남 수도)"], "5": ["숫자", "5"], "may)—allied": ["고유명사", "5월)—얼라이드(회사명)"], "agricultural": ["형용사", "농업의"], "technologies": ["고유명사", "테크놀로지스(회사명)", "technology"], "aat": ["고유명사", "AAT(회사 약칭)"], "the": ["관사", "그"], "suriname-based": ["형용사", "수리남에 기반을 둔"], "company": ["명사", "회사"], "that": ["관계사", "~하는"], "specializes": ["동사", "전문으로 하다", "specialize"], "in": ["전치사", "~에, ~안에"], "resources": ["명사", "자원", "resource"], "for": ["전치사", "~을 위해, ~동안"], "caribbean": ["고유명사", "카리브해 지역"], "and": ["접속사", "그리고"], "latin": ["고유명사", "라틴"], "america": ["고유명사", "아메리카"], "recently": ["부사", "최근에"], "patented": ["동사", "특허를 받았다", "patent"], "a": ["관사", "하나의"], "new": ["형용사", "새로운"], "grow-light": ["명사", "식물 재배용 조명"], "system": ["명사", "시스템"], "called": ["과거분사", "~라고 불리는", "call"], "agrotorch": ["고유명사", "아그로토치(제품명)"], "it": ["대명사", "그것"], "is": ["동사", "~이다", "be"], "designed": ["과거분사", "고안된", "design"], "to": ["to부정사", "~하도록"], "make": ["동사", "만들다"], "indoor": ["형용사", "실내의"], "farming": ["명사", "농업, 재배"], "easier": ["형용사", "더 쉬운", "easy"], "more": ["부사", "더"], "efficient": ["형용사", "효율적인"], "automatically": ["부사", "자동으로"], "creating": ["동명사", "만드는 것", "create"], "optimal": ["형용사", "최적의"], "lighting": ["명사", "조명"], "conditions": ["명사", "조건", "condition"], "growing": ["동명사", "기르는 것", "grow"], "crops": ["명사", "작물", "crop"], "according": ["부사", "(according to) ~에 따르면"], "ms": ["명사", "~씨(여성)"], "anuradha": ["고유명사", "아누라다(이름)"], "mohammed": ["고유명사", "모하메드(성)"], "aat's": ["고유명사", "AAT의"], "spokesperson": ["명사", "대변인"], "trying": ["동명사", "~하려고 애쓰는 것", "try"], "raise": ["동사", "기르다"], "plants": ["명사", "식물", "plant"], "inside": ["전치사", "~안에"], "greenhouse": ["명사", "온실"], "or": ["접속사", "또는"], "private": ["형용사", "개인의"], "home": ["명사", "집"], "can": ["조동사", "~할 수 있다"], "be": ["동사", "~이다, 되다"], "quite": ["부사", "꽤"], "this": ["한정사", "이"], "particularly": ["부사", "특히"], "true": ["형용사", "사실인"], "when": ["접속사", "~할 때"], "you": ["대명사", "당신"], "have": ["동사", "(have to) ~해야 한다"], "adjust": ["동사", "조절하다"], "your": ["한정사", "당신의"], "constantly": ["부사", "끊임없이"], "different": ["형용사", "다양한"], "species": ["명사", "종"], "takes": ["동사", "(take A out of ~) 덜어 주다", "take"], "job": ["명사", "일"], "of": ["전치사", "~의"], "having": ["동명사", "(have to) ~해야 하는 것", "have"], "light": ["명사", "조명, 빛"], "out": ["부사", "밖으로"], "farmer's": ["명사", "농부의", "farmer"], "hands": ["명사", "손", "hand"], "because": ["접속사", "~때문에"], "emits": ["동사", "방출하다", "emit"], "correct": ["형용사", "정확한"], "amount": ["명사", "양"], "moreover": ["부사", "게다가"], "ward": ["동사", "(ward off) 막다"], "off": ["부사", "(ward off) 물리쳐"], "diseases": ["명사", "질병", "disease"], "hopes": ["동사", "바라다", "hope"], "ready": ["형용사", "준비된"], "production": ["명사", "생산"], "early": ["부사", "초에, 일찍"], "next": ["형용사", "다음의"], "year": ["명사", "해"]}}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a-r5-p7',$mkd${"id": "a-r5-p7", "area": "RC", "part": 7, "group": "A급 과제", "series": 3, "round": 5, "level": "중급", "title": "A급 과제 5회 · PART 7 (기출독해 2문항 9·10회)", "notes": [], "items": [], "sets": [{"range": "147-148", "sub": "기출독해 2문항 9회", "passage": "Great news! Classico Blue Hotels, Inc., (CBHI) has expanded its rewards program. Members now receive greater discounts at our hotels worldwide, as well as room upgrades, special amenities―such as ironing services, free parking, and spa treatments―and free nights. To find out more about the program or to register for it, talk to our front-desk staff or visit www.cbhi.com.\nFor other questions or concerns, you can contact the front desk, the restaurant, or housekeeping services directly from your phone using our app, which can be downloaded from our Web site.\nThank you for choosing Classico Blue Hotels.", "tr": "좋은 소식입니다! Classico Blue Hotels, Inc.(CBHI)가 보상 프로그램을 확대했습니다. 회원은 이제 전 세계 저희 호텔에서 더 큰 할인은 물론 객실 업그레이드, 다림질 서비스·무료 주차·스파 트리트먼트 같은 특별 편의 서비스, 무료 숙박을 받습니다. 프로그램에 대해 더 알아보거나 등록하시려면 프런트 직원에게 말씀하시거나 www.cbhi.com을 방문하세요. 기타 질문이나 우려 사항은 저희 웹사이트에서 내려받을 수 있는 앱을 이용해 전화기에서 바로 프런트, 레스토랑, 객실 관리 서비스에 연락하실 수 있습니다. Classico Blue Hotels를 선택해 주셔서 감사합니다.", "vocab": "expand 동 확대하다 / rewards program 명 보상 프로그램 / amenity 명 편의 시설 / treatment 명 관리, 시술 / register for 구 ~에 등록하다 / housekeeping 명 객실 관리 / incentive 명 혜택 / intended for 구 ~을 대상으로 한", "questions": [{"no": 147, "q": "For whom is the information most likely intended?", "options": ["Hotel managers", "Hotel guests", "Front-desk staff", "Housekeeping staff"], "answer": 1, "explain": "정답 (B) Hotel guests\n해석: 이 안내문은 누구를 대상으로 할 것 같은가?\n정답 근거: \"프런트 직원에게 말하라\", \"전화기에서 프런트·객실 관리에 연락하라\", \"저희 호텔을 선택해 주셔서 감사\" → 투숙객 대상.\n오답 분석: (A) 호텔 관리자 대상 아님. / (C) 프런트 직원은 안내 대상이 아니라 연락처. / (D) 객실 관리 직원도 연락처일 뿐.\n지문 개요: Classico Blue Hotels가 보상 프로그램을 확대해 회원에게 더 큰 할인, 객실 업그레이드, 특별 편의 서비스, 무료 숙박을 제공하며, 가입은 프런트나 웹사이트에서, 기타 문의는 앱으로 하라고 안내하는 투숙객 대상 안내문.", "vocab": "Paraphrase: Thank you for choosing Classico Blue Hotels / talk to our front-desk staff → hotel guests", "g": {"for": ["전치사", "~을 위해, ~동안"], "whom": ["대명사", "누구를"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "information": ["명사", "안내문, 정보"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "intended": ["과거분사", "의도된, 대상으로 한", "intend"]}}, {"no": 148, "q": "According to the information, what has CBHI changed recently?", "options": ["Its vacation policies", "Its restaurant hours", "Its check-in procedures", "Its program incentives"], "answer": 3, "explain": "정답 (D) Its program incentives\n해석: 안내문에 따르면 CBHI가 최근 바꾼 것은?\n정답 근거: \"보상 프로그램을 확대했다(has expanded its rewards program)\" → 프로그램 혜택(incentives) 변경.\n오답 분석: (A) 휴가 정책 언급 없음. / (B) 레스토랑 영업시간 언급 없음. / (C) 체크인 절차 언급 없음.", "vocab": "Paraphrase: has expanded its rewards program / greater discounts, free nights → its program incentives", "g": {"according": ["부사", "(according to) ~에 따르면"], "to": ["to부정사", "~하려면"], "the": ["관사", "그"], "information": ["명사", "안내문, 정보"], "what": ["대명사", "무엇"], "has": ["동사", "(현재완료) ~했다", "have"], "cbhi": ["고유명사", "CBHI(회사 약칭)"], "changed": ["과거분사", "바꾼", "change"], "recently": ["부사", "최근에"]}}], "g": {"great": ["형용사", "훌륭한"], "news": ["명사", "소식"], "classico": ["고유명사", "클라시코(호텔명)"], "blue": ["고유명사", "블루(호텔명)"], "hotels": ["명사", "호텔", "hotel"], "inc": ["명사", "주식회사"], "cbhi": ["고유명사", "CBHI(회사 약칭)"], "has": ["동사", "(현재완료) ~했다", "have"], "expanded": ["과거분사", "확대한", "expand"], "its": ["한정사", "그것의"], "rewards": ["명사", "보상", "reward"], "program": ["명사", "프로그램"], "members": ["명사", "회원", "member"], "now": ["부사", "지금"], "receive": ["동사", "받다"], "greater": ["형용사", "더 큰", "great"], "discounts": ["명사", "할인", "discount"], "at": ["전치사", "~에, ~에서"], "our": ["한정사", "우리의"], "worldwide": ["부사", "전 세계적으로"], "as": ["접속사", "~처럼, ~때문에"], "well": ["부사", "(as well as) ~뿐만 아니라"], "room": ["명사", "객실"], "upgrades": ["명사", "업그레이드", "upgrade"], "special": ["형용사", "특별한"], "amenities―such": ["명사", "편의 시설―(such as) 예컨대", "amenity"], "ironing": ["명사", "다림질"], "services": ["명사", "서비스", "service"], "free": ["형용사", "무료의"], "parking": ["명사", "주차"], "and": ["접속사", "그리고"], "spa": ["명사", "스파"], "treatments―and": ["명사", "관리―그리고", "treatment"], "nights": ["명사", "숙박(박)", "night"], "to": ["to부정사", "~하려면"], "find": ["동사", "(find out) 알아내다"], "out": ["부사", "밖으로"], "more": ["부사", "더"], "about": ["전치사", "~에 대해"], "the": ["관사", "그"], "or": ["접속사", "또는"], "register": ["동사", "등록하다"], "for": ["전치사", "~을 위해, ~동안"], "it": ["대명사", "그것"], "talk": ["동사", "이야기하다"], "front-desk": ["명사", "프런트"], "staff": ["명사", "직원"], "visit": ["동사", "방문하다"], "www.cbhi.com": ["고유명사", "웹사이트 주소"], "other": ["형용사", "다른"], "questions": ["명사", "질문", "question"], "concerns": ["명사", "우려 사항", "concern"], "you": ["대명사", "당신"], "can": ["조동사", "~할 수 있다"], "contact": ["동사", "연락하다"], "front": ["형용사", "앞쪽의"], "desk": ["명사", "데스크"], "restaurant": ["명사", "식당"], "housekeeping": ["명사", "객실 관리"], "directly": ["부사", "직접"], "from": ["전치사", "~로부터"], "your": ["한정사", "당신의"], "phone": ["명사", "전화기"], "using": ["현재분사", "사용하여", "use"], "app": ["명사", "앱"], "which": ["관계사", "~하는 (것)"], "be": ["동사", "~이다, 되다"], "downloaded": ["과거분사", "다운로드되는", "download"], "web": ["명사", "웹"], "site": ["명사", "사이트"], "thank": ["동사", "감사하다"], "choosing": ["동명사", "선택한 것", "choose"]}}, {"range": "149-150", "sub": "기출독해 2문항 9회", "passage": "Changes to Popular Fashion Magazine Announced\nJOHANNESBURG (3 October) ― Publishing company Front Seat announced yesterday that its fashion magazine Distinctive will convert from a monthly to a quarterly publication. It will be available only at newsstands and in bookstores beginning with next January's issue.\nThe change is a response to a shrinking readership. At its peak, the oldest fashion magazine in the country had a circulation of 500,000. It has dropped to approximately 150,000 in recent years.\n\"Our readers can look forward to expanded fashion and beauty content printed on quality paper with beautiful photography,\" said Distinctive editor-in-chief Palesa Nel. \"We are very excited about the new direction of our magazine.\"", "tr": "인기 패션 잡지의 변화 발표\n요하네스버그(10월 3일) — 출판사 Front Seat는 어제 패션 잡지 Distinctive를 월간에서 계간으로 전환한다고 발표했다. 내년 1월호부터 가판대와 서점에서만 구입할 수 있게 된다. 이 변화는 줄어드는 독자층에 대한 대응이다. 전성기에 이 나라 최고(最古)의 패션 잡지는 발행 부수가 50 만 부였다. 최근 몇 년 사이 약 15만 부로 떨어졌다. \"독자들은 고급 용지에 아름다운 사진과 함께 인쇄된 확대된 패션·뷰티 콘텐츠를 기대할 수 있습니다.\" Distinctive 편집장 Palesa Nel이 말했다. \"저희는 잡지의 새로운 방향에 매우 들떠 있습니다.\"", "vocab": "convert 동 전환하다 / quarterly 형 분기별의 / publication 명 출판(물) / newsstand 명 신문 가판대 / shrinking 형 줄어드는 / readership 명 독자층 / circulation 명 발행 부수 / editor-in-chief 명 편집장", "questions": [{"no": 149, "q": "How often will Distinctive be published?", "options": ["Once a year", "Four times a year", "Once a month", "Two times a month"], "answer": 1, "explain": "정답 (B) Four times a year\n해석: Distinctive는 얼마나 자주 발행될 것인가?\n정답 근거: \"월간에서 계간(quarterly)으로 전환\" → 연 4회.\n오답 분석: (A) 연 1회 아님. / (C) 월 1회는 이전 주기. / (D) 월 2회 언급 없음.\n지문 개요: 출판사 Front Seat가 독자 감소(최고 50만 부→15만 부)에 대응해 패션 잡지 Distinctive를 월간에서 계간으로 바꾸고 내년 1월호부터 가판대·서점에서만 판매하며, 편집장은 고급 용지와 확대된 콘텐츠를 약속한 기사.", "vocab": "Paraphrase: convert from a monthly to a quarterly publication → four times a year", "g": {"how": ["부사", "어떻게"], "often": ["부사", "자주(how often 얼마나 자주)"], "will": ["조동사", "~할 것이다"], "distinctive": ["고유명사", "디스팅티브(잡지명)"], "be": ["동사", "~이다, 되다"], "published": ["과거분사", "발행되는", "publish"]}}, {"no": 150, "q": "What is indicated about Distinctive?", "options": ["It will appear online.", "It will be hiring a new editor.", "It has been losing subscribers.", "It features award-winning photography."], "answer": 2, "explain": "정답 (C) It has been losing subscribers.\n해석: Distinctive에 대해 언급된 것은?\n정답 근거: \"줄어드는 독자층(shrinking readership)\", \"발행 부수가 50만에서 15만으로 감소\" → 구독자를 잃고 있음.\n오답 분석: (A) 온라인이 아니라 가판대·서점에서만 판매. / (B) 새 편집장 채용 언급 없음. / (D) 사진이 수상작이라는 내용 없음.", "vocab": "Paraphrase: a shrinking readership / dropped to approximately 150,000 → losing subscribers", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "indicated": ["과거분사", "언급된", "indicate"], "about": ["전치사", "~에 대해"], "distinctive": ["고유명사", "디스팅티브(잡지명)"]}}], "g": {"changes": ["명사", "변경", "change"], "to": ["전치사", "~에게, ~로"], "popular": ["형용사", "인기 있는"], "fashion": ["명사", "패션"], "magazine": ["명사", "잡지"], "announced": ["과거분사", "발표된", "announce"], "johannesburg": ["고유명사", "요하네스버그"], "3": ["숫자", "3"], "october": ["명사", "10월"], "publishing": ["명사", "출판"], "company": ["명사", "회사"], "front": ["고유명사", "프런트(회사명)"], "seat": ["고유명사", "시트(회사명)"], "yesterday": ["부사", "어제"], "that": ["접속사", "~라는 것"], "its": ["한정사", "그것의"], "distinctive": ["고유명사", "디스팅티브(잡지명)"], "will": ["조동사", "~할 것이다"], "convert": ["동사", "전환하다"], "from": ["전치사", "~로부터"], "a": ["관사", "하나의"], "monthly": ["명사", "월간"], "quarterly": ["형용사", "계간의"], "publication": ["명사", "간행물"], "it": ["대명사", "그것"], "be": ["동사", "~이다, 되다"], "available": ["형용사", "구입 가능한"], "only": ["부사", "오직"], "at": ["전치사", "~에, ~에서"], "newsstands": ["명사", "가판대", "newsstand"], "and": ["접속사", "그리고"], "in": ["전치사", "~에, ~안에"], "bookstores": ["명사", "서점", "bookstore"], "beginning": ["현재분사", "~부터 시작하여", "begin"], "with": ["전치사", "~와 함께, ~으로"], "next": ["형용사", "다음의"], "january's": ["명사", "1월의", "january"], "issue": ["명사", "(잡지의) 호"], "the": ["관사", "그"], "change": ["명사", "변경"], "is": ["동사", "~이다", "be"], "response": ["명사", "대응"], "shrinking": ["현재분사", "줄어드는", "shrink"], "readership": ["명사", "독자 수"], "peak": ["명사", "정점"], "oldest": ["형용사", "가장 오래된", "old"], "country": ["명사", "나라"], "had": ["동사", "(과거완료) ~했었다", "have"], "circulation": ["명사", "발행 부수"], "of": ["전치사", "~의"], "500,000": ["숫자", "50만"], "has": ["동사", "(현재완료) ~했다", "have"], "dropped": ["과거분사", "떨어진", "drop"], "approximately": ["부사", "대략"], "150,000": ["숫자", "15만"], "recent": ["형용사", "최근의"], "years": ["명사", "년", "year"], "our": ["한정사", "우리의"], "readers": ["명사", "독자", "reader"], "can": ["조동사", "~할 수 있다"], "look": ["동사", "(look forward to) 고대하다"], "forward": ["부사", "(look forward to) 앞으로"], "expanded": ["과거분사", "확대된", "expand"], "beauty": ["명사", "미용"], "content": ["명사", "콘텐츠"], "printed": ["과거분사", "인쇄된", "print"], "on": ["전치사", "~에, ~위에"], "quality": ["형용사", "고급의"], "paper": ["명사", "종이"], "beautiful": ["형용사", "아름다운"], "photography": ["명사", "사진"], "said": ["동사", "말했다", "say"], "editor-in-chief": ["명사", "편집장"], "palesa": ["고유명사", "팔레사(이름)"], "nel": ["고유명사", "넬(성)"], "we": ["대명사", "우리"], "are": ["동사", "~이다", "be"], "very": ["부사", "매우"], "excited": ["형용사", "들뜬"], "about": ["전치사", "~에 대해"], "new": ["형용사", "새로운"], "direction": ["명사", "방향"]}}, {"range": "154-155", "sub": "기출독해 2문항 9회", "passage": "Gordon Li Flooring is the one stop for all your flooring needs. We have been serving the Melbourne area for more than twenty years. We strive to take all the stress out of shopping for flooring to meet your specific requirements. We can process and ship most orders within 24 hours and install your new flooring with minimal disruption to your life.\nStop by our store located at 402 Mawson Avenue. We are open daily from 10:00 A.M. to 8:00 P.M. You can also go online at www.glf.com.au to choose from our large selection of flooring from the comfort of your home. We can take your order online or you can call us at 0491 570 006.", "tr": "Gordon Li Flooring은 여러분의 모든 바닥재 필요를 한 번에 해결하는 곳입니다. 저희는 20년 넘게 멜버른 지역에 서비스를 제공해 왔습니다. 고객의 특정 요구에 맞는 바닥재 쇼핑의 모든 스트레스를 없애 드리려 노력합니다. 대부분의 주문을 24시간 내에 처리·배송하고 생활에 최소한의 지장만 주며 새 바닥재를 시공합니다. 402 Mawson Avenue에 있는 매장에 들러 주세요. 매일 오전 10시부터 오후 8시까지 영업합니다. 또한 www.glf.com.au에 접속해 집에서 편안하게 다양한 바닥재 중에서 고르실 수도 있습니다. 온라인으로 주문을 받거나 0491 570 006으로 전화하셔도 됩니다.", "vocab": "flooring 명 바닥재 / strive to 구 ~하려고 노력하다 / requirement 명 요구 사항 / process 동 처리하다 / minimal 형 최소한의 / disruption 명 지장 / stop by 구 들르다 / from the comfort of 구 ~에서 편안하게 / emphasize 동 강조하다", "questions": [{"no": 154, "q": "What is indicated about Gordon Li Flooring?", "options": ["Their customers can shop for flooring without leaving their homes.", "They specialize in restoring old floors.", "Their flooring is made from recycled materials.", "They have multiple locations around Melbourne."], "answer": 0, "explain": "정답 (A) Their customers can shop for flooring without leaving their homes.\n해석: Gordon Li Flooring에 대해 언급된 것은?\n정답 근거: \"집에서 편안하게(from the comfort of your home) 온라인으로 바닥재를 고르고 주문할 수 있다\" → 집을 떠나지 않고 쇼핑 가능.\n오답 분석: (B) 오래된 바닥 복원 전문 언급 없음. / (C) 재활용 소재 언급 없음. / (D) 매장은 한 곳(402 Mawson Avenue)만 언급.\n지문 개요: 멜버른에서 20년 넘게 영업한 바닥재 업체 Gordon Li Flooring이 대부분 주문을 24시간 내 처리·배송하고 최소한의 불편으로 시공하며, 매장 방문 외에 웹사이트에서 집에서 편하게 고르고 주문하거나 전화 주문도 가능하다고 홍보하는 광고.", "vocab": "Paraphrase: choose from our large selection ... from the comfort of your home → shop without leaving their homes", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "indicated": ["과거분사", "언급된", "indicate"], "about": ["전치사", "~에 대해"], "gordon": ["고유명사", "고든(이름)"], "li": ["고유명사", "리(성)"], "flooring": ["명사", "바닥재"]}}, {"no": 155, "q": "Why does the advertisement give details about order processing and shipping?", "options": ["To explain how orders can be tracked", "To point out that delivery times may vary", "To emphasize how quickly installations are made", "To inform customers about faster delivery options"], "answer": 2, "explain": "정답 (C) To emphasize how quickly installations are made\n해석: 광고는 왜 주문 처리와 배송에 대한 세부 사항을 제공하는가?\n정답 근거: \"24시간 내 처리·배송하고 최소한의 지장으로 시공\" → 주문부터 시공까지 빠르게 이루어짐을 강조.\n오답 분석: (A) 주문 추적 방법 언급 없음. / (B) 배송 시간이 다를 수 있다는 내용이 아니라 빠름을 강조. / (D) 더 빠른 배송 옵션(선택지) 제공 언급 없음.", "vocab": "Paraphrase: process and ship most orders within 24 hours and install → how quickly installations are made", "g": {"why": ["부사", "왜"], "does": ["조동사", "(의문문 조동사)", "do"], "the": ["관사", "그"], "advertisement": ["명사", "광고"], "give": ["동사", "주다"], "details": ["명사", "세부 사항", "detail"], "about": ["전치사", "~에 대해"], "order": ["명사", "주문"], "processing": ["명사", "처리"], "and": ["접속사", "그리고"], "shipping": ["명사", "배송"]}}], "g": {"gordon": ["고유명사", "고든(이름)"], "li": ["고유명사", "리(성)"], "flooring": ["명사", "바닥재"], "is": ["동사", "~이다", "be"], "the"