insert into content(key,data,updated_at) values('sec:a-r8-p6',$mkd${"id": "a-r8-p6", "area": "RC", "part": 6, "group": "A급 과제", "series": 3, "round": 8, "level": "중급", "title": "A급 과제 8회 · PART 6", "notes": [], "items": [], "sets": [{"range": "131-134", "passage": "Lupo's Goes Solar\n(14 April)—Solar energy leader GIGT Ltd. has teamed up with the Lupo's Pizzeria chain to introduce solar power at several of its locations. Company founder Antonio Lupo ---131--- three months consulting with GIGT engineers on potential designs. ---132---. With the design phase now complete, Mr. Lupo plans to begin renovations to the Geneva location, ---133--- the international chain got its start. While the technology will continue to improve, Mr. Lupo wants his company to be regarded as a leader in the ---134---. \"We can use this technology now,\" he says. \"There is no point in waiting.\"", "tr": "Lupo's, 태양광으로 간다 (4월 14일) — 태양 에너지 선도 기업 GIGT Ltd.가 Lupo's Pizzeria 체인과 손잡고 여러 지점에 태양광 발전을 도입한다. 회사 창업자 Antonio Lupo는 GIGT 엔지니어들과 가능한 설계를 협의하며 3개월을 보냈다(131). 그 결과물은 피자 오븐의 전력 수요를 완전히 충족한다(132). 설계 단계가 이제 완료되어 Lupo 씨는 이 국제 체인이 시작된 곳인(133) 제네바 지점의 개조를 시작할 계획이다. 기술은 계속 발전하겠지만 Lupo 씨는 자신의 회사가 업계(134)의 선두주자로 여겨지길 원한다. \"우리는 지금 이 기술을 쓸 수 있습니다.\" 그는 말한다. \"기다릴 이유가 없습니다.\"", "vocab": "team up with 구 ~와 협력하다 / introduce 동 도입하다 / founder 명 설립자 / spend A (V-ing) 구 ~하는 데 A를 쓰다 / consult 동 상의하다 / potential 형 잠재적인 / phase 명 단계 / renovation 명 개조 / get one's start 구 시작하다 / be regarded as 구 ~로 여겨지다 / industry 명 업계 / there is no point in 구 ~해도 소용없다", "g": {"lupo's": ["고유명사", "루포스(상호명)"], "goes": ["동사", "~로 가다", "go"], "solar": ["형용사", "태양광의"], "14": ["숫자", "14"], "april)—solar": ["명사", "4월)—태양(광)"], "energy": ["명사", "에너지"], "leader": ["명사", "선도 기업, 리더"], "gigt": ["고유명사", "GIGT(회사명)"], "ltd": ["명사", "유한회사"], "has": ["조동사", "(현재완료) ~했다", "have"], "teamed": ["동사", "협력했다(team up)", "team"], "up": ["부사", "(team up) 함께, 최대"], "with": ["전치사", "~와 함께, ~으로"], "the": ["관사", "그"], "pizzeria": ["명사", "피자 가게"], "chain": 